const GROUP_ADMIN_SKILL = `مهارت ۳ — مدیریت گروه (تو نگهبان گروهی):
- ابزارهای واقعی: /ban /unban /kick /mute /unmute (مدت مثل 30m، 2h، 1d) · /warn /unwarn /resetwarns /setwarnlimit · /del /purge /clean N · /pin /unpin · /close /open.
- قفل‌ها: /lock و /unlock (لینک، عکس، ویدیو، استیکر، گیف، فوروارد، ربات، ...) · /locks · /setaction برای نوع مجازات.
- فیلتر و ضد اسپم: /addblacklist /unblacklist /blacklistmode · /filter /stop · /antispam · /antiraid · /setflood · /captcha · /forcejoin @کانال.
- خوشامد و قوانین: /setwelcome /setgoodbye /setrules /rules · یادداشت: /save /get /notes · زمان‌بندی: /schedule · یادآور: /rem · آمار: /analytics /summary · لاگ: /log · پنل: /panel و پنل وب با /web.
- قانون طلایی: عضو عادی رو به ادمین ارجاع بده؛ برای ادمین دقیق بگو کدوم دستور و با چه مثالی. اگه کاربری داره اسپم/فحش/دعوا راه می‌ندازه، آروم و قاطع جمعش کن و راه‌حل مدیریتی پیشنهاد بده.
- بات باید ادمین گروه باشه با دسترسی حذف پیام، محدودکردن و پین؛ اگه کاری نشد احتمالاً دسترسی کمه.`;

const SKILL_PACK = `${FA_SPEAK_SKILL}\n\n${SMART_SKILL}`;

function withFaSkill(system, opts) {
  const o = opts || {};
  return String(system || '') + '\n\n' + SKILL_PACK + (o.group ? '\n\n' + GROUP_ADMIN_SKILL : '');
}

// ======================= QUICK REPLIES (zero-token answers for common small talk) =======================
// Short, very common messages are answered locally; the LLM is only called for real questions.
const QR_PUNCT = /[\s\u200c.,،!?؟…:;"'«»()\[\]{}\-_~*]+/g;
function qrNorm(t) {
  return String(t || '').toLowerCase()
    .replace(/[\u064B-\u065F\u0670\u0640]/g, '').replace(/ي/g, 'ی').replace(/ك/g, 'ک').replace(/[ۀة]/g, 'ه').replace(/[أإآ]/g, 'ا')
    .replace(/(.)\1{2,}/g, '$1$1') // سلاااام -> سلاام
    .replace(QR_PUNCT, ' ').trim();
}
const qrPick = (a) => a[Math.floor(Math.random() * a.length)];
const QR_RULES = [
  { re: /^(سلا+م|سلا+م علیکم|سلام علیک|سلامم|درود|درود بر تو|علیک سلام|slm|salam|salaam|hi+|hey+|hello|helo|سلام سگ|سلام داداش|سلام رفیق|سلام خوبی|سلام چطوری|سلام خوبین|hi there)( خوبی| چطوری| چطورین| خوبین| خوش اومدی)?$/,
    out: (n) => qrPick([`سلام ${n} 👋 خوبی؟ چه خبر؟`, `سلام ${n} جان 😊 جانم، بگو چی لازم داری؟`, `درود ${n} 🌱 حالت چطوره؟`, `سلام سلام ${n} 🐕‍🦺 در خدمتم!`]) },
  { re: /^(خوبی|خوبین|چطوری|چطورین|چه خبر|چخبر|چه خبرا|چخبرا|احوالت|حالت خوبه|khobi|chetori|che khabar|how are you|whats up|sup)$/,
    out: (n) => qrPick(['مرسی، خوبم 😄 تو چطوری؟', 'عالی‌ام، مثل همیشه سر پستم 🐕‍🦺 تو چه خبر؟', 'خوبم رفیق، تو خوبی؟ کاری داری بگو.']) },
  { re: /^(خوبم|منم خوبم|عالیم|مرسی خوبم|خوبم مرسی|خوبم ممنون|ای بد نیستم|بد نیستم|im fine|fine|good)( تو چطوری| تو خوبی| مرسی)?$/,
    out: () => qrPick(['خداروشکر 😊 بگو ببینم چیکار می‌تونم برات بکنم؟', 'همیشه خوب باشی ✨', 'چه خوب! اگه سوالی داری در خدمتم.']) },
  { re: /^(مرسی|مرسی داداش|مرسی رفیق|ممنون|ممنونم|خیلی ممنون|خیلی مرسی|تشکر|متشکرم|سپاس|سپاسگزارم|دمت گرم|دستت درد نکنه|thanks|thank you|thx|tnx|merci|mrc|mersi)( داداش| رفیق| سگ| جان| عزیزم)?$/,
    out: () => qrPick(['خواهش می‌کنم 🙏', 'قابلی نداشت 😊', 'فدات، هر وقت کاری داشتی هستم 🐕‍🦺', 'نوش جونت ✌️']) },
  { re: /^(خداحافظ|خدافظ|خداحافظی|بای|بای بای|فعلا|فعلا بای|شب خوش|شب بخیر|bye|bb|good night|gn)$/,
    out: (n) => qrPick([`خدانگهدار ${n} 👋`, 'فعلاً! مراقب خودت باش ✌️', 'شبت بخیر 🌙 خوب بخوابی.']) },
  { re: /^(صبح بخیر|صبح بخیر همگی|صبحتون بخیر|صبح عالی متعالی|good morning|gm)$/,
    out: (n) => qrPick([`صبح تو هم بخیر ${n} ☀️`, 'صبح بخیر! روز خوبی داشته باشی 🌤']) },
  { re: /^(اوکی|اوکیه|باشه|باشه مرسی|حله|اکی|ok|okay|okey|k|kk)$/,
    out: () => qrPick(['👌', 'حله ✌️', 'اوکی 👍']) },
  { re: /^(خخ+|ههه+|هه هه|لول|lol|lmao|haha+|😂+|🤣+)$/,
    out: () => qrPick(['😂', '😄', 'خخخ 😅']) },
  { re: /^(ربات|بات|سگ|سگ نگهبان|هوی|هی|اهای|bot|sag)$/,
    out: (n) => qrPick([`جانم ${n}؟ 🐕‍🦺`, 'بله؟ گوش می‌دم 👂', 'هوو؟ بگو چی شده 😄']) },
  { re: /^(ساعت چنده|ساعت چند است|الان ساعت چنده|ساعت|what time is it)$/,
    out: (n, env) => `🕒 الان ساعت ${new Intl.DateTimeFormat('fa-IR', { timeZone: (env && env.TIMEZONE) || 'Asia/Tehran', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date())} است.` },
  { re: /^(امروز چندمه|امروز چند شنبه است|امروز چندشنبه است|امروز چه روزیه|تاریخ امروز|تاریخ امروز چنده|امروز چندم است|what day is it|today date)$/,
    out: (n, env) => {
      const pt = Object.fromEntries(new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: (env && env.TIMEZONE) || 'Asia/Tehran', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).formatToParts(new Date()).map((x) => [x.type, x.value]));
      return `📅 امروز ${pt.weekday} ${pt.day} ${pt.month} ${pt.year}`;
    } },
  { re: /^(چیکار میکنی|چیکار می تونی بکنی|چیکار میتونی بکنی|چه کارایی بلدی|چیا بلدی|قابلیتات چیه|امکاناتت چیه|what can you do)$/,
    out: () => 'من سگ نگهبانم 🐕‍🦺\n🛡 مدیریت گروه: بن، میوت، اخطار، قفل لینک و رسانه، ضد اسپم و ضد ریید، کپچا، خوشامد\n💬 جواب سوال‌ها و گپ هوشمند\n💰 قیمت دلار، طلا و ارز دیجیتال\n🎬 فیلمیار، ⏰ یادآور، 📊 آمار گروه\nبرای راهنما /help بزن.' },
];
// returns a ready answer string or null (null = let the AI handle it)
function quickReply(text, name, env) {
  const raw = String(text || '');
  if (!raw || raw.length > 60 || raw.startsWith('/')) return null;
  const t = qrNorm(raw);
  if (!t || t.split(' ').length > 6) return null;
  const n = String(name || '').slice(0, 24).replace(/[<>]/g, '') || 'رفیق';
  for (const r of QR_RULES) if (r.re.test(t)) { try { return r.out(n, env); } catch { return null; } }
  return null;
}

// ======================= AI COMMAND PLANNER (RayZen-style) =======================
const AI_PLAN_SYSTEM = `تو برنامه‌ریز مدیریت گروه تلگرام هستی. هیچ کاری را انجام‌شده اعلام نکن.
فقط یک JSON خالص برگردان:
{"reply":"متن کوتاه یا خالی","clarify":null یا سؤال کوتاه,"actions":[{"tool":"نام","args":{...}}]}
ابزارها:
ban{target:"reply"|id,duration?,reason?} unban{target} mute{target,duration?} unmute{target} kick{target} warn{target,reason?}
lock{type:media|photos|videos|links|stickers|all,duration?} unlock{type}
night_lock{start:"HH:MM",end:"HH:MM"} night_off{}
roast_on{} roast_off{} ai_on{} ai_off{}
set_welcome{text} set_rules{text} delete_msg{}
اگر مبهم است clarify بپرس و actions=[].
مدت: 30m 2h 1d 1w. هدف reply = کاربر ریپلای‌شده.
reply و clarify را فارسی محاوره‌ای کوتاه بنویس.`;

const ADMIN_INTENT_RE = /(?:بن|میوت|سایلنت|سکوت|اخراج|کیک|اخطار|قفل|باز\s*کن|خوشامد|خوش‌آمد|قوانین|تیکه|خاموش|روشن|پاک\s*کن|حذف|فیلتر|قفل\s*شب|mute|ban|kick|warn|lock|unlock|delete|unmute|unban)/i;

function parseDurationSec(s) {
  const t = String(s || '').trim().toLowerCase().replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
  const m = t.match(/^(\d+)\s*(s|m|h|d|w|ثانیه|دقیقه|ساعت|روز|هفته)?/);
  if (!m) return 0;
  const n = Number(m[1]);
  const u = m[2] || 'm';
  if (u.startsWith('s') || u === 'ثانیه') return n;
  if (u.startsWith('m') || u === 'دقیقه') return n * 60;
  if (u.startsWith('h') || u === 'ساعت') return n * 3600;
  if (u.startsWith('d') || u === 'روز') return n * 86400;
  if (u.startsWith('w') || u === 'هفته') return n * 604800;
  return n * 60;
}

function describePlanAction(a) {
  const g = a.args || {};
  const tgt = g.target === 'reply' ? 'کاربر ریپلای‌شده' : (g.target || '');
  const dur = g.duration ? ` (${g.duration})` : '';
  const map = {
    ban: `بن ${tgt}${dur}`, unban: `رفع بن ${tgt}`, mute: `سکوت ${tgt}${dur}`, unmute: `رفع سکوت ${tgt}`,
    kick: `کیک ${tgt}`, warn: `اخطار به ${tgt}`, lock: `قفل ${g.type || ''}${dur}`, unlock: `بازکردن ${g.type || ''}`,
    night_lock: `قفل شب ${g.start || ''}→${g.end || ''}`, night_off: 'خاموش قفل شب',
    roast_on: 'روشن تیکه‌پرانی', roast_off: 'خاموش تیکه‌پرانی', ai_on: 'روشن AI', ai_off: 'خاموش AI',
    set_welcome: `خوش‌آمد: ${String(g.text || '').slice(0, 40)}`, set_rules: 'تنظیم قوانین', delete_msg: 'حذف پیام ریپلای',
  };
  return map[a.tool] || a.tool;
}

function extractPlanJson(text) {
  const raw = String(text || '').trim();
  const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  const s = fence ? fence[1] : raw;
  const i = s.indexOf('{');
  const j = s.lastIndexOf('}');
  if (i < 0 || j <= i) return null;
  try { return JSON.parse(s.slice(i, j + 1)); } catch { return null; }
}

async function resolvePlanTarget(env, m, target) {
  if (!target || target === 'reply') {
    const u = m.reply_to_message?.from;
    return u ? { id: u.id, name: u.first_name || String(u.id) } : null;
  }
  const id = Number(String(target).replace(/[^\d]/g, ''));
  return Number.isFinite(id) && id > 0 ? { id, name: String(id) } : null;
}

async function executePlanAction(env, m, g, action) {
  const chatId = m.chat.id;
  const tool = action.tool;
  const args = action.args || {};
  const mod = M(g);
  const save = () => env.KV.put(`grp:${chatId}`, JSON.stringify(g));

  if (tool === 'roast_on') { g.roast = true; g._roastForceOff = 0; if (!(g.chance > 0)) g.chance = 20; await save(); return 'تیکه روشن شد'; }
  if (tool === 'roast_off') { g.roast = false; g._roastForceOff = 1; await save(); return 'تیکه خاموش شد'; }
  if (tool === 'ai_on') { g.ai = true; await save(); return 'AI روشن'; }
  if (tool === 'ai_off') { g.ai = false; await save(); return 'AI خاموش'; }
  if (tool === 'night_off') { g.nightLock = null; await save(); return 'قفل شب خاموش'; }
  if (tool === 'night_lock') {
    const sh = Number(String(args.start || '23').split(':')[0]) || 23;
    const eh = Number(String(args.end || '7').split(':')[0]) || 7;
    g.nightLock = { start: sh, end: eh, on: true };
    await save();
    return `قفل شب ${sh}:00 تا ${eh}:00`;
  }
  if (tool === 'set_welcome' && args.text) {
    mod.welcome = { ...(mod.welcome || {}), on: true, text: String(args.text).slice(0, 1500) };
    await save();
    return 'خوش‌آمد ذخیره شد';
  }
  if (tool === 'set_rules' && args.text) {
    mod.rules = String(args.text).slice(0, 4000);
    await save();
    return 'قوانین ذخیره شد';
  }
  if (tool === 'delete_msg') {
    const mid = m.reply_to_message?.message_id;
    if (!mid) return 'ریپلای لازم است';
    const r = await tg(env, 'deleteMessage', { chat_id: chatId, message_id: mid });
    return r.ok ? 'پیام حذف شد' : ('حذف نشد: ' + (r.description || ''));
  }
  if (tool === 'lock' && args.type) {
    mod.locks = mod.locks || {};
    mod.locks[String(args.type)] = { on: true, mode: 'delete' };
    await save();
    return `قفل ${args.type} فعال`;
  }
  if (tool === 'unlock') {
    const typ = String(args.type || 'all');
    if (typ === 'all') mod.locks = {};
    else if (mod.locks) delete mod.locks[typ];
    await save();
    return `قفل ${typ} برداشته شد`;
  }

  const target = await resolvePlanTarget(env, m, args.target);
  if (!target && ['ban', 'unban', 'mute', 'unmute', 'kick', 'warn'].includes(tool)) return 'هدف مشخص نیست — ریپلای کن';

  if (tool === 'warn') {
    await addWarn(env, g, chatId, target, args.reason || 'اخطار');
    return `اخطار به ${target.name}`;
  }
  if (tool === 'kick') {
    await punish(env, chatId, target.id, 'kick');
    return `کیک ${target.name}`;
  }
  if (tool === 'ban') {
    await punish(env, chatId, target.id, 'ban', parseDurationSec(args.duration) || 0);
    return `بن ${target.name}`;
  }
  if (tool === 'unban') {
    await tg(env, 'unbanChatMember', { chat_id: chatId, user_id: target.id, only_if_is_banned: true });
    return `رفع بن ${target.name}`;
  }
  if (tool === 'mute') {
    const sec = parseDurationSec(args.duration) || 3600;
    await punish(env, chatId, target.id, 'mute', sec);
    return `سکوت ${target.name} (${args.duration || '1h'})`;
  }
  if (tool === 'unmute') {
    await unrestrict(env, chatId, target.id);
    return `رفع سکوت ${target.name}`;
  }
  return `ابزار ناشناخته: ${tool}`;
}


// ---- پاکسازی بر اساس کلمه ----
async function startPurgeWord(env, m, g, word, isOwner) {
  const chatId = m.chat.id;
  if (!(await senderIsAdmin(env, m, isOwner))) {
    await reply(env, m, 'فقط ادمین', true);
    return;
  }
  const w = String(word || '').trim().slice(0, 40);
  if (w.length < 2) {
    await reply(env, m, 'مثال: /purgeword تبلیغ', true);
    return;
  }
  const token = Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-3);
  await env.KV.put(`purge:${token}`, JSON.stringify({
    chatId, uid: m.from.id, word: w, exp: Date.now() + 5 * 60 * 1000,
  }), { expirationTtl: 600 });
  await tg(env, 'sendMessage', {
    chat_id: chatId,
    text: `🧹 پاکسازی «${w}»\nپیام‌های دارای این کلمه (از تاریخچهٔ دیده‌شده) حذف می‌شوند و ۱۰ دقیقه فیلتر موقت فعال می‌شود.\nتأیید؟`,
    reply_to_message_id: m.message_id,
    allow_sending_without_reply: true,
    reply_markup: {
      inline_keyboard: [[
        { text: '✅ پاک کن', callback_data: `pw:y:${token}` },
        { text: '✖️ لغو', callback_data: `pw:n:${token}` },
      ]],
    },
  });
}

async function purgeWordCallback(env, cq) {
  const parts = (cq.data || '').split(':');
  if (parts.length < 3) return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'نامعتبر' });
  const yes = parts[1] === 'y';
  const token = parts.slice(2).join(':');
  const payload = await env.KV.get(`purge:${token}`, 'json');
  if (!payload || Date.now() > payload.exp) {
    await env.KV.delete(`purge:${token}`);
    return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'منقضی', show_alert: true });
  }
  if (cq.from.id !== payload.uid) {
    return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'فقط درخواست‌دهنده', show_alert: true });
  }
  const chatId = cq.message?.chat?.id || payload.chatId;
  if (!yes) {
    await env.KV.delete(`purge:${token}`);
    if (cq.message) await tg(env, 'editMessageText', { chat_id: chatId, message_id: cq.message.message_id, text: '✖️ لغو شد.' });
    return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'لغو' });
  }
  const w = payload.word;
  await env.KV.put(`pwfilter:${chatId}`, JSON.stringify({ word: w, until: Date.now() + 10 * 60 * 1000 }), { expirationTtl: 700 });
  let deleted = 0;
  try {
    const log = await env.KV.get(`plog:${chatId}`, 'json');
    if (Array.isArray(log)) {
      const ids = log.filter((row) => row && row.mid && row.t && String(row.t).includes(w)).map((row) => row.mid);
      for (let i = 0; i < ids.length; i += 40) {
        const chunk = ids.slice(i, i + 40);
        const r = await tg(env, 'deleteMessages', { chat_id: chatId, message_ids: chunk });
        if (r.ok) deleted += chunk.length;
      }
    }
  } catch (e) { console.error('purge hist', e); }
  await env.KV.delete(`purge:${token}`);
  const text = `✅ فیلتر ۱۰ دقیقه‌ای «${w}» فعال شد` + (deleted ? `\n🗑 ${deleted} پیام حذف شد` : '');
  if (cq.message) await tg(env, 'editMessageText', { chat_id: chatId, message_id: cq.message.message_id, text });
  return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'انجام شد' });
}

async function purgeWordGate(env, m, text) {
  if (!text || !m.from || m.from.is_bot) return false;
  const f = await env.KV.get(`pwfilter:${m.chat.id}`, 'json');
  if (!f || !f.word || Date.now() > f.until) return false;
  if (String(text).includes(f.word)) {
    await tg(env, 'deleteMessage', { chat_id: m.chat.id, message_id: m.message_id }).catch(() => {});
    return true;
  }
  return false;
}

async function runAiPlanner(env, m, g, text, isOwner) {
  const chatId = m.chat.id;
  if (!(await senderIsAdmin(env, m, isOwner))) {
    await reply(env, m, 'این دستورها فقط برای ادمین است.', true);
    return true;
  }
  const msgs = [
    { role: 'system', content: withFaSkill(AI_PLAN_SYSTEM) },
    { role: 'user', content: `پیام ادمین: ${String(text).slice(0, 1500)}\n${m.reply_to_message?.from ? `ریپلای روی: ${m.reply_to_message.from.first_name} id=${m.reply_to_message.from.id}` : 'بدون ریپلای'}` },
  ];
  let res;
  try {
    res = await callLLM(env, msgs, null, g.model || (await getModel(env)), g.aicfg);
  } catch (e) {
    await reply(env, m, '⚠️ خطا: ' + String(e.message || e).slice(0, 120), true);
    return true;
  }
  if (res.error) {
    await reply(env, m, '⚠️ خطا در تحلیل: ' + res.error, true);
    return true;
  }
  const plan = extractPlanJson(res.message?.content || '');
  if (!plan) {
    await reply(env, m, String(res.message?.content || 'متوجه نشدم.').slice(0, 500), true);
    return true;
  }
  if (plan.clarify && !(Array.isArray(plan.actions) && plan.actions.length)) {
    await reply(env, m, String(plan.clarify).slice(0, 400), true);
    return true;
  }
  const actions = (Array.isArray(plan.actions) ? plan.actions : []).filter((a) => a && a.tool).slice(0, 5);
  if (!actions.length) {
    const r = String(plan.reply || '').trim();
    await reply(env, m, r ? r.slice(0, 1000) : 'دستوری برای اجرا پیدا نکردم.', true);
    return true;
  }
  const token = Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
  const payload = {
    chatId,
    uid: m.from.id,
    mid: m.message_id,
    actions,
    replyId: m.reply_to_message?.message_id || null,
    replyUser: m.reply_to_message?.from ? { id: m.reply_to_message.from.id, first_name: m.reply_to_message.from.first_name } : null,
    exp: Date.now() + 5 * 60 * 1000,
  };
  await env.KV.put(`aplan:${token}`, JSON.stringify(payload), { expirationTtl: 600 });
  const lines = ['<b>تأیید می‌کنی؟</b>'];
  if (plan.reply) lines.push(esc(String(plan.reply).slice(0, 200)));
  actions.forEach((a, i) => lines.push(`${i + 1}. ${esc(describePlanAction(a))}`));
  lines.push('روی ✅ بزن تا اجرا شود.');
  await tg(env, 'sendMessage', {
    chat_id: chatId,
    text: lines.join('\n'),
    parse_mode: 'HTML',
    reply_to_message_id: m.message_id,
    allow_sending_without_reply: true,
    reply_markup: {
      inline_keyboard: [[
        { text: '✅ بله، انجام بده', callback_data: `ap:y:${token}` },
        { text: '✖️ لغو', callback_data: `ap:n:${token}` },
      ]],
    },
  });
  return true;
}

async function aiPlanCallback(env, cq) {
  const parts = (cq.data || '').split(':');
  if (parts.length < 3) return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'نامعتبر' });
  const yes = parts[1] === 'y';
  const token = parts.slice(2).join(':');
  const payload = await env.KV.get(`aplan:${token}`, 'json');
  if (!payload || Date.now() > payload.exp) {
    await env.KV.delete(`aplan:${token}`);
    return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'منقضی شده', show_alert: true });
  }
  if (cq.from.id !== payload.uid) {
    return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'فقط درخواست‌دهنده', show_alert: true });
  }
  const chatId = cq.message?.chat?.id || payload.chatId;
  if (!yes) {
    await env.KV.delete(`aplan:${token}`);
    if (cq.message) await tg(env, 'editMessageText', { chat_id: chatId, message_id: cq.message.message_id, text: '✖️ لغو شد.' });
    return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'لغو شد' });
  }
  const g = await getGroup(env, chatId);
  if (!g) return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'گروه نیست', show_alert: true });
  const fakeM = {
    chat: { id: chatId },
    from: cq.from,
    message_id: payload.mid,
    reply_to_message: payload.replyUser ? { message_id: payload.replyId, from: payload.replyUser } : null,
  };
  const reports = [];
  for (const a of payload.actions || []) {
    try { reports.push(await executePlanAction(env, fakeM, g, a)); }
    catch (e) { reports.push('خطا: ' + String(e.message || e).slice(0, 80)); }
  }
  await env.KV.delete(`aplan:${token}`);
  const text = '✅ انجام شد:\n' + reports.map((r, i) => `${i + 1}. ${r}`).join('\n');
  if (cq.message) await tg(env, 'editMessageText', { chat_id: chatId, message_id: cq.message.message_id, text });
  return tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, text: 'اجرا شد' });
}


