const FOSH_MILD_C = [
  'تمام','نوبت بعدی','ادامه نده 😄','مسابقه تمومه','بریم بعدی','بازم بیا','کی بعدی؟','تموم شد رفت',
  'این فقط شروع بود','دست مریزاد','بدرود','آفرین',
];
const FOSH_NAM_A = [
  'استاد بزرگ لودگی','سلطان بی‌ادعا','قهرمان جهان در پرحرفی','رئیس هیئت چرت‌وپرت','پادشاه کامنت‌های بی‌ربط',
  'وزیر امور حاشیه','نایب‌قهرمان دری‌وری','مدیرکل شلوغ‌کاری','نخبه‌ی ضایع','ژنرال بحث‌های بی‌پایان',
];
const FOSH_NAM_B = [
  'این دفعه دست‌به‌عصا رفتی','جواب تندتر هم دارم ولی مهربونم','حال امروزت رو دوست داشتم','نیشت تیزه ولی بامزه‌ای',
  'یه لیوان آب خنک بنوش','اینجا رینگ مهربانیه','مدالت رو بعداً می‌دم','کل گروه دیدن، خجالت نداره','بیا دست بدیم و تمومش کنیم',
  'رعایت ادب جریمه نداره','فقط داشتم شوخی می‌کردم 😅','تا اینجا مساوی شدیم',
];
const FOSH_NAM_C = [
  'بیا دوستانه تمومش کنیم','دست مریزاد','تا دور بعد','فعلاً مساوی','حالا بریم سراغ جوک','این فقط گرم‌کردن بود',
  'قول بده آروم باشی','مهربونی هم هنره',
];
const FOSH_OPEN = [
  (n, a, b) => `${n} ${a}، ${b}`,
  (n, a, b) => `ای ${n} ${a} — ${b}`,
  (n, a, b) => `${a} ${n}، ${b}`,
  (n, a, b) => `ببین ${n} ${a}؛ ${b}`,
  (n, a, b) => `ها ${n}، ${a}، ${b}`,
  (n, a, b) => `${n} فکر کردی کی‌ای؟ ${a}. ${b}`,
  (n, a, b) => `سگ نگهبانم ${n}؛ ${a} — ${b}`,
  (n, a, b) => `با من در افتادی ${n}؟ ${a}، ${b}`,
  (n, a, b) => `${a} اومده جیک می‌زنه اسمش ${n}ه — ${b}`,
  (n, a, b) => `به به ${n} ${a}. ${b}`,
  (n, a, b) => `${n} ${b}، ${a}`,
  (n, a, b) => `حاجی ${n} ${a}؛ ${b}`,
];

function foshPick(arr) { return arr[(Math.random() * arr.length) | 0]; }
function foshShuffle(arr, n) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0; const t = a[i]; a[i] = a[j]; a[j] = t; }
  return a.slice(0, n);
}

// capacity estimate: opens×A×B×C  → thousands of unique lines, local only
const _clapRecent = [];
function _pushRecent(line) {
  _clapRecent.push(line);
  if (_clapRecent.length > 24) _clapRecent.shift();
  return line;
}

/** متلک عادی — بدون توکن AI */
function clapbackInsult(name) {
  const n = String(name || 'داداش').slice(0, 24);
  let line = '';
  for (let t = 0; t < 10; t++) {
    const open = foshPick(FOSH_OPEN);
    line = open(n, foshPick(FOSH_MILD_A), foshPick(FOSH_MILD_B));
    if (Math.random() < 0.55) line += ' — ' + foshPick(FOSH_MILD_C);
    if (!_clapRecent.includes(line)) break;
  }
  return _pushRecent(line);
}

/** متلک تندتر (بدون فحش) — بدون توکن AI */
function clapbackNamoos(name) {
  const n = String(name || 'داداش').slice(0, 24);
  let line = '';
  for (let t = 0; t < 10; t++) {
    const open = foshPick(FOSH_OPEN);
    line = open(n, foshPick(FOSH_NAM_A), foshPick(FOSH_NAM_B));
    if (Math.random() < 0.6) line += ' — ' + foshPick(FOSH_NAM_C);
    if (Math.random() < 0.35) line += '\n' + open(n, foshPick(FOSH_NAM_A), foshPick(FOSH_NAM_B));
    if (!_clapRecent.includes(line)) break;
  }
  return _pushRecent(line);
}

function foshBlock(name, hints) {
  const n = String(name || 'داداش').slice(0, 28);
  let hit = clapbackNamoos(n);
  if (hints && hints.length && Math.random() < 0.5) hit += '\n🎯 ' + hints[0];
  return hit;
}

