function dayIndex() {
  const d = new Date();
  const start = Date.UTC(d.getUTCFullYear(), 0, 0);
  return Math.floor((d.getTime() - start) / 86400000);
}

function jokeDaily() {
  const i = dayIndex() % JOKES_LIST.length;
  return `🤡 جوک امروز:\n${JOKES_LIST[i]}`;
}

function jokeRandom() {
  const i = Math.floor(Math.random() * JOKES_LIST.length);
  return `🤡 ${JOKES_LIST[i]}`;
}

function isJokeCmd(cmd) {
  return ['/joke', '/جوک'].includes(cmd);
}

