async function bumpFoshScore(env, chatId, userId, name) {
  try {
    const k = `foshsc:${chatId}`;
    const o = (await env.KV.get(k, 'json')) || {};
    const id = String(userId);
    if (!o[id]) o[id] = { n: 0, name: name || id };
    o[id].n += 1;
    o[id].name = name || o[id].name;
    await env.KV.put(k, JSON.stringify(o), { expirationTtl: 90 * 86400 });
  } catch {}
}

async function topFosh(env, chatId, limit = 10) {
  const o = (await env.KV.get(`foshsc:${chatId}`, 'json')) || {};
  return Object.entries(o)
    .map(([id, v]) => ({ id, name: v.name || id, n: v.n || 0 }))
    .sort((a, b) => b.n - a.n)
    .slice(0, limit);
}

async function setNick(env, chatId, userId, nick) {
  const k = `nick:${chatId}`;
  const o = (await env.KV.get(k, 'json')) || {};
  if (!nick) { delete o[String(userId)]; }
  else o[String(userId)] = String(nick).slice(0, 40);
  await env.KV.put(k, JSON.stringify(o), { expirationTtl: 180 * 86400 });
}

async function getNick(env, chatId, userId) {
  const o = (await env.KV.get(`nick:${chatId}`, 'json')) || {};
  return o[String(userId)] || null;
}

async function pickRandomMember(env, chatId) {
  // از ایندکس دیده‌شده‌ها
  try {
    const l = await env.KV.list({ prefix: `un:${chatId}:` });
    const keys = (l.keys || []).slice(0, 80);
    if (!keys.length) return null;
    const k = keys[Math.floor(Math.random() * keys.length)];
    const v = await env.KV.get(k.name, 'json');
    if (v?.id) return { id: v.id, first_name: v.n || 'عضو' };
  } catch {}
  return null;
}

async function startVoteKick(env, chatId, target, starter) {
  const code = `${chatId}:${target.id}:${Date.now()}`;
  const data = {
    chatId,
    tid: target.id,
    tname: target.first_name || 'هدف',
    sid: starter.id,
    yes: [starter.id],
    no: [],
    exp: Date.now() + 5 * 60 * 1000,
  };
  await env.KV.put(`vk:${code}`, JSON.stringify(data), { expirationTtl: 600 });
  return code;
}





// ======================= INSTAGRAM OG PREVIEW =======================
// Inline mode: type "@bot <instagram link>" in any chat.
// Group mode: auto-reply with the OGInstagram preview when an Instagram link is posted.
//   Toggle in group (owner): /ig on|off
// BotFather: /setinline must be enabled for inline mode to work.
const IG_FALLBACK_USERNAME = 'bot';

function findInstagramUrl(input) {
  const match = String(input || '').match(/https?:\/\/(?:www\.)?(?:instagram\.com|instagr\.am)\/[^\s<>"']+/i);
  return match ? match[0].replace(/[),.!?]+$/, '') : null;
}

function extractInstagramPostPath(rawUrl) {
  try {
    const url = new URL(rawUrl);
    const host = url.hostname.toLowerCase().replace(/^www\./, '');
    if (host !== 'instagram.com' && host !== 'instagr.am') return null;
    const parts = url.pathname.split('/').filter(Boolean);
    if (parts.length < 2) return null;
    const kind = parts[0].toLowerCase();
    if (!['reel', 'reels', 'p', 'tv'].includes(kind)) return null;
    const shortcode = parts[1];
    if (!/^[A-Za-z0-9_-]+$/.test(shortcode)) return null;
    return `${kind === 'reels' ? 'reel' : kind}/${shortcode}/`;
  } catch {
    return null;
  }
}

function igSenderName(from) {
  if (!from) return 'کاربر';
  const name = [from.first_name, from.last_name].filter(Boolean).join(' ').trim();
  if (from.username) return `${name || from.username} (@${from.username})`;
  return name || 'کاربر';
}

// the sent message: the post link as a real link, the sender line, and the "by @bot" line quoted
async function igMessageHtml(env, from, ogUrl, postPath) {
  const me = await botInfo(env);
  const label = /^reels?\//i.test(postPath || '') ? 'Instagram reels preview' : 'Instagram post preview';
  return `${esc(label)}\nارسال شده توسط "${esc(igSenderName(from))}"\n<blockquote><a href="${esc(ogUrl)}">${esc(ogUrl)}</a></blockquote>\n<blockquote>❤️‍🔥Powered by @${esc(me?.username || IG_FALLBACK_USERNAME)}</blockquote>`;
}
// the preview card is shown ABOVE the text
const igPreviewOpts = (ogUrl) => ({ url: ogUrl, show_above_text: true, prefer_large_media: true, is_disabled: false });

async function onInlineQuery(env, q) {
  const answer = (results, cache = 0) => tg(env, 'answerInlineQuery', { inline_query_id: q.id, results, cache_time: cache, is_personal: true });
  if (!q.from || !rateOk(`igq:${q.from.id}`, 30, 60000)) return answer([]);

  const input = (q.query || '').trim();
  const igUrl = findInstagramUrl(input);
  if (igUrl) {
    const postPath = extractInstagramPostPath(igUrl);
    if (!postPath) {
      return answer([{ type: 'article', id: 'invalid', title: 'لینک اینستاگرام معتبر نیست',
        input_message_content: { message_text: 'لطفاً لینک معتبر Reel یا Post اینستاگرام را ارسال کن.' } }]);
    }
    const ogUrl = `https://oginstagram.com/${postPath}`;
    const content = {
      message_text: await igMessageHtml(env, q.from, ogUrl, postPath),
      parse_mode: 'HTML',
      link_preview_options: igPreviewOpts(ogUrl),
    };
    return answer([
      { type: 'article', id: 'instant_view', title: 'Instant View', description: 'پیش‌نمایش OGInstagram', input_message_content: content },
      { type: 'article', id: 'media_caption', title: 'مدیا + کپشن', description: 'پیش‌نمایش OGInstagram', input_message_content: content },
    ]);
  }

  const inlineAsset = resolveAsset(input);
  if (inlineAsset) {
    if (!rateOk(`inpx:${q.from.id}`, 20, 60000)) return answer([]);
    try {
      const market = await getMarket(env, inlineAsset);
      if (!market.ok) return answer([{ type: 'article', id: `priceerr_${inlineAsset}`, title: 'قیمت الان در دسترس نیست', description: 'چند دقیقه‌ی دیگه دوباره امتحان کن', input_message_content: { message_text: 'الان نتونستم قیمت رو بگیرم 😕 چند دقیقه‌ی دیگه امتحان کن.' } }], 5);
      const d = market.data;
      let text = formatBlock(d) + (inlineAsset === 'GOLD' && d.extra ? `\n${d.extra}` : '');
      if (await aiAllowed(env, `u${q.from.id}`, LIMITS.privateUserPerDay, null).catch(() => false)) {
        const ai = await analyze(env, null, d).catch(() => '');
        if (ai) text += `\n\n🧠 ${ai}`;
      }
      return answer([{ type: 'article', id: `price_${inlineAsset}_${q.from.id}`, title: `💵 ${d.name}: ${oneLine(d).replace(/^\S+\s*/, '')}`, description: 'قیمت به‌روز، با تحلیل AI', input_message_content: { message_text: text.slice(0, 3900), link_preview_options: { is_disabled: true } } }], 0);
    } catch (e) { reportError(env, 'inline price', e); }
  }
  const aiMatch = input.match(/^(?:ai|هوش)\s+([\s\S]+)$/i);
  if (aiMatch) {
    const prompt = aiMatch[1].trim();
    if (!prompt || prompt.length > 700) return answer([{ type: 'article', id: 'inline_ai_help', title: 'متن AI رو کوتاه‌تر کن', description: 'حداکثر ۷۰۰ کاراکتر', input_message_content: { message_text: 'برای AI اینلاین بنویس: @ربات ai سوالت' } }]);
    if (prompt.length < 8 || !rateOk(`inai:${q.from.id}`, 3, 60000)) return answer([{ type: 'article', id: 'inline_ai_wait', title: '🤖 سوالت رو کامل‌تر کن', description: 'پاسخ بعد از کامل‌شدن عبارت آماده می‌شه', input_message_content: { message_text: 'برای AI اینلاین بنویس: @ربات ai سوالت' } }]);
    if (!await aiAllowed(env, `u${q.from.id}`, LIMITS.privateUserPerDay, null).catch(() => false)) return answer([{ type: 'article', id: 'inline_ai_limit', title: 'سهمیه‌ی امروز تموم شد', description: 'دعوت کن تا سهمیه‌ی بیشتری بگیری: /ref', input_message_content: { message_text: 'سهمیه‌ی AI امروزت تموم شده. برای لینک دعوت توی خصوصی /ref بزن.' } }]);
    const ai = await aiTask(env, null, 'به فارسی محاوره‌ای، کوتاه و دقیق جواب بده. اگر مطمئن نیستی واضح بگو.', prompt).catch((e) => { reportError(env, 'inline ai', e); return ''; });
    return answer([{ type: 'article', id: `ai_${q.from.id}_${Date.now()}`, title: '🤖 پاسخ AI', description: ai.slice(0, 180), input_message_content: { message_text: ai || 'الان جواب نگرفتم، دوباره امتحان کن.' } }], 0);
  }

  if (input.length < 2) {
    return answer([{
      type: 'article', id: 'help',
      title: '🎬 جستجوی فیلم / سریال',
      description: 'نام فیلم را بنویس — یا لینک اینستاگرام بفرست',
      input_message_content: {
        message_text: '🔎 اینلاین:\n• نام فیلم/سریال → نتایج فیلمیار\n• لینک اینستاگرام → پیش‌نمایش\n\nدستور چت: /film نام فیلم',
      },
    }]);
  }

  if (!(await fyEnsure(env))) {
    return answer([{ type: 'article', id: 'nodb', title: 'فیلمیار آماده نیست', description: 'FILM_DB یا TMDB تنظیم نشده',
      input_message_content: { message_text: '🎬 نیاز به binding «FILM_DB» و TMDB_API_KEY دارد.' } }]);
  }
  try {
    const list = await searchMovies(filmDb(env), input, env);
    if (!list.length) {
      return answer([{ type: 'article', id: 'empty', title: 'نتیجه‌ای پیدا نشد', description: input.slice(0, 40),
        input_message_content: { message_text: `🔎 برای «${input}» چیزی پیدا نشد.` } }], 30);
    }
    const bot = env.BOT_USERNAME || 'bot';
    const results = list.slice(0, 10).map((m, i) => {
      const id = String(m[0] || `r${i}`);
      const titleFa = m[3] || m[2] || id;
      const year = m[4] || '';
      const rating = m[5] || '';
      const kind = (m[1] === 'series' || m[1] === 'tv') ? '📺 سریال' : '🎬 فیلم';
      const desc = [kind, year, rating ? `⭐ ${rating}` : ''].filter(Boolean).join(' · ');
      const deep = `https://t.me/${bot}?start=${id}`;
      return {
        type: 'article',
        id: `${i}_${id}`.slice(0, 64),
        title: `${titleFa}${year ? ` (${year})` : ''}`,
        description: desc,
        input_message_content: {
          message_text: `${kind} <b>${esc(titleFa)}</b>${year ? ` (${esc(year)})` : ''}${rating ? `\n⭐ ${esc(rating)}` : ''}\n\n📥 جزئیات و دانلود:\n${deep}`,
          parse_mode: 'HTML',
          link_preview_options: { is_disabled: true },
        },
        reply_markup: { inline_keyboard: [[{ text: '📥 باز کردن در ربات', url: deep }]] },
      };
    });
    return answer(results, 120);
  } catch (e) {
    console.error('inline film', e);
    return answer([{ type: 'article', id: 'err', title: 'خطا در جستجو',
      input_message_content: { message_text: '⚠️ جستجوی فیلم موقتاً در دسترس نیست.' } }]);
  }
}

async function igGroupPreview(env, m) {
  const igUrl = findInstagramUrl(m.text || '');
  if (!igUrl) return false;
  const postPath = extractInstagramPostPath(igUrl);
  if (!postPath) return false;
  const ogUrl = `https://oginstagram.com/${postPath}`;
  const r = await tg(env, 'sendMessage', {
    chat_id: m.chat.id,
    reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true },
    text: await igMessageHtml(env, m.from, ogUrl, postPath),
    parse_mode: 'HTML',
    link_preview_options: igPreviewOpts(ogUrl),
    ...topicOf(m),
  });
  return r.ok;
}


// ======================= SHARED DM FEATURES (all users) =======================
async function userNotesList(env, uid) {
  const notes = (await env.KV.get(`notes:${uid}`, 'json')) || [];
  if (!notes.length) return 'یادداشتی نداری. با /savenote متن ذخیره کن.';
  return notes.map((n, i) => `${i + 1}. ${n.text}`).join('\n');
}
async function userNoteSave(env, uid, text) {
  const notes = (await env.KV.get(`notes:${uid}`, 'json')) || [];
  notes.push({ t: Date.now(), text: String(text || '').slice(0, 2000) });
  await env.KV.put(`notes:${uid}`, JSON.stringify(notes.slice(-100)));
  return '✅ یادداشت ذخیره شد.';
}
async function userNotesClear(env, uid) {
  await env.KV.delete(`notes:${uid}`);
  return '🗑 یادداشت‌ها پاک شد.';
}

/** دستورهای مشترک پیوی برای همه (به‌جز کارهای خطرناک فقط‌مالک) */
async function sharedDmCommands(env, m, text, cmd, say, isOwner) {
  const c = String(cmd || '').split('@')[0].toLowerCase();
  const arg = text.split(/\s+/).slice(1).join(' ').trim();
  const uid = m.from.id;

  if (c === '/reset') {
    await env.KV.delete(isOwner ? 'hist' : `ph:${uid}`);
    return say('🧹 مکالمه ریست شد.');
  }
  if (c === '/notes') return say(await userNotesList(env, uid));
  if (c === '/clearnotes') return say(await userNotesClear(env, uid));
  if (c === '/savenote' || c === '/note') {
    if (!arg) return say('مثال: /savenote متن یادداشت');
    return say(await userNoteSave(env, uid, arg));
  }
  if (c === '/usage') {
    if (!isOwner) return say('فقط مالک بات.');
    const v = await usageView(env);
    return tg(env, 'sendMessage', { chat_id: m.chat.id, text: v.text, parse_mode: 'HTML', link_preview_options: { is_disabled: true }, reply_markup: { inline_keyboard: v.kb } });
  }
  if (c === '/backup') {
    if (!isOwner) return say('فقط مالک بات.');
    return bkOpen(env, m);
  }
  if (c === '/ailimit') {
    if (!isOwner) return say('فقط مالک بات.');
    if (!arg) return say(`سهمیه‌ی روزانه‌ی AI برای هر نفر در گروه‌ها: ${(await userDailyLimit(env)) || 'نامحدود'}\nتغییر: /ailimit 10 — نامحدود: /ailimit 0\n(مالک، ادمین‌های گروه و گروه‌هایی که AI اختصاصی دارن معاف‌اند)`);
    const n = Number(String(arg).replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));
    if (!Number.isFinite(n) || n < 0 || n > 10000) return say('یه عدد بین ۰ تا ۱۰۰۰۰ بده؛ مثال: /ailimit 10');
    await env.KV.put('cfg:ailimit', String(Math.floor(n)));
    _ulMemo = { v: null, t: 0 };
    return say(n ? `✅ از الان هر نفر در گروه‌ها روزی ${Math.floor(n)} پیام AI داره.` : '✅ محدودیت روزانه‌ی هر نفر برداشته شد.');
  }
  if (c === '/models') {
    if (!isOwner) return say('انتخاب مدل فقط برای مالک بات هست.');
    if (!hasAiKey(env)) return say(NO_KEY_MSG);
    try {
      const v = await orModelView(env, 0, false);
      return tg(env, 'sendMessage', { chat_id: m.chat.id, text: v.text, reply_markup: { inline_keyboard: v.kb } });
    } catch (e) {
      return say('⚠️ گرفتن لیست مدل‌ها ناموفق بود: ' + String((e && e.message) || e).slice(0, 150));
    }
  }
  if (c === '/model') {
    if (!arg) return say(`مدل فعلی: ${await getModel(env)}`);
    if (!isOwner) return say('تغییر مدل کلی فقط برای مالکه. مدل خودت: /myai model نام');
    if (arg === 'reset') { await env.KV.delete('cfg:model'); _modelMemo = { v: '', t: 0 }; return say(`به پیش‌فرض برگشت: ${await getModel(env)}`); }
    if (!gwModelOk(arg)) return say('❌ اسم مدل باید به فرمت OpenRouter باشه (provider/model)، مثل: openrouter/free — یا /models بزن تا از لیست انتخاب کنی');
    await env.KV.put('cfg:model', arg); _modelMemo = { v: '', t: 0 };
    return say(`✅ مدل کلی: ${arg}`);
  }
  if (c === '/remind') {
    const d = parseDur(faDur(arg));
    if (!d.secs || !d.reason) return say('مثال: /remind 30m متن یادآوری');
    const at = Date.now() + d.secs * 1000;
    await addReminder(env, m.chat.id, at, d.reason);
    return say(`⏰ ${fmtTime(env, at)}\n${d.reason}`);
  }
  if (c === '/stream' || c === '/anim') {
    const key = `cfg:stream:${uid}`;
    const cur = (await env.KV.get(key, 'json')) || {};
    if (c === '/stream' && (arg === 'on' || arg === 'off')) cur.on = arg === 'on';
    else if (c === '/anim' && ['fast', 'natural', 'slow'].includes(arg)) cur.anim = arg;
    else return say(`استریم: ${cur.on === false ? 'خاموش' : 'روشن'} — ${cur.anim || 'natural'}\n/stream on|off · /anim fast|natural|slow`);
    await env.KV.put(key, JSON.stringify(cur));
    return say(`✅ استریم: ${cur.on === false ? 'خاموش' : 'روشن'} — ${cur.anim || 'natural'}`);
  }
  // natural language reminder for everyone
  if (!text.startsWith('/')) {
    const rm = parseReminderNL(env, text);
    if (rm) {
      const at = Date.now() + rm.secs * 1000;
      await addReminder(env, m.chat.id, at, rm.what);
      return say(`⏰ باشه! ${fmtTime(env, at)}\n${rm.what}`);
    }
  }
  return false;
}

async function userMedia(m, text, env, isOwner) {
  const say = (t) => reply(env, m, t, false);
  try {
    await tg(env, 'sendChatAction', { chat_id: m.chat.id, action: 'typing' });
    if (m.photo) {
      const ph = m.photo[m.photo.length - 1];
      const u8 = await tgFile(env, ph.file_id, 6e6);
      const content = [
        { type: 'text', text: text || 'این تصویر را توضیح بده.' },
        { type: 'image_url', image_url: { url: `data:image/jpeg;base64,${b64(u8)}` } },
      ];
      if (isOwner) return say(await runAgent(env, m.chat.id, `[تصویر] ${text || ''}`.trim(), content));
      // public: one-shot vision without tools
      const res = await callLLM(env, [
        { role: 'system', content: withFaSkill(PUBLIC_SYSTEM) },
        { role: 'user', content },
      ], null, await getModel(env));
      if (res.error) return say('❌ ' + res.error);
      return say(res.message?.content || 'نتونستم تصویر را بخونم.');
    }
    const v = m.voice || m.audio;
    if (v) {
      const t = await transcribe(env, await tgFile(env, v.file_id, 15e6));
      if (!t) return say('چیزی از ویس نفهمیدم 😕');
      await say(`🎙 «${t}»`);
      if (isOwner) return say(await runAgent(env, m.chat.id, t));
      // continue as normal text path by faking - handled by caller better; just AI reply:
      const key = `ph:${m.from.id}`;
      const hist = (await env.KV.get(key, 'json')) || [];
      const res = await callLLM(env, [{ role: 'system', content: withFaSkill(PUBLIC_SYSTEM) }, ...hist, { role: 'user', content: t }], null, await getModel(env));
      if (res.error) return say('❌ ' + res.error);
      const answer = (res.message?.content || '').trim();
      if (answer) await kvSoft(env, key, JSON.stringify([...hist, { role: 'user', content: t }, { role: 'assistant', content: answer }].slice(-10)), { expirationTtl: 86400 });
      return say(answer || 'پاسخ خالی.');
    }
  } catch (e) {
    return say(`⚠️ نشد: ${e.message}`);
  }
}

// ======================= OWNER PRIVATE =======================
async function ownerPrivate(m, text, env) {
  const say = (t) => reply(env, m, t, false);
  if (await fyTryCommand(env, m, text, env._ctx).catch(() => false)) return;
  const cmd = text.split(/\s+/)[0].split('@')[0];
  if (await sharedDmCommands(env, m, text, cmd, say, true)) return;
  if (isJokeCmd(String(cmd || '').split('@')[0].toLowerCase())) {
    const arg = text.split(/\s+/).slice(1).join(' ').trim().toLowerCase();
    return say((arg === 'random' || arg === 'رندوم' || arg === 'تصادفی') ? jokeRandom() : jokeDaily());
  }

  if (m.photo || m.voice || m.audio) return userMedia(m, text, env, true);
  if (m.reply_to_message && text && !text.startsWith('/')) {
    // replying to a Chat Automation draft = send your own text to the customer
    const did = await env.KV.get(`bdmsg:${m.reply_to_message.message_id}`);
    const d = did && (await env.KV.get(`bd:${did}`, 'json'));
    if (d) {
      const r = await sendBiz(env, d, text);
      if (r.ok) await env.KV.delete(`bd:${did}`);
      return say(r.ok ? `✅ برای ${d.name} ارسال شد.` : `⚠️ ارسال نشد: ${r.description}`);
    }
  }
  if (await ownerExtra(env, m, text, cmd, say)) return;

  if (cmd === '/start' || cmd === '/help') {
    return tg(env, 'sendMessage', { chat_id: m.chat.id, text: HELP_DM_PUBLIC + '\n\n👇 راهنما را از دکمه‌های زیر دسته‌بندی‌شده ببین:', reply_markup: HELP_MENU_KB });
  }
  if (cmd === '/model') {
    const arg = text.split(/\s+/).slice(1).join(' ').trim();
    if (!arg) return say(`مدل کلی: ${await getModel(env)}`);
    if (arg === 'reset') { await env.KV.delete('cfg:model'); _modelMemo = { v: '', t: 0 }; return say(`به مدل پیش‌فرض ورکر برگشت: ${await getModel(env)}`); }
    if (!gwModelOk(arg)) return say('❌ اسم مدل باید به فرمت OpenRouter باشه (provider/model)، مثل: openrouter/free — یا /models بزن تا از لیست انتخاب کنی');
    await env.KV.put('cfg:model', arg); _modelMemo = { v: '', t: 0 };
    return say(`✅ مدل کلی: ${arg}\n(گروه‌هایی که مدل مخصوص دارن همون رو نگه میدارن)`);
  }
  if (cmd === '/reset') { await env.KV.delete('hist'); return say('🧹 مکالمه ریست شد.'); }
  if (cmd === '/notes') return say(await toolListNotes(env));
  if (cmd === '/clearnotes') { await env.KV.delete('notes'); return say('🗑 یادداشت‌ها پاک شد.'); }
  if (cmd === '/autojoin') {
    const a = text.split(/\s+/)[1];
    if (a === 'on' || a === 'off') await env.KV.put('cfg:autojoin', a);
    return say(`ورود خودکار به گروه‌ها: ${(await env.KV.get('cfg:autojoin')) === 'off' ? 'خاموش' : 'روشن'}\n(/autojoin on|off)`);
  }
  if (cmd === '/leave') {
    const id = text.split(/\s+/)[1];
    if (!/^-?\d+$/.test(id || '')) return say('مثال: /leave -100123456  (آیدی از /groups)');
    const r = await tg(env, 'leaveChat', { chat_id: Number(id) });
    await env.KV.delete(`grp:${id}`);
    return say(r.ok ? '🚪 خارج شدم.' : `⚠️ ${r.description}`);
  }
  if (cmd === '/groups') {
    const list = await env.KV.list({ prefix: 'grp:' });
    if (!list.keys.length) return say('گروهی فعال نیست.');
    const rows = [];
    for (const k of list.keys) {
      const g = await env.KV.get(k.name, 'json');
      if (g) rows.push(`• ${g.title} [${k.name.slice(4)}] — ${g.enabled ? 'فعال' : 'غیرفعال'}، تیکه: ${g.roast ? 'روشن' : 'خاموش'} (${g.chance}%)`);
    }
    return say(rows.join('\n'));
  }
  if (cmd === '/reminders') {
    const list = await env.KV.list({ prefix: 'rem:' });
    if (!list.keys.length) return say('یادآوری در انتظار نیست.');
    const items = [];
    for (const k of list.keys) {
      const r = await env.KV.get(k.name, 'json');
      if (r) items.push(`• ${fmtTime(env, r.at)} — ${r.text}`);
    }
    return say(items.join('\n'));
  }

  const pa = cmd === '/price' ? resolveAsset(text.split(/\s+/).slice(1).join(' ')) : detectAsset(text);
  if (cmd === '/price' && !pa) return say(PRICE_HELP);
  if (pa) return handlePrice(env, m, pa, null, false, true);

  { const q = quickReply(text, m.from?.first_name || 'رئیس', env); if (q) return say(q); }
  tg(env, 'sendChatAction', { chat_id: m.chat.id, action: 'typing' }).catch(() => {});
  try {
    const out = await runAgent(env, m.chat.id, text);
    return say(out || '⚠️ پاسخ خالی از مدل آمد.');
  } catch (e) {
    console.error('owner AI', e);
    return say('⚠️ خطا در پاسخ AI: ' + String(e && e.message || e).slice(0, 180));
  }
}

async function runAgent(env, chatId, userText, userContent) {
  if (!hasAiKey(env)) return NO_KEY_MSG;
  const hist = (await env.KV.get('hist', 'json')) || [];
  const msgs = [{ role: 'system', content: withFaSkill(OWNER_SYSTEM, { group: true }) + (await x4AiExtra(env, { id: Number(env.OWNER_ID) }, userText, 'owner').catch(() => '')) }, ...slimHist(hist, 10, 1200), { role: 'user', content: userContent || userText }];
  const model = await getModel(env);
  if (!model) return '❌ مدل تنظیم نشده (متغیر MODEL یا /model نام).';

  let final = '';
  for (let i = 0; i < 6; i++) {
    const res = await callLLM(env, msgs, toolsFor(env), model);
    if (res.error) return `⚠️ خطا از AI Gateway: ${res.error}`;
    const msg = res.message;
    if (msg.tool_calls && msg.tool_calls.length) {
      msgs.push({ role: 'assistant', content: msg.content || '', tool_calls: msg.tool_calls });
      for (const tc of msg.tool_calls) {
        let args = {};
        try { args = JSON.parse(tc.function.arguments || '{}'); } catch {}
        let result;
        try { result = await runTool(env, chatId, tc.function.name, args); }
        catch (e) { result = `Tool error: ${e.message}`; }
        msgs.push({ role: 'tool', tool_call_id: tc.id, content: String(result).slice(0, 8000) });
      }
      continue;
    }
    final = msg.content || '';
    break;
  }
  if (!final) final = 'نتونستم به جواب نهایی برسم؛ دوباره امتحان کن.';
  const newHist = [...hist, { role: 'user', content: userText }, { role: 'assistant', content: final }].slice(-20);
  await kvSoft(env, 'hist', JSON.stringify(newHist));
  return final;
}

