const NQ_CATS = [...new Set(NQ.map(x => x[0]))];
function nqPick(category, avoid) {
  let a = NQ.filter(q => !category || category === 'تصادفی' || q[0] === category);
  if (!a.length) a = NQ;
  if (a.length > 1 && avoid) a = a.filter(q => q !== avoid);
  const q = a[Math.floor(Math.random() * a.length)];
  const opts = q[2].split('|');
  // Shuffle answers while retaining the correct one.
  const correct = opts[q[3]];
  for (let i = opts.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [opts[i], opts[j]] = [opts[j], opts[i]]; }
  return { c: q[0], q: q[1], o: opts, a: opts.indexOf(correct) };
}
const nqKey = (chat) => `ng:quiz:${chat}`;
const nativeRoomKey = (chat) => `ng:room:${chat}`;
async function nativeSay(env, chat, text, markup) {
  return tg(env, 'sendMessage', { chat_id: chat, text, ...(markup ? { reply_markup: markup } : {}) });
}
async function quizAsk(env, chat, round, previous) {
  if (!round || Date.now() >= round.end) return quizFinish(env, chat, round);
  const q = nqPick(round.cat, previous);
  round.q = q; round.qid = crypto.randomUUID().slice(0, 7); round.qend = Math.min(round.end, Date.now() + round.seconds * 1000);
  await env.KV.put(nqKey(chat), JSON.stringify(round), { expirationTtl: 86400 });
  const kb = q.o.map((x, i) => [{ text: `${String.fromCharCode(65 + i)}. ${x}`, callback_data: `ng:q:${chat}:${round.qid}:${i}` }]);
  await nativeSay(env, chat, `🧠 کوییز · ${q.c}\n⏱ ${round.seconds} ثانیه\n\n${q.q}`, { inline_keyboard: kb });
}
async function quizFinish(env, chat, round) {
  if (!round) return;
  await env.KV.delete(nqKey(chat));
  const scores = (await env.KV.get(`ng:qs:${chat}`, 'json')) || {};
  const top = Object.entries(scores).sort((a,b) => b[1].s-a[1].s).slice(0,10);
  const out = top.length ? top.map(([id,v],i) => `${i+1}. ${v.n || id} · ${v.s}`).join('\n') : 'هنوز امتیازی ثبت نشده.';
  await nativeSay(env, chat, `🏁 کوییز تموم شد!\nلیدربرد این گروه:\n${out}\n\nشروع دوباره: /quiz start`);
}
async function quizBoard(env, chat) {
  const scores = (await env.KV.get(`ng:qs:${chat}`, 'json')) || {};
  const top = Object.entries(scores).sort((a,b) => b[1].s-a[1].s).slice(0,10);
  return nativeSay(env, chat, `🏆 لیدربرد کوییز این گروه\n${top.length ? top.map(([id,v],i) => `${i+1}. ${v.n || id} · ${v.s}`).join('\n') : 'هنوز کسی امتیاز نگرفته.'}`);
}
