function nativeCard(c) { const suit=['♠️','♥️','♦️','♣️'][c.s], rank={11:'J',12:'Q',13:'K',14:'A'}[c.v]||String(c.v); return `${suit} ${rank}`; }
function pokerEval(hand) {
  const vals=hand.map(c=>c.v).sort((a,b)=>b-a), counts={};for(const v of vals)counts[v]=(counts[v]||0)+1;
  const groups=Object.entries(counts).map(([v,n])=>({v:Number(v),n})).sort((a,b)=>b.n-a.n||b.v-a.v);
  const flush=hand.every(c=>c.s===hand[0].s);const uniq=[...new Set(vals)].sort((a,b)=>a-b);let straight=uniq.length===5&&uniq[4]-uniq[0]===4?uniq[4]:0;if(uniq.join(',')==='2,3,4,5,14')straight=5;
  if(flush&&straight)return [8,straight];if(groups[0].n===4)return [7,groups[0].v,groups[1].v];if(groups[0].n===3&&groups[1].n===2)return [6,groups[0].v,groups[1].v];if(flush)return [5,...vals];if(straight)return [4,straight];if(groups[0].n===3)return [3,groups[0].v,...groups.slice(1).map(x=>x.v).sort((a,b)=>b-a)];if(groups[0].n===2&&groups[1].n===2)return [2,...groups.map(x=>x.v).sort((a,b)=>b-a),groups[2].v];if(groups[0].n===2)return [1,groups[0].v,...groups.slice(1).map(x=>x.v).sort((a,b)=>b-a)];return [0,...vals];
}
function pokerLabel(rank) {return ['کارت بالا','یک جفت','دو جفت','سه‌تایی','استریت','فلاش','فول‌هاوس','چهارتایی','استریت‌فلاش'][rank[0]]||'—';}
async function pokerPrompt(env,r,i) {
  const p=r.players[i],selected=new Set(r.drawn[p.id]||[]),hand=r.hands[i];
  const kb=hand.map((c,j)=>[{text:`${selected.has(j)?'✅ ':''}${nativeCard(c)}`,callback_data:`ng:p:${r.key}:d:${j}`}]);
  kb.push([{text:'♻️ تعویض کارت‌های انتخاب‌شده / پایان',callback_data:`ng:p:${r.key}:s`}]);
  return tg(env,'sendMessage',{chat_id:p.id,text:`🃏 دست تو: ${hand.map(nativeCard).join('  ')}\nتا ۳ کارت رو برای تعویض انتخاب کن، بعد دکمهٔ پایان رو بزن. انتخاب خالی یعنی بدون تعویض.`,reply_markup:{inline_keyboard:kb}});
}
async function pokerShowdown(env,r) {
  for(let i=0;i<r.players.length;i++){r.players[i].rank=pokerEval(r.hands[i]);r.players[i].hand=r.hands[i].map(nativeCard).join(' ');}
  const sorted=[...r.players].sort((a,b)=>{for(let i=0;i<Math.max(a.rank.length,b.rank.length);i++){const d=(b.rank[i]||0)-(a.rank[i]||0);if(d)return d;}return 0;});const winners=sorted.filter(x=>JSON.stringify(x.rank)===JSON.stringify(sorted[0].rank));r.done=true;r.phase='done';await env.KV.put(`ng:${r.key}`,JSON.stringify(r),{expirationTtl:86400});await env.KV.delete(nativeRoomKey(r.chat));
  await nativeSay(env,r.chat,`🏁 نتیجهٔ پوکر\n${sorted.map((x,i)=>`${i+1}. ${x.n}: ${pokerLabel(x.rank)} · ${x.hand}`).join('\n')}\n\n🏆 ${winners.map(x=>x.n).join('، ')} برنده${winners.length>1?'‌ها':''} شد${winners.length>1?'ند':''}!`);
}
function nativeHokmKb(r, i) {
  const hand=r.hands[i]||[]; let legal=hand;
  if(r.trick.length){const suit=r.trick[0].c.s;const has=hand.some(c=>c.s===suit);if(has)legal=hand.filter(c=>c.s===suit);}
  return legal.map(c=>[{text:nativeCard(c),callback_data:`ng:h:${r.key}:c:${c.s*20+c.v}`}]);
}
async function hokmPrompt(env,r) {
  const i=r.turn%4,p=r.players[i];
  const suit=['♠️','♥️','♦️','♣️'][r.trump];
  await nativeSay(env,r.chat,`🂡 نوبت ${p.n} · حکم ${suit} · دست ${r.round}/13\n${r.trick.map(x=>`${r.players[x.i].n}: ${nativeCard(x.c)}`).join(' | ')||'شروع دست'}`);
  await tg(env,'sendMessage',{chat_id:p.id,text:`نوبت توئه · حکم ${suit}. کارت مجاز رو بزن:`,reply_markup:{inline_keyboard:nativeHokmKb(r,i)}});
}
async function hokmPlay(env,r,cq,kind,value) {
  const uid=cq.from.id,ans=(t,a)=>tg(env,'answerCallbackQuery',{callback_query_id:cq.id,...(t?{text:t,show_alert:!!a}:{})});
  if(r.done)return ans('این بازی تموم شده.',true);
  if(kind==='t') {if(r.phase!=='trump'||r.players[0].id!==uid)return ans('فقط حاکم این دست حکم رو انتخاب می‌کنه.',true);r.trump=Number(value);r.phase='play';r.turn=0;await env.KV.put(`ng:${r.key}`,JSON.stringify(r),{expirationTtl:86400});await ans('حکم انتخاب شد');await hokmPrompt(env,r);return;}
  if(r.phase!=='play'||r.players[r.turn%4].id!==uid)return ans('هنوز نوبت تو نیست.',true);
  const ci=Number(value),card={s:Math.floor(ci/20),v:ci%20},hand=r.hands[r.turn%4],idx=hand.findIndex(c=>c.s===card.s&&c.v===card.v);
  if(idx<0)return ans('این کارت توی دستت نیست.',true);
  if(r.trick.length){const lead=r.trick[0].c.s;if(hand.some(c=>c.s===lead)&&card.s!==lead)return ans('اگه از خال شروع‌شده داری، باید همون خال رو بازی کنی.',true);}
  hand.splice(idx,1);r.trick.push({i:r.turn%4,c:card});r.turn++;
  if(r.trick.length<4){await env.KV.put(`ng:${r.key}`,JSON.stringify(r),{expirationTtl:86400});await ans();await hokmPrompt(env,r);return;}
  const lead=r.trick[0].c.s;const rank=x=>x.c.s===r.trump?100+x.c.v:x.c.s===lead?x.c.v:0;const win=r.trick.reduce((a,b)=>rank(b)>rank(a)?b:a);const team=win.i%2;r.tricks[team]++;r.trick=[];r.turn=win.i;r.round++;
  let line=`🏆 ${r.players[win.i].n} برندهٔ دست شد. تیم ${team?'دوم':'اول'}: ${r.tricks[team]} دست.`;
  if(r.round>13){const winner=r.tricks[0]>r.tricks[1]?0:1;r.scores[winner]++;line+=`\n🏁 دست تموم شد: ${r.tricks[0]} به ${r.tricks[1]} · امتیاز بازی: ${r.scores[0]}-${r.scores[1]}`;if(r.scores[winner]>=7){r.done=true;await env.KV.delete(nativeRoomKey(r.chat));line+=`\n🎉 تیم ${winner?'دوم':'اول'} بازی حکم رو برد! /hokm start برای بازی بعدی.`;}else{r.round=1;r.tricks=[0,0];r.hands=Array.from({length:4},()=>[]);const deck=[];for(let s=0;s<4;s++)for(let v=2;v<=14;v++)deck.push({s,v});for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}r.hands=r.players.map((_,i)=>deck.slice(i*13,(i+1)*13));r.phase='trump';}}
  await env.KV.put(`ng:${r.key}`,JSON.stringify(r),{expirationTtl:86400});await ans();await nativeSay(env,r.chat,line);
  if(!r.done){if(r.phase==='trump'){for(let i=0;i<4;i++){const p=r.players[i],hand=r.hands[i];await tg(env,'sendMessage',{chat_id:p.id,text:`🂡 دست جدید. ${i===0?'حاکم این دست تویی؛ حکم رو انتخاب کن.':'منتظر نوبت باش.'}\nدست تو: ${hand.map(nativeCard).join('  ')}`,...(i===0?{reply_markup:{inline_keyboard:[[{text:'♠️ پیک',callback_data:`ng:h:${r.key}:t:0`},{text:'♥️ دل',callback_data:`ng:h:${r.key}:t:1`}],[{text:'♦️ خشت',callback_data:`ng:h:${r.key}:t:2`},{text:'♣️ گشنیز',callback_data:`ng:h:${r.key}:t:3`}]]}}:{})});}}else await hokmPrompt(env,r);}
}
async function mafiaResolveDay(env,r) {
  const counts={};for(const ix of Object.values(r.votes))counts[ix]=(counts[ix]||0)+1;
  const sorted=Object.entries(counts).sort((a,b)=>b[1]-a[1]);
  if(sorted.length&&(!sorted[1]||Number(sorted[0][1])>Number(sorted[1][1]))){const target=r.players[Number(sorted[0][0])];if(target)target.alive=false;}
  const dead=r.players.filter(p=>!p.alive),alive=r.players.filter(p=>p.alive),mafia=alive.filter(p=>p.role==='mafia').length,town=alive.length-mafia;
  if(!mafia||mafia>=town){r.done=true;await env.KV.delete(nativeRoomKey(r.chat));await env.KV.put(`ng:${r.key}`,JSON.stringify(r));await nativeSay(env,r.chat,`⚖️ رأی‌گیری تموم شد. ${dead.length?`حذف‌شده: ${dead.slice(-1)[0].n} (${dead.slice(-1)[0].role==='mafia'?'مافیا':'شهروند'})`: 'رأی مساوی بود، کسی حذف نشد.'}\n${!mafia?'🏆 شهروندها بردن!':'🔫 مافیا برنده شد!'}`);return;}
  r.phase='night';r.votes={};r.night={};await env.KV.put(`ng:${r.key}`,JSON.stringify(r),{expirationTtl:86400});await nativeSay(env,r.chat,`⚖️ ${dead.length?`حذف‌شده: ${dead.slice(-1)[0].n} (${dead.slice(-1)[0].role==='mafia'?'مافیا':'شهروند'})`:'رأی مساوی بود، کسی حذف نشد.'}\n🌙 شب ${++r.round} شروع شد.`);
  const targets=r.players.map((p,i)=>p.alive&&p.role!=='mafia'?{p,i}:null).filter(Boolean);for(const p of alive.filter(x=>x.role==='mafia'))await tg(env,'sendMessage',{chat_id:p.id,text:'🌙 هدف شب رو انتخاب کن:',reply_markup:{inline_keyboard:targets.map(x=>[{text:`🎯 ${x.p.n}`,callback_data:`ng:m:${r.key}:n:${x.i}`}])}});
}
async function nativeGameCallback(env,cq) {
  const d=(cq.data||'').split(':'),ans=(t,a)=>tg(env,'answerCallbackQuery',{callback_query_id:cq.id,...(t?{text:t,show_alert:!!a}:{})});
  if(d[1]==='q') {const chat=Number(d[2]),round=await env.KV.get(nqKey(chat),'json');if(!round||round.qid!==d[3]||Date.now()>round.qend)return ans('زمان این سؤال تموم شده.',true);if(Number(d[4])!==round.q.a)return ans('نه، جواب درست نبود 🙂',false);const scores=(await env.KV.get(`ng:qs:${chat}`,'json'))||{},id=String(cq.from.id),old=scores[id]||{s:0,n:cq.from.first_name||'بازیکن'};old.s++;old.n=cq.from.first_name||old.n;scores[id]=old;await env.KV.put(`ng:qs:${chat}`,JSON.stringify(scores),{expirationTtl:180*86400});await env.KV.delete(nqKey(chat));await ans('✅ درست! +۱ امتیاز');await nativeSay(env,chat,`✅ ${cq.from.first_name||'بازیکن'} زودتر جواب درست رو داد: ${round.q.o[round.q.a]} · امتیاز +۱`);await quizAsk(env,chat,round,round.q);return;}
  const key=d[2],r=await env.KV.get(`ng:${key}`,'json');if(!r)return ans('این بازی منقضی شده.',true);
  if(d[1]==='p') {if(cq.message?.chat?.type!=='private')return ans('انتخاب کارت فقط در خصوصی انجام می‌شه.',true);const pi=r.players.findIndex(x=>x.id===cq.from.id);if(pi<0||r.done||r.phase!=='draw')return ans('تو توی این دست نیستی یا بازی تموم شده.',true);if(d[3]==='d'){if(r.drawn[cq.from.id]!==undefined)return ans('انتخابت ثبت شده.');const ix=Number(d[4]);if(ix<0||ix>4)return ans('کارت نامعتبره.',true);const a=r.drawn[cq.from.id]||[];const j=a.indexOf(ix);if(j>=0)a.splice(j,1);else if(a.length<3)a.push(ix);r.drawn[cq.from.id]=a;await env.KV.put(`ng:${key}`,JSON.stringify(r),{expirationTtl:86400});await ans('انتخاب به‌روز شد');await pokerPrompt(env,r,pi);return;}if(d[3]==='s'){if(r.drawn[cq.from.id]!==undefined)return ans('قبلاً تموم کردی.');const discard=r.drawn[cq.from.id]||[];const hand=r.hands[pi],deck=[];for(let ss=0;ss<4;ss++)for(let v=2;v<=14;v++)deck.push({s:ss,v});const used=new Set(r.hands.flat().map(c=>`${c.s}:${c.v}`));const rest=deck.filter(c=>!used.has(`${c.s}:${c.v}`));for(const ix of [...discard].sort((a,b)=>b-a)){let j=Math.floor(Math.random()*rest.length);hand[ix]=rest.splice(j,1)[0];}r.drawn[cq.from.id]=[];r.players[pi].ready=true;await env.KV.put(`ng:${key}`,JSON.stringify(r),{expirationTtl:86400});await ans('دست ثبت شد');await nativeSay(env,r.chat,`✅ ${r.players[pi].n} دستش رو ثبت کرد (${r.players.filter(x=>x.ready).length}/${r.players.length}).`);if(r.players.every(x=>x.ready))await pokerShowdown(env,r);return;}}
  if(d[1]==='h') {if(cq.message?.chat?.type!=='private')return ans('کارت‌ها فقط از پیام خصوصی بازی می‌شن.',true);return hokmPlay(env,r,cq,d[3],d[4]);}
  if(d[1]==='m') {const idx=Number(d[4]),p=r.players.find(x=>x.id===cq.from.id);if(!p||!p.alive)return ans('تو بازیکن زندهٔ این بازی نیستی.',true);
    if(d[3]==='n'){if(r.phase!=='night'||p.role!=='mafia'||!r.players[idx]?.alive||r.players[idx]?.role==='mafia')return ans('انتخاب معتبر نیست.',true);r.night[cq.from.id]=idx;await env.KV.put(`ng:${key}`,JSON.stringify(r),{expirationTtl:86400});const maf=r.players.filter(x=>x.alive&&x.role==='mafia');await ans('رأی شب ثبت شد.');if(maf.every(x=>r.night[x.id]!==undefined)){const c={};Object.values(r.night).forEach(v=>c[v]=(c[v]||0)+1);const sorted=Object.entries(c).sort((a,b)=>b[1]-a[1]);if(sorted.length&&(!sorted[1]||sorted[0][1]>sorted[1][1]))r.players[Number(sorted[0][0])].alive=false;r.phase='day';r.votes={};const dead=r.players.filter(x=>!x.alive);const alive=r.players.filter(x=>x.alive),mc=alive.filter(x=>x.role==='mafia').length,tc=alive.length-mc;if(!mc||mc>=tc){r.done=true;await env.KV.delete(nativeRoomKey(r.chat));await nativeSay(env,r.chat,`☀️ صبح شد. ${dead.length?`حذف‌شده: ${dead[dead.length-1].n} (${dead[dead.length-1].role==='mafia'?'مافیا':'شهروند'})`: 'کسی حذف نشد.'}\n${!mc?'🏆 شهروندها بردن!':'🔫 مافیا برنده شد!'}`);}else{await nativeSay(env,r.chat,`☀️ صبح شد. ${dead.length?`شب‌زده: ${dead[dead.length-1].n}`:'شب آرومی بود.'}\nروز ${r.round}: به یکی از مظنون‌ها رأی بدین.`);const kb=alive.map((x,i)=>[{text:`🗳 ${x.n}`,callback_data:`ng:m:${key}:d:${i}`}]);await nativeSay(env,r.chat,'رأی‌گیری روز:',{inline_keyboard:kb});}await env.KV.put(`ng:${key}`,JSON.stringify(r),{expirationTtl:86400});}return;}
    if(d[3]==='d'){if(r.phase!=='day'||!p.alive||!r.players[idx]?.alive||idx===r.players.findIndex(x=>x.id===cq.from.id))return ans('رأی معتبر نیست.',true);r.votes[cq.from.id]=idx;await env.KV.put(`ng:${key}`,JSON.stringify(r),{expirationTtl:86400});await ans('رأی ثبت شد.');if(r.players.filter(x=>x.alive).every(x=>r.votes[x.id]!==undefined))await mafiaResolveDay(env,r);return;}
  }
  return ans();
}
async function nativeGamesCron(env) {
  const list=await env.KV.list({prefix:'ng:quiz:'});const now=Date.now();
  for(const k of list.keys){const chat=Number(k.name.slice('ng:quiz:'.length));const r=await env.KV.get(k.name,'json');if(!r)continue;if(now>=r.end){await quizFinish(env,chat,r);continue;}if(r.qend&&now>=r.qend){await env.KV.delete(k.name);await nativeSay(env,chat,`⏱ وقت تموم شد! جواب: ${r.q.o[r.q.a]}`);await quizAsk(env,chat,r,r.q);}}
}

// ======================= LOCAL TIME =======================
function localParts(env, ts = Date.now()) {
  const tz = env.TIMEZONE || 'Asia/Tehran';
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(new Date(ts));
  const p = Object.fromEntries(parts.map((x) => [x.type, x.value]));
  const h = Number(p.hour) % 24;
  const mi = Number(p.minute);
  return { h, m: mi, hf: h + mi / 60, date: `${p.year}-${p.month}-${p.day}` };
}
const inWindow = (hf, start, end) => (start <= end ? hf >= start && hf < end : hf >= start || hf < end);

// ======================= PRICES (Toman) + ANALYSIS =======================
// Iranian assets (dollar, euro, gold, coin) come from TGJU (reachable from Cloudflare);
// crypto comes from free exchange APIs (no key) and is converted with the TGJU dollar.
const ASSETS = {
  USD: { fa: 'دلار آزاد', names: ['دلار', 'دلار آزاد', 'دلار آمریکا', 'تتر', 'usd', 'usdt', 'dollar', 'tether'], tg: 'usd' },
  EUR: { fa: 'یورو', names: ['یورو', 'eur', 'euro'], tg: 'eur' },
  GOLD: { fa: 'طلای ۱۸ عیار (هر گرم)', names: ['طلا', 'طلای 18', 'طلا 18', 'gold'], tg: 'gold18' },
  MESGHAL: { fa: 'مثقال طلا', names: ['مثقال', 'مثقال طلا'], tg: 'mesghal' },
  COIN: { fa: 'سکه امامی', names: ['سکه', 'سکه امامی'], tg: 'coin' },
  OUNCE: { fa: 'اونس جهانی طلا', names: ['اونس', 'انس', 'اونس طلا', 'انس طلا', 'ons', 'xau'], tg: 'ounce' },
  TRX: { fa: 'ترون', names: ['ترون', 'trx', 'tron'], cg: 'tron' },
  BTC: { fa: 'بیت‌کوین', names: ['بیت کوین', 'بیتکوین', 'btc', 'bitcoin'], cg: 'bitcoin' },
  ETH: { fa: 'اتریوم', names: ['اتریوم', 'eth', 'ethereum'], cg: 'ethereum' },
  TON: { fa: 'تون‌کوین', names: ['تون کوین', 'تونکوین', 'ton', 'toncoin'], cg: 'the-open-network' },
  SOL: { fa: 'سولانا', names: ['سولانا', 'sol', 'solana'], cg: 'solana' },
  XRP: { fa: 'ریپل', names: ['ریپل', 'xrp', 'ripple'], cg: 'ripple' },
  DOGE: { fa: 'دوج‌کوین', names: ['دوج', 'دوج کوین', 'دوجکوین', 'doge', 'dogecoin'], cg: 'dogecoin' },
  BNB: { fa: 'بایننس‌کوین', names: ['بی ان بی', 'bnb'], cg: 'binancecoin' },
  ADA: { fa: 'کاردانو', names: ['کاردانو', 'ada', 'cardano'], cg: 'cardano' },
  LTC: { fa: 'لایت‌کوین', names: ['لایت کوین', 'لایتکوین', 'ltc', 'litecoin'], cg: 'litecoin' },
  SHIB: { fa: 'شیبا', names: ['شیبا', 'shib'], cg: 'shiba-inu' },
};
const EMOJI = { USD: '💵', EUR: '💶', GOLD: '🥇', MESGHAL: '🥇', COIN: '🥇', OUNCE: '🥇' };
const PRICE_HELP = 'مثال: /price دلار | یورو | طلا | سکه | ترون | بیت‌کوین | اتریوم | تون | سولانا | ریپل | دوج\nیا هر تیکر انگلیسی مثل /price PEPE — یا فقط اسمش رو بنویس.';

const pk = (s) =>
  norm(String(s || '').replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/\u200c/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
const ALIAS = Object.create(null);
for (const [key, a] of Object.entries(ASSETS)) {
  ALIAS[key.toLowerCase()] = key;
  for (const n of a.names) ALIAS[pk(n)] = key;
}
const FILLER = new Set(['قیمت', 'چنده', 'چقدره', 'چقد', 'الان', 'الآن', 'چند', 'شد', 'شده', 'price', 'بگو', 'بده', 'امروز', 'لحظه ای', 'تحلیل', 'رو', 'را']);

function resolveAsset(arg) {
  const t = pk((arg || '').replace(/[?؟!.,،:$]/g, ' '));
  if (!t) return null;
  if (ALIAS[t]) return ALIAS[t];
  const j = t.split(' ').filter((x) => x && !FILLER.has(x)).join(' ');
  if (ALIAS[j]) return ALIAS[j];
  if (/^[a-z0-9]{2,10}$/i.test(t)) return t.toUpperCase(); // arbitrary ticker via Binance
  return null;
}

// fires only when the whole message is basically just an asset name (+ filler words)
function detectAsset(text) {
  if (!text || text.length > 40 || text.startsWith('/')) return null;
  const t = pk(text.replace(/[?؟!.,،:]/g, ' '));
  const w = t.split(' ').filter((x) => x && !FILLER.has(x));
  if (!w.length || w.length > 2) return null;
  return ALIAS[w.join(' ')] || (w.length === 1 ? ALIAS[w[0]] : null) || null;
}

async function jfetch(url, opts = {}, ms = 6000) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), ms);
  try {
    const r = await fetch(url, { ...opts, signal: ctrl.signal, headers: { 'user-agent': 'Mozilla/5.0 (compatible; PriceBot/1.0)', ...(opts.headers || {}) } });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return await r.json();
  } finally {
    clearTimeout(timer);
  }
}

// ---- TGJU scraping (values on the page are in Rial; we convert to Toman) ----
const TG_PATTERNS = {
  usd: /(?:^|\s)دلار\s+([\d,]{6,})/,
  eur: /یورو\s+([\d,]{6,})/,
  gold18: /طلا\s*18\s+([\d,]{6,})/,
  mesghal: /مثقال\s*طلا\s+([\d,]{6,})/,
  coin: /(?:^|\s)سکه\s+([\d,]{8,})/,
};
function parseTgju(html) {
  const text = pk(html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' '));
  const num = (s) => Number(String(s).replace(/,/g, ''));
  const out = {};
  for (const [k, re] of Object.entries(TG_PATTERNS)) {
    const mt = text.match(re);
    if (mt) out[k] = num(mt[1]) / 10;
  }
  const o = text.match(/انس\s*طلا\s+([\d,]+(?:\.\d+)?)/);
  if (o) out.ounce = num(o[1]);
  const dc = html.match(/data-col="info\.last_trade\.PDrCotVal"[^>]*>\s*([\d,]+)/);
  if (dc) out.usd = num(dc[1]) / 10; // most precise source for the dollar when present
  return out;
}

async function pushHist(env, t, force) {
  try {
    const h = (await env.KV.get('fxh', 'json')) || [];
    const last = h[h.length - 1];
    if (!force && last && t.ts - last.t < 10 * 60000) return;
    h.push({ t: t.ts, usd: t.usd, eur: t.eur, gold18: t.gold18, coin: t.coin, mesghal: t.mesghal, ounce: t.ounce });
    await env.KV.put('fxh', JSON.stringify(h.slice(-1008)), { expirationTtl: 8 * 86400 });
  } catch (e) { /* ignore */ }
}

// 24h change/high/low computed from the bot's own price history (source-independent)
function histStat(h, field, now = Date.now()) {
  const pts = (h || []).filter((p) => p[field] > 0 && now - p.t <= 24 * 3600 * 1000);
  if (pts.length < 3) return {};
  const vals = pts.map((p) => p[field]);
  const cur = vals[vals.length - 1];
  const out = { high: Math.max(...vals), low: Math.min(...vals) };
  if (now - pts[0].t >= 18 * 3600 * 1000) out.change = ((cur - vals[0]) / vals[0]) * 100;
  return out;
}

async function getTgju(env, errs) {
  const cached = await env.KV.get('tg:cur', 'json');
  if (cached && Date.now() - cached.ts < 60000) return cached;
  let t = null;
  if (env.PRICE_RELAY) {
    try {
      const j = await jfetch(env.PRICE_RELAY);
      if (j.usd > 1000) t = { ...j, src: 'Relay' };
    } catch (e) { errs.push(`relay: ${e.message}`); }
  }
  if (!t) {
    try {
      const r = await fetch('https://www.tgju.org/profile/price_dollar_rl', {
        headers: { 'user-agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124 Safari/537.36', 'accept-language': 'fa,en;q=0.8' },
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const p = parseTgju(await r.text());
      if (p.usd > 10000 && p.usd < 5e6) t = { ...p, src: 'TGJU' };
      else errs.push(`tgju: dollar not found in page (${JSON.stringify(p)})`);
    } catch (e) { errs.push(`tgju: ${e.message}`); }
  }
  if (t) {
    t.ts = Date.now();
    await env.KV.put('tg:cur', JSON.stringify(t), { expirationTtl: 86400 }).catch(() => {});
    await pushHist(env, t);
    return t;
  }
  if (cached && Date.now() - cached.ts < 6 * 3600 * 1000) return { ...cached, stale: true };
  const man = await env.KV.get('fx:manual', 'json');
  if (man && Date.now() - man.ts < 24 * 3600 * 1000) return { usd: man.usd, src: 'نرخ دستی', ts: man.ts, stale: true };
  return null;
}

// ---- crypto price providers: every one is free and needs no API key; a provider that fails (geo-block, rate-limit) is skipped for 2 minutes ----
const num = (v) => (v === undefined || v === null || v === '' ? NaN : Number(v));
const parseBinance = (t) => (t && num(t.lastPrice) > 0 ? { price: num(t.lastPrice), change: num(t.priceChangePercent), high: num(t.highPrice), low: num(t.lowPrice), vol: num(t.quoteVolume) } : null);
const parseOkx = (d) => { const last = num(d?.last); const open = num(d?.open24h); return last > 0 ? { price: last, change: open > 0 ? ((last - open) / open) * 100 : NaN, high: num(d.high24h), low: num(d.low24h), vol: num(d.volCcy24h) } : null; };
const parseKucoin = (d) => (d && num(d.last) > 0 ? { price: num(d.last), change: num(d.changeRate) * 100, high: num(d.high), low: num(d.low), vol: num(d.volValue) } : null);
const parseGate = (d) => (d && num(d.last) > 0 ? { price: num(d.last), change: num(d.change_percentage), high: num(d.high_24h), low: num(d.low_24h), vol: num(d.quote_volume) } : null);
const parseBybit = (d) => (d && num(d.lastPrice) > 0 ? { price: num(d.lastPrice), change: num(d.price24hPcnt) * 100, high: num(d.highPrice24h), low: num(d.lowPrice24h), vol: num(d.turnover24h) } : null);
const parseCC = (r) => (r && num(r.PRICE) > 0 ? { price: num(r.PRICE), change: num(r.CHANGEPCT24HOUR), high: num(r.HIGH24HOUR), low: num(r.LOW24HOUR), vol: num(r.VOLUME24HOURTO) } : null);

const parseCG = (v) => (v && num(v.current_price) > 0 ? { price: num(v.current_price), change: num(v.price_change_percentage_24h), high: num(v.high_24h), low: num(v.low_24h), vol: num(v.total_volume) } : null);
const CG_PROVIDER = { name: 'CoinGecko', src: 'CoinGecko', known: true, url: (k) => `https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&ids=${ASSETS[k].cg}`, parse: (j) => parseCG(Array.isArray(j) ? j[0] : null) };
const CRYPTO_PROVIDERS = [
  { name: 'Binance-vision', src: 'Binance', week: true, url: (k) => `https://data-api.binance.vision/api/v3/ticker/24hr?symbol=${k}USDT`, parse: (j) => parseBinance(j) },
  { name: 'OKX', src: 'OKX', url: (k) => `https://www.okx.com/api/v5/market/ticker?instId=${k}-USDT`, parse: (j) => parseOkx(j.data?.[0]) },
  { name: 'KuCoin', src: 'KuCoin', url: (k) => `https://api.kucoin.com/api/v1/market/stats?symbol=${k}-USDT`, parse: (j) => parseKucoin(j.data) },
  { name: 'Gate', src: 'Gate.io', url: (k) => `https://api.gateio.ws/api/v4/spot/tickers?currency_pair=${k}_USDT`, parse: (j) => parseGate(Array.isArray(j) ? j[0] : null) },
  { name: 'CryptoCompare', src: 'CryptoCompare', url: (k) => `https://min-api.cryptocompare.com/data/pricemultifull?fsyms=${k}&tsyms=USD`, parse: (j, k) => parseCC(j.RAW?.[k]?.USD) },
  { name: 'Bybit', src: 'Bybit', url: (k) => `https://api.bybit.com/v5/market/tickers?category=spot&symbol=${k}USDT`, parse: (j) => parseBybit(j.result?.list?.[0]) },
  { name: 'Binance', src: 'Binance', week: true, url: (k) => `https://api.binance.com/api/v3/ticker/24hr?symbol=${k}USDT`, parse: (j) => parseBinance(j) },
];
const provDown = new Map();

const cgHeaders = (env) => (env?.COINGECKO_API_KEY ? { 'x-cg-demo-api-key': env.COINGECKO_API_KEY } : {});
const providersFor = (env) => (env?.COINGECKO_API_KEY ? [CG_PROVIDER, ...CRYPTO_PROVIDERS] : [...CRYPTO_PROVIDERS, CG_PROVIDER]);

async function getCrypto(key, errs, env) {
  const a = ASSETS[key];
  if (!/^[A-Z0-9]{2,10}$/.test(key)) return null;
  for (const p of providersFor(env)) {
    if (p.known && !a?.cg) continue;
    if ((provDown.get(p.name) || 0) > Date.now()) { errs.push(`${p.name}: skipped (failed recently)`); continue; }
    try {
      const j = await jfetch(p.url(key), p.name === 'CoinGecko' ? { headers: cgHeaders(env) } : {}, 4500);
      const r = p.parse(j, key);
      if (!r) { errs.push(`${p.name}: no data for ${key}`); continue; } // the provider is fine, it just does not list this ticker
      if (p.week) {
        try {
          const kl = await jfetch(`https://data-api.binance.vision/api/v3/klines?symbol=${key}USDT&interval=1d&limit=8`, {}, 4000);
          const c = kl.map((x) => Number(x[4]));
          if (c.length >= 2) r.week = ((c[c.length - 1] - c[0]) / c[0]) * 100;
        } catch { /* optional */ }
      }
      return { ...r, src: p.src };
    } catch (e) {
      if (/HTTP (400|404)\b/.test(e.message)) { errs.push(`${p.name}: no data for ${key}`); continue; } // unknown ticker on this exchange; the provider itself is fine
      provDown.set(p.name, Date.now() + 120000);
      errs.push(`${p.name}: ${e.message}`);
    }
  }
  return null;
}

// one request for many coins (used by the list command so 8 coins do not mean 8+ subrequests)
const CG_BATCH = { name: 'CoinGecko', src: 'CoinGecko', get: async (keys, env) => { const ids = keys.map((k) => ASSETS[k]?.cg).filter(Boolean); const j = await jfetch(`https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&ids=${ids.join(',')}`, { headers: cgHeaders(env) }, 6000); const byId = Object.fromEntries((Array.isArray(j) ? j : []).map((v) => [v.id, v])); return Object.fromEntries(keys.map((k) => [k, parseCG(byId[ASSETS[k]?.cg])])); } };
const BATCH_PROVIDERS = [
  { name: 'Binance-vision', src: 'Binance', get: async (keys) => { const j = await jfetch(`https://data-api.binance.vision/api/v3/ticker/24hr?symbols=${encodeURIComponent(JSON.stringify(keys.map((k) => `${k}USDT`)))}`, {}, 5000); return Object.fromEntries((Array.isArray(j) ? j : []).map((t) => [String(t.symbol).replace(/USDT$/, ''), parseBinance(t)])); } },
  { name: 'OKX', src: 'OKX', get: async (keys) => { const j = await jfetch('https://www.okx.com/api/v5/market/tickers?instType=SPOT', {}, 6000); const want = new Set(keys.map((k) => `${k}-USDT`)); return Object.fromEntries((j.data || []).filter((d) => want.has(d.instId)).map((d) => [d.instId.replace('-USDT', ''), parseOkx(d)])); } },
  { name: 'KuCoin', src: 'KuCoin', get: async (keys) => { const j = await jfetch('https://api.kucoin.com/api/v1/market/allTickers', {}, 6000); const want = new Set(keys.map((k) => `${k}-USDT`)); return Object.fromEntries((j.data?.ticker || []).filter((d) => want.has(d.symbol)).map((d) => [d.symbol.replace('-USDT', ''), parseKucoin(d)])); } },
  { name: 'Gate', src: 'Gate.io', get: async (keys) => { const j = await jfetch('https://api.gateio.ws/api/v4/spot/tickers', {}, 6000); const want = new Set(keys.map((k) => `${k}_USDT`)); return Object.fromEntries((Array.isArray(j) ? j : []).filter((d) => want.has(d.currency_pair)).map((d) => [d.currency_pair.replace('_USDT', ''), parseGate(d)])); } },
];
async function fetchBatch(keys, errs, env) {
  for (const p of (env?.COINGECKO_API_KEY ? [CG_BATCH, ...BATCH_PROVIDERS] : [...BATCH_PROVIDERS, CG_BATCH])) {
    if ((provDown.get(p.name) || 0) > Date.now()) { errs.push(`${p.name}: skipped (failed recently)`); continue; }
    try {
      const r = await p.get(keys, env);
      const got = Object.entries(r).filter(([, v]) => v);
      if (got.length >= Math.ceil(keys.length / 2)) return { data: Object.fromEntries(got), src: p.src };
      errs.push(`${p.name}: only ${got.length}/${keys.length} coins`);
    } catch (e) { provDown.set(p.name, Date.now() + 120000); errs.push(`${p.name}: ${e.message}`); }
  }
  return null;
}
const cryptoData = (key, c, tgd) => ({ kind: 'crypto', key, name: ASSETS[key]?.fa || key, usd: c.price, toman: tgd?.usd ? c.price * tgd.usd : null, changePct: c.change, week: c.week, high: c.high, low: c.low, vol: c.vol, src: `${c.src}${tgd?.usd ? ` + ${tgd.src}` : ''}`, usdToman: tgd?.usd || null });

async function getTether(env) {
  const t = await env.KV.get('fx:tether', 'json');
  return t && Date.now() - t.ts < 6 * 3600 * 1000 ? t : null;
}

async function getMarket(env, key) {
  const cached = await env.KV.get(`px:${key}`, 'json');
  if (cached) return { ok: true, data: cached };
  const errs = [];
  const a = ASSETS[key];
  const tgd = await getTgju(env, errs);
  let data;
  if (key === 'USD') {
    const th = await getTether(env);
    if (th) {
      const v = th.toman + 1000;
      const st = histStat(await env.KV.get('fxh', 'json'), 'usd');
      data = { kind: 'tgju', key, name: 'دلار (قیمت تتر + ۱۰۰۰ تومان)', toman: v, usd: null, changePct: st.change, high: st.high, low: st.low, src: `تتر ${fmtT(th.toman)} تومان (دستی، ${ageText(th.ts)})`, ts: th.ts };
      await env.KV.put(`px:${key}`, JSON.stringify(data), { expirationTtl: 60 }).catch(() => {});
      return { ok: true, data };
    }
  }
  if (a?.tg) {
    const v = tgd?.[a.tg];
    if (!(v > 0)) return { ok: false, errs };
    const st = histStat(await env.KV.get('fxh', 'json'), a.tg);
    const usdUnit = a.tg === 'ounce';
    data = { kind: 'tgju', key, name: a.fa, toman: usdUnit ? null : v, usd: usdUnit ? v : null, changePct: st.change, high: st.high, low: st.low, src: `${tgd.src}${tgd.stale ? ' (قدیمی)' : ''}`, ts: tgd.ts };
  } else {
    const c = await getCrypto(key, errs, env);
    if (!c) return { ok: false, errs, notFound: !a && !errs.some((e) => /(HTTP|abort|timeout|fetch|skipped)/i.test(e)) };
    data = cryptoData(key, c, tgd);
  }
  await env.KV.put(`px:${key}`, JSON.stringify(data), { expirationTtl: 60 }).catch(() => {});
  return { ok: true, data };
}

const fin = Number.isFinite;
const pct = (v) => `${v > 0 ? '+' : ''}${v.toFixed(2)}% ${v > 0 ? '▲' : v < 0 ? '▼' : '▬'}`;
function fmtT(v) { if (!fin(v)) return '—'; return v >= 100 ? Math.round(v).toLocaleString('en-US') : v.toFixed(2); }
function fmtUsd(v) {
  if (!fin(v)) return '—';
  if (v >= 1) return v.toLocaleString('en-US', { maximumFractionDigits: 2 });
  if (v >= 0.01) return v.toFixed(4);
  return v.toFixed(8).replace(/0+$/, '');
}
function ageText(ts) {
  const mins = Math.round((Date.now() - ts) / 60000);
  return mins < 2 ? 'همین الان' : mins < 90 ? `${mins} دقیقه پیش` : `${Math.round(mins / 60)} ساعت پیش`;
}

function formatBlock(d) {
  const L = [];
  const chg = [];
  if (fin(d.changePct)) chg.push(`۲۴ ساعت: ${pct(d.changePct)}`);
  if (fin(d.week)) chg.push(`۷ روز: ${pct(d.week)}`);
  const ic = EMOJI[d.key] || '🪙';
  if (d.kind === 'tgju') {
    const usdUnit = d.toman == null;
    const f = (v) => (usdUnit ? `${fmtUsd(v)}$` : `${fmtT(v)} تومان`);
    L.push(`${ic} ${d.name}`, `قیمت: ${f(usdUnit ? d.usd : d.toman)}`);
    if (chg.length) L.push(chg.join(' | '));
    if (fin(d.high) && fin(d.low)) L.push(`بیشترین/کمترین ۲۴ساعته: ${f(d.high)} / ${f(d.low)}`);
    L.push(`📡 ${d.src}${d.ts ? ` — ${ageText(d.ts)}` : ''}`);
  } else {
    L.push(`${ic} ${d.name} (${d.key})`, d.toman != null ? `قیمت: ${fmtUsd(d.usd)}$ ≈ ${fmtT(d.toman)} تومان` : `قیمت: ${fmtUsd(d.usd)}$ (قیمت تومانی الان در دسترس نیست)`);
    if (chg.length) L.push(chg.join(' | '));
    if (fin(d.high) && fin(d.low)) L.push(`بیشترین/کمترین ۲۴ساعته: ${fmtUsd(d.high)}$ / ${fmtUsd(d.low)}$`);
    if (fin(d.vol) && d.vol > 0) L.push(`حجم معاملات ۲۴ساعته: ${fmtBig(d.vol)}$`);
    L.push(`📡 ${d.src}${d.usdToman ? ` | دلار: ${fmtT(d.usdToman)} تومان` : ''}`);
  }
  return L.join('\n');
}

function oneLine(d) {
  const ic = EMOJI[d.key] || '🪙';
  const v = d.kind === 'crypto' ? `${fmtUsd(d.usd)}$${d.toman != null ? ` ≈ ${fmtT(d.toman)} ت` : ''}` : d.toman != null ? `${fmtT(d.toman)} تومان` : `${fmtUsd(d.usd)}$`;
  return `${ic} ${d.name}: ${v}${fin(d.changePct) ? ` (${pct(d.changePct)})` : ''}`;
}

async function aiTask(env, g, instruction, content) {
  const res = await callLLM(env, [{ role: 'system', content: instruction }, { role: 'user', content }], null, g?.model || (await getModel(env)), await aiCfgFor(env, g));
  return res.message?.content?.trim() || '';
}

async function analyze(env, g, d) {
  const data = {
    kind: d.kind,
    name: d.name,
    price_toman: fin(d.toman) ? Math.round(d.toman) : null,
    price_usd: d.usd ?? null,
    change_24h_pct: fin(d.changePct) ? Number(d.changePct.toFixed(2)) : null,
    change_7d_pct: fin(d.week) ? Number(d.week.toFixed(2)) : null,
    high_24h: d.high ?? null,
    low_24h: d.low ?? null,
    high_low_unit: d.kind === 'crypto' || d.toman == null ? 'usd' : 'toman',
  };
  const instruction =
    'تو یه تحلیل‌گر بازار خوش‌بیان و صادق هستی. با داده‌های JSON کاربر یه تحلیل خیلی کوتاه (۳ تا ۵ جمله) به فارسی بنویس: روند کوتاه‌مدت، سطح‌های حمایت/مقاومت تقریبی از روی بیشترین/کمترین ۲۴ساعته، و ریسک‌ها. ' +
    'فقط از اعداد همین داده استفاده کن و عدد جدید نساز؛ اگه فیلدی null بود درباره‌ش حرف نزن. درباره‌ی خبر یا دلیل سیاسی/اقتصادی حدس نزن. پیش‌بینی قطعی و توصیه‌ی مستقیم خرید/فروش نکن. ' +
    'اگه kind برابر tgju بود قیمت بازار آزاد ایرانه؛ اگه crypto بود قیمت جهانی با تبدیل به تومان. آخرش یه جمله‌ی کوتاه بگو این تحلیل اطلاعاتیه و توصیه‌ی مالی نیست.';
  return aiTask(env, g, instruction, JSON.stringify(data));
}

async function handlePrice(env, m, key, g, inGroup, isOwner) {
  await tg(env, 'sendChatAction', { chat_id: m.chat.id, action: 'typing' });
  const say = (t) => reply(env, m, t, inGroup);
  const r = await getMarket(env, key);
  if (!r.ok) {
    if (r.notFound) return say('این یکی رو نشناختم 🤷 (تیکر انگلیسی بده، مثلاً /price PEPE)');
    return say('الان نتونستم قیمت رو بگیرم 😕 چند دقیقه‌ی دیگه امتحان کن.' + (isOwner && r.errs?.length ? `\n\n${r.errs.join('\n')}\n\nراه‌حل موقت: /setrate 256000 (قیمت دلار به تومان)` : ''));
  }
  const d = r.data;
  if (key === 'GOLD') {
    const oz = await getMarket(env, 'OUNCE');
    if (oz.ok) d.extra = `🌍 ${oneLine(oz.data)}`;
  }
  let analysis = '';
  const wantAI = g ? g.ai !== false : true;
  const allowed = (!inGroup && isOwner) || ((!inGroup || (await userAiOk(env, m, g, isOwner, false))) && (await aiAllowed(env, inGroup ? `g${m.chat.id}` : `u${m.from.id}`, inGroup ? LIMITS.groupPerDay : LIMITS.privateUserPerDay, g)));
  if (wantAI && allowed) analysis = await analyze(env, g, d);
  return say(formatBlock(d) + (d.extra ? `\n${d.extra}` : '') + (analysis ? `\n\n🧠 ${analysis}` : ''));
}

// ---- price alerts (owner) ----
async function cmdAlert(env, arg, say) {
  const x = (arg || '').match(/^(.+?)\s*(>=|<=|>|<|بالای|بیشتر از|زیر|کمتر از)\s*([\d.,۰-۹٠-٩]+)\s*(\$|دلار|usd|ت|تومان)?\s*$/i);
  if (!x) return say('مثال:\n/alert ترون > 0.4$\n/alert دلار < 250000\n/alert طلا > 30000000');
  const key = resolveAsset(x[1]);
  if (!key) return say('اون دارایی رو نشناختم.');
  const a = ASSETS[key];
  const op = ['>', '>=', 'بالای', 'بیشتر از'].includes(x[2]) ? '>' : '<';
  const value = Number(pk(x[3]).replace(/,/g, ''));
  if (!(value > 0)) return say('عدد معتبر بده.');
  const isCrypto = !a?.tg;
  const wantsUsd = x[4] && /\$|دلار|usd/i.test(x[4]);
  const unit = a?.tg === 'ounce' ? 'usd' : isCrypto ? (x[4] && !wantsUsd ? 'toman' : 'usd') : 'toman';
  const list = (await env.KV.get('alerts', 'json')) || [];
  if (list.length >= 20) return say('حداکثر ۲۰ هشدار.');
  list.push({ id: crypto.randomUUID().slice(0, 6), key, op, value, unit });
  await env.KV.put('alerts', JSON.stringify(list));
  return say(`🔔 هشدار ثبت شد: ${a?.fa || key} ${op === '>' ? 'بالاتر از' : 'پایین‌تر از'} ${unit === 'usd' ? fmtUsd(value) + '$' : fmtT(value) + ' تومان'}\n(هر ۵ دقیقه چک میشه)`);
}

async function cronAlerts(env) {
  const list = await env.KV.get('alerts', 'json');
  if (!list?.length) return;
  const keep = [];
  const cache = {};
  for (const al of list) {
    cache[al.key] = cache[al.key] || (await getMarket(env, al.key));
    const r = cache[al.key];
    if (!r.ok) { keep.push(al); continue; }
    const cur = al.unit === 'usd' ? r.data.usd : r.data.toman;
    const hit = cur != null && (al.op === '>' ? cur >= al.value : cur <= al.value);
    if (hit) {
      await tg(env, 'sendMessage', { chat_id: Number(env.OWNER_ID), text: `🔔 هشدار: ${r.data.name} ${al.op === '>' ? 'بالاتر از' : 'پایین‌تر از'} ${al.unit === 'usd' ? fmtUsd(al.value) + '$' : fmtT(al.value) + ' تومان'} رسید.\n\n${formatBlock(r.data)}` });
    } else keep.push(al);
  }
  if (keep.length !== list.length) await env.KV.put('alerts', JSON.stringify(keep));
}

// ---- morning briefing (owner) ----
const ownerCfg = async (env) => ({ morning: { on: true, hour: 8 }, watch: ['USD', 'GOLD', 'BTC'], ...((await env.KV.get('cfg:owner', 'json')) || {}) });

async function listReminders(env, withinMs) {
  const l = await env.KV.list({ prefix: 'rem:' });
  const now = Date.now();
  const out = [];
  for (const k of l.keys.slice(0, 20)) {
    const r = await env.KV.get(k.name, 'json');
    if (r && r.at - now <= withinMs) out.push({ at: r.at, text: r.text });
  }
  return out.sort((a, b) => a.at - b.at).slice(0, 8).map((r) => `• ${fmtTime(env, r.at)} — ${r.text}`);
}

async function sendMorning(env) {
  const cfg = await ownerCfg(env);
  const lines = ['☀️ صبح بخیر!'];
  for (const k of cfg.watch) {
    const r = await getMarket(env, k);
    lines.push(r.ok ? oneLine(r.data) : `• ${ASSETS[k]?.fa || k}: نامشخص`);
  }
  const rems = await listReminders(env, 24 * 3600 * 1000);
  if (rems.length) lines.push('', '⏰ یادآورهای ۲۴ ساعت آینده:', ...rems);
  const al = (await env.KV.get('alerts', 'json')) || [];
  if (al.length) lines.push('', `🔔 ${al.length} هشدار قیمت فعال`);
  await tg(env, 'sendMessage', { chat_id: Number(env.OWNER_ID), text: lines.join('\n') });
}

async function cronMorning(env) {
  const cfg = await ownerCfg(env);
  if (!cfg.morning.on) return;
  const lp = localParts(env);
  if (lp.h < cfg.morning.hour || lp.h >= cfg.morning.hour + 2) return;
  const flag = `sent:morning:${lp.date}`;
  if (await env.KV.get(flag)) return;
  await env.KV.put(flag, '1', { expirationTtl: 172800 });
  await sendMorning(env);
}

async function cronPrices(env) {
  if (localParts(env).m % 5 !== 0) return; // refresh the price history every ~5 minutes
  await getTgju(env, []);
}

// ======================= BUSINESS (Chat Automation) =======================
const BZ_DEFAULTS = {
  enabled: true,
  mode: 'offline', // offline | always
  start: 22,
  end: 9,
  draft: false, // true = AI writes a draft, you approve from your DM
  sigName: '', // signature shown under every automatic reply (empty = off)
  sigTime: true, // show the local time after the name
  pauseMinutes: 120,
  dailyAiLimit: 30,
  digest: true,
  digestHour: 21,
  menu: 'سلام 👋\nمن دستیار خودکار هستم و صاحب این حساب الان در دسترس نیست.\nپیامت رو بنویس؛ به‌محض آنلاین‌شدن جواب میده.',
  rules: {},
  vip: [],
  skip: [],
  prompt:
    "You are an automatic assistant replying on behalf of the account owner while they are unavailable. Be short, polite and helpful. Reply in the same language the person writes in (Persian or English). If asked, say clearly that you are an AI assistant, not the owner. Never make promises, agree to prices/deals, or share private info on the owner's behalf; say the owner will follow up personally. Keep answers under 4 sentences.",
};
// settings per connected business account: the owner keeps 'cfg:bz'; other users get 'bz:<their id>'
const bzKey = (env, uid) => (uid == null || Number(uid) === Number(env.OWNER_ID) ? 'cfg:bz' : `bz:${uid}`);
const getBz = async (env, uid = Number(env.OWNER_ID)) => ({ ...BZ_DEFAULTS, ...((await env.KV.get(bzKey(env, uid), 'json')) || {}) });
const saveBz = (env, bz, uid = Number(env.OWNER_ID)) => env.KV.put(bzKey(env, uid), JSON.stringify(bz));
// does this user have Chat Automation connected to their own account?
async function userBizConnected(env, uid) {
  const l = await env.KV.list({ prefix: 'bconn:' });
  for (const k of l.keys.slice(0, 50)) { const c = await env.KV.get(k.name, 'json'); if (c && Number(c.user_id) === Number(uid)) return true; }
  return false;
}

async function onBizConnection(c, env) {
  const canReply = c.rights ? !!c.rights.can_reply : !!c.can_reply;
  if (c.is_enabled) await env.KV.put(`bconn:${c.id}`, JSON.stringify({ user_id: c.user.id, can_reply: canReply }));
  else await env.KV.delete(`bconn:${c.id}`);
  await tg(env, 'sendMessage', {
    chat_id: Number(env.OWNER_ID),
    text: c.is_enabled
      ? `✅ Chat Automation به حساب ${c.user.first_name} وصل شد.` + (canReply ? '' : '\n⚠️ اجازه‌ی پاسخ‌دادن فعال نیست؛ توی تنظیمات Chat Automation چک کن.')
      : '❌ اتصال Chat Automation قطع شد.',
  });
}

async function bzLog(env, entry) {
  try {
    const k = `bzlog:${localParts(env).date}`;
    const log = (await env.KV.get(k, 'json')) || [];
    log.push(entry);
    await env.KV.put(k, JSON.stringify(log.slice(-300)), { expirationTtl: 3 * 86400 });
  } catch (e) { /* ignore */ }
}

// signature line "Ali 13:13" under automatic replies (local time of the bot timezone)
function bzWithSig(env, bz, text) {
  const name = String(bz.sigName || '').replace(/[\r\n]+/g, ' ').trim().slice(0, 32);
  if (!name) return text;
  const lp = localParts(env);
  const time = bz.sigTime === false ? '' : ` ${String(lp.h).padStart(2, '0')}:${String(lp.m).padStart(2, '0')}`;
  return `${text}\n\n${name}${time}`;
}
const sendBiz = async (env, d, text) => tg(env, 'sendMessage', { business_connection_id: d.conn, chat_id: d.chatId, text: bzWithSig(env, await getBz(env), text) });

async function bzSaveHist(env, chatId, userText, answer) {
  const k = `bh:${chatId}`;
  const h = (await env.KV.get(k, 'json')) || [];
  await env.KV.put(k, JSON.stringify([...h, { role: 'user', content: userText }, { role: 'assistant', content: answer }].slice(-10)), { expirationTtl: 86400 });
}

async function bizDraft(env, d) {
  d = { ...d, owner: d.owner || Number(env.OWNER_ID) };
  const id = crypto.randomUUID().slice(0, 8);
  await env.KV.put(`bd:${id}`, JSON.stringify(d), { expirationTtl: 86400 });
  const r = await tg(env, 'sendMessage', {
    chat_id: d.owner,
    text: `✉️ پیش‌نویس برای ${d.name} (${d.uid})\n\n«${d.orig.slice(0, 300)}»\n\n💬 ${d.text}`,
    reply_markup: { inline_keyboard: [[{ text: '✅ ارسال', callback_data: `bd:send:${id}` }, { text: '✏️ ویرایش', callback_data: `bd:edit:${id}` }, { text: '🚫 نادیده', callback_data: `bd:skip:${id}` }]] },
  });
  if (r.result?.message_id) await env.KV.put(`bdmsg:${r.result.message_id}`, id, { expirationTtl: 86400 });
}

async function onBusinessMessage(m, env) {
  const chatId = m.chat.id;
  const conn = m.business_connection_id ? await env.KV.get(`bconn:${m.business_connection_id}`, 'json') : null;
  const owner = Number(conn?.user_id || env.OWNER_ID); // the connected account's owner
  const bz = await getBz(env, owner);

  // you replied manually -> pause automation for this chat
  if (m.from && m.from.id === owner) {
    await env.KV.put(`bpause:${chatId}`, '1', { expirationTtl: Math.max(60, bz.pauseMinutes * 60) });
    return;
  }
  if (!m.from || m.from.is_bot) return;

  const text = (m.text || m.caption || '').trim();
  const name = m.from.first_name || m.from.username || String(m.from.id);
  await bzLog(env, { id: m.from.id, name, text: (text || '[مدیا]').slice(0, 120) });

  if (!bz.enabled) return;
  if (bz.skip.includes(m.from.id)) return;
  if (bz.vip.includes(m.from.id)) {
    await tg(env, 'sendMessage', { chat_id: owner, text: `⭐ پیام از ${name} (VIP):\n${(text || '[مدیا]').slice(0, 500)}` });
    return;
  }
  if (!text) return;
  if (await env.KV.get(`bpause:${chatId}`)) return;

  const connId = m.business_connection_id;
  const send = (t) => tg(env, 'sendMessage', { business_connection_id: connId, chat_id: chatId, text: bzWithSig(env, bz, t) });
  { const cr = creatorReplyFor(env, text, null); if (cr) return send(cr); }
  const q = norm(text);

  if (['منو', 'menu', '/menu', 'help', 'راهنما'].includes(q)) return send(bz.menu);
  for (const [kw, r] of Object.entries(bz.rules)) {
    if (q.includes(norm(kw))) return send(r);
  }
  if (bz.mode === 'offline' && !inWindow(localParts(env).hf, bz.start, bz.end)) return;
  if (isIdentityQuestion(text)) return send(IDENTITY_REPLY);
  if (!(await aiAllowed(env, `b${chatId}`, bz.dailyAiLimit))) return;

  await tg(env, 'sendChatAction', { business_connection_id: connId, chat_id: chatId, action: 'typing' });
  const hist = (await env.KV.get(`bh:${chatId}`, 'json')) || [];
  const msgs = [{ role: 'system', content: bz.prompt }, ...hist, { role: 'user', content: text }];
  const res = await callLLM(env, msgs, null, await getModel(env));
  const answer = res.message?.content?.trim();
  if (!answer) return;

  if (bz.draft) return bizDraft(env, { conn: connId, chatId, uid: m.from.id, name, orig: text, text: answer, owner });
  await send(answer);
  await bzSaveHist(env, chatId, text, answer);
}

async function bizCallback(env, cq) {
  const ans = (t, a) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: t, show_alert: !!a } : {}) });
  const [, act, id] = (cq.data || '').split(':');
  const d = await env.KV.get(`bd:${id}`, 'json');
  if (!d) return ans('این پیش‌نویس منقضی شده', true);
  if (cq.from.id !== Number(d.owner || env.OWNER_ID) && cq.from.id !== Number(env.OWNER_ID)) return ans('فقط صاحب حساب', true);
  const edit = (t) => tg(env, 'editMessageText', { chat_id: cq.message.chat.id, message_id: cq.message.message_id, text: t });
  if (act === 'edit') return ans('روی همین پیام ریپلای کن و متن جدیدت رو بفرست.', true);
  if (act === 'skip') {
    await env.KV.delete(`bd:${id}`);
    await edit(`🚫 نادیده گرفته شد (${d.name})`);
    return ans();
  }
  if (act === 'send') {
    const r = await sendBiz(env, d, d.text);
    await edit(r.ok ? `✅ برای ${d.name} ارسال شد:\n${d.text}` : `⚠️ ارسال نشد: ${r.description}`);
    if (r.ok) { await env.KV.delete(`bd:${id}`); await bzSaveHist(env, d.chatId, d.orig, d.text); }
    return ans();
  }
  return ans();
}

async function cronDigest(env) {
  const bz = await getBz(env);
  if (!bz.enabled || !bz.digest) return;
  const lp = localParts(env);
  if (lp.h < bz.digestHour || lp.h >= bz.digestHour + 2) return;
  const flag = `sent:digest:${lp.date}`;
  if (await env.KV.get(flag)) return;
  const log = await env.KV.get(`bzlog:${lp.date}`, 'json');
  if (!log?.length) return;
  await env.KV.put(flag, '1', { expirationTtl: 172800 });
  const by = {};
  for (const e of log) { (by[e.id] = by[e.id] || { name: e.name, n: 0, last: '' }).n++; by[e.id].last = e.text; }
  const rows = Object.entries(by).slice(0, 15).map(([id, v]) => `• ${v.name} (${id}) — ${v.n} پیام\n  «${v.last}»`);
  await tg(env, 'sendMessage', { chat_id: Number(env.OWNER_ID), text: `📬 خلاصه‌ی امروز (Chat Automation)\n${log.length} پیام از ${Object.keys(by).length} نفر:\n\n${rows.join('\n')}` });
}

async function bizCommand(env, cmd, arg, say, uid = Number(env.OWNER_ID)) {
  const bz = await getBz(env, uid);
  const num = (s) => Number(String(s || '').trim());
  switch (cmd) {
    case '/biz': {
      if (arg === 'on' || arg === 'off') { bz.enabled = arg === 'on'; await saveBz(env, bz, uid); return say(bz.enabled ? '✅ Chat Automation روشن' : '⏸ خاموش'); }
      return say(
        `🏢 Chat Automation: ${bz.enabled ? 'روشن ✅' : 'خاموش ⏸'}\nحالت: ${bz.mode === 'always' ? 'همیشه' : `فقط آفلاین (${bz.start}-${bz.end})`}\nپیش‌نویس: ${bz.draft ? 'روشن' : 'خاموش'}\n` +
          `قوانین: ${Object.keys(bz.rules).length} | VIP: ${bz.vip.length} | نادیده: ${bz.skip.length}\nخلاصه‌ی روزانه: ${bz.digest ? `ساعت ${bz.digestHour}` : 'خاموش'}\n\n` +
          '/biz on|off — /bizstatus — /bizmode always|offline — /bizhours 22-9 — /bizdraft on|off\n/bizsig اسم | /bizsig off | /bizsig time on|off\n/bizrule کلمه | جواب — /bizdelrule کلمه — /bizrules — /bizmenu متن — /bizprompt متن\n/bizvip آیدی|del آیدی — /bizskip آیدی|del آیدی — /bizdigest on|off|ساعت'
      );
    }
    case '/bizsig': {
      const a = arg.trim();
      if (!a || /^(off|خاموش)$/i.test(a)) { bz.sigName = ''; await saveBz(env, bz, uid); return say('امضای پاسخ‌ها خاموش شد.'); }
      if (/^time\s+/i.test(a)) { bz.sigTime = !/^time\s+(off|خاموش)$/i.test(a); await saveBz(env, bz, uid); return say(`ساعت کنار امضا: ${bz.sigTime ? 'روشن' : 'خاموش'}`); }
      bz.sigName = a.replace(/[\r\n]+/g, ' ').slice(0, 32);
      await saveBz(env, bz, uid);
      return say(`✍️ امضا: «${bz.sigName}» — مثال پاسخ: ${bz.sigName}${bz.sigTime === false ? '' : ' ' + String(localParts(env).h).padStart(2, '0') + ':' + String(localParts(env).m).padStart(2, '0')}`);
    }
    case '/bizstatus': {
      const head = (x, n) => String(x || '').replace(/\s+/g, ' ').slice(0, n);
      return say(`🏢 وضعیت Chat Automation (ذخیره‌شده الان)\nروشن: ${bz.enabled ? 'بله' : 'خیر'} — حالت: ${bz.mode} — پیش‌نویس: ${bz.draft ? 'بله' : 'خیر'}\nامضا: ${bz.sigName ? `«${bz.sigName}»` : 'خاموش'} — ساعت امضا: ${bz.sigTime === false ? 'خاموش' : 'روشن'}\nمنو: ${head(bz.menu, 160)}\nپرامپت AI: ${head(bz.prompt, 120)}\nقوانین: ${Object.keys(bz.rules).length} — VIP: ${bz.vip.length}\n\nمنو با این پیام‌ها نشون داده میشه: «منو» / «menu» / «راهنما».\nپاسخ‌های عادی با پرامپت ساخته میشن.`);
    }
    case '/bizmode':
      if (!['always', 'offline'].includes(arg)) return say('/bizmode always|offline');
      bz.mode = arg; await saveBz(env, bz, uid); return say(`حالت: ${arg}`);
    case '/bizhours': {
      const mt = arg.match(/^(\d{1,2})\s*-\s*(\d{1,2})$/);
      if (!mt) return say('مثال: /bizhours 22-9');
      bz.start = +mt[1]; bz.end = +mt[2]; await saveBz(env, bz, uid); return say(`ساعات آفلاین: ${bz.start} تا ${bz.end}`);
    }
    case '/bizdraft':
      bz.draft = arg !== 'off'; await saveBz(env, bz, uid);
      return say(bz.draft ? '✉️ حالت پیش‌نویس روشن: جواب‌ها اول برای تو میاد و با دکمه تأیید می‌کنی.' : 'جواب مستقیم (بدون تأیید)');
    case '/bizrule': {
      const [kw, ...r] = arg.split('|');
      if (!kw.trim() || !r.join('|').trim()) return say('مثال: /bizrule قیمت | قیمت‌ها از ... شروع میشه');
      bz.rules[kw.trim()] = r.join('|').trim(); await saveBz(env, bz, uid); return say(`✅ قانون «${kw.trim()}» اضافه شد`);
    }
    case '/bizdelrule':
      if (!(arg in bz.rules)) return say('همچین کلمه‌ای نیست');
      delete bz.rules[arg]; await saveBz(env, bz, uid); return say('🗑 حذف شد');
    case '/bizrules':
      return say(Object.entries(bz.rules).map(([k, v]) => `• ${k} → ${v}`).join('\n') || 'قانونی نیست');
    case '/bizmenu':
      if (!arg) return say(bz.menu);
      bz.menu = arg; await saveBz(env, bz, uid); return say('✅ منو ذخیره شد');
    case '/bizprompt':
      if (!arg) return say('/bizprompt دستورالعمل جدید (انگلیسی یا فارسی)');
      bz.prompt = arg; await saveBz(env, bz, uid); return say('✅ پرامپت ذخیره شد');
    case '/bizvip':
    case '/bizskip': {
      const field = cmd === '/bizvip' ? 'vip' : 'skip';
      const del = /^del\s+/i.test(arg);
      const id = num(arg.replace(/^del\s+/i, ''));
      if (!id) return say(`${bz[field].length ? `لیست: ${bz[field].join(', ')}\n` : ''}مثال: ${cmd} 123456789  یا  ${cmd} del 123456789`);
      bz[field] = del ? bz[field].filter((x) => x !== id) : [...new Set([...bz[field], id])];
      await saveBz(env, bz, uid); return say(`✅ ${field === 'vip' ? 'VIP' : 'نادیده'}: ${bz[field].join(', ') || '—'}`);
    }
    case '/bizdigest': {
      if (arg === 'off') bz.digest = false;
      else if (arg === 'on') bz.digest = true;
      else if (/^\d{1,2}$/.test(arg)) { bz.digest = true; bz.digestHour = Math.min(23, +arg); }
      else return say('/bizdigest on|off|ساعت (مثلاً 21)');
      await saveBz(env, bz, uid); return say(bz.digest ? `خلاصه‌ی روزانه: ساعت ${bz.digestHour}` : 'خلاصه‌ی روزانه خاموش');
    }
  }
}

// ======================= BROADCAST =======================
async function registerUser(env, u) {
  if (!u || u.is_bot) return;
  const k = `usr:${u.id}`;
  if (!(await env.KV.get(k))) {
    await env.KV.put(k, JSON.stringify({ n: u.first_name || '', u: u.username || '', t: Date.now(), a: 1 }), { metadata: { a: 1 } });
  }
}

async function setUserActive(env, id, a, stopped) {
  const k = `usr:${id}`;
  const cur = (await env.KV.get(k, 'json')) || { n: '', t: Date.now() };
  cur.a = a;
  if (stopped !== undefined) cur.stopped = stopped;
  await env.KV.put(k, JSON.stringify(cur), { metadata: { a } });
}

async function listUsers(env) {
  const out = { active: [], total: 0 };
  let cursor;
  do {
    const r = await env.KV.list({ prefix: 'usr:', cursor });
    for (const k of r.keys) {
      out.total++;
      if (!k.metadata || k.metadata.a !== 0) out.active.push(Number(k.name.slice(4)));
    }
    cursor = r.list_complete ? undefined : r.cursor;
  } while (cursor);
  return out;
}

async function collectTargets(env, mode) {
  const ids = [];
  if (mode === 'users' || mode === 'all') ids.push(...(await listUsers(env)).active);
  if (mode === 'groups' || mode === 'all') {
    const l = await env.KV.list({ prefix: 'grp:' });
    for (const k of l.keys) {
      const g = await env.KV.get(k.name, 'json');
      if (g?.enabled) ids.push(Number(k.name.slice(4)));
    }
  }
  return ids;
}

async function cmdBroadcast(env, m, text, say) {
  const mode = text.split(/\s+/)[1];
  if (!['users', 'groups', 'all'].includes(mode)) {
    return say('مثال:\n/broadcast users متن پیام\n/broadcast all  (روی یه پیام ریپلای کن تا همون پیام کپی بشه)\nمقصد: users | groups | all');
  }
  const body = text.replace(/^\S+\s+\S+\s*/, '').trim();
  const rep = m.reply_to_message;
  if (!rep && !body) return say('متن بده یا روی یه پیام ریپلای کن.');
  const ids = await collectTargets(env, mode);
  if (!ids.length) return say('مخاطبی پیدا نشد.');
  const id = crypto.randomUUID().slice(0, 8);
  const job = { id, mode, kind: rep ? 'copy' : 'text', text: body, from: m.chat.id, mid: rep?.message_id, queue: ids, total: ids.length, sent: 0, fail: 0, blocked: 0, t: Date.now() };
  await env.KV.put('bc:pending', JSON.stringify(job), { expirationTtl: 3600 });
  return tg(env, 'sendMessage', {
    chat_id: m.chat.id,
    text: `📣 برودکست «${mode}» به ${ids.length} مخاطب:\n\n${rep ? '(پیام ریپلای‌شده کپی میشه)' : body.slice(0, 500)}\n\nتأیید می‌کنی؟`,
    reply_markup: { inline_keyboard: [[{ text: '✅ شروع ارسال', callback_data: `bc:go:${id}` }, { text: '❌ لغو', callback_data: `bc:no:${id}` }]] },
  });
}

async function startBroadcast(env, job) {
  const cur = await env.KV.get('bc:job', 'json');
  if (cur && cur.status === 'running') return false;
  job.status = 'running';
  await env.KV.put('bc:job', JSON.stringify(job));
  if (env._ctx) env._ctx.waitUntil(runBroadcast(env));
  return true;
}

async function bcCallback(env, cq) {
  const ans = (t, a) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: t, show_alert: !!a } : {}) });
  if (cq.from.id !== Number(env.OWNER_ID)) return ans('فقط صاحب بات', true);
  const [, act, id] = (cq.data || '').split(':');
  const edit = (t) => tg(env, 'editMessageText', { chat_id: cq.message.chat.id, message_id: cq.message.message_id, text: t });
  const job = await env.KV.get('bc:pending', 'json');
  if (!job || job.id !== id) return ans('این برودکست منقضی شده', true);
  await env.KV.delete('bc:pending');
  if (act === 'no') { await edit('❌ لغو شد.'); return ans(); }
  const started = await startBroadcast(env, job);
  await edit(started ? `🚀 ارسال شروع شد (${job.total} مخاطب). /bcstatus برای پیگیری` : '⚠️ یه برودکست دیگه در جریانه. /bcstatus یا /bccancel');
  return ans();
}

async function sendOne(env, job, id) {
  const copy = job.kind === 'copy';
  const body = copy ? { chat_id: id, from_chat_id: job.from, message_id: job.mid } : { chat_id: id, text: id > 0 ? `${job.text}\n\n— لغو دریافت: /stop` : job.text };
  const r = await tg(env, copy ? 'copyMessage' : 'sendMessage', body);
  if (r.ok) return 'ok';
  if (r.error_code === 429) return { retry: r.parameters?.retry_after || 5 };
  if ((r.error_code === 403 || r.error_code === 400) && /blocked|deactivated|chat not found|kicked|not a member|initiate|rights to send/i.test(r.description || '')) {
    try {
      if (id > 0) await setUserActive(env, id, 0);
      else {
        const g = await getGroup(env, id);
        if (g) { g.enabled = false; await env.KV.put(`grp:${id}`, JSON.stringify(g)); }
      }
    } catch (e) { /* ignore */ }
    return 'blocked';
  }
  return 'fail';
}

async function runBroadcast(env) {
  const job = await env.KV.get('bc:job', 'json');
  if (!job || job.status !== 'running') return;
  if (job.pause && Date.now() < job.pause) return;
  job.pause = 0;
  const batch = job.queue.splice(0, 25);
  let idx = 0;
  let pause = 0;
  while (idx < batch.length && !pause) {
    const chunk = batch.slice(idx, idx + 5);
    const res = await Promise.all(chunk.map((id) => sendOne(env, job, id)));
    const retry = [];
    res.forEach((r, j) => {
      if (r === 'ok') job.sent++;
      else if (r === 'blocked') job.blocked++;
      else if (r && r.retry) { pause = Math.max(pause, r.retry); retry.push(chunk[j]); }
      else job.fail++;
    });
    idx += 5;
    if (pause) job.queue.unshift(...retry, ...batch.slice(idx));
  }
  if (pause) job.pause = Date.now() + pause * 1000;
  const done = job.queue.length === 0;
  if (done) job.status = 'done';
  await env.KV.put('bc:job', JSON.stringify(job));
  if (done) {
    await tg(env, 'sendMessage', { chat_id: Number(env.OWNER_ID), text: `📣 برودکست تموم شد.\nارسال: ${job.sent} از ${job.total}\nبلاک/غیرفعال: ${job.blocked}\nخطا: ${job.fail}` });
  } else if (!pause) {
    await kickBroadcast(env);
  }
}

// chain the next batch through a fresh invocation (new subrequest budget); cron is the fallback
async function kickBroadcast(env) {
  const origin = await env.KV.get('cfg:origin');
  if (origin && env._ctx) env._ctx.waitUntil(fetch(`${origin}/bc/run?key=${encodeURIComponent(env.WEBHOOK_SECRET)}`).catch(() => {}));
}

async function bcStatus(env) {
  const job = await env.KV.get('bc:job', 'json');
  if (!job) return 'برودکستی ثبت نشده.';
  return `📣 وضعیت: ${job.status}\nارسال: ${job.sent}/${job.total} | بلاک: ${job.blocked} | خطا: ${job.fail} | مانده: ${job.queue.length}`;
}

