async function adminApi(env, b) {
  switch (b.action) {
    case 'overview': {
      const u = await listUsers(env);
      const gl = await env.KV.list({ prefix: 'grp:' });
      const groups = [];
      for (const k of gl.keys) {
        const g = await env.KV.get(k.name, 'json');
        if (g) groups.push({ id: k.name.slice(4), title: g.title, enabled: !!g.enabled, roast: !!g.roast, ai: g.ai !== false, prices: g.prices !== false, chance: g.chance, model: g.model || '' });
      }
      const job = await env.KV.get('bc:job', 'json');
      const bz = await getBz(env);
      const alerts = (await env.KV.get('alerts', 'json')) || [];
      return {
        users: { total: u.total, active: u.active.length },
        groups,
        job: job && { status: job.status, sent: job.sent, total: job.total, blocked: job.blocked, left: job.queue.length },
        bz: { enabled: bz.enabled, mode: bz.mode, draft: bz.draft },
        alerts: alerts.length,
        model: await getModel(env),
      };
    }
    case 'group': {
      const id = String(b.id);
      const g = await getGroup(env, id);
      if (!g) return { error: 'not found' };
      const p = b.patch || {};
      for (const k of ['enabled', 'roast', 'ai', 'prices']) if (typeof p[k] === 'boolean') g[k] = p[k];
      if (p.chance != null) g.chance = Math.min(100, Math.max(0, Number(p.chance) || 0));
      if (typeof p.model === 'string') { if (p.model.trim()) g.model = p.model.trim(); else delete g.model; }
      await env.KV.put(`grp:${id}`, JSON.stringify(g));
      return { ok: true };
    }
    case 'biz': {
      const bz = await getBz(env);
      const p = b.patch || {};
      if (typeof p.enabled === 'boolean') bz.enabled = p.enabled;
      if (typeof p.draft === 'boolean') bz.draft = p.draft;
      if (['offline', 'always'].includes(p.mode)) bz.mode = p.mode;
      await saveBz(env, bz);
      return { ok: true };
    }
    case 'broadcast': {
      if (!['users', 'groups', 'all'].includes(b.mode) || !String(b.text || '').trim()) return { error: 'bad request' };
      const ids = await collectTargets(env, b.mode);
      if (!ids.length) return { error: 'no recipients' };
      const job = { id: crypto.randomUUID().slice(0, 8), mode: b.mode, kind: 'text', text: String(b.text).trim(), queue: ids, total: ids.length, sent: 0, fail: 0, blocked: 0, t: Date.now() };
      if (!(await startBroadcast(env, job))) return { error: 'another broadcast is running' };
      return { ok: true, total: ids.length };
    }
    case 'cancelbc': {
      const job = await env.KV.get('bc:job', 'json');
      if (job && job.status === 'running') { job.status = 'cancelled'; await env.KV.put('bc:job', JSON.stringify(job)); }
      return { ok: true };
    }
    case 'setrate': {
      const v = Number(b.value);
      if (!(v > 1000 && v < 1e7)) return { error: 'invalid' };
      await env.KV.put('fx:manual', JSON.stringify({ usd: v, ts: Date.now() }), { expirationTtl: 86400 });
      await env.KV.delete('tg:cur');
      return { ok: true };
    }
  }
  return { error: 'unknown action' };
}

// ======================= GROUP EXTRAS (anti-spam, knowledge base, schedules, stats) =======================
const EXTRA_ADMIN = new Set(['/antispam', '/spammode', '/setkb', '/addkb', '/clearkb', '/kb', '/schedule', '/unschedule', '/remind']);
const EXTRA_PUBLIC = new Set(['/stats', '/schedules']);
for (const c of EXTRA_ADMIN) ADMIN_CMDS.add(c);
for (const c of EXTRA_PUBLIC) PUBLIC_CMDS.add(c);

const SPAM_WORDS = ['کسب درآمد', 'درآمد دلاری', 'سود تضمینی', 'سرمایه گذاری', 'سیگنال', 'ربح', 'فروش ویژه', 'تخفیف', 'کلیک کنید', 'جایزه', 'برنده شدید', 'عضو شوید', 'واتس اپ', 'بدون سرمایه', 'join', 'investment', 'guaranteed', 'airdrop', 'giveaway', 'whatsapp'];
function spamScore(m, text) {
  let s = 0;
  const t = norm(text);
  if (hasLink(m)) s += 1;
  if (/t\.me\/(\+|joinchat)/i.test(text)) s += 2;
  if (/@\w{4,}/.test(text)) s += 1;
  s += Math.min(3, SPAM_WORDS.filter((k) => t.includes(norm(k))).length);
  if (m.forward_origin) s += 1;
  if ((text.match(/[\u{1F300}-\u{1FAFF}]/gu) || []).length >= 6) s += 1;
  return s;
}
async function isSpam(env, g, m, text) {
  if (spamScore(m, text) < 2) return false;
  if (!(await aiAllowed(env, `g${m.chat.id}`, LIMITS.groupPerDay, g))) return false;
  const out = await aiTask(
    env, g,
    'تو یه فیلتر اسپم برای گروه تلگرامی هستی. پیام رو بررسی کن: تبلیغ ناخواسته، کلاهبرداری، کسب درآمد جعلی، لینک دعوت کانال/گروه، فروش، سیگنال یا جایزه‌ی فریبنده = اسپم. گفت‌وگوی عادی یا لینک مرتبط با بحث = اسپم نیست. فقط یه JSON بده: {"spam":true} یا {"spam":false}',
    text.slice(0, 800)
  );
  return /"spam"\s*:\s*true/i.test(out);
}

async function updSchedIdx(env, chatId, has) {
  const set = new Set((await env.KV.get('sched:idx', 'json')) || []);
  if (has) set.add(chatId); else set.delete(chatId);
  await env.KV.put('sched:idx', JSON.stringify([...set]));
}

async function groupExtra(env, m, g, cmd, arg, isOwner, save) {
  const chatId = m.chat.id;
  const mod = M(g);
  const say = (t) => reply(env, m, t, true);

  if (cmd === '/stats') return say(await statsText(env, chatId, g));
  if (cmd === '/schedules') {
    return say(mod.sched.length ? mod.sched.map((s, i) => `${i + 1}. ${s.time} — ${SCHED_FA[s.act || 'say']} ${String(s.arg ?? s.text ?? '').slice(0, 60)}`).join('\n') : 'زمان‌بندی‌ای نیست.');
  }

  const denyX = await adminGate(env, m, g, cmd);
  if (denyX) return say(denyX);
  await logAction(env, g, m, 'settings', { x: cmd.slice(1) });

  switch (cmd) {
    case '/antispam':
      mod.spam = { ...mod.spam, on: arg !== 'off' }; await save();
      return say(mod.spam.on ? `🛡 ضد اسپم هوشمند روشن (حالت: ${mod.spam.mode})` : 'ضد اسپم خاموش شد');
    case '/spammode':
      if (!['delete', 'warn'].includes(arg)) return say('/spammode delete|warn');
      mod.spam = { ...mod.spam, mode: arg }; await save(); return say(`حالت ضد اسپم: ${arg}`);
    case '/setkb':
      if (!arg) return say('مثال: /setkb ساعت کاری ما ... قوانین ... قیمت‌ها ...');
      mod.kb = arg.slice(0, 3000); await save(); return say('✅ دانش گروه ذخیره شد. وقتی منشنم کنن بر اساسش جواب میدم.');
    case '/addkb':
      if (!arg) return say('/addkb متن اضافه');
      mod.kb = `${mod.kb ? mod.kb + '\n' : ''}${arg}`.slice(0, 3000); await save(); return say(`✅ اضافه شد (${mod.kb.length}/3000)`);
    case '/clearkb':
      mod.kb = ''; await save(); return say('🗑 دانش گروه پاک شد.');
    case '/kb':
      return say(mod.kb ? `📚 دانش گروه (${mod.kb.length}/3000):\n${mod.kb.slice(0, 1500)}` : 'دانشی ثبت نشده. /setkb متن');
    case '/schedule': {
      const ps = parseSchedule(arg);
      if (ps.error) return say(ps.error);
      if (mod.sched.length >= 12) return say('حداکثر ۱۲ زمان‌بندی.');
      mod.sched = [...mod.sched, { id: crypto.randomUUID().slice(0, 6), time: ps.time, act: ps.act, arg: ps.arg, ...(ps.act === 'say' ? { text: ps.arg } : {}), last: '' }];
      await save(); await updSchedIdx(env, chatId, true);
      return say(`⏰ هر روز ساعت ${toFa(ps.time)}: ${SCHED_FA[ps.act]}${ps.act === 'say' ? '' : ` ${ps.arg}`}`);
    }
    case '/unschedule': {
      const i = parseInt(arg, 10) - 1;
      if (!(i >= 0 && i < mod.sched.length)) return say('شماره‌ی درست بده (از /schedules).');
      mod.sched = mod.sched.filter((_, j) => j !== i);
      await save(); await updSchedIdx(env, chatId, mod.sched.length > 0);
      return say('🗑 حذف شد.');
    }
    case '/remind': {
      const d = parseDur(arg);
      if (!d.secs || !d.reason) return say('مثال: /remind 30m جلسه شروع میشه');
      await addReminder(env, chatId, Date.now() + d.secs * 1000, d.reason);
      return say(`⏰ ${d.label} دیگه یادآوری میشه.`);
    }
  }
}


