      var Pq = Q[q], dd = (1 - Pq[2]) / 2;
      cx.fillStyle = Pq[2] < 0 ? "rgba(255,214,150," + (.25 + dd * .7) + ")" : "rgba(120,240,255," + (.12 + dd * .35) + ")";
      cx.beginPath(); cx.arc(Pq[0], Pq[1], .6 + dd * 1.9, 0, 6.283); cx.fill();
