    cx.save(); cx.translate(ox, oy); cx.rotate(sweep);
    cx.fillStyle = rg; cx.beginPath(); cx.moveTo(0, 0); cx.arc(0, 0, R * 1.35, 0, .55); cx.closePath(); cx.fill();
    cx.restore();
