function barChart(vals, labels, hotN) {
  var mx = Math.max.apply(null, vals.concat([1]));
  var sorted = vals.slice().sort(function (a, b) { return b - a; }), thr = sorted[Math.min(hotN || 3, sorted.length) - 1] || Infinity;
  var bars = el("div", { class: "bars" });
  vals.forEach(function (v, i) {
    bars.appendChild(el("div", { class: "b" + (v >= thr && v > 0 ? " hot" : ""), style: "height:" + Math.max(2, v / mx * 100) + "%;animation-delay:" + (i * 25) + "ms", "data-t": labels[i] + " · " + fa(v) }));
  });
  return bars;
}
