// ======================= CRYPTO LIST / SEARCH / SECURITY AUDIT (Phase 13, 16, 20) =======================
const fmtBig = (v) => (!fin(v) ? '—' : v >= 1e9 ? `${(v / 1e9).toFixed(2)}B` : v >= 1e6 ? `${(v / 1e6).toFixed(2)}M` : v >= 1e3 ? `${(v / 1e3).toFixed(1)}K` : v.toFixed(0));
const TOP_COINS = ['BTC', 'ETH', 'SOL', 'TON', 'TRX', 'XRP', 'BNB', 'DOGE'];
async function cryptoList(env, errsOut) {
  const errs = errsOut || [];
  const tgd = await getTgju(env, []);
  const batch = await fetchBatch(TOP_COINS, errs, env);
  let lines = [];
  if (batch) lines = TOP_COINS.filter((k) => batch.data[k]).map((k) => oneLine(cryptoData(k, { ...batch.data[k], src: batch.src }, tgd)));
  if (lines.length < 4) { // batch failed: per-coin chain (cached, health-aware)
    const rs = await Promise.all(TOP_COINS.map((k) => getMarket(env, k)));
    lines = rs.filter((r) => r.ok).map((r) => oneLine(r.data));
  }
  return lines.length ? `🪙 ارزهای دیجیتال\n${lines.join('\n')}\n\n(برای قیمت دقیق + تحلیل هر ارز، فقط اسمش رو بنویس)` : 'الان نتونستم قیمت‌ها رو بگیرم 😕 چند دقیقه‌ی دیگه امتحان کن.';
}

// ---- web search: provider chain, results sanitized ----
const stripTags = (s) => String(s || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
const cleanResults = (arr) => (arr || []).filter((x) => /^https?:\/\//i.test(x?.url || '')).slice(0, 5).map((x) => ({ title: stripTags(x.title).slice(0, 120) || x.url, url: String(x.url).slice(0, 300), snippet: stripTags(x.snippet).slice(0, 200) }));
// keyless search helpers (best-effort): DuckDuckGo HTML + Wikipedia
async function ddgSearch(q) {
  const r = await fetch('https://html.duckduckgo.com/html/', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded', 'user-agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36', 'accept-language': 'fa,en;q=0.8' },
    body: `q=${encodeURIComponent(q)}&kl=wt-wt`,
    signal: AbortSignal.timeout(10000),
  });
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  const html = await r.text();
  const out = [];
  const re = /<a([^>]*class="result__a"[^>]*)>([\s\S]*?)<\/a>([\s\S]*?)(?=<a[^>]*class="result__a"|$)/g;
  let mt;
  while ((mt = re.exec(html)) && out.length < 6) {
    const hm = /href="([^"]+)"/.exec(mt[1]);
    if (!hm) continue;
    let url = hm[1].replace(/&amp;/g, '&');
    try {
      const u = new URL(url.startsWith('//') ? 'https:' + url : url, 'https://duckduckgo.com');
      url = u.searchParams.get('uddg') || u.href;
    } catch { continue; }
    if (/duckduckgo\.com\/y\.js|ad_provider/.test(url)) continue; // sponsored
    const sn = /class="result__snippet"[^>]*>([\s\S]*?)<\/(?:a|td|div)>/.exec(mt[3]);
    out.push({ title: mt[2], url, snippet: sn ? sn[1] : '' });
  }
  return out;
}
async function wikiSearch(q) {
  const fa = /[\u0600-\u06FF]/.test(q);
  const langs = fa ? ['fa', 'en'] : ['en', 'fa'];
  for (const lg of langs) {
    const r = await fetch(`https://${lg}.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&srlimit=4&format=json&origin=*`, { signal: AbortSignal.timeout(8000) });
    if (!r.ok) continue;
    const j = await r.json();
    const rs = (j.query?.search || []).map((x) => ({ title: x.title, url: `https://${lg}.wikipedia.org/wiki/${encodeURIComponent(String(x.title).replace(/ /g, '_'))}`, snippet: x.snippet }));
    if (rs.length) return rs;
  }
  return [];
}
async function searchWeb(env, q) {
  noteUse('srch');
  const errs = [];
  const enc = encodeURIComponent(q);
  if (env.LANGSEARCH_API_KEY && (provDown.get('langsearch') || 0) < Date.now()) {
    try {
      const r = await fetch('https://api.langsearch.com/v1/web-search', {
        method: 'POST',
        headers: { authorization: `Bearer ${env.LANGSEARCH_API_KEY}`, 'content-type': 'application/json' },
        body: JSON.stringify({ query: q, count: 5, freshness: 'noLimit', contents: { text: false } }),
        signal: AbortSignal.timeout(10000),
      });
      if (r.status === 429) provDown.set('langsearch', Date.now() + 3600000); // daily token allowance exhausted (resets 00:00 UTC): skip for an hour
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const j = await r.json();
      return { results: cleanResults((j.data?.webPages?.value || []).map((x) => ({ title: x.name, url: x.url, snippet: x.snippet }))), src: 'LangSearch' };
    } catch (e) { errs.push(`langsearch: ${e.message}`); }
  }
  if (env.TAVILY_API_KEY) {
    try {
      const j = await jfetch('https://api.tavily.com/search', { method: 'POST', headers: { 'content-type': 'application/json', authorization: `Bearer ${env.TAVILY_API_KEY}` }, body: JSON.stringify({ query: q, max_results: 5, api_key: env.TAVILY_API_KEY }) }, 10000);
      return { results: cleanResults((j.results || []).map((x) => ({ title: x.title, url: x.url, snippet: x.content }))), src: 'Tavily' };
    } catch (e) { errs.push(`tavily: ${e.message}`); }
  }
  if (env.BRAVE_API_KEY) {
    try {
      const j = await jfetch(`https://api.search.brave.com/res/v1/web/search?q=${enc}&count=5`, { headers: { accept: 'application/json', 'x-subscription-token': env.BRAVE_API_KEY } }, 10000);
      return { results: cleanResults((j.web?.results || []).map((x) => ({ title: x.title, url: x.url, snippet: x.description }))), src: 'Brave' };
    } catch (e) { errs.push(`brave: ${e.message}`); }
  }
  if (env.SEARXNG_URL) {
    try {
      const j = await jfetch(`${String(env.SEARXNG_URL).replace(/\/$/, '')}/search?q=${enc}&format=json`, {}, 10000);
      return { results: cleanResults((j.results || []).map((x) => ({ title: x.title, url: x.url, snippet: x.content }))), src: 'SearXNG' };
    } catch (e) { errs.push(`searxng: ${e.message}`); }
  }
  // keyless fallbacks (no API key needed): DuckDuckGo first, then Wikipedia
  if ((provDown.get('ddg') || 0) < Date.now()) {
    try {
      const rs = await ddgSearch(q);
      if (rs.length) return { results: cleanResults(rs), src: 'DuckDuckGo' };
      throw new Error('empty');
    } catch (e) { errs.push(`ddg: ${e.message}`); provDown.set('ddg', Date.now() + 120000); }
  }
  try {
    const rs = await wikiSearch(q);
    if (rs.length) return { results: cleanResults(rs), src: 'Wikipedia' };
  } catch (e) { errs.push(`wiki: ${e.message}`); }
  return { error: 'سرویس جستجو الان در دسترس نیست. (برای نتیجه‌ی بهتر یکی از TAVILY_API_KEY، BRAVE_API_KEY یا LANGSEARCH_API_KEY رو ست کن.)', errs };
}

async function doSearch(env, m, g, q, inGroup, isOwner) {
  q = String(q || '').replace(/\s+/g, ' ').trim().slice(0, 200);
  const say = (t) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t.slice(0, 3900), link_preview_options: { is_disabled: true }, ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  if (!q) return say('مثال: جستجو بهترین زمان سفر به استانبول');
  if (inGroup && g?.search === false) return;
  if (!rateOk(`srch:${m.from.id}`, 3, 60000)) return say('⏳ آروم‌تر؛ هر دقیقه حداکثر ۳ جستجو.');
  if (!rateOk(`srchc:${m.chat.id}`, 12, 60000)) return say('⏳ این گروه الان جستجوهای زیادی داره؛ کمی صبر کن.');
  await tg(env, 'sendChatAction', { chat_id: m.chat.id, action: 'typing' });
  const r = await searchWeb(env, q);
  if (r.error) return say(`❌ ${r.error}${isOwner && r.errs?.length ? `\n${r.errs.join('\n')}` : ''}`);
  if (!r.results.length) return say('نتیجه‌ای پیدا نشد.');
  let text = `🔎 ${q}\n\n${r.results.map((x, i) => `${i + 1}. ${x.title}\n${x.url}${x.snippet ? `\n${x.snippet}` : ''}`).join('\n\n')}`;
  const allowed = (!inGroup && isOwner) || ((!inGroup || (await userAiOk(env, m, g, isOwner, false))) && (await aiAllowed(env, inGroup ? `g${m.chat.id}` : `u${m.from.id}`, inGroup ? LIMITS.groupPerDay : LIMITS.privateUserPerDay, g)));
  if (allowed && (g ? g.ai !== false : true)) {
    const sum = await aiTask(env, g, 'با استفاده‌ی فقط از نتایج جستجوی زیر، به فارسی در ۲ تا ۳ جمله به سوال کاربر جواب بده. اگه نتایج برای جواب کافی نیست همین رو بگو. چیزی از خودت اضافه نکن و لینک نساز.', `سوال: ${q}\n\nنتایج:\n${r.results.map((x) => `- ${x.title}: ${x.snippet}`).join('\n')}`);
    if (sum) text = `🧠 ${sum}\n\n${text}`;
  }
  return say(`${text}\n\n📡 ${r.src}`);
}
async function toolWebSearch(env, q) {
  const r = await searchWeb(env, String(q || '').slice(0, 200));
  if (r.error) return `Search unavailable: ${r.error}`;
  return r.results.map((x, i) => `${i + 1}. ${x.title}\n${x.url}\n${x.snippet}`).join('\n\n') || 'No results.';
}

// ---- group security audit (what is protected, what is missing) ----
async function auditGroup(env, chatId, g) {
  const mod = M(g);
  const me0 = await botInfo(env);
  const me = (await tg(env, 'getMe', {})).result || me0; // fresh: the owner may have just changed the privacy mode
  const bm = await tg(env, 'getChatMember', { chat_id: chatId, user_id: me0.id });
  const b = bm.ok ? bm.result : {};
  const L = [];
  let score = 0;
  let total = 0;
  const chk = (ok, good, bad, w = 1) => { total += w; if (ok) score += w; L.push(`${ok ? '✅' : '⚠️'} ${ok ? good : bad}`); };
  const isAdm = b.status === 'administrator' || b.status === 'creator';
  chk(isAdm, 'بات ادمینه', 'بات ادمین نیست؛ بدون ادمین‌بودن قفل‌ها، حذف پیام و میوت کار نمی‌کنن.', 3);
  if (isAdm) {
    chk(b.can_delete_messages !== false && (b.status === 'creator' || b.can_delete_messages), 'دسترسی حذف پیام داره', 'دسترسی «حذف پیام» به بات داده نشده.', 2);
    chk(b.status === 'creator' || b.can_restrict_members, 'دسترسی محدودکردن/بن کاربران داره', 'دسترسی «بن/محدودکردن کاربران» به بات داده نشده.', 2);
    chk(b.status === 'creator' || b.can_pin_messages, 'دسترسی پین داره', 'دسترسی «پین» به بات داده نشده (فقط برای دستور پین لازمه).', 0.5);
  }
  chk(me.can_read_all_group_messages !== false, 'بات همه‌ی پیام‌ها رو می‌بینه (Privacy خاموشه)', 'حالت Privacy بات روشنه؛ BotFather ← /setprivacy ← Disable (بعدش بات رو از گروه حذف و دوباره اضافه کن). بدون اون قفل‌ها، ضدفلود و تیکه‌پرانی روی پیام‌های عادی کار نمی‌کنن.', 3);
  const active = Object.keys(mod.locks || {}).length;
  chk(active > 0, `${toFa(active)} قفل فعاله`, 'هیچ قفلی فعال نیست (پیشنهاد: «قفل لینک»، «قفل تبلیغات»).', 1.5);
  chk(mod.flood > 0, `ضدفلود روشنه (${toFa(mod.flood)} پیام)`, 'ضدفلود خاموشه (پیشنهاد: «ضد فلود 5»).', 1);
  chk(mod.captcha.on, 'کپچای ورود روشنه', 'کپچای ورود خاموشه (جلوی ربات‌های عضوشونده رو می‌گیره: «کپچا روشن»).', 1);
  chk(mod.spam.on, 'ضداسپم هوشمند روشنه', 'ضداسپم هوشمند خاموشه («ضد اسپم روشن»).', 1);
  chk(mod.raid.on, 'ضد ریید روشنه', 'ضد ریید خاموشه («ضد ریید روشن»).', 0.5);
  chk(mod.warnLimit >= 2, `اخطار: سقف ${toFa(mod.warnLimit)} → ${mod.warnMode}`, 'سقف اخطار نامعتبره.', 0.5);
  const custom = Object.keys(mod.perms || {}).length;
  L.push(`ℹ️ ادمین‌های با دسترسی محدودشده: ${toFa(custom)}`);
  L.push(`ℹ️ هوش مصنوعی: ${g.aicfg?.on ? 'اختصاصی گروه' : 'مشترک بات'} — استریم: ${g.stream !== false ? 'روشن' : 'خاموش'}`);
  if (mod.fj.on) L.push(`ℹ️ عضویت اجباری: ${mod.fj.ch.map((c) => c.t || c.u).join('، ')}`);
  if (mod.permBackup) L.push('ℹ️ گروه الان بسته است.');
  if (mod.raidUntil && Date.now() < mod.raidUntil) L.push('🚨 حالت ریید فعاله.');
  const pctScore = Math.round((score / total) * 100);
  return `🔍 بررسی امنیت گروه — امتیاز ${toFa(pctScore)}٪\n\n${L.join('\n')}`;
}


async function dmMisc(env, m, text, isOwner) {
  const t = pk(text);
  const first = text.split(/\s+/)[0].split('@')[0].toLowerCase();
  if (first === '/crypto' || ['ارزها', 'ارز دیجیتال', 'ارز های دیجیتال', 'کریپتو', 'ارزهای دیجیتال'].includes(t)) { await reply(env, m, await cryptoList(env), false); return true; }
  if (first === '/search') { await doSearch(env, m, null, text.split(/\s+/).slice(1).join(' '), false, isOwner); return true; }
  if (/^(جستجو|سرچ)\s+\S/.test(t) && text.length <= 220) { await doSearch(env, m, null, text.replace(/^\S+\s+/, ''), false, isOwner); return true; }
  return false;
}

