// features that do NOT exist yet — the AI must say so instead of improvising
const CAP_UNAVAILABLE = ['دانلود از یوتیوب/اینستاگرام (هنوز فعال نیست)', 'پخش موزیک در Voice Chat (هنوز فعال نیست؛ با Bot API ممکن نیست)', 'آمار دقیق و نمودار فعالیت اعضا (هنوز فعال نیست؛ فقط آمار تقریبی)'];
const capAliases = (cmd) => [...new Set(FA_LIST.filter((a) => a.c === cmd).map((a) => a.n.join(' ')))].slice(0, 2);
const capScope = (cmd) => (ADMIN_CMDS.has(cmd) ? 'ادمین' : 'همه');
function capsRelevant(question, max = 28) {
  const qt = new Set(pk(question).split(' ').filter((w) => w.length > 1));
  const scored = Object.entries(CAP_INFO).map(([cmd, [usage, desc]]) => {
    const hay = pk(`${usage} ${desc} ${capAliases(cmd).join(' ')} ${cmd}`).split(' ');
    return { cmd, usage, desc, s: hay.filter((w) => qt.has(w)).length };
  });
  const top = scored.filter((x) => x.s > 0).sort((a, b) => b.s - a.s).slice(0, max);
  const list = top.length ? top : scored.filter((x) => ['/panel', '/help', '/lock', '/ban', '/mute', '/warn', '/price', '/search', '/audit'].includes(x.cmd));
  return list.map((x) => `• ${capAliases(x.cmd)[0] || x.cmd} — ${x.usage} — ${x.desc} [${capScope(x.cmd)}${CMD_PERM[x.cmd] ? `؛ دسترسی: ${PERM_FA[CMD_PERM[x.cmd]]}` : ''}]`).join('\n');
}
const CAP_PROMPT = (q) => `قابلیت‌های واقعی این بات (فقط از همین‌ها حرف بزن؛ دستور یا قابلیت اختراع نکن):\n${capsRelevant(q)}\n\nقابلیت‌هایی که وجود ندارن: ${CAP_UNAVAILABLE.join('؛ ')}.\nاگه چیزی توی لیست نبود بگو «این قابلیت توی نسخه‌ی فعلی بات نیست». هرگز نگو کاری انجام شده مگر اینکه بات خودش اجراش کرده باشه. دستورهای ادمین رو فقط برای ادمین‌ها توضیح بده و به اعضا بگو ادمین باید انجام بده.`;
const HOWTO_RE = /(چطور|چطوری|چجوری|چگونه|چه‌جوری|راهنما|دستور|قابلیت|امکانات|میتونی|می‌تونی|میشه|می‌شه|بلدی|how\s+(do|to|can)|command|feature|can\s+you)/i;
const ACTION_RE = /(بن|بنش|کیک|اخراج|میوت|ساکت|اخطار|وارن|پاک|حذف|قفل|ببند|باز\s*کن|رفع|\b(mute|ban|kick|warn|lock|unlock|delete|close|open)\b)/i;

// ======================= AI ACTIONS: propose -> human confirms -> same code path as manual commands =======================
const AI_ACTIONS = nullObj({ ban: '/ban', unban: '/unban', kick: '/kick', mute: '/mute', unmute: '/unmute', warn: '/warn', unwarn: '/unwarn', clean: '/clean', lock: '/lock', unlock: '/unlock', close: '/close', open: '/open' });
const AI_ACTION_TOOL = [{ type: 'function', function: { name: 'propose_action', description: 'Propose ONE moderation action for the admin to confirm. Never claims it was executed.', parameters: { type: 'object', properties: { action: { type: 'string', enum: Object.keys(AI_ACTIONS) }, target: { type: 'string', description: "'@username', a numeric user id, or 'reply' when the admin replied to the user's message" }, duration: { type: 'string', description: 'e.g. 30m, 2h, 1d (mute/ban/close only; omit for permanent)' }, count: { type: 'integer', description: 'messages to delete (clean)' }, locks: { type: 'string', description: 'lock names in Persian or English (lock/unlock)' } }, required: ['action'] } } }];

function buildActionArg(m, a) {
  const act = a.action;
  const needsTarget = ['ban', 'unban', 'kick', 'mute', 'unmute', 'warn', 'unwarn'].includes(act);
  let tok = '';
  if (needsTarget) {
    const t = String(a.target || '').trim();
    if (t === 'reply' || t === '') { if (!m.reply_to_message?.from) return { error: 'هدف مشخص نیست: روی پیام کاربر ریپلای کن یا @یوزرنیم/آیدی بده.' }; tok = ''; }
    else if (USERNAME_RE.test(t)) tok = t;
    else if (/^\d{5,}$/.test(t)) tok = t;
    else return { error: 'هدف نامعتبره؛ فقط ریپلای، @username یا آیدی عددی.' };
  }
  let dur = '';
  if (['ban', 'mute', 'close'].includes(act) && String(a.duration || '').trim()) {
    const raw = String(a.duration).trim();
    if (!/^(permanent|forever|دائم|دائمی)$/i.test(raw)) { // anything else must be a real, safe duration — never silently turn garbage into "forever"
      const d = parseDurSafe(raw);
      if (d.error) return { error: d.error };
      if (!d.secs) return { error: '❌ فرمت مدت نامعتبره. مثال: 30m ، 2h ، 1d' };
      dur = d.label;
    }
  }
  if (act === 'clean') { const n = Math.round(Number(a.count)); if (!(n >= 1 && n <= 999)) return { error: 'تعداد پیام برای پاکسازی بین ۱ تا ۹۹۹ باشه.' }; return { cmd: '/clean', arg: String(n), label: `پاکسازی ${toFa(n)} پیام` }; }
  if (act === 'lock' || act === 'unlock') { const p = parseLockArgs(String(a.locks || '')); if (p.error || !p.ids.length) return { error: 'نام قفل مشخص نیست.' }; return { cmd: AI_ACTIONS[act], arg: String(a.locks), label: `${act === 'lock' ? 'قفل' : 'رفع قفل'} ${p.ids.map((i) => LOCK_MAP[i].fa).join('، ')}` }; }
  const name = tok || m.reply_to_message?.from?.first_name || '';
  return { cmd: AI_ACTIONS[act], arg: `${tok} ${dur}`.trim(), label: `${ACT_FA[act] || act} ${name}${dur ? ` (${dur})` : ''}`.trim() };
}

async function aiActionFlow(env, m, g, clean) {
  const chatId = m.chat.id;
  const say = async (t) => { await reply(env, m, t, true); return true; }; // every branch below has ALREADY answered: tell the caller not to answer again
  if (!rateOk(`aiact:${m.from.id}`, 5, 60000)) return say('⏳ آروم‌تر؛ هر دقیقه حداکثر ۵ درخواست اجرای کار.');
  if (!(await aiAllowed(env, `g${chatId}`, LIMITS.groupPerDay, g))) return null;
  // only the admin's own words (no group transcript): other members' messages cannot steer the model
  const sys = `${GROUP_CHAT_SYSTEM}\n\n${CAP_PROMPT(clean)}\n\nاگه ادمین درخواست اجرای یک کار مدیریتی داد، فقط با ابزار propose_action پیشنهادش رو بده (اجرا نمی‌کنی؛ ادمین باید تأیید کنه). اگه هدف مشخص نیست سوال بپرس. اگه درخواست مدیریتی نبود عادی جواب بده.`;
  const res = await callLLM(env, [{ role: 'system', content: sys }, { role: 'user', content: `${m.reply_to_message?.from ? '[این ادمین روی پیام یک کاربر ریپلای کرده]\n' : ''}${clean}` }], AI_ACTION_TOOL, g.model || (await getModel(env)), await aiCfgFor(env, g));
  if (res.error) return say('❌ دریافت پاسخ AI با مشکل مواجه شد.');
  const tc = res.message?.tool_calls?.[0];
  if (!tc || tc.function?.name !== 'propose_action') { const t = res.message?.content?.trim(); if (t) return say(t); return null; }
  let args = {};
  try { args = JSON.parse(tc.function.arguments || '{}'); } catch { return say('نتونستم درخواستت رو بفهمم؛ دوباره بگو.'); }
  if (!AI_ACTIONS[args.action]) return say('این کار رو نمی‌تونم پیشنهاد بدم.');
  const built = buildActionArg(m, args);
  if (built.error) return say(`❓ ${built.error}`);
  const deny = await adminGate(env, m, g, built.cmd); // refuse early if the asker could not run it manually either
  if (deny) return say(deny);
  const id = crypto.randomUUID().slice(0, 8);
  await env.KV.put(`ac:${id}`, JSON.stringify({ chat: chatId, uid: m.from.id, cmd: built.cmd, arg: built.arg, mid: m.message_id, reply: m.reply_to_message ? { message_id: m.reply_to_message.message_id, from: m.reply_to_message.from } : null, th: m.is_topic_message ? m.message_thread_id : null }), { expirationTtl: 180 });
  await tg(env, 'sendMessage', { chat_id: chatId, text: `🤖 پیشنهاد اجرا:\n«${built.label}»\n\nفقط ${m.from.first_name || 'درخواست‌دهنده'} می‌تونه تأیید کنه (تا ۳ دقیقه).`, reply_markup: { inline_keyboard: [[{ text: '✅ اجرا کن', callback_data: `ac:go:${id}` }, { text: '❌ لغو', callback_data: `ac:no:${id}` }]] }, reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true }, ...(m.is_topic_message ? { message_thread_id: m.message_thread_id } : {}) });
  return true;
}

async function aiActionCallback(env, cq) {
  const ans = (t, a) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: t, show_alert: !!a } : {}) });
  const [, act, id] = (cq.data || '').split(':');
  const p = await env.KV.get(`ac:${id}`, 'json');
  if (!p) return ans('این پیشنهاد منقضی شده', true);
  if (cq.from.id !== p.uid) return ans('این پیشنهاد مال یکی دیگه‌ست 🙂', true);
  const chat = cq.message?.chat;
  if (!chat || chat.id !== p.chat) return ans();
  await env.KV.delete(`ac:${id}`); // single use: no replays
  const edit = (t) => tg(env, 'editMessageText', { chat_id: chat.id, message_id: cq.message.message_id, text: t });
  if (act === 'no') { await edit('❌ لغو شد.'); return ans(); }
  const g = await getGroup(env, p.chat);
  if (!g?.enabled) return ans();
  const m2 = { chat, from: cq.from, message_id: p.mid, reply_to_message: p.reply ? { message_id: p.reply.message_id, from: p.reply.from, chat } : undefined, is_topic_message: !!p.th, message_thread_id: p.th || undefined };
  await edit('⏳ در حال اجرا...');
  await modCommand(env, m2, g, p.cmd, p.arg, false, () => env.KV.put(`grp:${p.chat}`, JSON.stringify(g)));
  await edit('✅ دستور اجرا شد (نتیجه بالاست).');
  return ans();
}

// ======================= SOCIAL MEDIA DOWNLOADER (Cobalt API, documented contract) =======================
// Contract (docs.cobalt / api.md): POST <COBALT_API_URL>/ with JSON {url}; header "Authorization: Api-Key <key>" when the instance enforces keys.
// Replies: tunnel|redirect {url, filename?}, picker {picker:[{type,url}]}, local-processing, error {error:{code}}.
// The Worker never downloads the file: we hand Telegram the URL the API returned (sendVideo/sendPhoto/sendDocument by URL).
const DL_HOSTS = [/^(www\.|m\.)?instagram\.com$/i, /^(www\.|vm\.|vt\.)?tiktok\.com$/i, /^(www\.|m\.)?youtube\.com$/i, /^youtu\.be$/i, /^(www\.|mobile\.)?(twitter|x)\.com$/i, /^(www\.|m\.|fb\.)?facebook\.com$/i, /^fb\.watch$/i];
const DL_ERR_FA = {
  'error.api.auth.key.missing': 'سرویس دانلودر کلید می‌خواد؛ مالک بات COBALT_API_KEY رو تنظیم کنه.',
  'error.api.auth.key.invalid': 'کلید سرویس دانلودر نامعتبره.',
  'error.api.link.unsupported': 'این لینک رو پشتیبانی نمی‌کنیم.',
  'error.api.content.video.unavailable': 'این ویدیو در دسترس نیست (حذف شده یا خصوصیه).',
  'error.api.fetch.empty': 'محتوایی برای این لینک پیدا نشد.',
  'error.api.fetch.rate': 'سرویس دانلودر الان محدودیت نرخ داره؛ کمی بعد امتحان کن.',
  'error.api.fetch.fail': 'دریافت از سرویس دانلودر ناموفق بود.',
  'error.api.content.too_long': 'این فایل خیلی بزرگه.',
  'error.api.youtube.login': 'یوتیوب این لینک رو فقط با ورود به حساب می‌خواد؛ از این بخش پشتیبانی نمی‌شه.',
};
// returns a safe https URL on one of the supported hosts, or null
function dlValidUrl(raw) {
  let u;
  try { u = new URL(String(raw || '').trim()); } catch { return null; }
  if (u.protocol !== 'https:' || u.username || u.password) return null;
  if (u.port && u.port !== '443') return null;
  if (!DL_HOSTS.some((re) => re.test(u.hostname))) return null;
  return u.href;
}
// the URL the API returns must also be https and must not point at private/internal hosts (SSRF guard)
function dlSafeMediaUrl(raw) {
  let u;
  try { u = new URL(String(raw || '')); } catch { return null; }
  if (u.protocol !== 'https:' || u.username || u.password) return null;
  const h = u.hostname.toLowerCase();
  if (/^(localhost|0\.0\.0\.0)$/.test(h) || h.includes(':') || /^\d{1,3}(\.\d{1,3}){3}$/.test(h)) return null;
  if (!h.includes('.') || /\.(local|internal|lan|localdomain|home|corp|intranet|test|invalid|example)$/.test(h)) return null;
  return u.href;
}
async function cobaltCall(env, url) {
  const base = String(env.COBALT_API_URL || '').replace(/\/+$/, '');
  if (!base) return { error: 'دانلودر پیکربندی نشده (مالک بات باید COBALT_API_URL رو تنظیم کنه).' };
  const headers = { 'content-type': 'application/json', accept: 'application/json' };
  if (env.COBALT_API_KEY) headers.authorization = `Api-Key ${env.COBALT_API_KEY}`;
  let r;
  try {
    r = await fetch(`${base}/`, { method: 'POST', headers, body: JSON.stringify({ url }), signal: AbortSignal.timeout(20000) });
  } catch (e) {
    return { error: /timeout|abort/i.test(e.message) ? 'سرویس دانلودر دیر جواب داد؛ دوباره امتحان کن.' : 'به سرویس دانلودر وصل نشد.' };
  }
  let j = null;
  try { j = await r.json(); } catch { /* not json */ }
  if (!j || typeof j !== 'object') return { error: `پاسخ نامعتبر از سرویس دانلودر (HTTP ${r.status}).` };
  if (j.status === 'error') {
    const code = String(j.error?.code || '');
    return { error: DL_ERR_FA[code] || 'سرویس دانلودر خطا داد؛ بعداً امتحان کن.' };
  }
  if (j.status === 'tunnel' || j.status === 'redirect') {
    const u = dlSafeMediaUrl(j.url);
    if (!u) return { error: 'لینک رسانه‌ی برگشتی از سرویس معتبر نیست.' };
    return { items: [{ url: u, filename: String(j.filename || '') }] };
  }
  if (j.status === 'picker') {
    const items = (Array.isArray(j.picker) ? j.picker : []).map((x) => ({ url: dlSafeMediaUrl(x?.url), type: String(x?.type || '') })).filter((x) => x.url).slice(0, 5);
    if (!items.length) return { error: 'موردی برای نمایش پیدا نشد.' };
    return { items, picker: true };
  }
  if (j.status === 'local-processing') return { error: 'این رسانه نیاز به پردازش جدا دارد و در این بات پشتیبانی نمی‌شه.' };
  return { error: 'پاسخ ناشناخته از سرویس دانلودر.' };
}
function dlKindOf(item) {
  const f = (item.filename || item.url || '').toLowerCase().split('?')[0];
  if (/\.(jpe?g|png|webp)$/.test(f) || item.type === 'photo') return 'photo';
  if (/\.(mp4|mov|webm|m4v)$/.test(f) || item.type === 'video') return 'video';
  if (/\.(mp3|m4a|ogg|opus|wav|flac)$/.test(f) || item.type === 'audio') return 'audio';
  return 'document';
}
// the bot does not download anything: Telegram fetches the URL itself; if that fails the user still gets the link
async function dlDeliver(env, m, items, inGroup) {
  const chat = m.chat.id;
  const base = { chat_id: chat, ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) };
  let sentAny = false;
  for (const it of items) {
    const k = dlKindOf(it);
    const method = { photo: 'sendPhoto', video: 'sendVideo', audio: 'sendAudio', document: 'sendDocument' }[k];
    const field = k === 'document' ? 'document' : k;
    const r = await tg(env, method, { ...base, [field]: it.url, caption: '📥 دانلود شد' });
    if (r.ok) sentAny = true;
    else await tg(env, 'sendMessage', { ...base, text: `⚠️ تلگرام نتونست این رسانه رو مستقیم بفرسته (${explainTg(r).replace(/^⚠️ /, '')}).\nلینک مستقیم: ${it.url}`, link_preview_options: { is_disabled: true } });
  }
  return sentAny;
}
async function dlHandle(env, m, rawUrl, inGroup, userId, moduleOn) {
  const say = (t) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t, ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  if (!moduleOn) return say('📥 دانلودر در این چت خاموشه.');
  const url = dlValidUrl(rawUrl);
  if (!url) return say('❌ فقط لینک https از اینستاگرام، تیک‌تاک، یوتیوب، ایکس (توییتر) یا فیسبوک قبول می‌شه.');
  if (!rateOk(`dl:${userId}`, 5, 600000)) return say('⏳ هر ۱۰ دقیقه حداکثر ۵ دانلود. کمی صبر کن.');
  await tg(env, 'sendChatAction', { chat_id: m.chat.id, action: 'upload_video' });
  const res = await cobaltCall(env, url);
  if (res.error) return say(`❌ ${res.error}`);
  const ok = await dlDeliver(env, m, res.items, inGroup);
  if (!ok) return say('❌ رسانه برگشت، ولی تلگرام نتونست بفرستدش. لینک‌ها بالا هست.');
  return null;
}
const DL_CMD = /^(\/dl|\/download|دانلود)(@\S+)?\s+(\S+)/i;
const dlGroupOn = (g) => g.dl !== false;
const dlGlobalOn = async (env) => (await env.KV.get('cfg:dl')) !== 'off';

// ======================= ARCHIVE (D1; personal items + group-shared items) =======================
const ARCH = { max: 500, body: 2000, tags: 5, page: 8, title: 80 };
let archReady = false;
const ARCH_SCHEMA = [
  "CREATE TABLE IF NOT EXISTS archive_items (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL, chat_id INTEGER NOT NULL DEFAULT 0, visibility TEXT NOT NULL DEFAULT 'private' CHECK (visibility IN ('private','group')), title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', search TEXT NOT NULL DEFAULT '', src_chat INTEGER, src_msg INTEGER, created INTEGER NOT NULL, updated INTEGER NOT NULL)",
  'CREATE INDEX IF NOT EXISTS idx_arch_owner ON archive_items (owner_id, chat_id)',
  'CREATE INDEX IF NOT EXISTS idx_arch_group ON archive_items (chat_id, visibility)',
];
async function archInit(env) {
  if (archReady || !env.DB) return;
  await env.DB.batch(ARCH_SCHEMA.map((q) => env.DB.prepare(q)));
  archReady = true;
}
const archOn = async (env) => (await env.KV.get('cfg:arch')) !== 'off';
const likeEsc = (q) => q.replace(/[\\%_]/g, (c) => '\\' + c);
// the visibility rule, enforced in SQL for every read and write
function archWhere(uid, scope) {
  if (!scope) return { sql: 'owner_id = ? AND chat_id = 0', args: [uid] };
  return { sql: '((owner_id = ? AND chat_id = ?) OR (chat_id = ? AND visibility = ?))', args: [uid, scope, scope, 'group'] };
}
function archParse(raw) {
  const text = String(raw || '').trim();
  let title = '';
  let body = text;
  const bar = text.indexOf('|');
  if (bar > 0 && bar <= ARCH.title + 1 && !text.slice(0, bar).includes('\n')) { title = text.slice(0, bar).trim(); body = text.slice(bar + 1).trim(); }
  const tags = [...new Set([...body.matchAll(/#([\p{L}\p{N}_]{1,30})/gu)].map((x) => x[1].toLowerCase()))].slice(0, ARCH.tags);
  const url = (body.match(/https?:\/\/[^\s<>"']+/i) || [''])[0].slice(0, 500);
  body = body.slice(0, ARCH.body);
  title = (title || body.replace(/\s+/g, ' ').slice(0, ARCH.title) || url).slice(0, ARCH.title);
  return { title, body, url, tags };
}
async function archAdd(env, uid, scope, raw, src) {
  await archInit(env);
  const p = archParse(raw);
  if (!p.body) return { error: 'متنی برای ذخیره نیست.' };
  const cnt = await env.DB.prepare('SELECT COUNT(*) AS n FROM archive_items WHERE owner_id = ?').bind(uid).first();
  if (Number(cnt?.n || 0) >= ARCH.max) return { error: `به سقف ${ARCH.max} مورد رسیدی؛ اول چیزی رو پاک کن.` };
  const now = Date.now();
  const tagStr = p.tags.join(' ');
  const r = await env.DB.prepare('INSERT INTO archive_items (owner_id, chat_id, visibility, title, body, url, tags, search, src_chat, src_msg, created, updated) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
    .bind(uid, scope || 0, 'private', p.title, p.body, p.url, tagStr, norm([p.title, p.body, tagStr, p.url].join(' ')), src?.chat ?? null, src?.msg ?? null, now, now).run();
  return { id: Number(r.meta?.last_row_id) };
}
async function archPage(env, uid, scope, page, q) {
  await archInit(env);
  const w = archWhere(uid, scope);
  let where = w.sql;
  const args = [...w.args];
  if (q) {
    where += " AND (search LIKE ? ESCAPE '\\' OR tags LIKE ? ESCAPE '\\' OR url LIKE ? ESCAPE '\\')";
    const L = `%${likeEsc(norm(q))}%`;
    args.push(L, L, L);
  }
  const tot = await env.DB.prepare(`SELECT COUNT(*) AS n FROM archive_items WHERE ${where}`).bind(...args).first();
  const rows = await env.DB.prepare(`SELECT id, title, tags, url, created, owner_id, visibility FROM archive_items WHERE ${where} ORDER BY id DESC LIMIT ? OFFSET ?`).bind(...args, ARCH.page, page * ARCH.page).all();
  return { total: Number(tot?.n || 0), rows: rows?.results || [] };
}
async function archGet(env, uid, scope, id) {
  await archInit(env);
  const w = archWhere(uid, scope);
  return env.DB.prepare(`SELECT * FROM archive_items WHERE id = ? AND ${w.sql}`).bind(id, ...w.args).first();
}
async function archDel(env, uid, scope, id, isAdmin) {
  const it = await archGet(env, uid, scope, id);
  if (!it) return { error: 'همچین موردی پیدا نشد.' };
  if (it.owner_id !== uid && !(isAdmin && scope && it.visibility === 'group')) return { error: 'فقط صاحب مورد یا ادمین گروه (برای موارد اشتراکی) می‌تونه حذفش کنه.' };
  await env.DB.prepare('DELETE FROM archive_items WHERE id = ?').bind(id).run();
  return { ok: true, title: it.title };
}
async function archVis(env, uid, scope, id, vis) {
  if (!scope) return { error: 'اشتراک‌گذاری فقط داخل گروه ممکنه.' };
  const it = await archGet(env, uid, scope, id);
  if (!it || it.owner_id !== uid) return { error: 'فقط صاحب مورد می‌تونه تغییرش بده.' };
  await env.DB.prepare('UPDATE archive_items SET visibility = ?, updated = ? WHERE id = ? AND owner_id = ?').bind(vis, Date.now(), id, uid).run();
  return { ok: true, title: it.title };
}
async function archClear(env, uid, scope) {
  await archInit(env);
  const r = await env.DB.prepare('DELETE FROM archive_items WHERE owner_id = ? AND chat_id = ?').bind(uid, scope || 0).run();
  return Number(r.meta?.changes || 0);
}
const ARCH_HELP = [
  '🗂 آرشیو',
  '/archive add [عنوان |] متن یا لینک #برچسب',
  '/archive list [صفحه]  ·  /archive find کلمه  ·  /archive get شماره',
  '/archive del شماره  ·  /archive clear yes (فقط موارد همین چت)',
  'داخل گروه: /archive share شماره (اشتراک با اعضای همین گروه)  ·  /archive private شماره',
  'فقط موارد خودت دیده میشن؛ موارد اشتراکی فقط داخل همان گروه.',
].join('\n');
const archLine = (env, r) => `#${r.id} • ${r.title}${r.tags ? ` — ${r.tags.split(' ').map((t) => '#' + t).join(' ')}` : ''}${r.visibility === 'group' ? ' 👥' : ''} (${localParts(env, r.created).date})`;
function archKb(scope, page, total) {
  const nav = [];
  if (page > 0) nav.push({ text: '◀️ قبلی', callback_data: `ar:${scope}:${page - 1}` });
  if ((page + 1) * ARCH.page < total) nav.push({ text: 'بعدی ▶️', callback_data: `ar:${scope}:${page + 1}` });
  return nav.length ? [nav] : null;
}
function archListText(env, res, page) {
  const from = page * ARCH.page + 1;
  if (!res.total) return '🗂 چیزی توی آرشیو نیست.';
  return `🗂 آرشیو (${res.total} مورد) — صفحه ${Math.floor(page) + 1} از ${Math.ceil(res.total / ARCH.page)}\n` + res.rows.map((r) => archLine(env, r)).join('\n') + `\n(موارد ${from} تا ${from + res.rows.length - 1})`;
}
async function archCmd(env, m, scope, text, uid, isOwner, inGroup) {
  const send = (t, kb) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t, ...(kb ? { reply_markup: { inline_keyboard: kb } } : {}), ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const subRaw = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(subRaw.length).trim();
  if (!subRaw || subRaw === 'help' || subRaw === 'راهنما') return send(ARCH_HELP);
  if (subRaw === 'on' || subRaw === 'off') {
    if (!isOwner) return send('فقط مالک بات می‌تونه آرشیو رو روشن یا خاموش کنه.');
    await env.KV.put('cfg:arch', subRaw);
    return send(`🗂 آرشیو: ${subRaw === 'on' ? 'روشن' : 'خاموش'}`);
  }
  if (!(await archOn(env))) return send('🗂 آرشیو در حال حاضر خاموشه.');
  if (!env.DB) return send('🗂 آرشیو نیاز به دیتابیس D1 داره (binding به نام DB). مالک بات باید وصلش کنه.');
  if (!rateOk(`arch:${uid}`, 20, 60000)) return send('⏳ آروم‌تر؛ هر دقیقه حداکثر ۲۰ عملیات آرشیو.');
  const isAdmin = inGroup && scope ? await isAdminOf(env, scope, uid) : false;
  try {
    if (subRaw === 'add') {
      if (!rest) return send('مثال: /archive add عنوان | متن یا لینک #برچسب');
      const r = await archAdd(env, uid, scope, rest, { chat: m.chat.id, msg: m.message_id });
      if (r.error) return send(`❌ ${r.error}`);
      return send(`✅ ذخیره شد #${r.id}`);
    }
    if (subRaw === 'list' || subRaw === 'find') {
      const q = subRaw === 'find' ? rest : '';
      if (subRaw === 'find' && !q) return send('مثال: /archive find کلمه');
      const page = subRaw === 'list' ? Math.max(0, (parseInt(rest, 10) || 1) - 1) : 0;
      const res = await archPage(env, uid, scope, page, q);
      if (subRaw === 'find' && !res.total) return send(`🔎 چیزی با «${q}» پیدا نشد.`);
      const txt = subRaw === 'find' ? `🔎 نتایج «${q}» (${res.total} مورد)\n` + res.rows.map((r) => archLine(env, r)).join('\n') : archListText(env, res, page);
      return send(txt, subRaw === 'list' ? archKb(scope, page, res.total) : null);
    }
    const id = parseInt(rest, 10);
    if (['get', 'del', 'share', 'private'].includes(subRaw) && !(id > 0)) return send('شماره‌ی مورد رو بنویس. مثال: /archive get 12');
    if (subRaw === 'get') {
      const it = await archGet(env, uid, scope, id);
      if (!it) return send('همچین موردی پیدا نشد.');
      return send(`${archLine(env, it)}\n\n${it.body}${it.url ? `\n\n🔗 ${it.url}` : ''}`);
    }
    if (subRaw === 'del') {
      const r = await archDel(env, uid, scope, id, isAdmin);
      return send(r.error ? `❌ ${r.error}` : `🗑 «${r.title}» حذف شد.`);
    }
    if (subRaw === 'share' || subRaw === 'private') {
      const r = await archVis(env, uid, scope, id, subRaw === 'share' ? 'group' : 'private');
      if (r.error) return send(`❌ ${r.error}`);
      return send(subRaw === 'share' ? `👥 «${r.title}» با اعضای این گروه به اشتراک گذاشته شد.` : `🔒 «${r.title}» دوباره خصوصی شد.`);
    }
    if (subRaw === 'clear') {
      if (rest.toLowerCase() !== 'yes') return send('⚠️ این فقط موارد خودت توی همین چت رو پاک می‌کنه.\nبرای تأیید بنویس: /archive clear yes');
      const n = await archClear(env, uid, scope);
      return send(`🗑 ${n} مورد حذف شد.`);
    }
    return send(ARCH_HELP);
  } catch (e) {
    console.error('archive', e);
    return send('⚠️ خطا در آرشیو؛ دوباره امتحان کن.');
  }
}
async function archCallback(env, cq) {
  const ans = (t, a) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: t, show_alert: !!a } : {}) });
  const [, scopeS, pageS] = (cq.data || '').split(':');
  const chat = cq.message?.chat;
  if (!chat) return ans();
  const here = chat.type === 'private' ? 0 : chat.id;
  if (Number(scopeS) !== here) return ans('این صفحه مال این چت نیست', true);
  if (!env.DB || !rateOk(`arch:${cq.from.id}`, 20, 60000)) return ans('⏳ آروم‌تر', true);
  const page = Math.max(0, parseInt(pageS, 10) || 0);
  try {
    const res = await archPage(env, cq.from.id, here, page, '');
    await tg(env, 'editMessageText', { chat_id: chat.id, message_id: cq.message.message_id, text: archListText(env, res, page), reply_markup: archKb(here, page, res.total) ? { inline_keyboard: archKb(here, page, res.total) } : undefined });
  } catch (e) {
    console.error('archive cb', e);
    return ans('خطا در آرشیو', true);
  }
  return ans();
}

// ======================= SITE & API MONITORING (D1 + Cron) =======================
// Checks run from the existing Cron Trigger (every minute), a few monitors per run; redirects are NOT followed (SSRF).
const MON = { perOwner: 10, perChat: 20, minMin: 5, maxMin: 1440, hist: 50, runLimit: 4, timeoutMs: 8000 };
let monReady = false;
const MON_SCHEMA = [
  "CREATE TABLE IF NOT EXISTS monitors (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL, chat_id INTEGER NOT NULL DEFAULT 0, alert_chat INTEGER NOT NULL, url TEXT NOT NULL, interval_sec INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'unknown' CHECK (state IN ('unknown','up','down')), last_code INTEGER, last_ms INTEGER, last_checked INTEGER, down_since INTEGER, created INTEGER NOT NULL)",
  "CREATE TABLE IF NOT EXISTS monitor_checks (id INTEGER PRIMARY KEY AUTOINCREMENT, monitor_id INTEGER NOT NULL, t INTEGER NOT NULL, code INTEGER, ms INTEGER, ok INTEGER NOT NULL, err TEXT)",
  'CREATE INDEX IF NOT EXISTS idx_mon_due ON monitors (enabled, last_checked)',
  'CREATE INDEX IF NOT EXISTS idx_mon_chk ON monitor_checks (monitor_id, t)',
];
async function monInit(env) {
  if (monReady || !env.DB) return;
  await env.DB.batch(MON_SCHEMA.map((q) => env.DB.prepare(q)));
  monReady = true;
}
const monOn = async (env) => (await env.KV.get('cfg:mon')) !== 'off';
// public https only: no credentials, default port, no IP literals, no internal/local names
function monUrlOk(raw) {
  let u;
  try { u = new URL(String(raw || '').trim()); } catch { return null; }
  if (u.protocol !== 'https:' || u.username || u.password || (u.port && u.port !== '443')) return null;
  const h = u.hostname.toLowerCase();
  if (h.includes(':') || /^\d{1,3}(\.\d{1,3}){3}$/.test(h) || !h.includes('.')) return null;
  if (/^(localhost|0\.0\.0\.0)$/.test(h) || /\.(local|internal|lan|localdomain|home|corp|intranet|test|invalid|example)$/.test(h)) return null;
  if (u.href.length > 500) return null;
  return u.href;
}
async function monProbe(url) {
  const t0 = Date.now();
  try {
    const r = await fetch(url, { method: 'GET', redirect: 'manual', headers: { 'user-agent': 'UptimeCheck/1.0', accept: '*/*' }, signal: AbortSignal.timeout(MON.timeoutMs) });
    try { await r.body?.cancel(); } catch { /* ignore */ }
    return { code: r.status, ms: Date.now() - t0, ok: r.status >= 200 && r.status < 400, err: '' };
  } catch (e) {
    return { code: null, ms: Date.now() - t0, ok: false, err: /abort|timeout/i.test(e.message || '') ? 'timeout' : 'network' };
  }
}
const monWhere = (uid, scope) => (scope ? { sql: 'chat_id = ?', args: [scope] } : { sql: 'owner_id = ? AND chat_id = 0', args: [uid] });
async function monAdd(env, uid, scope, url, minutes) {
  await monInit(env);
  const u = monUrlOk(url);
  if (!u) return { error: 'آدرس باید https عمومی و معتبر باشه (IP، آدرس داخلی و پورت غیراستاندارد قبول نیست).' };
  const mins = Math.round(minutes);
  if (!(mins >= MON.minMin && mins <= MON.maxMin)) return { error: `فاصله‌ی بررسی بین ${toFa(MON.minMin)} و ${toFa(MON.maxMin)} دقیقه باشه.` };
  const w = monWhere(uid, scope);
  const c = await env.DB.prepare(`SELECT COUNT(*) AS n FROM monitors WHERE ${w.sql}`).bind(...w.args).first();
  const cap = scope ? MON.perChat : MON.perOwner;
  if (Number(c?.n || 0) >= cap) return { error: scope ? `هر گروه حداکثر ${toFa(MON.perChat)} آدرس.` : `هر کاربر حداکثر ${toFa(MON.perOwner)} آدرس.` };
  const alertChat = scope || uid;
  const r = await env.DB.prepare("INSERT INTO monitors (owner_id, chat_id, alert_chat, url, interval_sec, enabled, state, created) VALUES (?, ?, ?, ?, ?, 1, 'unknown', ?)")
    .bind(uid, scope || 0, alertChat, u, mins * 60, Date.now()).run();
  return { id: Number(r.meta?.last_row_id), url: u, mins };
}
function monAlertText(mo, p, st, now, downSince) {
  const host = new URL(mo.url).hostname;
  if (st === 'down') return `🔴 قطع شد: ${host}\nکد: ${p.code ?? '—'} ${p.err ? `(${p.err})` : ''}\n${mo.url}`;
  const mins = downSince ? Math.max(1, Math.round((now - downSince) / 60000)) : 0;
  return `🟢 برگشت: ${host}\nکد: ${p.code}\nمدت قطعی: ${mins} دقیقه\n${mo.url}`;
}
// called from the Cron Trigger: only due monitors, a few per run; alerts only on real transitions
async function runMonitors(env) {
  if (!env.DB || !(await monOn(env))) return;
  await monInit(env);
  const now = Date.now();
  const due = await env.DB.prepare("SELECT * FROM monitors WHERE enabled = 1 AND (last_checked IS NULL OR last_checked + interval_sec * 1000 <= ?) ORDER BY COALESCE(last_checked, 0) LIMIT ?").bind(now, MON.runLimit).all();
  for (const mo of due.results || []) {
    const p = await monProbe(mo.url);
    const st = p.ok ? 'up' : 'down';
    await env.DB.prepare('INSERT INTO monitor_checks (monitor_id, t, code, ms, ok, err) VALUES (?, ?, ?, ?, ?, ?)').bind(mo.id, now, p.code, p.ms, p.ok ? 1 : 0, p.err).run();
    await env.DB.prepare('DELETE FROM monitor_checks WHERE monitor_id = ? AND id NOT IN (SELECT id FROM monitor_checks WHERE monitor_id = ? ORDER BY id DESC LIMIT ?)').bind(mo.id, mo.id, MON.hist).run();
    const downSince = st === 'down' ? (mo.state === 'down' && mo.down_since ? mo.down_since : now) : null;
    await env.DB.prepare('UPDATE monitors SET state = ?, last_code = ?, last_ms = ?, last_checked = ?, down_since = ? WHERE id = ?').bind(st, p.code, p.ms, now, downSince, mo.id).run();
    const alert = (st === 'down' && mo.state !== 'down') || (st === 'up' && mo.state === 'down');
    if (alert) await tg(env, 'sendMessage', { chat_id: mo.alert_chat, text: monAlertText(mo, p, st, now, mo.down_since || downSince) });
  }
}
const MON_HELP = [
  '📡 پایش سایت و API',
  '/monitor add <آدرس https> [دقیقه]   (پیش‌فرض ۱۰)',
  '/monitor list  ·  /monitor history شماره  ·  /monitor del شماره',
  '/monitor pause شماره  ·  /monitor resume شماره',
  'داخل گروه: ساختن/حذف/توقف فقط برای ادمین‌ها؛ هشدارها به همان گروه میرن.',
  'مالک: /monitor on|off',
].join('\n');
const monLine = (r) => `#${r.id} ${r.state === 'up' ? '🟢' : r.state === 'down' ? '🔴' : '⚪️'} ${new URL(r.url).hostname}${r.enabled ? '' : ' (متوقف)'} — هر ${toFa(Math.round(r.interval_sec / 60))} دقیقه — کد ${r.last_code ?? '—'}${r.last_ms != null ? ` — ${r.last_ms}ms` : ''}`;
async function monCmd(env, m, scope, text, uid, isOwner, inGroup) {
  const send = (t) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t, ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const subRaw = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(subRaw.length).trim();
  if (!subRaw || subRaw === 'help' || subRaw === 'راهنما') return send(MON_HELP);
  if (subRaw === 'on' || subRaw === 'off') {
    if (!isOwner) return send('فقط مالک بات می‌تونه پایش رو روشن یا خاموش کنه.');
    await env.KV.put('cfg:mon', subRaw);
    return send(`📡 پایش: ${subRaw === 'on' ? 'روشن' : 'خاموش'}`);
  }
  if (!(await monOn(env))) return send('📡 پایش در حال حاضر خاموشه.');
  if (!env.DB) return send('📡 پایش نیاز به دیتابیس D1 داره (binding به نام DB).');
  if (!rateOk(`mon:${uid}`, 20, 60000)) return send('⏳ آروم‌تر؛ هر دقیقه حداکثر ۲۰ دستور پایش.');
  const isAdmin = inGroup && scope ? await isAdminOf(env, scope, uid) : !inGroup;
  try {
    await monInit(env);
    const w = monWhere(uid, scope);
    if (subRaw === 'add') {
      if (inGroup && !isAdmin) return send('فقط ادمین‌های گروه می‌تونن آدرس اضافه کنن.');
      const parts = rest.split(/\s+/);
      const mins = parts.length > 1 ? Number(parts[parts.length - 1]) : 10;
      const url = parts.length > 1 && Number.isFinite(mins) && parts.length > 1 ? parts.slice(0, -1).join(' ') : rest;
      if (!url) return send('مثال: /monitor add https://example.com/health 5');
      const r = await monAdd(env, uid, scope, url, Number.isFinite(mins) ? mins : 10);
      if (r.error) return send(`❌ ${r.error}`);
      return send(`✅ پایش شد #${r.id}: ${new URL(r.url).hostname} — هر ${toFa(r.mins)} دقیقه.\nهشدار به ${inGroup ? 'این گروه' : 'پیوی تو'} میره.`);
    }
    if (subRaw === 'list' || subRaw === 'status') {
      const rows = await env.DB.prepare(`SELECT * FROM monitors WHERE ${w.sql} ORDER BY id DESC LIMIT 20`).bind(...w.args).all();
      if (!rows.results?.length) return send('📡 آدرسی تحت پایش نیست.');
      return send('📡 وضعیت فعلی\n' + rows.results.map(monLine).join('\n'));
    }
    const id = parseInt(rest, 10);
    if (!(id > 0)) return send('شماره‌ی پایش رو بنویس. مثال: /monitor history 3');
    const mo = await env.DB.prepare(`SELECT * FROM monitors WHERE id = ? AND ${w.sql}`).bind(id, ...w.args).first();
    if (!mo) return send('همچین پایشی پیدا نشد.');
    if (subRaw === 'history') {
      const h = await env.DB.prepare('SELECT t, code, ms, ok, err FROM monitor_checks WHERE monitor_id = ? ORDER BY id DESC LIMIT 15').bind(id).all();
      const ln = (x) => `${new Date(x.t).toISOString().slice(5, 16).replace('T', ' ')} ${x.ok ? '✅' : '❌'} ${x.code ?? '—'}${x.ms != null ? ` ${x.ms}ms` : ''}${x.err ? ` (${x.err})` : ''}`;
      return send(`📈 تاریخچه #${id} (UTC)\n` + ((h.results || []).map(ln).join('\n') || 'هنوز بررسی نشده.'));
    }
    if (inGroup && !isAdmin) return send('فقط ادمین‌های گروه می‌تونه این کار رو بکنه.');
    if (subRaw === 'del') {
      await env.DB.prepare('DELETE FROM monitor_checks WHERE monitor_id = ?').bind(id).run();
      await env.DB.prepare('DELETE FROM monitors WHERE id = ?').bind(id).run();
      return send(`🗑 پایش #${id} حذف شد.`);
    }
    if (subRaw === 'pause' || subRaw === 'resume') {
      await env.DB.prepare('UPDATE monitors SET enabled = ? WHERE id = ?').bind(subRaw === 'resume' ? 1 : 0, id).run();
      return send(subRaw === 'resume' ? `▶️ پایش #${id} دوباره فعال شد.` : `⏸ پایش #${id} متوقف شد.`);
    }
    return send(MON_HELP);
  } catch (e) {
    console.error('monitor', e);
    return send('⚠️ خطا در پایش؛ دوباره امتحان کن.');
  }
}

// ======================= ANALYTICS (D1; collected from the moment it is deployed) =======================
const AN_SCHEMA = [
  "CREATE TABLE IF NOT EXISTS msg_hourly (chat_id INTEGER NOT NULL, day TEXT NOT NULL, hour INTEGER NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (chat_id, day, hour))",
  "CREATE TABLE IF NOT EXISTS member_events (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('join','leave')), day TEXT NOT NULL, t INTEGER NOT NULL)",
  'CREATE INDEX IF NOT EXISTS idx_mev ON member_events (chat_id, day)',
];
let anReady = false;
async function anInit(env) {
  if (anReady || !env.DB) return;
  try { await env.DB.batch(AN_SCHEMA.map((q) => env.DB.prepare(q))); anReady = true; } catch (e) { console.error('analytics init', e); }
}
// one row per group per hour; called for every counted human message
async function recordHour(env, chatId) {
  await anInit(env);
  const lp = localParts(env);
  await env.DB.prepare('INSERT INTO msg_hourly (chat_id, day, hour, n) VALUES (?, ?, ?, 1) ON CONFLICT(chat_id, day, hour) DO UPDATE SET n = n + 1').bind(chatId, lp.date, lp.h).run();
}
// service messages: only what Telegram actually delivers to the bot (bots are never counted)
async function recordMembers(env, m) {
  if (!env.DB) return;
  const joins = (m.new_chat_members || []).filter((u) => !u.is_bot);
  const left = m.left_chat_member && !m.left_chat_member.is_bot ? [m.left_chat_member] : [];
  if (!joins.length && !left.length) return;
  await anInit(env);
  const day = localParts(env).date;
  const t = Date.now();
  const stmts = [
    ...joins.map((u) => env.DB.prepare("INSERT INTO member_events (chat_id, user_id, kind, day, t) VALUES (?, ?, 'join', ?, ?)").bind(m.chat.id, u.id, day, t)),
    ...left.map((u) => env.DB.prepare("INSERT INTO member_events (chat_id, user_id, kind, day, t) VALUES (?, ?, 'leave', ?, ?)").bind(m.chat.id, u.id, day, t)),
  ];
  await env.DB.batch(stmts);
}
const dayBack = (env, n) => localParts(env, Date.now() - n * 86400000).date;
async function anPeriod(env, chatId, since) {
  const one = (sql, ...a) => env.DB.prepare(sql).bind(...a).first();
  const msgs = await one('SELECT COALESCE(SUM(n), 0) AS n FROM msg_stats WHERE chat_id = ? AND day >= ?', chatId, since);
  const active = await one('SELECT COUNT(DISTINCT user_id) AS n FROM msg_stats WHERE chat_id = ? AND day >= ? AND n > 0', chatId, since);
  const joins = await one("SELECT COUNT(*) AS n FROM member_events WHERE chat_id = ? AND day >= ? AND kind = 'join'", chatId, since);
  const leaves = await one("SELECT COUNT(*) AS n FROM member_events WHERE chat_id = ? AND day >= ? AND kind = 'leave'", chatId, since);
  return { msgs: Number(msgs?.n || 0), active: Number(active?.n || 0), joins: Number(joins?.n || 0), leaves: Number(leaves?.n || 0) };
}
// every number here comes from rows the bot actually recorded; nothing is estimated or back-filled
async function analyticsData(env, chatId) {
  if (!env.DB) return { error: 'آمار دقیق نیاز به D1 داره (binding به نام DB).' };
  await d1Init(env);
  await anInit(env);
  const first = await env.DB.prepare('SELECT MIN(day) AS d FROM msg_stats WHERE chat_id = ?').bind(chatId).first();
  if (!first?.d) return { empty: true };
  const today = localParts(env).date;
  const since7 = dayBack(env, 6);
  const since30 = dayBack(env, 29);
  const hourRows = (await env.DB.prepare('SELECT hour, SUM(n) AS n FROM msg_hourly WHERE chat_id = ? AND day >= ? GROUP BY hour').bind(chatId, since30).all()).results || [];
  const byHour = new Array(24).fill(0);
  for (const r of hourRows) byHour[Number(r.hour)] = Number(r.n);
  const dayRows = (await env.DB.prepare('SELECT day, SUM(n) AS n FROM msg_stats WHERE chat_id = ? AND day >= ? GROUP BY day').bind(chatId, since30).all()).results || [];
  const WD = ['یک‌شنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنج‌شنبه', 'جمعه', 'شنبه'];
  const byWd = new Array(7).fill(0);
  for (const r of dayRows) byWd[new Date(`${r.day}T12:00:00Z`).getUTCDay()] += Number(r.n);
  const top = (await env.DB.prepare('SELECT user_id, MAX(name) AS name, SUM(n) AS n FROM msg_stats WHERE chat_id = ? AND day >= ? GROUP BY user_id ORDER BY n DESC LIMIT 10').bind(chatId, since7).all()).results || [];
  const memDays = (await env.DB.prepare("SELECT day, kind, COUNT(*) AS n FROM member_events WHERE chat_id = ? AND day >= ? GROUP BY day, kind ORDER BY day DESC").bind(chatId, since7).all()).results || [];
  return {
    first: first.d,
    today,
    day: await anPeriod(env, chatId, today),
    week: await anPeriod(env, chatId, since7),
    month: await anPeriod(env, chatId, since30),
    byHour,
    wd: WD.map((name, i) => ({ name, n: byWd[i] })),
    top: top.map((r) => ({ name: r.name || String(r.user_id), n: Number(r.n) })),
    members: memDays.map((r) => ({ day: r.day, kind: r.kind, n: Number(r.n) })),
  };
}
const AN_VIEWS = ['sum', 'hours', 'users', 'members'];
const AN_BARS = ' ▁▂▃▄▅▆▇█';
function anRender(env, title, d, view) {
  if (d.error) return `❌ ${d.error}`;
  if (d.empty) return `📊 ${title}\nهنوز داده‌ای جمع‌آوری نشده. آمار از اولین پیامی که بات توی این گروه می‌بینه شروع میشه.`;
  const head = `📊 گزارش آمار «${title}»\nجمع‌آوری از ${toFa(d.first)} تا امروز (فقط داده‌های واقعی از زمان فعال‌شدن؛ قبل از آن چیزی ثبت نشده).`;
  if (view === 'hours') {
    const max = Math.max(...d.byHour, 1);
    const bar = d.byHour.map((v) => AN_BARS[Math.round((v / max) * 8)]).join('');
    const topH = d.byHour.map((n, h) => ({ h, n })).filter((x) => x.n > 0).sort((a, b) => b.n - a.n).slice(0, 3);
    return `${head}\n\n⏰ ساعت‌های پرترافیک (۳۰ روز، به وقت ایران)\n[${bar}]\nبرترین ساعت‌ها: ${topH.map((x) => `${toFa(String(x.h).padStart(2, '0'))}:۰۰ (${toFa(x.n)})`).join('، ') || '—'}\n\n📅 روزهای هفته (۳۰ روز)\n${d.wd.map((x) => `${x.name}: ${toFa(x.n)} پیام`).join('\n')}`;
  }
  if (view === 'users') {
    return `${head}\n\n👥 فعال‌ترین کاربران (۷ روز)\n${d.top.map((u, i) => `${i + 1}. ${u.name} — ${toFa(u.n)} پیام`).join('\n') || '—'}\n\nکاربران فعال: ۷ روز ${toFa(d.week.active)} · ۳۰ روز ${toFa(d.month.active)}`;
  }
  if (view === 'members') {
    const rows = d.members.map((r) => `${r.day} ${r.kind === 'join' ? '➕ عضو جدید' : '➖ خروج'}: ${toFa(r.n)}`);
    return `${head}\n\n🧾 رویدادهای عضویت (۷ روز)\n${rows.join('\n') || 'رویدادی ثبت نشده.'}\n\n(فقط رویدادهایی که تلگرام به بات می‌فرسته ثبت میشن.)`;
  }
  return `${head}\n\n📝 پیام: امروز ${toFa(d.day.msgs)} | ۷ روز ${toFa(d.week.msgs)} | ۳۰ روز ${toFa(d.month.msgs)}\n👥 کاربر فعال: امروز ${toFa(d.day.active)} | ۷ روز ${toFa(d.week.active)} | ۳۰ روز ${toFa(d.month.active)}\n➕ عضو جدید: امروز ${toFa(d.day.joins)} | ۷ روز ${toFa(d.week.joins)} | ۳۰ روز ${toFa(d.month.joins)}\n➖ خروج: امروز ${toFa(d.day.leaves)} | ۷ روز ${toFa(d.week.leaves)} | ۳۰ روز ${toFa(d.month.leaves)}`;
}
const anKb = (chatId) => [[
  { text: '📋 خلاصه', callback_data: `an:${chatId}:sum` },
  { text: '⏰ ساعت‌ها', callback_data: `an:${chatId}:hours` },
], [
  { text: '👥 کاربران', callback_data: `an:${chatId}:users` },
  { text: '🧾 عضویت', callback_data: `an:${chatId}:members` },
]];
async function anCmd(env, m, chatId, uid, inGroup) {
  const send = (t, kb) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t, ...(kb ? { reply_markup: { inline_keyboard: kb } } : {}), ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  if (!inGroup) return send('📊 گزارش آمار فقط داخل گروه قابل‌دیدنه.');
  if (uid !== Number(env.OWNER_ID) && !(await isAdminOf(env, chatId, uid))) return send('این گزارش فقط برای ادمین‌های گروهه.');
  if (!rateOk(`an:${uid}`, 10, 60000)) return send('⏳ آروم‌تر؛ هر دقیقه حداکثر ۱۰ گزارش.');
  let d;
  try { d = await analyticsData(env, chatId); } catch (e) { console.error('analytics', e); d = { error: 'خطا در خواندن آمار؛ دوباره امتحان کن.' }; }
  return send(anRender(env, m.chat.title || 'گروه', d, 'sum'), d.error || d.empty ? null : anKb(chatId));
}
async function anCallback(env, cq) {
  const ans = (t, a) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: t, show_alert: !!a } : {}) });
  const [, scS, viewRaw] = (cq.data || '').split(':');
  const chat = cq.message?.chat;
  if (!chat || chat.type === 'private') return ans('فقط داخل گروه', true);
  if (Number(scS) !== chat.id) return ans('این گزارش مال این گروه نیست', true);
  if (cq.from.id !== Number(env.OWNER_ID) && !(await isAdminOf(env, chat.id, cq.from.id))) return ans('فقط ادمین‌های گروه', true);
  if (!rateOk(`an:${cq.from.id}`, 10, 60000)) return ans('⏳ آروم‌تر', true);
  const view = AN_VIEWS.includes(viewRaw) ? viewRaw : 'sum';
  let d;
  try { d = await analyticsData(env, chat.id); } catch (e) { console.error('analytics cb', e); return ans('خطا در خواندن آمار', true); }
  await tg(env, 'editMessageText', { chat_id: chat.id, message_id: cq.message.message_id, text: anRender(env, chat.title || 'گروه', d, view), reply_markup: { inline_keyboard: anKb(chat.id) } });
  return ans();
}

// ======================= WORD RULES (D1; per group, with actions and exemptions) =======================
const WR = { max: 100, actions: ['delete', 'warn', 'mute', 'log'] };
let wrReady = false;
const WR_SCHEMA = [
  "CREATE TABLE IF NOT EXISTS word_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, pattern TEXT NOT NULL, action TEXT NOT NULL CHECK (action IN ('delete','warn','mute','log')), enabled INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL)",
  'CREATE INDEX IF NOT EXISTS idx_wr_chat ON word_rules (chat_id, enabled)',
  'CREATE TABLE IF NOT EXISTS rule_exempt (chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, PRIMARY KEY (chat_id, user_id))',
];
async function wrInit(env) {
  if (wrReady || !env.DB) return;
  await env.DB.batch(WR_SCHEMA.map((q) => env.DB.prepare(q)));
  wrReady = true;
}
// Persian/Arabic variants and invisible marks; digits to latin; lowercase
const WR_MARKS = /[\u200c\u200d\u200e\u200f\u202a-\u202e\u0640\u064b-\u065f\u0670]/g;
function wrNorm(s) {
  return String(s || '').replace(WR_MARKS, '').replace(/[يىئ]/g, 'ی').replace(/[كک]/g, 'ک').replace(/ة/g, 'ه')
    .replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).toLowerCase();
}
// spaced form: words separated by one space, runs of the same letter collapsed ("بدددد" -> "بد")
const wrWords = (s) => wrNorm(s).replace(/[^\p{L}\p{N}]+/gu, ' ').replace(/(\p{L})\1+/gu, '$1').trim();
// flat form: no spaces at all, so "ب د ک ل م ه" still matches "بدکلمه"
const wrFlat = (s) => wrNorm(s).replace(/[^\p{L}\p{N}]+/gu, '').replace(/(\p{L})\1+/gu, '$1');
function wrMatch(text, pattern) {
  const p = wrWords(pattern);
  if (!p) return false;
  if (` ${wrWords(text)} `.includes(` ${p} `)) return true;
  const pf = p.replace(/ /g, '');
  return pf.length >= 4 && wrFlat(text).includes(pf); // evasion check only for longer patterns
}
const wrCache = new Map();
async function wrRules(env, chatId) {
  const c = wrCache.get(chatId);
  if (c && c.exp > Date.now()) return c.rules;
  await wrInit(env);
  const list = (await env.DB.prepare('SELECT id, pattern, action FROM word_rules WHERE chat_id = ? AND enabled = 1 ORDER BY id LIMIT ?').bind(chatId, WR.max).all()).results || [];
  const ex = new Set(((await env.DB.prepare('SELECT user_id FROM rule_exempt WHERE chat_id = ?').bind(chatId).all()).results || []).map((r) => r.user_id));
  const rules = { list, ex };
  if (wrCache.size > 500) wrCache.clear();
  wrCache.set(chatId, { rules, exp: Date.now() + 60000 });
  return rules;
}
const wrInvalidate = (chatId) => wrCache.delete(chatId);
async function wrCheck(env, m, text) {
  if (!env.DB || !text || !m.from) return null;
  const rules = await wrRules(env, m.chat.id);
  if (!rules.list.length || rules.ex.has(m.from.id)) return null;
  return rules.list.find((r) => wrMatch(text, r.pattern)) || null;
}
const WR_ACT_FA = { delete: 'حذف پیام', warn: 'اخطار', mute: 'میوت', log: 'فقط ثبت' };
const WR_ACT_ALIAS = { delete: 'delete', حذف: 'delete', warn: 'warn', اخطار: 'warn', mute: 'mute', میوت: 'mute', log: 'log', ثبت: 'log' };
async function wrCmd(env, m, g, text, isOwner) {
  const send = (t) => reply(env, m, t, true);
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const subRaw = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(subRaw.length).trim();
  const chatId = m.chat.id;
  const mine = (p) => (p ? p : p);
  if (!env.DB) return send('🚫 قانون کلمه نیاز به D1 داره (binding به نام DB).');
  if (subRaw === 'list' || subRaw === '') {
    if (!env.DB) return send('D1 وصل نیست.');
    await wrInit(env);
    const rows = (await env.DB.prepare('SELECT id, pattern, action, enabled FROM word_rules WHERE chat_id = ? ORDER BY id').bind(chatId).all()).results || [];
    const ex = (await env.DB.prepare('SELECT COUNT(*) AS n FROM rule_exempt WHERE chat_id = ?').bind(chatId).first())?.n || 0;
    if (!subRaw && !rows.length) return send(`🚫 قانون کلمه (هر گروه جدا)\n/rule add <کلمه یا عبارت> [حذف|اخطار|میوت|ثبت]\n/rule list · /rule del شماره · /rule on|off شماره\n/rule exempt @user|آیدی · /rule unexempt @user|آیدی\nادمین‌های گروه همیشه معافن. دورزدن ساده (فاصله، تکرار حرف، ی/ک عربی) تشخیص داده میشه.`);
    return send(`🚫 قانون‌های کلمه (${rows.length}/${WR.max})\n${rows.map((r) => `#${r.id} ${r.enabled ? '🟢' : '⚪️'} «${r.pattern}» → ${WR_ACT_FA[r.action]}`).join('\n') || 'هنوز نیست.'}\nمعاف‌شده‌ها: ${ex}`);
  }
  if (subRaw === 'add') {
    const parts = rest.split(/\s+/);
    const last = (parts[parts.length - 1] || '').toLowerCase();
    const act = WR_ACT_ALIAS[last] || 'delete';
    const pat = wrWords(WR_ACT_ALIAS[last] && parts.length > 1 ? parts.slice(0, -1).join(' ') : rest);
    if (pat.length < 2 || pat.length > 40) return send('عبارت باید بین ۲ و ۴۰ حرف باشه.');
    const cnt = (await env.DB.prepare('SELECT COUNT(*) AS n FROM word_rules WHERE chat_id = ?').bind(chatId).first())?.n || 0;
    if (cnt >= WR.max) return send(`به سقف ${WR.max} قانون رسیدی.`);
    await wrInit(env);
    const r = await env.DB.prepare('INSERT INTO word_rules (chat_id, pattern, action, enabled, created) VALUES (?, ?, ?, 1, ?)').bind(chatId, pat, act, Date.now()).run();
    wrInvalidate(chatId);
    await logAction(env, g, m, 'settings', { x: `rule+ ${pat}` });
    return send(`✅ قانون #${r.meta?.last_row_id} ساخته شد: «${pat}» → ${WR_ACT_FA[act]}\n(کلمه‌های کامل و دورزدن ساده هم گرفته میشن)`);
  }
  if (subRaw === 'del' || subRaw === 'on' || subRaw === 'off') {
    const id = parseInt(rest, 10);
    if (!(id > 0)) return send('شماره‌ی قانون رو بنویس. مثال: /rule del 3');
    if (subRaw === 'del') await env.DB.prepare('DELETE FROM word_rules WHERE id = ? AND chat_id = ?').bind(id, chatId).run();
    else await env.DB.prepare('UPDATE word_rules SET enabled = ? WHERE id = ? AND chat_id = ?').bind(subRaw === 'on' ? 1 : 0, id, chatId).run();
    wrInvalidate(chatId);
    return send(subRaw === 'del' ? `🗑 قانون #${id} حذف شد.` : `قانون #${id} ${subRaw === 'on' ? 'روشن' : 'خاموش'} شد.`);
  }
  if (subRaw === 'exempt' || subRaw === 'unexempt') {
    const t = await resolveTarget(env, m, rest);
    if (!t) return send('روی پیام کاربر ریپلای کن، یا @username / آیدی عددی بده.');
    if (t.error) return send(t.error);
    if (subRaw === 'exempt') await env.DB.prepare('INSERT OR IGNORE INTO rule_exempt (chat_id, user_id) VALUES (?, ?)').bind(chatId, t.id).run();
    else await env.DB.prepare('DELETE FROM rule_exempt WHERE chat_id = ? AND user_id = ?').bind(chatId, t.id).run();
    wrInvalidate(chatId);
    return send(subRaw === 'exempt' ? `✅ ${t.name} از قانون‌های کلمه معاف شد.` : `${t.name} دوباره تحت قانون‌هاست.`);
  }
  return send('دستور ناشناخته. /rule را بدون چیز دیگه بفرست تا راهنما ببینی.');
}

// ======================= RSS (D1 + Cron; new items only, first run seeds silently) =======================
const RSS = { max: 5, minMin: 15, maxMin: 1440, perRun: 3, seenCap: 300, items: 30, sendMax: 5, pauseAfter: 5, pauseSec: 6 * 3600 };
let rssReady = false;
const RSS_SCHEMA = [
  'CREATE TABLE IF NOT EXISTS rss_feeds (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, dest INTEGER NOT NULL, owner_id INTEGER NOT NULL, url TEXT NOT NULL, interval_sec INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, last_checked INTEGER, last_ok INTEGER, fail_count INTEGER NOT NULL DEFAULT 0, paused_until INTEGER, created INTEGER NOT NULL)',
  'CREATE TABLE IF NOT EXISTS rss_seen (id INTEGER PRIMARY KEY AUTOINCREMENT, feed_id INTEGER NOT NULL, item_key TEXT NOT NULL, t INTEGER NOT NULL)',
  'CREATE INDEX IF NOT EXISTS idx_rss_seen ON rss_seen (feed_id, item_key)',
];
async function rssInit(env) {
  if (rssReady || !env.DB) return;
  await env.DB.batch(RSS_SCHEMA.map((q) => env.DB.prepare(q)));
  rssReady = true;
}
const rssOn = async (env) => (await env.KV.get('cfg:rss')) !== 'off';
const rssStrip = (s) => String(s || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
// RSS 2.0 <item> and Atom <entry>; no XML library, bounded sizes
function rssParse(xml) {
  const blocks = [...String(xml).matchAll(/<(item|entry)\b[\s\S]*?<\/\1>/gi)].map((x) => x[0]).slice(0, RSS.items);
  const tag = (b, name) => { const mt = b.match(new RegExp(`<${name}\\b[^>]*>([\\s\\S]*?)<\\/${name}>`, 'i')); return mt ? mt[1] : ''; };
  const out = [];
  for (const b of blocks) {
    const href = (b.match(/<link\b[^>]*href=["']([^"']+)["'][^>]*\/?>/i) || [])[1];
    const link = (href || rssStrip(tag(b, 'link'))).trim();
    const title = rssStrip(tag(b, 'title')).slice(0, 200);
    const desc = rssStrip(tag(b, 'description') || tag(b, 'summary') || tag(b, 'content')).slice(0, 300);
    const guid = rssStrip(tag(b, 'guid') || tag(b, 'id'));
    const key = (guid || link || title).slice(0, 500);
    if (key) out.push({ key, title: title || '(بدون عنوان)', link: /^https?:\/\//i.test(link) ? link.slice(0, 400) : '', desc });
  }
  return out;
}
async function rssFetch(url) {
  try {
    const r = await fetch(url, { method: 'GET', redirect: 'manual', headers: { 'user-agent': 'FeedReader/1.0', accept: 'application/rss+xml, application/atom+xml, application/xml, text/xml, */*' }, signal: AbortSignal.timeout(8000) });
    if (!r.ok) return { error: `HTTP ${r.status}` };
    const len = Number(r.headers.get('content-length') || 0);
    if (len > 600000) { try { await r.body?.cancel(); } catch {} return { error: 'فید خیلی بزرگه' }; }
    const txt = (await r.text()).slice(0, 600000);
    if (!/<(rss|feed|rdf)[\s>:]/i.test(txt)) return { error: 'این آدرس فید RSS/Atom نیست' };
    return { items: rssParse(txt) };
  } catch (e) {
    return { error: /abort|timeout/i.test(e.message || '') ? 'timeout' : 'network' };
  }
}
const rssLine = (f) => `#${f.id} ${f.enabled ? '🟢' : '⚪️'} ${new URL(f.url).hostname} — هر ${toFa(Math.round(f.interval_sec / 60))} دقیقه${f.paused_until && f.paused_until > Date.now() ? ' — ⏸ موقتاً قطع' : ''}${f.fail_count ? ` — خطا: ${toFa(f.fail_count)}` : ''}`;
// one feed: seed on first success, then send only items never seen before
async function rssCheckFeed(env, f) {
  const now = Date.now();
  const r = await rssFetch(f.url);
  if (r.error) {
    const fails = Number(f.fail_count || 0) + 1;
    const pause = fails >= RSS.pauseAfter ? now + RSS.pauseSec * 1000 : null;
    await env.DB.prepare('UPDATE rss_feeds SET last_checked = ?, fail_count = ?, paused_until = ? WHERE id = ?').bind(now, fails, pause, f.id).run();
    return { error: r.error, paused: !!pause };
  }
  const seenRows = (await env.DB.prepare('SELECT item_key FROM rss_seen WHERE feed_id = ?').bind(f.id).all()).results || [];
  const seen = new Set(seenRows.map((x) => x.item_key));
  const seeded = seen.size > 0;
  const fresh = r.items.filter((it) => !seen.has(it.key));
  let sent = 0;
  for (const it of fresh) {
    if (seeded && sent < RSS.sendMax) {
      const text = `📰 ${it.title}${it.desc ? `\n${it.desc}` : ''}${it.link ? `\n${it.link}` : ''}`;
      const res = await tg(env, 'sendMessage', { chat_id: f.dest, text: text.slice(0, 3900), link_preview_options: { is_disabled: true } });
      if (!res.ok) break; // not posted -> not marked as seen, retried next time
      sent++;
    }
    await env.DB.prepare('INSERT INTO rss_seen (feed_id, item_key, t) VALUES (?, ?, ?)').bind(f.id, it.key, now).run();
  }
  await env.DB.prepare('DELETE FROM rss_seen WHERE feed_id = ? AND id NOT IN (SELECT id FROM rss_seen WHERE feed_id = ? ORDER BY id DESC LIMIT ?)').bind(f.id, f.id, RSS.seenCap).run();
  await env.DB.prepare('UPDATE rss_feeds SET last_checked = ?, last_ok = ?, fail_count = 0, paused_until = NULL WHERE id = ?').bind(now, now, f.id).run();
  return { sent, seeded: !seeded, fresh: fresh.length };
}
async function runRss(env) {
  if (!env.DB || !(await rssOn(env))) return;
  await rssInit(env);
  const now = Date.now();
  const due = (await env.DB.prepare('SELECT * FROM rss_feeds WHERE enabled = 1 AND (paused_until IS NULL OR paused_until <= ?) AND (last_checked IS NULL OR last_checked + interval_sec * 1000 <= ?) ORDER BY COALESCE(last_checked, 0) LIMIT ?').bind(now, now, RSS.perRun).all()).results || [];
  for (const f of due) await rssCheckFeed(env, f).catch((e) => console.error('rss feed', e));
}
const RSS_HELP = '📰 خبرخوان RSS\n/rss add <آدرس https> [دقیقه]  (پیش‌فرض ۶۰، بین ۱۵ و ۱۴۴۰)\n/rss list · /rss test <آدرس> · /rss on|off|del شماره\nاولین بار فقط ثبت میشه (خبرهای قدیمی ارسال نمیشن)؛ بعدش فقط موارد جدید.';
async function rssCmd(env, m, scope, text, uid, isOwner, inGroup) {
  const send = (t) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t, ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const subRaw = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(subRaw.length).trim();
  if (!subRaw) return send(RSS_HELP);
  if ((subRaw === 'on' || subRaw === 'off') && !rest) { // global switch (owner only); with a feed id it switches that feed
    if (!isOwner) return send('فقط مالک بات می‌تونه کل خبرخوان رو روشن یا خاموش کنه.');
    await env.KV.put('cfg:rss', subRaw);
    return send(`📰 خبرخوان: ${subRaw === 'on' ? 'روشن' : 'خاموش'}`);
  }
  if (!(await rssOn(env))) return send('📰 خبرخوان در حال حاضر خاموشه.');
  if (!env.DB) return send('📰 خبرخوان نیاز به دیتابیس D1 داره (binding به نام DB).');
  if (!rateOk(`rss:${uid}`, 20, 60000)) return send('⏳ آروم‌تر؛ هر دقیقه حداکثر ۲۰ دستور.');
  const isAdmin = inGroup && scope ? await isAdminOf(env, scope, uid) : true;
  try {
    await rssInit(env);
    if (subRaw === 'test') {
      const u = monUrlOk(rest.split(/\s+/)[0]);
      if (!u) return send('آدرس https عمومی بده. مثال: /rss test https://example.com/feed.xml');
      const r = await rssFetch(u);
      if (r.error) return send(`❌ ${r.error}`);
      return send(`✅ فید خوانده شد: ${toFa(r.items.length)} مورد. (این فقط آزمایشه؛ چیزی ارسال یا ثبت نشد.)\nاولین مورد: ${r.items[0]?.title || '—'}`);
    }
    if (subRaw === 'list') {
      const w = scope ? ['chat_id = ?', [scope]] : ['chat_id = 0 AND owner_id = ?', [uid]];
      const rows = (await env.DB.prepare(`SELECT * FROM rss_feeds WHERE ${w[0]} ORDER BY id`).bind(...w[1]).all()).results || [];
      return send(rows.length ? '📰 منابع\n' + rows.map(rssLine).join('\n') : 'منبعی ثبت نشده.');
    }
    if (inGroup && !isAdmin) return send('فقط ادمین‌های گروه می‌تونه منبع اضافه یا حذف کنه.');
    if (subRaw === 'add') {
      const parts = rest.split(/\s+/);
      const mins = parts.length > 1 ? Number(parts[parts.length - 1]) : 60;
      const url = monUrlOk(parts.length > 1 && Number.isFinite(mins) ? parts.slice(0, -1).join(' ') : rest);
      if (!url) return send('آدرس باید https عمومی باشه (IP و آدرس داخلی قبول نیست).');
      const m2 = Number.isFinite(mins) ? Math.round(mins) : 60;
      if (!(m2 >= RSS.minMin && m2 <= RSS.maxMin)) return send(`فاصله‌ی بررسی بین ${toFa(RSS.minMin)} و ${toFa(RSS.maxMin)} دقیقه باشه.`);
      const cnt = (await env.DB.prepare('SELECT COUNT(*) AS n FROM rss_feeds WHERE chat_id = ?').bind(scope || 0).first())?.n || 0;
      if (cnt >= RSS.max) return send(`حداکثر ${toFa(RSS.max)} منبع برای هر ${scope ? 'گروه' : 'کاربر'}.`);
      const r = await env.DB.prepare('INSERT INTO rss_feeds (chat_id, dest, owner_id, url, interval_sec, enabled, created) VALUES (?, ?, ?, ?, ?, 1, ?)').bind(scope || 0, scope || uid, uid, url, m2 * 60, Date.now()).run();
      return send(`✅ منبع #${r.meta?.last_row_id} ثبت شد (هر ${toFa(m2)} دقیقه). اولین بررسی به‌زودی انجام میشه و خبرهای موجود فقط ثبت میشن.`);
    }
    const id = parseInt(rest, 10);
    if (!(id > 0)) return send('شماره‌ی منبع رو بنویس. مثال: /rss del 2');
    const f = await env.DB.prepare('SELECT * FROM rss_feeds WHERE id = ? AND chat_id = ?').bind(id, scope || 0).first();
    if (!f) return send('همچین منبعی اینجا نیست.');
    if (!scope && f.owner_id !== uid) return send('این منبع مال تو نیست.');
    if (subRaw === 'del') { await env.DB.prepare('DELETE FROM rss_seen WHERE feed_id = ?').bind(id).run(); await env.DB.prepare('DELETE FROM rss_feeds WHERE id = ?').bind(id).run(); return send(`🗑 منبع #${id} حذف شد.`); }
    if (subRaw === 'on' || subRaw === 'off') { await env.DB.prepare('UPDATE rss_feeds SET enabled = ? WHERE id = ?').bind(subRaw === 'on' ? 1 : 0, id).run(); return send(`منبع #${id} ${subRaw === 'on' ? 'روشن' : 'خاموش'} شد.`); }
    return send(RSS_HELP);
  } catch (e) {
    console.error('rss', e);
    return send('⚠️ خطا در خبرخوان؛ دوباره امتحان کن.');
  }
}

// ======================= TRIGGERS (a phrase set by an admin -> a text reply or a file reply) =======================
const TGR = { max: 50, chatCool: 30000, userCool: 60000, minLen: 2, maxLen: 40 };
let tgrReady = false;
const TGR_SCHEMA = [
  "CREATE TABLE IF NOT EXISTS triggers (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, phrase TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('text','file')), body TEXT NOT NULL DEFAULT '', file_id TEXT NOT NULL DEFAULT '', file_type TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL)",
  'CREATE INDEX IF NOT EXISTS idx_tg_chat ON triggers (chat_id, enabled)',
];
async function tgrInit(env) {
  if (tgrReady || !env.DB) return;
  await env.DB.batch(TGR_SCHEMA.map((q) => env.DB.prepare(q)));
  tgrReady = true;
}
const tgrCache = new Map();
const tgrLast = new Map();
async function tgrRules(env, chatId) {
  const c = tgrCache.get(chatId);
  if (c && c.exp > Date.now()) return c.rules;
  await tgrInit(env);
  const rules = (await env.DB.prepare('SELECT * FROM triggers WHERE chat_id = ? AND enabled = 1 ORDER BY id LIMIT ?').bind(chatId, TGR.max).all()).results || [];
  if (tgrCache.size > 500) tgrCache.clear();
  tgrCache.set(chatId, { rules, exp: Date.now() + 60000 });
  return rules;
}
const tgrInvalidate = (chatId) => tgrCache.delete(chatId);
const TGR_FILE_METHOD = { photo: 'sendPhoto', video: 'sendVideo', document: 'sendDocument', audio: 'sendAudio', voice: 'sendVoice', animation: 'sendAnimation', sticker: 'sendSticker' };
// the file (if any) carried by a replied-to message; only its file_id is stored, nothing is downloaded
function tgrFileOf(msg) {
  if (!msg) return null;
  if (msg.photo?.length) return { type: 'photo', file_id: msg.photo[msg.photo.length - 1].file_id };
  for (const k of ['video', 'document', 'audio', 'voice', 'animation', 'sticker']) if (msg[k]?.file_id) return { type: k, file_id: msg[k].file_id };
  return null;
}
async function tgrCmd(env, m, g, text, uid) {
  const send = (t) => reply(env, m, t, true);
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const subRaw = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(subRaw.length).trim();
  const chatId = m.chat.id;
  if (!env.DB) return send('🔔 تریگر نیاز به دیتابیس D1 داره (binding به نام DB).');
  await tgrInit(env);
  if (!subRaw || subRaw === 'list') {
    const rows = (await env.DB.prepare('SELECT id, phrase, kind, enabled FROM triggers WHERE chat_id = ? ORDER BY id').bind(chatId).all()).results || [];
    if (!subRaw && !rows.length) return send('🔔 تریگر (پاسخ خودکار به یه عبارت)\n/trigger add <عبارت> | <متن جواب>\nیا روی یه فایل ریپلای کن و بنویس: /trigger add <عبارت>\n/trigger list · /trigger del شماره · /trigger on|off شماره\nوقتی کسی عبارت رو توی پیامش بگه، جواب داده میشه (هر عبارت هر ۳۰ ثانیه حداکثر یک بار، و هر کاربر هر دقیقه).');
    return send(`🔔 تریگرها (${toFa(rows.length)}/${toFa(TGR.max)})\n${rows.map((r) => `#${r.id} ${r.enabled ? '🟢' : '⚪️'} «${r.phrase}» → ${r.kind === 'file' ? 'فایل' : 'متن'}`).join('\n') || 'هنوز نیست.'}`);
  }
  if (subRaw === 'add') {
    const file = tgrFileOf(m.reply_to_message);
    let phrase;
    let bodyText = '';
    if (file && rest) phrase = rest;
    else if (rest.includes('|')) { const i = rest.indexOf('|'); phrase = rest.slice(0, i); bodyText = rest.slice(i + 1).trim(); }
    else return send('مثال: /trigger add فلان | متن جواب\nیا روی یه فایل ریپلای کن و بنویس: /trigger add فلان');
    const pat = wrWords(phrase);
    if (pat.length < TGR.minLen || pat.length > TGR.maxLen) return send(`عبارت باید بین ${toFa(TGR.minLen)} و ${toFa(TGR.maxLen)} حرف باشه.`);
    if (!file && !bodyText) return send('متن جواب خالیه.');
    const cnt = (await env.DB.prepare('SELECT COUNT(*) AS n FROM triggers WHERE chat_id = ?').bind(chatId).first())?.n || 0;
    if (cnt >= TGR.max) return send(`به سقف ${toFa(TGR.max)} تریگر رسیدی.`);
    const r = await env.DB.prepare('INSERT INTO triggers (chat_id, phrase, kind, body, file_id, file_type, enabled, created) VALUES (?, ?, ?, ?, ?, ?, 1, ?)')
      .bind(chatId, pat, file ? 'file' : 'text', file ? '' : bodyText.slice(0, 1500), file?.file_id || '', file?.type || '', Date.now()).run();
    tgrInvalidate(chatId);
    return send(`✅ تریگر #${r.meta?.last_row_id} ساخته شد: «${pat}» → ${file ? `فایل (${file.type})` : 'متن'}`);
  }
  if (subRaw === 'del' || subRaw === 'on' || subRaw === 'off') {
    const id = parseInt(rest, 10);
    if (!(id > 0)) return send('شماره‌ی تریگر رو بنویس. مثال: /trigger del 2');
    if (subRaw === 'del') await env.DB.prepare('DELETE FROM triggers WHERE id = ? AND chat_id = ?').bind(id, chatId).run();
    else await env.DB.prepare('UPDATE triggers SET enabled = ? WHERE id = ? AND chat_id = ?').bind(subRaw === 'on' ? 1 : 0, id, chatId).run();
    tgrInvalidate(chatId);
    return send(subRaw === 'del' ? `🗑 تریگر #${id} حذف شد.` : `تریگر #${id} ${subRaw === 'on' ? 'روشن' : 'خاموش'} شد.`);
  }
  return send('دستور ناشناخته. /trigger را بدون چیز دیگه بفرست.');
}
// fires at most once per trigger per chat every 30 s, and once per user per trigger every 60 s
async function tgrFire(env, m, text) {
  if (!env.DB || !text || text.startsWith('/') || !m.from) return false;
  const rules = await tgrRules(env, m.chat.id);
  if (!rules.length) return false;
  // whole words only: triggers must not fire on longer words (unlike the word-rule evasion check)
  const hit = rules.find((r) => { const p = wrWords(r.phrase); return !!p && ` ${wrWords(text)} `.includes(` ${p} `); });
  if (!hit) return false;
  const now = Date.now();
  const ck = `c:${m.chat.id}:${hit.id}`;
  const uk = `u:${m.chat.id}:${m.from.id}:${hit.id}`;
  if ((tgrLast.get(ck) || 0) + TGR.chatCool > now || (tgrLast.get(uk) || 0) + TGR.userCool > now) return false;
  if (tgrLast.size > 5000) tgrLast.clear();
  tgrLast.set(ck, now);
  tgrLast.set(uk, now);
  const base = { chat_id: m.chat.id, reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true }, ...topicOf(m) };
  if (hit.kind === 'text') return (await tg(env, 'sendMessage', { ...base, text: hit.body })).ok;
  const method = TGR_FILE_METHOD[hit.file_type];
  if (!method) return false;
  return (await tg(env, method, { ...base, [hit.file_type]: hit.file_id })).ok;
}

// ======================= EXPENSES (group ledgers; whole money; equal split; minimal settlement) =======================
const EXP = { max: 1000000000000, perLedger: 500, descLen: 60 };
let expReady = false;
const EXP_SCHEMA = [
  'CREATE TABLE IF NOT EXISTS ledgers (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, title TEXT NOT NULL, created_by INTEGER NOT NULL, created INTEGER NOT NULL, closed INTEGER NOT NULL DEFAULT 0)',
  'CREATE TABLE IF NOT EXISTS ledger_members (ledger_id INTEGER NOT NULL, user_id INTEGER NOT NULL, name TEXT NOT NULL DEFAULT \'\', PRIMARY KEY (ledger_id, user_id))',
  'CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY AUTOINCREMENT, ledger_id INTEGER NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), description TEXT NOT NULL DEFAULT \'\', payer_id INTEGER NOT NULL, created_by INTEGER NOT NULL, created INTEGER NOT NULL)',
  'CREATE TABLE IF NOT EXISTS expense_shares (expense_id INTEGER NOT NULL, user_id INTEGER NOT NULL, share INTEGER NOT NULL, PRIMARY KEY (expense_id, user_id))',
  'CREATE TABLE IF NOT EXISTS settlements (id INTEGER PRIMARY KEY AUTOINCREMENT, ledger_id INTEGER NOT NULL, from_id INTEGER NOT NULL, to_id INTEGER NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), created INTEGER NOT NULL)',
];
async function expInit(env) {
  if (expReady || !env.DB) return;
  await env.DB.batch(EXP_SCHEMA.map((q) => env.DB.prepare(q)));
  expReady = true;
}
const expDigits = (s) => String(s || '').replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
// whole Toman only: "۱۲۰٬۰۰۰" "120,000" "120000"; anything fractional or negative is refused
function expParseAmount(raw) {
  const t = expDigits(raw).replace(/[,٬،\s]/g, '');
  if (!/^\d{1,15}$/.test(t)) return null;
  const n = Number(t);
  return n > 0 && n <= EXP.max ? n : null;
}
// equal split in whole units; the remainder goes one unit at a time to the lowest ids (deterministic, sums exactly)
function expSplit(amount, ids) {
  const sorted = [...ids].sort((a, b) => a - b);
  const base = Math.floor(amount / sorted.length);
  const rem = amount - base * sorted.length;
  return new Map(sorted.map((id, i) => [id, base + (i < rem ? 1 : 0)]));
}
// greedy settlement: largest debtor pays largest creditor; always sums exactly
function expSettle(net) {
  const cred = [];
  const debt = [];
  for (const [id, v] of net) { if (v > 0) cred.push({ id, v }); else if (v < 0) debt.push({ id, v: -v }); }
  cred.sort((a, b) => b.v - a.v || a.id - b.id);
  debt.sort((a, b) => b.v - a.v || a.id - b.id);
  const out = [];
  let i = 0;
  let j = 0;
  while (i < debt.length && j < cred.length) {
    const x = Math.min(debt[i].v, cred[j].v);
    out.push({ from: debt[i].id, to: cred[j].id, amount: x });
    debt[i].v -= x;
    cred[j].v -= x;
    if (debt[i].v === 0) i++;
    if (cred[j].v === 0) j++;
  }
  return out;
}
async function expActive(env, chatId) {
  await expInit(env);
  return env.DB.prepare('SELECT * FROM ledgers WHERE chat_id = ? AND closed = 0 ORDER BY id DESC LIMIT 1').bind(chatId).first();
}
async function expMembers(env, lid) {
  return (await env.DB.prepare('SELECT user_id, name FROM ledger_members WHERE ledger_id = ? ORDER BY user_id').bind(lid).all()).results || [];
}
async function expJoin(env, lid, u) {
  await env.DB.prepare('INSERT OR IGNORE INTO ledger_members (ledger_id, user_id, name) VALUES (?, ?, ?)').bind(lid, u.id, String(u.first_name || u.username || u.id).slice(0, 40)).run();
}
// net position per member: + they are owed, - they owe. paid - owed + settlements sent - settlements received
async function expNet(env, lid) {
  const net = new Map((await expMembers(env, lid)).map((r) => [r.user_id, 0]));
  const add = (id, v) => net.set(id, (net.get(id) || 0) + v);
  for (const r of (await env.DB.prepare('SELECT payer_id AS id, SUM(amount) AS n FROM expenses WHERE ledger_id = ? GROUP BY payer_id').bind(lid).all()).results || []) add(r.id, Number(r.n));
  for (const r of (await env.DB.prepare('SELECT s.user_id AS id, SUM(s.share) AS n FROM expense_shares s JOIN expenses e ON e.id = s.expense_id WHERE e.ledger_id = ? GROUP BY s.user_id').bind(lid).all()).results || []) add(r.id, -Number(r.n));
  for (const r of (await env.DB.prepare('SELECT from_id AS id, SUM(amount) AS n FROM settlements WHERE ledger_id = ? GROUP BY from_id').bind(lid).all()).results || []) add(r.id, Number(r.n));
  for (const r of (await env.DB.prepare('SELECT to_id AS id, SUM(amount) AS n FROM settlements WHERE ledger_id = ? GROUP BY to_id').bind(lid).all()).results || []) add(r.id, -Number(r.n));
  return net;
}
async function expAdd(env, lid, uid, payer, amount, desc) {
  const cnt = (await env.DB.prepare('SELECT COUNT(*) AS n FROM expenses WHERE ledger_id = ?').bind(lid).first())?.n || 0;
  if (cnt >= EXP.perLedger) return { error: `این دفتر به سقف ${toFa(EXP.perLedger)} هزینه رسیده.` };
  await expJoin(env, lid, payer);
  const mem = (await expMembers(env, lid)).map((r) => r.user_id);
  const shares = expSplit(amount, mem);
  const now = Date.now();
  const r = await env.DB.prepare('INSERT INTO expenses (ledger_id, amount, description, payer_id, created_by, created) VALUES (?, ?, ?, ?, ?, ?)').bind(lid, amount, desc.slice(0, EXP.descLen), payer.id, uid, now).run();
  const id = Number(r.meta?.last_row_id);
  for (const [user, sh] of shares) await env.DB.prepare('INSERT INTO expense_shares (expense_id, user_id, share) VALUES (?, ?, ?)').bind(id, user, sh).run();
  return { id, members: mem.length };
}
function expReport(env, title, members, net, transfers) {
  const nm = (id) => (members.find((x) => x.user_id === id)?.name || String(id));
  const fmt = (n) => toFa(Math.abs(n).toLocaleString('en-US'));
  const rows = members.map((x) => { const v = net.get(x.user_id) || 0; return `${nm(x.user_id)}: ${v > 0 ? `طلب دارد ${fmt(v)}` : v < 0 ? `بدهکار ${fmt(v)}` : 'تسویه'}`; });
  const tr = transfers.map((t) => `${nm(t.from)} ➜ ${nm(t.to)}: ${fmt(t.amount)} تومان`);
  return `🧾 دفتر «${title}»\nوضعیت هر نفر:\n${rows.join('\n') || '—'}\n\nپیشنهاد تسویه (کمترین پرداخت تقریبی):\n${tr.join('\n') || 'همه تسویه‌اند ✅'}`;
}
async function expCmd(env, m, g, text, uid, isAdmin) {
  const send = (t) => reply(env, m, t, true);
  const chatId = m.chat.id;
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const sub = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(sub.length).trim();
  if (!env.DB) return send('🧾 دفتر هزینه نیاز به D1 داره (binding به نام DB).');
  if (!rateOk(`exp:${uid}`, 30, 60000)) return send('⏳ آروم‌تر؛ هر دقیقه حداکثر ۳۰ دستور هزینه.');
  await expInit(env);
  try {
    if (text.match(/^\/ledger/i)) {
      if (sub === 'new') {
        const title = rest.slice(0, 60).trim();
        if (!title) return send('مثال: /ledger new سفر شمال');
        if (await expActive(env, chatId)) return send('یه دفتر فعال داری. اول با /ledger close ببندش.');
        const r = await env.DB.prepare('INSERT INTO ledgers (chat_id, title, created_by, created) VALUES (?, ?, ?, ?)').bind(chatId, title, uid, Date.now()).run();
        return send(`✅ دفتر «${title}» ساخته شد (#${r.meta?.last_row_id}). هزینه‌ها: /exp add <مبلغ> <توضیح>`);
      }
      const l = await expActive(env, chatId);
      if (!l) return send('دفتر فعالی نیست. با /ledger new <عنوان> یکی بساز.');
      if (sub === 'join') { await expJoin(env, l.id, m.from); return send(`✅ ${m.from.first_name || 'تو'} به دفتر «${l.title}» اضافه شد.`); }
      if (sub === 'close') {
        if (!isAdmin && uid !== l.created_by) return send('فقط ادمین یا سازنده‌ی دفتر می‌تونه ببندتش.');
        await env.DB.prepare('UPDATE ledgers SET closed = 1 WHERE id = ?').bind(l.id).run();
        return send(`🔒 دفتر «${l.title}» بسته شد.`);
      }
      return send('/ledger new <عنوان> · /ledger join · /ledger close');
    }
    const l = await expActive(env, chatId);
    if (!l && sub !== 'list') return send('دفتر فعالی نیست. اول /ledger new <عنوان> بزن.');
    if (sub === 'add') {
      const parts = rest.split(/\s+/);
      const amount = expParseAmount(parts[0]);
      if (!amount) return send('مبلغ باید عدد صحیح تومان باشه (مثال: 250000). کسری و منفی قبول نیست.');
      const desc = parts.slice(1).join(' ');
      const payer = m.reply_to_message?.from && !m.reply_to_message.from.is_bot ? m.reply_to_message.from : m.from;
      const r = await expAdd(env, l.id, uid, payer, amount, desc);
      if (r.error) return send(`❌ ${r.error}`);
      return send(`✅ هزینه #${r.id} ثبت شد: ${toFa(amount.toLocaleString('en-US'))} تومان — پرداخت‌کننده ${payer.first_name || payer.id} — بین ${toFa(r.members)} نفر به‌طور مساوی.`);
    }
    if (sub === 'list') {
      if (!l) return send('دفتر فعالی نیست.');
      const rows = (await env.DB.prepare('SELECT id, amount, description, payer_id FROM expenses WHERE ledger_id = ? ORDER BY id DESC LIMIT 10').bind(l.id).all()).results || [];
      return send(rows.length ? `🧾 آخرین هزینه‌ها («${l.title}»)\n${rows.map((r) => `#${r.id} • ${toFa(Number(r.amount).toLocaleString('en-US'))} • ${r.description || '—'}`).join('\n')}` : 'هنوز هزینه‌ای ثبت نشده.');
    }
    if (sub === 'del' || sub === 'edit') {
      const parts = rest.split(/\s+/);
      const id = parseInt(expDigits(parts[0]), 10);
      if (!(id > 0)) return send(`مثال: /exp ${sub}${sub === 'edit' ? ' 12 300000' : ' 12'}`);
      const e = await env.DB.prepare('SELECT * FROM expenses WHERE id = ? AND ledger_id = ?').bind(id, l.id).first();
      if (!e) return send('همچین هزینه‌ای توی این دفتر نیست.');
      if (!isAdmin && e.created_by !== uid) return send('فقط ادمین یا ثبت‌کننده‌ی این هزینه می‌تونه تغییرش بده.');
      if (sub === 'del') {
        await env.DB.prepare('DELETE FROM expense_shares WHERE expense_id = ?').bind(id).run();
        await env.DB.prepare('DELETE FROM expenses WHERE id = ?').bind(id).run();
        return send(`🗑 هزینه #${id} حذف شد.`);
      }
      const amount = expParseAmount(parts[1]);
      if (!amount) return send('مبلغ جدید باید عدد صحیح تومان باشه.');
      const mem = (await expMembers(env, l.id)).map((r) => r.user_id);
      const shares = expSplit(amount, mem);
      await env.DB.prepare('UPDATE expenses SET amount = ? WHERE id = ?').bind(amount, id).run();
      await env.DB.prepare('DELETE FROM expense_shares WHERE expense_id = ?').bind(id).run();
      for (const [user, sh] of shares) await env.DB.prepare('INSERT INTO expense_shares (expense_id, user_id, share) VALUES (?, ?, ?)').bind(id, user, sh).run();
      return send(`✏️ هزینه #${id} شد ${toFa(amount.toLocaleString('en-US'))} تومان و دوباره بین اعضا تقسیم شد.`);
    }
    if (sub === 'paid') {
      const parts = rest.split(/\s+/);
      const amount = expParseAmount(parts[parts.length - 1]);
      if (!amount || parts.length < 1) return send('مثال: ریپلای روی پیام بدهکار بزن: /exp paid 150000');
      const toU = m.reply_to_message?.from;
      if (!toU || toU.is_bot) return send('روی پیام کسی که پولش رو دادی ریپلای کن: /exp paid <مبلغ>');
      const mem = await expMembers(env, l.id);
      if (!mem.some((x) => x.user_id === uid)) return send('اول /ledger join بزن تا تو دفتر باشی.');
      await expJoin(env, l.id, toU);
      await env.DB.prepare('INSERT INTO settlements (ledger_id, from_id, to_id, amount, created) VALUES (?, ?, ?, ?, ?)').bind(l.id, uid, toU.id, amount, Date.now()).run();
      return send(`✅ ثبت شد: ${m.from.first_name || uid} ${toFa(amount.toLocaleString('en-US'))} تومان به ${toU.first_name || toU.id} داد.`);
    }
    if (sub === '' || sub === 'report') {
      if (!l) return send('🧾 دفتر هزینه: /ledger new <عنوان> ، سپس /exp add <مبلغ> <توضیح>');
      const mem = await expMembers(env, l.id);
      const net = await expNet(env, l.id);
      const transfers = expSettle(net);
      const total = (await env.DB.prepare('SELECT COALESCE(SUM(amount),0) AS n FROM expenses WHERE ledger_id = ?').bind(l.id).first())?.n || 0;
      const head = `جمع کل: ${toFa(Number(total).toLocaleString('en-US'))} تومان`;
      return send(`${head}\n${expReport(env, l.title, mem, net, transfers)}`);
    }
    return send('🧾 دستورهای هزینه: /ledger new|join|close · /exp add <مبلغ> <توضیح> · /exp list|report · /exp edit|del <شماره> · /exp paid <مبلغ> (ریپلای)');
  } catch (e) {
    console.error('expenses', e);
    return send('⚠️ خطا در دفتر هزینه؛ دوباره امتحان کن.');
  }
}

// ======================= REMINDERS (manage: list, edit, delete, repeat; groups: admins manage) =======================
const REM = { max: 50, minEvery: 1800000 };
const remId = () => crypto.randomUUID().slice(0, 6);
async function remAll(env, chatId) {
  const out = [];
  const l = await env.KV.list({ prefix: 'rem:' });
  for (const k of l.keys) {
    const r = await env.KV.get(k.name, 'json');
    if (r && r.chatId === chatId) out.push({ key: k.name, ...r, id: r.id || k.name.slice(4, 10) });
  }
  return out.sort((a, b) => a.at - b.at);
}
async function remFind(env, chatId, id) {
  return (await remAll(env, chatId)).find((r) => r.id === id) || null;
}
async function remSave(env, rec) {
  const { key, ...data } = rec;
  await env.KV.put(key || `rem:${rec.id}`, JSON.stringify(data));
}
const remLine = (env, r) => `#${r.id} ${r.every ? '🔁' : '⏰'} ${fmtTime(env, r.at)} — ${r.text}${r.every ? ` (هر ${toFa(Math.round(r.every / 60000))} دقیقه)` : ''}`;
const REM_HELP = '⏰ یادآورها\n/rem add <30m|2h|1d> <متن>   یک‌باره\n/rem daily <HH:MM> <متن>   هر روز\n/rem every <30m|2h|1d> <متن>   تکرار\n/rem list · /rem del <شناسه> · /rem text <شناسه> <متن جدید> · /rem when <شناسه> <30m>\nداخل گروه: ساختن، ویرایش و حذف فقط برای ادمین‌ها؛ همه لیست رو می‌بینن.';
async function remCmd(env, m, scope, text, uid, isOwner, inGroup) {
  const send = (t) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t, ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const sub = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(sub.length).trim();
  const chatId = inGroup ? scope : uid;
  if (!sub) return send(REM_HELP);
  if (!env.KV) return send('⏰ یادآورها در دسترس نیست.');
  if (!rateOk(`rem:${uid}`, 20, 60000)) return send('⏳ آروم‌تر؛ هر دقیقه حداکثر ۲۰ دستور یادآور.');
  const isAdmin = inGroup ? (isOwner || (await isAdminOf(env, scope, uid))) : true;
  const writes = ['add', 'daily', 'every', 'del', 'text', 'when'];
  if (writes.includes(sub) && inGroup && !isAdmin) return send('فقط ادمین‌های گروه می‌تونن یادآور بسازن یا تغییر بدن.');
  try {
    if (sub === 'list') {
      const rows = await remAll(env, chatId);
      return send(rows.length ? `⏰ یادآورها (${toFa(rows.length)})\n${rows.map((r) => remLine(env, r)).join('\n')}` : 'یادآوری ثبت نشده.');
    }
    if (sub === 'add' || sub === 'every') {
      const parts = rest.split(/\s+/);
      const d = parseDurSafe(parts[0] || '');
      if (d.error || !d.secs) return send(`مثال: /rem ${sub} ${sub === 'add' ? '30m' : '2h'} متن یادآور`);
      const msgText = parts.slice(1).join(' ').trim() || rest.slice(parts[0].length).trim();
      if (!msgText) return send('متن یادآور رو بنویس.');
      if (sub === 'every' && d.secs * 1000 < REM.minEvery) return send('تکرار کمتر از ۳۰ دقیقه مجاز نیست.');
      if ((await remAll(env, chatId)).length >= REM.max) return send(`به سقف ${toFa(REM.max)} یادآور رسیدی.`);
      const rec = { id: remId(), at: Date.now() + d.secs * 1000, text: msgText.slice(0, 500), chatId, owner: uid, ...(sub === 'every' ? { every: d.secs * 1000 } : {}) };
      await remSave(env, { ...rec, key: `rem:${rec.id}` });
      return send(`✅ یادآور #${rec.id} ثبت شد: ${fmtTime(env, rec.at)}${rec.every ? ` و سپس هر ${toFa(Math.round(rec.every / 60000))} دقیقه` : ''}`);
    }
    if (sub === 'daily') {
      const parts = rest.split(/\s+/);
      const mt = faDigits(parts[0] || '').match(/^(\d{1,2}):(\d{2})$/);
      const msgText = parts.slice(1).join(' ').trim();
      if (!mt || +mt[1] > 23 || +mt[2] > 59 || !msgText) return send('مثال: /rem daily 18:30 وقت دعا');
      const lp = localParts(env);
      let diff = Number(mt[1]) * 60 + Number(mt[2]) - (lp.h * 60 + lp.m);
      if (diff <= 0) diff += 1440;
      if ((await remAll(env, chatId)).length >= REM.max) return send(`به سقف ${toFa(REM.max)} یادآور رسیدی.`);
      const rec = { id: remId(), at: Date.now() + diff * 60000, text: msgText.slice(0, 500), chatId, owner: uid, every: 86400000 };
      await remSave(env, { ...rec, key: `rem:${rec.id}` });
      return send(`✅ یادآور روزانه #${rec.id} ثبت شد؛ اولین بار ${fmtTime(env, rec.at)}`);
    }
    const id = rest.split(/\s+/)[0];
    if (!['del', 'text', 'when'].includes(sub)) return send(REM_HELP);
    const r = id ? await remFind(env, chatId, id) : null;
    if (!r) return send('همچین یادآوری اینجا نیست. (شناسه رو از /rem list بگیر)');
    if (sub === 'del') { await env.KV.delete(r.key); return send(`🗑 یادآور #${r.id} حذف شد.`); }
    if (sub === 'text') {
      const t = rest.slice(id.length).trim();
      if (!t) return send('متن جدید رو بنویس.');
      await remSave(env, { ...r, text: t.slice(0, 500), claimed: 0 });
      return send(`✏️ یادآور #${r.id} ویرایش شد.`);
    }
    const d = parseDurSafe(rest.slice(id.length).trim());
    if (d.error || !d.secs) return send('مدت جدید رو بده، مثلاً 2h یا 45m.');
    await remSave(env, { ...r, at: Date.now() + d.secs * 1000, claimed: 0 });
    return send(`🔁 یادآور #${r.id} برای ${fmtTime(env, Date.now() + d.secs * 1000)} تنظیم شد.`);
  } catch (e) {
    console.error('reminders', e);
    return send('⚠️ خطا در یادآورها؛ دوباره امتحان کن.');
  }
}

// ======================= MEMBER SCORES (real activity; capped; admin adjustments logged) =======================
const SCR = { perMsg: 1, minLetters: 5, cooldownMs: 20000, dupMs: 60000, dayCap: 60, levels: [[1000, 'افسانه'], [500, 'ستاره'], [200, 'پرکار'], [50, 'فعال'], [0, 'تازه‌وارد']] };
let scrReady = false;
const SCR_SCHEMA = [
  "CREATE TABLE IF NOT EXISTS scores (chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('award','adj')), name TEXT NOT NULL DEFAULT '', pts INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (chat_id, user_id, day, kind))",
  'CREATE INDEX IF NOT EXISTS idx_scores_chat_day ON scores (chat_id, day)',
];
async function scrInit(env) {
  if (scrReady || !env.DB) return;
  await env.DB.batch(SCR_SCHEMA.map((q) => env.DB.prepare(q)));
  scrReady = true;
}
const scrLast = new Map(); // per isolate: last award time and last text per user (anti-spam)
const scrLevel = (total) => (SCR.levels.find(([min]) => total >= min) || [0, 'تازه‌وارد'])[1];
const scrOn = (g) => g?.score === true;
// one award per qualifying message: real text, not a command, not a repeat, not too fast, capped per day
async function scoreAward(env, m, g, text) {
  if (!env.DB || !scrOn(g) || !m.from || m.from.is_bot || !text || text.startsWith('/')) return;
  const letters = (text.match(/\p{L}/gu) || []).length;
  if (letters < SCR.minLetters) return;
  const now = Date.now();
  const key = `${m.chat.id}:${m.from.id}`;
  const prev = scrLast.get(key) || { t: 0, text: '', at: 0 };
  const norm2 = wrWords(text);
  if (now - prev.t < SCR.cooldownMs) return;
  if (norm2 === prev.text && now - prev.at < SCR.dupMs) return;
  scrLast.set(key, { t: now, text: norm2, at: now });
  if (scrLast.size > 5000) scrLast.clear();
  await scrInit(env);
  const day = localParts(env).date;
  const today = await env.DB.prepare("SELECT COALESCE(SUM(pts),0) AS n FROM scores WHERE chat_id = ? AND user_id = ? AND day = ? AND kind = 'award'").bind(m.chat.id, m.from.id, day).first();
  if (Number(today?.n || 0) >= SCR.dayCap) return;
  await env.DB.prepare("INSERT INTO scores (chat_id, user_id, day, kind, name, pts) VALUES (?, ?, ?, 'award', ?, ?) ON CONFLICT(chat_id, user_id, day, kind) DO UPDATE SET pts = pts + excluded.pts, name = excluded.name")
    .bind(m.chat.id, m.from.id, day, String(m.from.first_name || m.from.username || m.from.id).slice(0, 40), SCR.perMsg).run();
}
// window: 'day' | 'week' | 'all'
async function scrTotals(env, chatId, window) {
  const lp = localParts(env);
  const since = window === 'day' ? lp.date : window === 'week' ? localParts(env, Date.now() - 6 * 86400000).date : '0000-00-00';
  const rows = (await env.DB.prepare('SELECT user_id, MAX(name) AS name, SUM(pts) AS n FROM scores WHERE chat_id = ? AND day >= ? GROUP BY user_id ORDER BY n DESC, user_id ASC LIMIT 10').bind(chatId, since).all()).results || [];
  return rows.map((r) => ({ id: r.user_id, name: r.name || String(r.user_id), n: Number(r.n) }));
}
async function scrOwn(env, chatId, uid) {
  const r = await env.DB.prepare('SELECT COALESCE(SUM(pts),0) AS n FROM scores WHERE chat_id = ? AND user_id = ?').bind(chatId, uid).first();
  return Number(r?.n || 0);
}
async function scrCmd(env, m, g, text, uid, isAdmin, inGroup) {
  const send = (t) => reply(env, m, t, inGroup);
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const sub = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(sub.length).trim();
  const chatId = m.chat.id;
  if (!inGroup) return send('امتیاز فقط داخل گروه‌ها فعاله.');
  if (!env.DB) return send('🏅 امتیازها نیاز به D1 داره (binding به نام DB).');
  await scrInit(env);
  if (sub === 'on' || sub === 'off') {
    if (!isAdmin) return send('فقط ادمین می‌تونه امتیازدهی رو روشن یا خاموش کنه.');
    g.score = sub === 'on'; await env.KV.put(`grp:${chatId}`, JSON.stringify(g));
    return send(g.score ? '🏅 امتیازدهی روشن شد. هر پیام واقعی ۱ امتیاز (حداکثر ۶۰ در روز).' : 'امتیازدهی خاموش شد.');
  }
  if (sub === 'add' || sub === 'sub') {
    if (!isAdmin) return send('فقط ادمین می‌تونه امتیاز تنظیم کنه.');
    const parts = rest.split(/\s+/);
    const n = parseInt(expDigits(sub === 'add' ? parts[parts.length - 1] : parts[parts.length - 1]), 10);
    if (!Number.isFinite(n) || n <= 0 || n > 10000) return send('مثال: ریپلای کن و بنویس /score add 20 (یا /score sub 5)');
    const target = m.reply_to_message?.from && !m.reply_to_message.from.is_bot ? m.reply_to_message.from : (parts.length > 1 ? await resolveTarget(env, m, parts[0]) : null);
    if (!target || target.error || !target.id) return send('روی پیام کاربر ریپلای کن، یا @username / آیدی عددی بده.');
    const id = target.id;
    const name = target.name || target.first_name || String(id);
    const delta = sub === 'add' ? n : -n;
    await env.DB.prepare("INSERT INTO scores (chat_id, user_id, day, kind, name, pts) VALUES (?, ?, ?, 'adj', ?, ?) ON CONFLICT(chat_id, user_id, day, kind) DO UPDATE SET pts = pts + excluded.pts, name = excluded.name")
      .bind(chatId, id, localParts(env).date, String(name).slice(0, 40), delta).run();
    await logAction(env, g, m, 'settings', { to: String(name), x: `امتیاز ${delta > 0 ? '+' : ''}${delta}` });
    return send(`✅ ${name}: ${delta > 0 ? '+' : ''}${toFa(delta)} امتیاز (ثبت شد در گزارش فعالیت‌ها).`);
  }
  if (sub === 'rank' || sub === 'top' || sub === '' || sub === 'day' || sub === 'week' || sub === 'all' || sub === 'روز' || sub === 'هفته' || sub === 'امروز' || sub === 'کل' || sub === 'همه') {
    const FA_WIN = { روز: 'day', امروز: 'day', هفته: 'week', کل: 'all', همه: 'all' };
    const pick = (sub === 'rank' || sub === 'top') ? (rest.split(/\s+/)[0] || 'all') : sub;
    const w = FA_WIN[pick] || pick.toLowerCase();
    const window = ['day', 'week', 'all'].includes(w) ? w : 'all';
    if (sub === '' ) {
      const mine = await scrOwn(env, chatId, uid);
      return send(`🏅 امتیاز تو: ${toFa(mine)} — سطح: ${scrLevel(mine)}\nجدول: /rank روز · /rank هفته · /rank all\nامتیاز روی پیام‌های واقعی (حداکثر ۶۰ در روز). سطح‌ها: تازه‌وارد ← فعال (۵۰) ← پرکار (۲۰۰) ← ستاره (۵۰۰) ← افسانه (۱۰۰۰).`);
    }
    const rows = await scrTotals(env, chatId, window);
    if (!rows.length) return send('هنوز امتیازی ثبت نشده.');
    const lbl = { day: 'امروز', week: '۷ روز اخیر', all: 'کل' }[window];
    return send(`🏆 جدول امتیاز (${lbl})\n${rows.map((r, i) => `${['🥇', '🥈', '🥉'][i] || `${toFa(i + 1)}.`} ${r.name} — ${toFa(r.n)} (${scrLevel(r.n)})`).join('\n')}`);
  }
  return send('🏅 امتیاز: /score · /rank [روز|هفته|all] · /score on|off (ادمین) · /score add|sub <عدد> (ریپلای، ادمین)');
}

// ======================= GROUP SUMMARIES (daily + weekly report; real data only; once per period) =======================
const SUM = { defHour: 21, defWeekday: 6 }; // weekday: 0 = Sunday ... 6 = Saturday
const SUM_WD = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
function sumCfg(g) {
  const s = g.summary || {};
  return {
    daily: { on: !!s.daily?.on, hour: Number.isFinite(s.daily?.hour) ? s.daily.hour : SUM.defHour },
    weekly: { on: !!s.weekly?.on, hour: Number.isFinite(s.weekly?.hour) ? s.weekly.hour : SUM.defHour, wd: Number.isFinite(s.weekly?.wd) ? s.weekly.wd : SUM.defWeekday },
  };
}
const sumWeekday = (env) => SUM_WD[new Intl.DateTimeFormat('en-US', { timeZone: env.TIMEZONE || 'Asia/Tehran', weekday: 'short' }).format(new Date(Date.now()))];
const SUM_DAYS_FA = ['یک‌شنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنج‌شنبه', 'جمعه', 'شنبه'];
// both texts come from the same real rows as /analytics; a period without rows is said to be empty, never estimated
function sumDailyText(env, title, d) {
  const hour = d.byHour.indexOf(Math.max(...d.byHour));
  if (!d.day.msgs) return `📊 خلاصه‌ی امروز «${title}»\nامروز هنوز پیامی ثبت نشده.`;
  const top = d.top.slice(0, 3).map((u, i) => `${i + 1}. ${u.name}`).join('  ');
  return [
    `📊 خلاصه‌ی امروز «${title}»`,
    `📝 پیام‌ها: ${toFa(d.day.msgs)}`,
    `👥 کاربر فعال: ${toFa(d.day.active)}`,
    `➕ عضو جدید: ${toFa(d.day.joins)} — ➖ خروج: ${toFa(d.day.leaves)}`,
    `⏰ پرترافیک‌ترین ساعت: ${toFa(String(hour).padStart(2, '0'))}:۰۰`,
    top ? `🏅 فعال‌ترین‌ها: ${top}` : null,
  ].filter(Boolean).join('\n');
}
function sumWeeklyText(env, title, d) {
  if (!d.week.msgs) return `🗓 گزارش هفتگی «${title}»\nدر ۷ روز اخیر پیامی ثبت نشده.`;
  const peakH = d.byHour.indexOf(Math.max(...d.byHour));
  const topH = d.byHour.map((n, h) => ({ h, n })).filter((x) => x.n > 0).sort((a, b) => b.n - a.n).slice(0, 3).map((x) => `${toFa(String(x.h).padStart(2, '0'))}:۰۰ (${toFa(x.n)})`);
  const topD = [...d.wd].sort((a, b) => b.n - a.n)[0];
  return [
    `🗓 گزارش هفتگی «${title}»`,
    `📝 پیام‌ها (۷ روز): ${toFa(d.week.msgs)}`,
    `👥 کاربران فعال (۷ روز): ${toFa(d.week.active)}`,
    `📈 رشد اعضا (۷ روز): ➕ ${toFa(d.week.joins)} — ➖ ${toFa(d.week.leaves)}`,
    `⏰ ساعت‌های شلوغ (۳۰ روز): ${topH.join('، ') || '—'} (برترین ساعت: ${toFa(String(peakH).padStart(2, '0'))}:۰۰)`,
    topD && topD.n ? `📅 شلوغ‌ترین روز هفته (۳۰ روز): ${topD.name}` : null,
    d.top.length ? `🏅 فعال‌ترین‌ها (۷ روز): ${d.top.slice(0, 5).map((u, i) => `${i + 1}. ${u.name}`).join('  ')}` : null,
  ].filter(Boolean).join('\n');
}
async function sumSendOnce(env, chatId, kind, date, g) {
  const key = `sum:${chatId}:${kind}:${date}`;
  if (await env.KV.get(key)) return false;
  await env.KV.put(key, 'claimed', { expirationTtl: 3 * 86400 }); // claim first: an overlapping cron run cannot send it again
  let d;
  try { d = await analyticsData(env, chatId); } catch (e) { console.error('summary data', e); d = null; }
  if (!d || d.error || d.empty) { await env.KV.delete(key); return false; }
  const text = kind === 'daily' ? sumDailyText(env, g.title || String(chatId), d) : sumWeeklyText(env, g.title || String(chatId), d);
  const r = await tg(env, 'sendMessage', { chat_id: chatId, text });
  if (!r.ok) { await env.KV.delete(key); return false; } // not posted: retry on the next run
  return true;
}
// called by the Cron Trigger every minute; a group gets its daily report once a day and its weekly report once a week
async function runSummaries(env) {
  if (!env.DB) return;
  const list = await env.KV.list({ prefix: 'grp:' });
  const lp = localParts(env);
  const wd = sumWeekday(env);
  for (const k of list.keys.slice(0, 40)) {
    const g = await env.KV.get(k.name, 'json');
    if (!g?.enabled) continue;
    const cfg = sumCfg(g);
    const chatId = Number(k.name.slice(4));
    if (cfg.daily.on && lp.h === cfg.daily.hour) await sumSendOnce(env, chatId, 'daily', lp.date, g);
    if (cfg.weekly.on && lp.h === cfg.weekly.hour && wd === cfg.weekly.wd) await sumSendOnce(env, chatId, 'weekly', lp.date, g);
  }
}
async function sumCmd(env, m, g, text, uid, isOwner) {
  const chatId = m.chat.id;
  const send = (t) => reply(env, m, t, true);
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const parts = body.split(/\s+/).filter(Boolean);
  const kind = (parts[0] || '').toLowerCase();
  const isAdmin = isOwner || (await isAdminOf(env, chatId, uid));
  if (!parts.length) {
    const c = sumCfg(g);
    return send(`🗓 خلاصه‌ها\nروزانه: ${c.daily.on ? `روشن، ساعت ${toFa(c.daily.hour)}` : 'خاموش'}\nهفتگی: ${c.weekly.on ? `روشن، ${Object.keys(SUM_WD).find((k) => SUM_WD[k] === c.weekly.wd)} ساعت ${toFa(c.weekly.hour)}` : 'خاموش'}\n\n/summary daily on|off [ساعت]\n/summary weekly on|off [ساعت] [Sat|Sun|...]\n/summary now`);
  }
  if (!isAdmin) return send('این تنظیمات فقط برای ادمین‌های گروهه.');
  if (!env.DB) return send('🗓 خلاصه‌ها نیاز به D1 داره (binding به نام DB).');
  if (kind === 'now') {
    const d = await analyticsData(env, chatId).catch(() => null);
    if (!d || d.error) return send(d?.error || 'خطا در خواندن آمار.');
    if (d.empty) return send('هنوز داده‌ای برای خلاصه جمع نشده.');
    return send(sumDailyText(env, g.title || String(chatId), d));
  }
  if (kind !== 'daily' && kind !== 'weekly') return send('مثال: /summary daily on 21');
  const cur = sumCfg(g);
  const on = parts[1] && /^(on|روشن)$/i.test(parts[1]) ? true : parts[1] && /^(off|خاموش)$/i.test(parts[1]) ? false : null;
  if (on === null) return send('on یا off بنویس.');
  const hourRaw = parts.find((x, i) => i >= 2 && /^[۰-۹0-9]{1,2}$/.test(x));
  const hour = hourRaw !== undefined ? parseInt(expDigits(hourRaw), 10) : cur[kind].hour;
  if (!(hour >= 0 && hour <= 23)) return send('ساعت باید بین ۰ و ۲۳ باشه.');
  const wdRaw = parts.find((x, i) => i >= 2 && SUM_WD[x[0].toUpperCase() + x.slice(1, 3).toLowerCase()] !== undefined);
  const wd = wdRaw ? SUM_WD[wdRaw[0].toUpperCase() + wdRaw.slice(1, 3).toLowerCase()] : cur.weekly.wd;
  g.summary = { ...(g.summary || {}), [kind]: kind === 'daily' ? { on, hour } : { on, hour, wd } };
  await env.KV.put(`grp:${chatId}`, JSON.stringify(g));
  return send(kind === 'daily' ? `🗓 گزارش روزانه: ${on ? `روشن، هر روز ساعت ${toFa(hour)}` : 'خاموش'}` : `🗓 گزارش هفتگی: ${on ? `روشن، ${Object.keys(SUM_WD).find((k) => SUM_WD[k] === wd)} ساعت ${toFa(hour)}` : 'خاموش'}`);
}

// ======================= FORMS & SURVEYS (D1; public/private; buttons; answers private to managers) =======================
const FRM = { maxQ: 20, maxText: 500, maxOpts: 8, stateTtl: 3600 };
let frmReady = false;
const FRM_SCHEMA = [
  "CREATE TABLE IF NOT EXISTS forms (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, owner_id INTEGER NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'public' CHECK (kind IN ('public','private')), state TEXT NOT NULL DEFAULT 'draft' CHECK (state IN ('draft','open','closed')), one_per_user INTEGER NOT NULL DEFAULT 1, ends_at INTEGER, created INTEGER NOT NULL)",
  "CREATE TABLE IF NOT EXISTS form_questions (id INTEGER PRIMARY KEY AUTOINCREMENT, form_id INTEGER NOT NULL, pos INTEGER NOT NULL, qtype TEXT NOT NULL CHECK (qtype IN ('text','choice','yn')), prompt TEXT NOT NULL, options TEXT NOT NULL DEFAULT '[]', required INTEGER NOT NULL DEFAULT 1)",
  "CREATE TABLE IF NOT EXISTS form_answers (id INTEGER PRIMARY KEY AUTOINCREMENT, form_id INTEGER NOT NULL, user_id INTEGER NOT NULL, name TEXT NOT NULL DEFAULT '', submitted INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL)",
  "CREATE TABLE IF NOT EXISTS form_values (answer_id INTEGER NOT NULL, question_id INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (answer_id, question_id))",
  'CREATE INDEX IF NOT EXISTS idx_form_answers ON form_answers (form_id, user_id)',
];
async function frmInit(env) {
  if (frmReady || !env.DB) return;
  await env.DB.batch(FRM_SCHEMA.map((q) => env.DB.prepare(q)));
  frmReady = true;
}
const frmState = (chatId, uid) => `fmst:${chatId}:${uid}`;
async function frmGet(env, id) {
  const f = await env.DB.prepare('SELECT * FROM forms WHERE id = ?').bind(id).first();
  if (!f) return null;
  const qs = (await env.DB.prepare('SELECT * FROM form_questions WHERE form_id = ? ORDER BY pos').bind(id).all()).results || [];
  return { ...f, questions: qs.map((q) => ({ ...q, options: JSON.parse(q.options || '[]') })) };
}
// managers: the creator, or an admin of the group the form belongs to (or the bot owner)
async function frmCanManage(env, f, uid) {
  if (uid === Number(env.OWNER_ID) || f.owner_id === uid) return true;
  return f.chat_id !== 0 && (await isAdminOf(env, f.chat_id, uid));
}
const frmLive = (f) => f.state === 'open' && !(f.ends_at && f.ends_at <= Date.now());
const frmKb = (rows) => ({ inline_keyboard: rows });
function frmQuestionView(f, pos) {
  const q = f.questions[pos];
  const head = `📋 ${f.title} — سؤال ${toFa(pos + 1)} از ${toFa(f.questions.length)}`;
  const opt = q.qtype === 'choice' ? '\n' + q.options.map((o, i) => `${toFa(i + 1)}) ${o}`).join('\n') : q.qtype === 'yn' ? '\n(بله / خیر)' : '';
  return `${head}\n\n${q.prompt}${opt}${q.required ? '' : '\n(اختیاری)'}`;
}
function frmQuestionKb(f, pos) {
  const q = f.questions[pos];
  const rows = [];
  if (q.qtype === 'choice') rows.push(q.options.map((o, i) => ({ text: o.slice(0, 40), callback_data: `fm:c:${f.id}:${pos}:${i}` })).slice(0, FRM.maxOpts));
  if (q.qtype === 'yn') rows.push([{ text: 'بله', callback_data: `fm:c:${f.id}:${pos}:1` }, { text: 'خیر', callback_data: `fm:c:${f.id}:${pos}:0` }]);
  const nav = [];
  if (pos > 0) nav.push({ text: '◀️ بازگشت', callback_data: `fm:b:${f.id}` });
  if (!q.required && q.qtype === 'text') nav.push({ text: '⏭ رد کردن', callback_data: `fm:k:${f.id}:${pos}` });
  nav.push({ text: '❌ لغو', callback_data: `fm:x:${f.id}` });
  rows.push(nav);
  return frmKb(rows);
}
async function frmSendQuestion(env, chatId, f, pos) {
  return tg(env, 'sendMessage', { chat_id: chatId, text: frmQuestionView(f, pos).slice(0, 3900), reply_markup: frmQuestionKb(f, pos) });
}
// answers are saved per question; going back removes the value of the previous question
async function frmSetValue(env, aid, qid, value) {
  await env.DB.prepare('INSERT INTO form_values (answer_id, question_id, value) VALUES (?, ?, ?) ON CONFLICT(answer_id, question_id) DO UPDATE SET value = excluded.value').bind(aid, qid, value).run();
}
async function frmAdvance(env, chatId, uid, st, f) {
  const next = st.pos + 1;
  if (next < f.questions.length) {
    await env.KV.put(frmState(chatId, uid), JSON.stringify({ ...st, pos: next }), { expirationTtl: FRM.stateTtl });
    return frmSendQuestion(env, chatId, f, next);
  }
  await env.DB.prepare('UPDATE form_answers SET submitted = 1 WHERE id = ?').bind(st.aid).run();
  await env.KV.delete(frmState(chatId, uid));
  return tg(env, 'sendMessage', { chat_id: chatId, text: `✅ ممنونم! پاسخ‌هات برای «${f.title}» ثبت شد.` });
}
async function frmStart(env, chatId, uid, name, f) {
  if (!frmLive(f)) return { error: 'این فرم بسته‌ست.' };
  if (f.kind === 'private' && uid !== f.owner_id) return { error: 'این فرم خصوصیه و فقط سازنده‌اش می‌تونه پاسخ بده.' };
  if (!f.questions.length) return { error: 'این فرم هنوز سؤالی نداره.' };
  if (f.one_per_user) {
    const done = await env.DB.prepare('SELECT id FROM form_answers WHERE form_id = ? AND user_id = ? AND submitted = 1').bind(f.id, uid).first();
    if (done) return { error: 'تو قبلاً پاسخ دادی؛ این فرم فقط یک بار قابل پاسخ‌دادنه.' };
  }
  if (await env.KV.get(frmState(chatId, uid))) return { error: 'یه فرم نیمه‌کاره داری؛ اول همون رو تموم یا لغو کن.' };
  const r = await env.DB.prepare('INSERT INTO form_answers (form_id, user_id, name, submitted, created) VALUES (?, ?, ?, 0, ?)').bind(f.id, uid, String(name || '').slice(0, 40), Date.now()).run();
  const st = { f: f.id, aid: Number(r.meta?.last_row_id), pos: 0, chat: chatId, uid };
  await env.KV.put(frmState(chatId, uid), JSON.stringify(st), { expirationTtl: FRM.stateTtl });
  return { st };
}
async function frmCallback(env, cq) {
  const ans = (t, a) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: t, show_alert: !!a } : {}) });
  const parts = (cq.data || '').split(':');
  const act = parts[1];
  const fid = Number(parts[2]);
  const chat = cq.message?.chat;
  if (!chat || !env.DB) return ans();
  await frmInit(env);
  const f = await frmGet(env, fid);
  if (!f) return ans('این فرم پیدا نشد', true);
  const uid = cq.from.id;
  if (act === 's') {
    const r = await frmStart(env, chat.id, uid, cq.from.first_name, f);
    if (r.error) return ans(r.error, true);
    await ans('شروع شد');
    return frmSendQuestion(env, chat.id, f, 0);
  }
  const st = await env.KV.get(frmState(chat.id, uid), 'json');
  if (!st || st.f !== fid) return ans('این فرم برای تو فعال نیست. دوباره شروع کن.', true);
  if (act === 'c') {
    const pos = Number(parts[3]);
    const q = f.questions[pos];
    if (!q || pos !== st.pos) return ans('این سؤال دیگه فعال نیست.', true);
    const idx = Number(parts[4]);
    const value = q.qtype === 'yn' ? (idx === 1 ? 'بله' : 'خیر') : (q.options[idx] ?? null);
    if (value === null) return ans('گزینه‌ی نامعتبر', true);
    await frmSetValue(env, st.aid, q.id, value);
    await ans();
    return frmAdvance(env, chat.id, uid, st, f);
  }
  if (act === 'k') {
    const pos = Number(parts[3]);
    if (pos !== st.pos || f.questions[pos].required) return ans();
    await ans();
    return frmAdvance(env, chat.id, uid, st, f);
  }
  if (act === 'b') {
    if (st.pos === 0) return ans();
    const prev = f.questions[st.pos - 1];
    await env.DB.prepare('DELETE FROM form_values WHERE answer_id = ? AND question_id = ?').bind(st.aid, prev.id).run();
    await env.KV.put(frmState(chat.id, uid), JSON.stringify({ ...st, pos: st.pos - 1 }), { expirationTtl: FRM.stateTtl });
    await ans();
    return frmSendQuestion(env, chat.id, f, st.pos - 1);
  }
  if (act === 'x') {
    await env.DB.prepare('DELETE FROM form_values WHERE answer_id = ?').bind(st.aid).run();
    await env.DB.prepare('DELETE FROM form_answers WHERE id = ? AND submitted = 0').bind(st.aid).run();
    await env.KV.delete(frmState(chat.id, uid));
    await ans('لغو شد');
    return tg(env, 'sendMessage', { chat_id: chat.id, text: `❌ پاسخ‌دادن به «${f.title}» لغو شد.` });
  }
  return ans();
}
// a typed answer for a text question, when this user is in the middle of a form in this chat
async function frmText(env, m, text) {
  if (!env.DB || !text || text.startsWith('/')) return false;
  const st = await env.KV.get(frmState(m.chat.id, m.from.id), 'json');
  if (!st) return false;
  await frmInit(env);
  const f = await frmGet(env, st.f);
  const q = f && f.questions[st.pos];
  if (!f || !q) { await env.KV.delete(frmState(m.chat.id, m.from.id)); return false; }
  if (q.qtype !== 'text') { await tg(env, 'sendMessage', { chat_id: m.chat.id, text: 'لطفاً با دکمه‌ها جواب بده 🙂' }); return true; }
  const v = text.slice(0, FRM.maxText);
  await frmSetValue(env, st.aid, q.id, v);
  await frmAdvance(env, m.chat.id, m.from.id, st, f);
  return true;
}
const FRM_HELP = '📋 فرم‌ساز\n/form new public|private <عنوان>  (public: همه می‌تونن جواب بدن؛ private: فقط خودت)\n/form add <شناسه> text|choice|yn [optional] <سؤال> [| گزینه | گزینه]\n/form publish <شناسه> · /form close <شناسه> · /form end <شناسه> <مدت>\n/form stats <شناسه> · /form csv <شناسه> · /form list\nپاسخ‌ها فقط برای سازنده و ادمین‌های گروه دیده میشن.';
async function frmCmd(env, m, scope, text, uid, isOwner, inGroup) {
  const send = (t, kb) => tg(env, 'sendMessage', { chat_id: m.chat.id, text: t, ...(kb ? { reply_markup: kb } : {}), ...(inGroup ? { reply_parameters: { message_id: m.message_id, allow_sending_without_reply: true } } : {}), ...topicOf(m) });
  const body = text.replace(/^\/\S+\s*/, '').trim();
  const sub = (body.split(/\s+/)[0] || '').toLowerCase();
  const rest = body.slice(sub.length).trim();
  if (!env.DB) return send('📋 فرم‌ساز نیاز به D1 داره (binding به نام DB).');
  if (inGroup && (sub === 'new' || sub === 'publish') && !(isOwner || (await isAdminOf(env, scope, uid)))) return send('فقط ادمین‌های گروه می‌تونن فرم بسازن یا منتشر کنن.');
  if (!rateOk(`frm:${uid}`, 30, 60000)) return send('⏳ آروم‌تر؛ هر دقیقه حداکثر ۳۰ دستور فرم.');
  await frmInit(env);
  try {
    if (!sub) return send(FRM_HELP);
    if (sub === 'new') {
      const parts = rest.split(/\s+/);
      const kind = /^(private|خصوصی)$/i.test(parts[0]) ? 'private' : 'public';
      const title = (/^(public|private|عمومی|خصوصی)$/i.test(parts[0]) ? rest.slice(parts[0].length) : rest).trim().slice(0, 80);
      if (!title) return send('مثال: /form new public نظرسنجی ناهار');
      const r = await env.DB.prepare('INSERT INTO forms (chat_id, owner_id, title, kind, state, one_per_user, created) VALUES (?, ?, ?, ?, ?, 1, ?)').bind(scope || 0, uid, title, kind, 'draft', Date.now()).run();
      return send(`✅ فرم #${r.meta?.last_row_id} «${title}» ساخته شد (${kind === 'private' ? 'خصوصی' : 'عمومی'}، پیش‌نویس).\nسؤال اضافه کن: /form add ${r.meta?.last_row_id} text سؤال`);
    }
    if (sub === 'list') {
      const rows = (await env.DB.prepare('SELECT id, title, state, kind FROM forms WHERE chat_id = ? AND (owner_id = ? OR chat_id != 0) ORDER BY id DESC LIMIT 20').bind(scope || 0, uid).all()).results || [];
      return send(rows.length ? `📋 فرم‌ها\n${rows.map((r) => `#${r.id} • ${r.title} • ${r.state === 'open' ? '🟢 باز' : r.state === 'closed' ? '🔒 بسته' : '✏️ پیش‌نویس'} • ${r.kind === 'private' ? 'خصوصی' : 'عمومی'}`).join('\n')}` : 'فرمی ثبت نشده.');
    }
    const parts = rest.split(/\s+/);
    const id = parseInt(parts[0], 10);
    if (!(id > 0)) return send(FRM_HELP);
    const f = await frmGet(env, id);
    if (!f || (scope && f.chat_id !== scope) || (!scope && f.chat_id !== 0)) return send('همچین فرمی اینجا نیست.');
    if (!(await frmCanManage(env, f, uid))) return send('فقط سازنده یا ادمین گروه می‌تونه این فرم رو مدیریت کنه.');
    if (sub === 'add') {
      if (f.state !== 'draft') return send('فقط فرم پیش‌نویس سؤال می‌گیره.');
      if (f.questions.length >= FRM.maxQ) return send(`حداکثر ${toFa(FRM.maxQ)} سؤال.`);
      let r2 = parts.slice(1);
      let qtype = (r2[0] || '').toLowerCase();
      if (!['text', 'choice', 'yn'].includes(qtype)) return send('نوع سؤال: text | choice | yn');
      r2 = r2.slice(1);
      let required = 1;
      if (/^(optional|اختیاری)$/i.test(r2[0] || '')) { required = 0; r2 = r2.slice(1); }
      const joined = r2.join(' ');
      const [promptRaw, ...optRest] = joined.split('|');
      const prompt = promptRaw.trim().slice(0, 300);
      if (!prompt) return send('متن سؤال رو بنویس.');
      let options = [];
      if (qtype === 'choice') {
        options = optRest.map((o) => o.trim()).filter(Boolean).slice(0, FRM.maxOpts);
        if (options.length < 2) return send('برای سؤال انتخابی حداقل ۲ گزینه بعد از | بنویس.');
      }
      await env.DB.prepare('INSERT INTO form_questions (form_id, pos, qtype, prompt, options, required) VALUES (?, ?, ?, ?, ?, ?)').bind(id, f.questions.length, qtype, prompt, JSON.stringify(options), required).run();
      return send(`✅ سؤال ${toFa(f.questions.length + 1)} اضافه شد (${qtype}${required ? '' : '، اختیاری'}).`);
    }
    if (sub === 'publish') {
      if (!f.questions.length) return send('اول حداقل یک سؤال اضافه کن.');
      await env.DB.prepare("UPDATE forms SET state = 'open' WHERE id = ?").bind(id).run();
      const kb = frmKb([[{ text: '📝 شروع پاسخ‌دادن', callback_data: `fm:s:${id}` }]]);
      return tg(env, 'sendMessage', { chat_id: m.chat.id, text: `📋 فرم «${f.title}» باز شد (${toFa(f.questions.length)} سؤال). ${f.kind === 'private' ? 'فقط سازنده می‌تونه جواب بده.' : 'هر کسی می‌تونه جواب بده.'}`, reply_markup: kb, ...topicOf(m) });
    }
    if (sub === 'close') { await env.DB.prepare("UPDATE forms SET state = 'closed' WHERE id = ?").bind(id).run(); return send(`🔒 فرم #${id} بسته شد.`); }
    if (sub === 'end') {
      const d = parseDurSafe(parts[1] || '');
      if (d.error || !d.secs) return send('مدت رو بده، مثلاً /form end 3 2d (بعد از این مدت بسته میشه).');
      await env.DB.prepare('UPDATE forms SET ends_at = ? WHERE id = ?').bind(Date.now() + d.secs * 1000, id).run();
      return send(`⏳ فرم #${id} تا ${fmtTime(env, Date.now() + d.secs * 1000)} باز می‌مونه.`);
    }
    if (sub === 'stats') {
      const total = (await env.DB.prepare('SELECT COUNT(*) AS n FROM form_answers WHERE form_id = ? AND submitted = 1').bind(id).first())?.n || 0;
      if (!total) return send(`📊 «${f.title}»: هنوز پاسخی ثبت نشده.`);
      const lines = [];
      for (const q of f.questions) {
        const rows = (await env.DB.prepare('SELECT value, COUNT(*) AS n FROM form_values fv JOIN form_answers fa ON fa.id = fv.answer_id WHERE fa.form_id = ? AND fa.submitted = 1 AND fv.question_id = ? GROUP BY value ORDER BY n DESC').bind(id, q.id).all()).results || [];
        const answered = rows.reduce((a, r) => a + Number(r.n), 0);
        if (q.qtype === 'text') { lines.push(`• ${q.prompt}: ${toFa(answered)} پاسخ متنی (متن‌ها فقط در CSV)`); continue; }
        lines.push(`• ${q.prompt}: ${toFa(answered)} پاسخ` + rows.slice(0, 6).map((r) => `\n   ${r.value}: ${toFa(r.n)}`).join(''));
      }
      return send(`📊 «${f.title}» — ${toFa(total)} پاسخ کامل\n${lines.join('\n')}`);
    }
    if (sub === 'csv') {
      const ans = (await env.DB.prepare('SELECT id, name, user_id, created FROM form_answers WHERE form_id = ? AND submitted = 1 ORDER BY id').bind(id).all()).results || [];
      const esc2 = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
      const head = ['شناسه', 'نام', 'زمان', ...f.questions.map((q) => q.prompt)];
      const vals = await env.DB.prepare('SELECT answer_id, question_id, value FROM form_values WHERE answer_id IN (SELECT id FROM form_answers WHERE form_id = ? AND submitted = 1)').bind(id).all();
      const map = new Map();
      for (const v of vals.results || []) map.set(`${v.answer_id}:${v.question_id}`, v.value);
      const rows = ans.map((a) => [a.id, a.name, new Date(a.created).toISOString(), ...f.questions.map((q) => map.get(`${a.id}:${q.id}`) ?? '')].map(esc2).join(','));
      const csv = '\ufeff' + [head.map(esc2).join(','), ...rows].join('\n');
      const fd = new FormData();
      fd.append('chat_id', String(m.chat.id));
      fd.append('caption', `📄 پاسخ‌های «${f.title}» (${toFa(ans.length)} پاسخ)`);
      fd.append('document', new Blob([csv], { type: 'text/csv' }), `form-${id}.csv`);
      const r = await (await fetch(`https://api.telegram.org/bot${env.BOT_TOKEN}/sendDocument`, { method: 'POST', body: fd })).json();
      return r.ok ? undefined : send(explainTg(r));
    }
    return send(FRM_HELP);
  } catch (e) {
    console.error('forms', e);
    return send('⚠️ خطا در فرم‌ساز؛ دوباره امتحان کن.');
  }
}
// closes forms whose end time has passed (cron)
async function runForms(env) {
  if (!env.DB) return;
  await frmInit(env);
  await env.DB.prepare("UPDATE forms SET state = 'closed' WHERE state = 'open' AND ends_at IS NOT NULL AND ends_at <= ?").bind(Date.now()).run();
}

// shared helpers (kept after the games module was removed)
const pick = (a) => a[Math.floor(Math.random() * a.length)];
const topicOf = (m) => (m.is_topic_message && m.message_thread_id ? { message_thread_id: m.message_thread_id } : {});

// ======================= TAG-ALL (members the bot has seen; admins only; cooldown) =======================
const TAG = { perMsg: 15, max: 200, cooldownMs: 600000 };
let tagReady = false;
async function tagInit(env) {
  if (tagReady || !env.DB) return;
  await env.DB.batch([
    env.DB.prepare('CREATE TABLE IF NOT EXISTS seen_members (chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, name TEXT NOT NULL DEFAULT \'\', last_seen INTEGER NOT NULL, PRIMARY KEY (chat_id, user_id))'),
    env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_seen_chat ON seen_members (chat_id, last_seen)'),
  ]);
  tagReady = true;
}
// every human who writes or joins is remembered for the group (name kept only for the mention text)
async function recordSeen(env, chatId, u) {
  if (!env.DB || !u || u.is_bot) return;
  await tagInit(env);
  await env.DB.prepare('INSERT INTO seen_members (chat_id, user_id, name, last_seen) VALUES (?, ?, ?, ?) ON CONFLICT(chat_id, user_id) DO UPDATE SET name = excluded.name, last_seen = excluded.last_seen')
    .bind(chatId, u.id, String(u.first_name || u.username || u.id).slice(0, 40), Date.now()).run();
}
async function forgetSeen(env, chatId, u) {
  if (!env.DB || !u) return;
  await tagInit(env);
  await env.DB.prepare('DELETE FROM seen_members WHERE chat_id = ? AND user_id = ?').bind(chatId, u.id).run();
}
// "تگ" or "/tag" as the first word; anything after it is the message to put above the mentions
function tagTrigger(text) {
  const mt = text.match(/^(تگ|\/tag(?:all)?)(?:@\S+)?(?=\s|$)\s*([\s\S]*)$/i);
  return mt ? { body: mt[2].trim() } : null;
}
async function tagAll(env, m, g, body, uid, isOwner) {
  const chatId = m.chat.id;
  const say = (t) => reply(env, m, t, true);
  if (!(isOwner || (await isAdminOf(env, chatId, uid)))) return say('این دستور فقط برای ادمین‌های گروهه.');
  if (!env.DB) return say('🏷 تگ همه نیاز به D1 داره (binding به نام DB).');
  await tagInit(env);
  const cool = await env.KV.get(`tagcool:${chatId}`);
  if (cool) return say(`⏳ یه ${toFa(Math.ceil((Number(cool) - Date.now()) / 60000))} دقیقه‌ی دیگه می‌تونی دوباره تگ کنی.`);
  const rows = (await env.DB.prepare('SELECT user_id, name FROM seen_members WHERE chat_id = ? ORDER BY last_seen DESC LIMIT ?').bind(chatId, TAG.max).all()).results || [];
  if (!rows.length) return say('هنوز عضوی ثبت نشده. بات فقط کسایی رو می‌بینه که توی گروه پیام داده یا عضو شدن.');
  await env.KV.put(`tagcool:${chatId}`, String(Date.now() + TAG.cooldownMs), { expirationTtl: 700 });
  const replyTo = m.reply_to_message?.message_id;
  let sent = 0;
  for (let i = 0; i < rows.length; i += TAG.perMsg) {
    const part = rows.slice(i, i + TAG.perMsg);
    const mentions = part.map((r) => `<a href="tg://user?id=${Number(r.user_id)}">${esc(r.name)}</a>`).join('  ');
    const head = i === 0 && body ? `${esc(body)}\n\n` : '';
    const r = await tg(env, 'sendMessage', {
      chat_id: chatId,
      text: `${head}${mentions}`,
      parse_mode: 'HTML',
      link_preview_options: { is_disabled: true },
      ...(replyTo ? { reply_parameters: { message_id: replyTo, allow_sending_without_reply: true } } : {}),
      ...topicOf(m),
    });
    if (r.ok) sent += part.length;
  }
  await logAction(env, g, m, 'settings', { x: `تگ همه: ${toFa(sent)} نفر` });
  return sent;
}

// ======================= DONATE (empty by default — set DONATE_RIAL / DONATE_TON) =======================
const DONATE_RIAL = ''; // optional: your donation page (or set the DONATE_RIAL variable)
const DONATE_TON = ''; // optional: your TON wallet (or set the DONATE_TON variable)
const donateRial = (env) => (/^https:\/\/\S+$/i.test(String((env && env.DONATE_RIAL) || '')) ? String(env.DONATE_RIAL) : DONATE_RIAL);
const donateTon = (env) => String((env && env.DONATE_TON) || DONATE_TON || '').trim();
