// New bindings / vars (all optional except where noted):
//   DB            (D1)  required for: games & leaderboards, channel autopilot, translation cache
//   GAME_URL      (var) your Vercel game panel URL, e.g. https://watchdog-arcade.vercel.app
//   GAME_SHORT_NAME (var) short name of the game you created in @BotFather (/newgame), default "arcade"
//   PUBLIC_URL    (var) worker public origin (otherwise taken from /setup)
//   X4_GEN_HOUR   (var) local hour when the channel autopilot writes the day's drafts (default 7)
//   X4_AUTOTR     (var) "off" to disable automatic UI translation for non-Persian users

const X4_LANGS = [
  ['fa', '🇮🇷 فارسی', 'Persian'], ['en', '🇬🇧 English', 'English'], ['zh', '🇨🇳 中文', 'Simplified Chinese'],
  ['hi', '🇮🇳 हिन्दी', 'Hindi'], ['es', '🇪🇸 Español', 'Spanish'], ['ar', '🇸🇦 العربية', 'Arabic'],
  ['fr', '🇫🇷 Français', 'French'], ['ru', '🇷🇺 Русский', 'Russian'], ['pt', '🇧🇷 Português', 'Portuguese'],
];
const X4_LANG_CODES = X4_LANGS.map((x) => x[0]);
const x4LangName = (c) => (X4_LANGS.find((x) => x[0] === c) || X4_LANGS[0])[2];
const x4LangLabel = (c) => (X4_LANGS.find((x) => x[0] === c) || X4_LANGS[0])[1];
function x4GuessLang(code) {
  const c = String(code || '').toLowerCase().slice(0, 2);
  return X4_LANG_CODES.includes(c) ? c : c === 'ur' || c === 'bn' ? 'hi' : 'fa';
}

