        if (uid !== Number(env.OWNER_ID)) { return true; }
        if (!hasAiKey(env)) { await tg(env, 'sendMessage', { chat_id: uid, text: NO_KEY_MSG }); return true; }
        const v = await orModelView(env, 0, false);
