async function x4ApCmd(env, m, cmd, arg, L, isOwner) {
  const chatId = m.chat.id;
  const uid = m.from.id;
  if (!env.DB) return tg(env, 'sendMessage', { chat_id: chatId, ...x4M(L, 'needDb') });
  await x4Init(env);
  if (cmd === '/queue' || cmd === '/صف') return x4QueueView(env, chatId, uid, L, 0);
  const sub = (arg.split(/\s+/)[0] || '').toLowerCase();
  if (sub === 'help') return tg(env, 'sendMessage', { chat_id: chatId, ...x4M(L, 'apHelp') });
  if (sub === 'add') {
    const ref = arg.slice(3).trim().split(/\s+/)[0] || '';
    const target = /^-?\d+$/.test(ref) ? Number(ref) : ref.startsWith('@') ? ref : ref ? `@${ref.replace(/^https?:\/\/t\.me\//, '')}` : '';
    const info = target ? await tg(env, 'getChat', { chat_id: target }) : { ok: false };
    if (!info.ok || info.result?.type !== 'channel') return tg(env, 'sendMessage', { chat_id: chatId, ...x4M(L, 'chanNotAdmin') });
    const me = await botInfo(env);
    const bm = await tg(env, 'getChatMember', { chat_id: info.result.id, user_id: me.id });
    if (!bm.ok || bm.result?.status !== 'administrator' || !(await chanRole(env, info.result.id, uid))) return tg(env, 'sendMessage', { chat_id: chatId, ...x4M(L, 'chanNotAdmin') });
    await x4ChanJoined(env, info.result, m.from, bm.result);
    return;
  }
  return x4ApList(env, chatId, uid, L);
}
async function x4Reviewers(env, chan, adderId) {
  const out = new Set([Number(adderId)]);
  const r = await tg(env, 'getChatAdministrators', { chat_id: chan });
  if (r.ok) {
    for (const a of r.result || []) {
      if (out.size >= 5) break;
      const id = a.user?.id;
      if (!id || a.user.is_bot || out.has(id)) continue;
      const known = (await x4Get(env, `x4u:${id}`)) || (await env.KV.get(`usr:${id}`).catch(() => null));
      if (known || id === Number(env.OWNER_ID)) out.add(id);
    }
  }
  return [...out];
}
