async function x4ChanGenerate(env, row, opts = {}) {
  await ccInit(env);
  let plan = {};
  try { plan = JSON.parse(row.plan || '{}'); } catch {}
  if (!plan.type || Date.now() - Number(row.analyzed || 0) > 7 * 86400000) {
    const L = (await x4User(env, row.adder_id)).lang || 'fa';
    const np = await x4ChanAnalyze(env, row.chan_id, L);
    if (np && !np.error) plan = np;
    if (!plan.type) return { error: (np && np.error) || 'analysis' };
  }
  const n = Math.max(1, Math.min(8, Number(row.per_day) || Number(plan.posts_per_day) || 2));
  let hours = (plan.hours || []).filter((h) => /^\d{2}:\d{2}$/.test(h)).sort();
  if (hours.length < n) {
    const fill = [];
    for (let i = 0; i < n; i++) fill.push(`${String(Math.round(9 + (i * 13) / Math.max(1, n - 1 || 1))).padStart(2, '0')}:00`);
    hours = [...new Set([...hours, ...fill])].sort();
  }
  const slots = [];
  for (let i = 0; i < n; i++) slots.push(hours[Math.floor((i * hours.length) / n)]);
  const p = await ccProfile(env, row.chan_id);
  const recent = ((await env.DB.prepare('SELECT body FROM content_drafts WHERE chan_id = ? ORDER BY id DESC LIMIT 8').bind(row.chan_id).all()).results || []).map((x) => String(x.body).slice(0, 160));
  const cfg = await userAiCfgReady(env, row.adder_id).catch(() => null);
  if (!cfg && !hasAiKey(env)) return { error: 'AI' };
  const pl = { type: plan.type, topic: plan.topic, audience: plan.audience, tone: plan.tone, language: plan.language, avg_len: plan.avg_len, pillars: plan.pillars, style: plan.style, emoji: plan.emoji, hashtags: plan.hashtags, cta: plan.cta, mix: plan.mix };
  // Built-in content skills: editorial strategy, conversion copywriting, audience retention,
  // natural-language editing, and factuality control. These are prompt modules, not external deps.
  const sys = `You are a senior Telegram channel editor and writer for "${row.title}". Apply these skills together:
1) EDITORIAL STRATEGIST: serve this channel's audience and content pillars; make each post useful, specific, and appropriate to the niche.
2) COPYWRITER: open with a concrete hook (a surprising angle, useful promise, sharp question, or direct point); deliver the value quickly; end naturally, with a CTA only when it fits.
3) AUDIENCE RETENTION: use short mobile-friendly paragraphs, varied sentence rhythm, strong information order, and one clear central idea per post.
4) NATURAL HUMAN EDITOR: sound like a knowledgeable person who runs this channel, not a generic AI. Avoid formulaic intros, repetitive conclusions, corporate filler, fake enthusiasm, overexplaining, empty claims, and stock phrases such as "در دنیای امروز", "در این مقاله", "بیایید بررسی کنیم", "نکته مهم این است", "در نهایت" unless genuinely fitting. Do not add fake personal stories or pretend to have firsthand experience. Vary structure between posts.
5) FACT CHECKER: never invent news, facts, prices, statistics, citations, quotes, names, or links. If evidence is missing, write evergreen guidance, analysis, a useful question, or clearly framed opinion instead.

Write ${n} distinct, ready-to-publish posts following this channel profile: ${JSON.stringify(pl)}.
Language: ${plan.language || 'the language of the samples'}. Match the examples' actual voice and formality, average length (~${plan.avg_len || p.avgLen || 300} characters), emoji level, and hashtag habits; do not copy their wording. Use a different pillar/angle for each post. Avoid generic advice and repeated hooks. Be concrete: include practical steps, examples, comparisons, or a useful perspective when appropriate to the topic. Keep claims proportional to available information. Use plain text and Telegram-friendly line breaks; no markdown headings unless the channel uses them; no preamble.
Output ONLY a JSON array of ${n} objects: [{"text":"...","pillar":"..."}]. Ensure valid JSON and non-empty text for every object.`;
  const user = `CHANNEL STYLE EXAMPLES (imitate voice and formatting, never copy phrases):\n${p.samples.map((s, i) => `${i + 1}) ${String(s).slice(0, 500)}`).join('\n') || '(none yet)'}\n\nRECENTLY GENERATED (avoid repeating topics, structure, hooks, and wording):\n${recent.map((s) => `- ${s}`).join('\n') || '(none)'}${opts.topic ? `\n\nOWNER'S TOPIC REQUEST (prioritize this): ${opts.topic}` : ''}\n\nCreate genuinely different posts for this channel's actual readers. Prefer one clear takeaway over padding.`;
  const messages = [{ role: 'system', content: sys }, { role: 'user', content: user }];
  const options = { max_tokens: Math.min(4000, 400 + n * Math.round((Number(plan.avg_len) || 350) * 1.3)), temperature: 0.8 };
  let r = await x4LLM(env, messages, { ...options, cfg });
  let arr = x4Json(r.text);
  let posts = (Array.isArray(arr) ? arr : []).map((x) => (typeof x === 'string' ? x : x && x.text)).filter((t) => typeof t === 'string' && t.trim().length > 10).slice(0, n);
  // Some custom providers return an empty or non-JSON answer despite HTTP success.
  // Retry via the bot's default AI, then fall back to plain-text output instead of failing with "empty".
  if (r.error || !posts.length) {
    const fallbackMessages = r.error || !String(r.text || '').trim()
      ? messages
      : [{ role: 'system', content: `Write one ready-to-publish Telegram channel post in ${plan.language || 'the channel language'}. Match the channel's tone and topic. Output ONLY the post text, no JSON and no explanation. Do not invent facts or links.` }, { role: 'user', content: `${user}${opts.topic ? `\nTopic: ${opts.topic}` : ''}` }];
    const fallback = await x4LLM(env, fallbackMessages, { ...options, cfg: null }).catch(() => ({ error: 'fallback failed', text: '' }));
    const fallbackArr = x4Json(fallback.text);
    posts = (Array.isArray(fallbackArr) ? fallbackArr : []).map((x) => (typeof x === 'string' ? x : x && x.text)).filter((t) => typeof t === 'string' && t.trim().length > 10).slice(0, n);
    if (!posts.length && String(fallback.text || '').trim().length > 10) posts = [String(fallback.text).trim()];
    if (!posts.length) return { error: String(r.error || fallback.error || 'AI پاسخ قابل استفاده‌ای نداد').slice(0, 180) };
  }
  // Humanizer pass: improve flow and remove template-like phrasing without changing facts.
  // If the custom provider returns nothing or invalid JSON, try the default provider; if both fail,
  // preserve the already-generated drafts rather than failing the whole run.
  try {
    const humanizeMessages = [
      { role: 'system', content: `You are a meticulous native-language editor. Edit the supplied Telegram posts so they read naturally and specifically for their audience. Preserve the language, meaning, factual claims, names, numbers, links, channel voice, and approximate length. Remove robotic transitions, repetitive sentence patterns, generic filler, forced enthusiasm, and awkward phrasing. Do not add facts, invented personal experiences, unsupported claims, or new links. Keep each post's distinct angle and useful details. Do not make every post follow the same structure. Return ONLY valid JSON in the same array format: [{"text":"...","pillar":"..."}].` },
      { role: 'user', content: JSON.stringify(posts.map((text, i) => ({ text, pillar: (Array.isArray(arr) && arr[i] && arr[i].pillar) || (Array.isArray(pl.pillars) && pl.pillars[i % Math.max(1, pl.pillars.length)]) || pl.topic || '' }))) }
    ];
    let hr = await x4LLM(env, humanizeMessages, { cfg, max_tokens: Math.min(4000, 400 + n * Math.round((Number(plan.avg_len) || 350) * 1.3)), temperature: 0.45 });
    let hj = x4Json(hr.text);
    let hp = (Array.isArray(hj) ? hj : []).map((x) => typeof x === 'string' ? x : x && x.text).filter((t) => typeof t === 'string' && t.trim().length > 10).slice(0, posts.length);
    if (hp.length !== posts.length) {
      hr = await x4LLM(env, humanizeMessages, { max_tokens: Math.min(4000, 400 + n * Math.round((Number(plan.avg_len) || 350) * 1.3)), temperature: 0.45 });
      hj = x4Json(hr.text);
      hp = (Array.isArray(hj) ? hj : []).map((x) => typeof x === 'string' ? x : x && x.text).filter((t) => typeof t === 'string' && t.trim().length > 10).slice(0, posts.length);
    }
    if (hp.length === posts.length) posts = hp;
  } catch { /* Keep original generated posts if editing fails. */ }

  const reviewers = await x4Reviewers(env, row.chan_id, row.adder_id);
  const made = [];
  for (let i = 0; i < posts.length; i++) {
    const at = x4NextAt(env, slots[i] || slots[0], 30) || Date.now() + (i + 1) * 3600000;
    const ins = await env.DB.prepare("INSERT INTO content_drafts (chan_id, owner_id, body, status, publish_at, created) VALUES (?, ?, ?, 'pending', ?, ?)").bind(row.chan_id, row.adder_id, posts[i].trim().slice(0, CC.draftMax), at, Date.now()).run();
    made.push({ id: ins.meta?.last_row_id, body: posts[i].trim().slice(0, CC.draftMax), publish_at: at });
  }
  made.sort((a, b) => a.publish_at - b.publish_at);
  for (const d of made) for (const uid of reviewers) await x4SendDraftReview(env, d, uid, row.title).catch(() => {});
  return { n: made.length };
}
async function x4DraftAuth(env, id, uid) {
  await ccInit(env);
  const d = await env.DB.prepare('SELECT * FROM content_drafts WHERE id = ?').bind(Number(id)).first();
  if (!d) return null;
  if (d.owner_id !== uid && uid !== Number(env.OWNER_ID) && !(await chanRole(env, d.chan_id, uid))) return null;
  return d;
}
async function x4DraftInput(env, m, u, text, L) {
  const uid = m.from.id;
  const ed = u.ed;
  await x4UserSave(env, uid, { ed: null });
  const d = await x4DraftAuth(env, ed.d, uid);
  if (!d || !['pending', 'approved'].includes(d.status)) return tg(env, 'sendMessage', { chat_id: uid, ...x4M(L, 'draftGone') });
  const row = await x4ChanRow(env, d.chan_id);
  if (ed.k === 'time') {
    const at = x4NextAt(env, text.trim(), 2);
    if (!at) { await x4UserSave(env, uid, { ed }); return tg(env, 'sendMessage', { chat_id: uid, ...x4M(L, 'draftBadTime') }); }
    await env.DB.prepare('UPDATE content_drafts SET publish_at = ?, tries = 0 WHERE id = ?').bind(at, d.id).run();
    d.publish_at = at;
  } else {
    const body = text.trim().slice(0, CC.draftMax);
    await env.DB.prepare('UPDATE content_drafts SET body = ? WHERE id = ?').bind(body, d.id).run();
    d.body = body;
  }
  return x4SendDraftReview(env, d, uid, row?.title || String(d.chan_id));
}
async function x4ApCallback(env, cq, u, L, ans) {
  const uid = cq.from.id;
  const mid = cq.message?.message_id;
  const [pre, act, idS] = (cq.data || '').split(':');
  const fa = L === 'fa';
  const l = x4L2(L);
  if (!env.DB) return ans(x4S(l, 'needDb'), true);
  await x4Init(env); await ccInit(env);
  if (pre === 'xd' || act === 'x' || act === 'now' || act === 'show') {
    const d = await x4DraftAuth(env, idS, uid);
    if (!d) return ans(fa ? 'این پیش‌نویس مال تو نیست' : 'Not your draft', true);
    const row = await x4ChanRow(env, d.chan_id);
    const title = row?.title || String(d.chan_id);
    const live = ['pending', 'approved'].includes(d.status);
    if (act === 'show') { await ans(); return x4SendDraftReview(env, d, uid, title); }
    if (!live) return ans(x4S(l, 'draftGone'), true);
    const by = x4Name(cq.from);
    if (act === 'x' || act === 'no') {
      await env.DB.prepare("UPDATE content_drafts SET status = 'rejected' WHERE id = ?").bind(d.id).run();
      await ans('🗑');
      if (act === 'no') return tg(env, 'editMessageText', { chat_id: uid, message_id: mid, text: `${x4DraftText(env, d, title, l)}\n\n${x4S(l, 'draftNo', { by })}`, x4raw: true });
      return x4QueueView(env, uid, uid, L, 0, mid);
    }
    if (act === 'ok' || act === 'now') {
      const at = act === 'now' ? Date.now() : Math.max(Number(d.publish_at || 0), Date.now() + 60000);
      await env.DB.prepare("UPDATE content_drafts SET status = 'approved', publish_at = ?, tries = 0 WHERE id = ?").bind(at, d.id).run();
      await ans('✅');
      if (act === 'now') { await runChanDrafts(env).catch(() => {}); return x4QueueView(env, uid, uid, L, 0, mid); }
      return tg(env, 'editMessageText', { chat_id: uid, message_id: mid, text: `${x4DraftText(env, { ...d, publish_at: at }, title, l)}\n\n${x4S(l, 'draftOk', { t: x4Hm(env, at), by })}`, x4raw: true, reply_markup: { inline_keyboard: [[{ text: fa ? '🚀 همین الان منتشر کن' : '🚀 Publish now', callback_data: `xc:now:${d.id}` }, { text: fa ? '🗑 لغو' : '🗑 Cancel', callback_data: `xc:x:${d.id}` }]] } });
    }
    if (act === 'ed' || act === 'tm') {
      await x4UserSave(env, uid, { ed: { d: d.id, k: act === 'tm' ? 'time' : 'text', exp: Date.now() + 20 * 60000 } });
      await ans();
      return tg(env, 'sendMessage', { chat_id: uid, ...x4M(L, act === 'tm' ? 'draftTime' : 'draftEdit', { id: d.id }), reply_markup: { inline_keyboard: [[{ text: x4Btn(L, 'b_cancel'), callback_data: 'nx:x' }]] } });
    }
    if (act === 'rw') {
      await ans('🔁');
      const cfg = await userAiCfgReady(env, uid).catch(() => null) || await userAiCfgReady(env, row?.adder_id).catch(() => null);
      const r = await x4LLM(env, [{ role: 'system', content: 'Act as a skilled native-language Telegram editor and humanizer. Rewrite this post with a genuinely fresh, useful angle while preserving its facts, meaning, language, channel voice, approximate length, emoji level and hashtag habit. Remove generic AI phrasing, filler, repetitive transitions and stiff wording. Use natural rhythm and mobile-friendly paragraphs. Do not invent facts, fake personal experience, or add links. Output only the final post.' }, { role: 'user', content: String(d.body) }], { cfg, max_tokens: 1200, temperature: 0.9 });
      if (r.error || !r.text) return tg(env, 'sendMessage', { chat_id: uid, ...x4M(L, 'chanGenFail', { e: String(r.error || 'empty').slice(0, 120) }) });
      const body = r.text.slice(0, CC.draftMax);
      await env.DB.prepare('UPDATE content_drafts SET body = ? WHERE id = ?').bind(body, d.id).run();
      return x4SendDraftReview(env, { ...d, body }, uid, title, mid);
    }
    return ans();
  }
  // channel-level actions
  if (act === 'l') { await ans(); return x4ApList(env, uid, uid, L, mid); }
  const chan = Number(idS);
  const row = await x4ChanRow(env, chan);
  if (!row || (row.adder_id !== uid && uid !== Number(env.OWNER_ID) && !(await chanRole(env, chan, uid)))) return ans(x4S(l, 'chanNotAdmin'), true);
  if (act === 'v') { await ans(); return x4SendPlan(env, uid, chan, L, mid); }
  if (act === 'on' || act === 'off') {
    await env.DB.prepare('UPDATE x4_chan SET active = ? WHERE chan_id = ?').bind(act === 'on' ? 1 : 0, chan).run();
    await ans(act === 'on' ? '🚀' : '⏸');
    await x4SendPlan(env, uid, chan, L, mid);
    return tg(env, 'sendMessage', { chat_id: uid, ...x4M(L, act === 'on' ? 'chanOn' : 'chanOff', { h: String(Number(env.X4_GEN_HOUR ?? 7)).padStart(2, '0') }) });
  }
  if (act === 'pm' || act === 'pp') {
    const n = Math.max(1, Math.min(8, (Number(row.per_day) || 2) + (act === 'pp' ? 1 : -1)));
    await env.DB.prepare('UPDATE x4_chan SET per_day = ? WHERE chan_id = ?').bind(n, chan).run();
    await ans(String(n));
    return x4SendPlan(env, uid, chan, L, mid);
  }
  if (act === 'an') {
    await ans('🧭');
    const plan = await x4ChanAnalyze(env, chan, L);
    if (plan.error) return tg(env, 'sendMessage', { chat_id: uid, ...x4M(L, 'chanGenFail', { e: String(plan.error).slice(0, 120) }) });
    return x4SendPlan(env, uid, chan, L);
  }
  if (act === 'gen') {
    if (!rateOk(`x4gen:${chan}`, 3, 3600000)) return ans(x4S(l, 'slow'), true);
    await ans('✍️');
    await tg(env, 'sendMessage', { chat_id: uid, ...x4M(L, 'chanGen') });
    const r = await x4ChanGenerate(env, row, {});
    return tg(env, 'sendMessage', { chat_id: uid, ...(r.error ? x4M(L, 'chanGenFail', { e: String(r.error).slice(0, 150) }) : x4M(L, 'chanGenDone', { n: r.n })) });
  }
  if (act === 'q') { await ans(); return x4QueueView(env, uid, uid, L, chan, mid); }
  return ans();
}
async function x4CronChannels(env) {
  if (!env.DB) return;
  await x4Init(env); await ccInit(env);
  const now = Date.now();
  // drafts nobody reviewed before their time are dropped (nothing is ever published without approval)
  await env.DB.prepare("UPDATE content_drafts SET status = 'rejected' WHERE status = 'pending' AND publish_at IS NOT NULL AND publish_at < ? AND chan_id IN (SELECT chan_id FROM x4_chan)").bind(now - 30 * 60000).run();
  const lp = localParts(env);
  if (lp.h < Number(env.X4_GEN_HOUR ?? 7)) return;
  const rows = (await env.DB.prepare('SELECT * FROM x4_chan WHERE active = 1 AND last_gen != ? LIMIT 2').bind(lp.date).all()).results || [];
  for (const row of rows) {
    await env.DB.prepare('UPDATE x4_chan SET last_gen = ? WHERE chan_id = ?').bind(lp.date, row.chan_id).run();
    const r = await x4ChanGenerate(env, row, {}).catch((e) => ({ error: String(e && e.message || e) }));
    if (r.error) {
      const L = (await x4User(env, row.adder_id)).lang || 'fa';
      await tg(env, 'sendMessage', { chat_id: row.adder_id, ...x4M(L, 'chanGenFail', { e: `«${row.title}»: ${String(r.error).slice(0, 140)}` }) });
    }
  }
}
async function x4Cron(env) {
  const jobs = [x4CronTourney(env)];
  if (new Date().getUTCMinutes() % 5 === 0) jobs.push(x4CronChannels(env));
  if (env.DB && new Date().getUTCMinutes() === 17) jobs.push((async () => { await x4Init(env); await env.DB.prepare('DELETE FROM x4_kv WHERE exp > 0 AND exp < ?').bind(Date.now()).run(); })());
  await Promise.allSettled(jobs);
}

