// ======================= D1 GROWTH & GROUP TENSION =======================
let growthReady = false;
const GROWTH_SCHEMA = [
  'CREATE TABLE IF NOT EXISTS d1_daily (kind TEXT NOT NULL, user_id INTEGER NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(kind,user_id,day))',
  'CREATE TABLE IF NOT EXISTS referrals (user_id INTEGER PRIMARY KEY, referrer_id INTEGER, created INTEGER NOT NULL)',
  'CREATE INDEX IF NOT EXISTS idx_referrals_referrer ON referrals (referrer_id)',
  'CREATE TABLE IF NOT EXISTS tension_messages (chat_id INTEGER NOT NULL, message_id INTEGER NOT NULL, user_id INTEGER NOT NULL, name TEXT NOT NULL, text TEXT NOT NULL, reply_user INTEGER, created INTEGER NOT NULL, PRIMARY KEY(chat_id,message_id))',
  'CREATE INDEX IF NOT EXISTS idx_tension_recent ON tension_messages(chat_id,created)',
  "CREATE TABLE IF NOT EXISTS tension_incidents (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER NOT NULL, user_a INTEGER NOT NULL, user_b INTEGER NOT NULL, name_a TEXT NOT NULL, name_b TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', topic TEXT NOT NULL DEFAULT '', is_real INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, hour INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', closed_until INTEGER NOT NULL DEFAULT 0)",
  'CREATE INDEX IF NOT EXISTS idx_tension_week ON tension_incidents(chat_id,created,is_real)',
];
async function growthInit(env) {
  if (growthReady || !env.DB) return;
  await env.DB.batch(GROWTH_SCHEMA.map((q) => env.DB.prepare(q)));
  growthReady = true;
}
async function d1DailyLimit(env, kind, userId, max) {
  await growthInit(env);
  const day = new Date().toISOString().slice(0, 10);
  const r = await env.DB.prepare("INSERT INTO d1_daily(kind,user_id,day,n) VALUES(?,?,?,1) ON CONFLICT(kind,user_id,day) DO UPDATE SET n=n+1 WHERE n < ?")
    .bind(kind, userId, day, max).run();
  return Number(r?.meta?.changes || 0) > 0;
}
function tensionName(u) { return [u?.first_name, u?.last_name].filter(Boolean).join(' ').trim().slice(0, 80) || 'کاربر'; }
async function referralLink(env, m) {
  const say = (text) => tg(env, 'sendMessage', { chat_id: m.chat.id, text });
  if (!env.DB) return say('برای لینک دعوت، مالک بات باید D1 رو با نام DB وصل کنه.');
  try {
    await growthInit(env);
    const me = await botInfo(env);
    const row = await env.DB.prepare('SELECT COUNT(*) AS n FROM referrals WHERE referrer_id = ?').bind(m.from.id).first();
    const refs = Number(row?.n || 0);
    const bonus = Math.min(50, refs * 5);
    return say(`لینک دعوت اختصاصی تو:\nhttps://t.me/${me.username}?start=ref_${m.from.id}\n\nدعوت موفق: ${refs}\nسهمیه‌ی اضافه‌ی AI: روزی ${bonus} پیام (۵ تا برای هر دعوت، تا سقف ۵۰).`);
  } catch (e) { await reportError(env, 'referral link', e); return say('الان نتونستم لینک دعوت رو بسازم.'); }
}
async function registerReferral(env, m) {
  if (!env.DB) return;
  await growthInit(env);
  const raw = String(m.text || '').match(/^\/start(?:@\S+)?\s+ref_([A-Za-z0-9_-]+)/i)?.[1] || '';
  const referrer = Number(raw);
  if (!Number.isSafeInteger(referrer) || referrer <= 0 || referrer === Number(m.from.id) || m.from.is_bot) return;
  const r = await env.DB.prepare('INSERT OR IGNORE INTO referrals(user_id,referrer_id,created) VALUES(?,?,?)').bind(m.from.id, referrer, Date.now()).run();
  if (Number(r?.meta?.changes || 0) > 0) await tg(env, 'sendMessage', { chat_id: referrer, text: '🎉 یه نفر با لینک تو اومد! روزی ۵ پیام AI اضافه گرفتی. برای لینک دعوت دوباره /ref بزن.' });
}
async function growthCron(env) { // housekeeping for the daily counters
  if (!env.DB) return;
  await growthInit(env);
  await env.DB.prepare('DELETE FROM d1_daily WHERE day < ?').bind(new Date(Date.now() - 14 * 86400000).toISOString().slice(0, 10)).run();
}

async function tensionObserve(env, m, text) {
  if (!env.DB || !m.from || m.from.is_bot || !m.chat?.id || m.chat.type === 'private') return;
  if (text.length > 800 || /^\//.test(text)) return;
  await growthInit(env);
  const replyUid = Number(m.reply_to_message?.from?.id || 0) || null;
  const now = Date.now();
  await env.DB.prepare('INSERT OR IGNORE INTO tension_messages(chat_id,message_id,user_id,name,text,reply_user,created) VALUES(?,?,?,?,?,?,?)')
    .bind(m.chat.id, m.message_id, m.from.id, tensionName(m.from), text.slice(0, 800), replyUid, now).run();
  await env.DB.prepare('DELETE FROM tension_messages WHERE chat_id = ? AND created < ?').bind(m.chat.id, now - 10 * 60000).run();
  const rows = (await env.DB.prepare('SELECT user_id,name,text,reply_user,created FROM tension_messages WHERE chat_id = ? AND created > ? ORDER BY created DESC LIMIT 20').bind(m.chat.id, now - 180000).all()).results || [];
  if (rows.length < 8) return;
  const pair = new Map();
  let punctuation = 0, stressWords = 0;
  const kw = /(?:خفه|برو گمشو|دعوا|می‌کشمت|می کشمت|احمق|بی‌شعور|بی شعور|دروغگو|دروغ‌گو|stop it|shut up|idiot|hate|fight|angry)/i;
  for (const r of rows) {
    const ex = (String(r.text).match(/[!！?؟]{2,}/g) || []).join('').length;
    const caps = (String(r.text).match(/[A-Z]{4,}/g) || []).length;
    punctuation += ex > 0 || caps > 0 ? 1 : 0;
    stressWords += kw.test(String(r.text)) ? 1 : 0;
    if (r.reply_user && Number(r.reply_user) !== Number(r.user_id)) {
      const a = Math.min(Number(r.user_id), Number(r.reply_user)), b = Math.max(Number(r.user_id), Number(r.reply_user));
      const k = `${a}:${b}`; pair.set(k, (pair.get(k) || 0) + 1);
    }
  }
  const best = [...pair.entries()].sort((a,b)=>b[1]-a[1])[0];
  const pairSignal = best && best[1] >= 3;
  if (!pairSignal && punctuation < 3 && stressWords < 2) return;
  const recent = (await env.DB.prepare('SELECT id FROM tension_incidents WHERE chat_id = ? AND created > ? LIMIT 1').bind(m.chat.id, now - 30 * 60000).first());
  if (recent) return;
  const users = best ? best[0].split(':').map(Number) : [...new Set(rows.map((x) => Number(x.user_id)))].slice(0, 2);
  if (users.length < 2 || users[0] === users[1]) return;
  const pairRows = rows.filter((x) => users.includes(Number(x.user_id)));
  const nameA = pairRows.find((x) => Number(x.user_id) === users[0])?.name || String(users[0]);
  const nameB = pairRows.find((x) => Number(x.user_id) === users[1])?.name || String(users[1]);
  const lp = localParts(env);
  const ins = await env.DB.prepare("INSERT INTO tension_incidents(chat_id,user_a,user_b,name_a,name_b,created,hour,status) VALUES(?,?,?,?,?,?,?,'checking')")
    .bind(m.chat.id, users[0], users[1], nameA, nameB, now, lp.h).run();
  const iid = Number(ins?.meta?.last_row_id || 0);
  if (!iid) return;
  const context = rows.slice().reverse().map((x) => `${x.name}: ${x.text}`).join('\n');
  const run = tensionEvaluate(env, iid, m.chat, context).catch((e) => reportError(env, 'tension evaluate', e));
  if (env._ctx?.waitUntil) env._ctx.waitUntil(run); else await run;
}
async function tensionEvaluate(env, id, chat, context) {
  if (!hasAiKey(env)) return;
  const groupCfg = await getGroup(env, chat.id);
  if (!await aiAllowed(env, `g${chat.id}`, LIMITS.groupPerDay, groupCfg)) { await env.DB.prepare("UPDATE tension_incidents SET status='quota' WHERE id=?").bind(id).run(); return; }
  const prompt = 'این پیام‌های اخیر یک گروه را از نظر تنش واقعی بررسی کن. شوخی دوستانه را تنش حساب نکن. فقط JSON بده: {"real":true/false,"summary":"خلاصه‌ی دو خطی فارسی","topic":"موضوع کوتاه"}.\n' + context;
  const result = await aiTask(env, groupCfg, 'داور بی‌طرف گفت‌وگوی گروهی هستی؛ دقیق و کوتاه.', prompt);
  let o = null;
  try { const a = result.indexOf('{'), b = result.lastIndexOf('}'); o = JSON.parse(result.slice(a, b + 1)); } catch {}
  const real = !!o?.real;
  const summary = String(o?.summary || '').slice(0, 400);
  const topic = String(o?.topic || 'نامشخص').slice(0, 80);
  await env.DB.prepare("UPDATE tension_incidents SET is_real=?,summary=?,topic=?,status=? WHERE id=?").bind(real ? 1 : 0, summary, topic, real ? 'alerted' : 'joke', id).run();
  if (!real) return;
  const incident = await env.DB.prepare('SELECT name_a,name_b FROM tension_incidents WHERE id=?').bind(id).first();
  const admins = await tg(env, 'getChatAdministrators', { chat_id: chat.id });
  for (const a of (admins.result || []).filter((x) => !x.user.is_bot)) {
    const text = `⚠️ تب‌سنج گروه: تنش بین ${incident?.name_a || 'X'} و ${incident?.name_b || 'Y'} بالا رفته.\n${summary}`;
    await tg(env, 'sendMessage', { chat_id: a.user.id, text, reply_markup: { inline_keyboard: [[{ text: '🔒 بستن گروه ۱۰ دقیقه', callback_data: `th:${id}:c` }], [{ text: `⚠️ اخطار به ${incident?.name_a || 'X'}`, callback_data: `th:${id}:w` }, { text: '🙈 نادیده بگیر', callback_data: `th:${id}:i` }]] } }).catch(() => {});
  }
}
async function tensionCallback(env, cq) {
  const [_, idRaw, act] = String(cq.data || '').split(':');
  const id = Number(idRaw);
  const ans = (t, alert = false) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: t, show_alert: alert } : {}) });
  if (!Number.isSafeInteger(id) || !['c','w','i'].includes(act) || !env.DB) return ans('درخواست نامعتبره.', true);
  await growthInit(env);
  const row = await env.DB.prepare('SELECT * FROM tension_incidents WHERE id=?').bind(id).first();
  if (!row) return ans('گزارش پیدا نشد.', true);
  if (!(await isAdminOf(env, row.chat_id, cq.from.id)) && Number(cq.from.id) !== Number(env.OWNER_ID)) return ans('فقط ادمین‌های گروه.', true);
  if (act === 'i') { await env.DB.prepare("UPDATE tension_incidents SET status='ignored' WHERE id=?").bind(id).run(); return ans('نادیده گرفته شد.'); }
  if (act === 'c') {
    const g = await getGroup(env, row.chat_id);
    if (!g) return ans('تنظیمات گروه در دسترس نیست.', true);
    const r = await setGroupOpen(env, row.chat_id, false, g);
    if (!r.ok) return ans(explainTg(r), true);
    await env.DB.prepare('UPDATE tension_incidents SET status=?,closed_until=? WHERE id=?').bind('closed', Date.now() + 10 * 60000, id).run();
    await env.KV.put(`grp:${row.chat_id}`, JSON.stringify(g));
    return ans('گروه برای ۱۰ دقیقه بسته شد.');
  }
  const target = { id: row.user_a, name: row.name_a };
  const g = await getGroup(env, row.chat_id);
  if (!g) return ans('تنظیمات گروه در دسترس نیست.', true);
  await addWarn(env, g, row.chat_id, target, 'تب‌سنج: تنش گفت‌وگو');
  await env.DB.prepare("UPDATE tension_incidents SET status='warned' WHERE id=?").bind(id).run();
  return ans(`اخطار به ${row.name_a} ثبت شد.`);
}
async function tensionCron(env) {
  if (!env.DB) return;
  await growthInit(env);
  const rows = (await env.DB.prepare("SELECT id,chat_id FROM tension_incidents WHERE status='closed' AND closed_until > 0 AND closed_until <= ? LIMIT 20").bind(Date.now()).all()).results || [];
  for (const r of rows) {
    const g = await getGroup(env, r.chat_id);
    if (g) { await setGroupOpen(env, r.chat_id, true, g).catch(() => {}); await env.KV.put(`grp:${r.chat_id}`, JSON.stringify(g)).catch(() => {}); }
    await env.DB.prepare("UPDATE tension_incidents SET status='reopened',closed_until=0 WHERE id=?").bind(r.id).run();
  }
  await env.DB.prepare('DELETE FROM tension_messages WHERE created < ?').bind(Date.now() - 10 * 60000).run();
}
async function tensionReport(env, m) {
  if (!env.DB) return reply(env, m, 'گزارش تنش به D1 نیاز داره.', true);
  if (!(await isAdminOf(env, m.chat.id, m.from.id)) && String(m.from.id) !== String(env.OWNER_ID)) return reply(env, m, 'این گزارش فقط برای ادمین‌هاست.', true);
  await growthInit(env);
  const since = Date.now() - 7 * 86400000;
  const rows = (await env.DB.prepare('SELECT hour,topic,COUNT(*) AS n FROM tension_incidents WHERE chat_id=? AND created>=? AND is_real=1 GROUP BY hour,topic ORDER BY n DESC LIMIT 10').bind(m.chat.id, since).all()).results || [];
  if (!rows.length) return reply(env, m, 'این هفته تنش واقعی ثبت نشده. 👍', true);
  return reply(env, m, `📊 گزارش تنش هفته\\n${rows.map((r) => `• ساعت ${String(r.hour).padStart(2,'0')}: ${r.topic || 'نامشخص'} (${r.n})`).join('\\n')}`, true);
}


