const YA_PRICE_HTML = "<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\"/>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n<title>YAprice — نبض بازار</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"/>\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&display=swap\" rel=\"stylesheet\"/>\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<script>\ntailwind.config={theme:{extend:{fontFamily:{sans:['Vazirmatn','system-ui','sans-serif']},colors:{ya:{bg:'#0a0a0b',card:'#141416',line:'#2a0f12',red:'#e11d48',red2:'#fb7185',muted:'#a1a1aa'}}}}}\n</script>\n<style>\nbody{background:#0a0a0b;color:#fafafa;font-family:Vazirmatn,system-ui,sans-serif}\n.card{background:#141416;border:1px solid #2a0f12;border-radius:1rem}\n.pill{background:rgba(225,29,72,.12);border:1px solid rgba(225,29,72,.35);color:#fb7185}\n.tab.active{background:#e11d48;color:#fff}\n.tab{background:#1c1c1f;color:#a1a1aa}\n.price{font-variant-numeric:tabular-nums}\n.live{box-shadow:0 0 0 0 rgba(225,29,72,.5);animation:pulse 2s infinite}\n@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(225,29,72,.45)}70%{box-shadow:0 0 0 10px rgba(225,29,72,0)}100%{box-shadow:0 0 0 0 rgba(225,29,72,0)}}\n</style>\n</head>\n<body class=\"min-h-screen\">\n<div class=\"max-w-6xl mx-auto px-4 py-8\">\n  <header class=\"flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8 pb-6 border-b border-ya-line\">\n    <div>\n      <div class=\"inline-flex items-center gap-2 pill text-xs font-bold px-3 py-1 rounded-full mb-3\">\n        <span class=\"w-2 h-2 rounded-full bg-ya-red live\"></span>\n        به‌روزرسانی زنده\n      </div>\n      <h1 class=\"text-3xl md:text-4xl font-extrabold tracking-tight\">YA<span class=\"text-ya-red\">price</span></h1>\n      <p class=\"text-ya-muted text-sm mt-1\">قیمت ارز، طلا، سکه و رمزارز — تم مشکی‌قرمز</p>\n    </div>\n    <div class=\"text-left md:text-right text-sm text-ya-muted\">\n      <div id=\"upd\">—</div>\n      <button onclick=\"loadAll()\" class=\"mt-2 px-4 py-2 rounded-xl bg-ya-red text-white text-xs font-bold hover:opacity-90\">بروزرسانی</button>\n    </div>\n  </header>\n\n  <div class=\"flex flex-wrap gap-2 mb-6\">\n    <button class=\"tab active px-4 py-2 rounded-xl text-sm font-bold\" data-tab=\"fiat\" onclick=\"showTab('fiat')\">💵 ارز</button>\n    <button class=\"tab px-4 py-2 rounded-xl text-sm font-bold\" data-tab=\"gold\" onclick=\"showTab('gold')\">🪙 طلا و سکه</button>\n    <button class=\"tab px-4 py-2 rounded-xl text-sm font-bold\" data-tab=\"crypto\" onclick=\"showTab('crypto')\">₿ رمزارز</button>\n  </div>\n\n  <div id=\"fiat\" class=\"grid sm:grid-cols-2 lg:grid-cols-3 gap-3\"></div>\n  <div id=\"gold\" class=\"grid sm:grid-cols-2 lg:grid-cols-3 gap-3 hidden\"></div>\n  <div id=\"crypto\" class=\"grid sm:grid-cols-2 lg:grid-cols-3 gap-3 hidden\"></div>\n</div>\n<script>\nconst FIAT_KEYS = {\n  usd:['دلار آمریکا','🇺🇸'], eur:['یورو','🇪🇺'], gbp:['پوند','🇬🇧'], aed:['درهم','🇦🇪'], try:['لیر','🇹🇷'],\n  cad:['دلار کانادا','🇨🇦'], aud:['دلار استرالیا','🇦🇺'], cny:['یوان','🇨🇳'], rub:['روبل','🇷🇺'],\n  sar:['ریال سعودی','🇸🇦'], iqd:['دینار عراق','🇮🇶'], afn:['افغانی','🇦🇫'], jpy:['ین','🇯🇵'],\n  chf:['فرانک سوئیس','🇨🇭'], inr:['روپیه هند','🇮🇳'], myr:['رینگیت','🇲🇾'], krw:['وون','🇰🇷']\n};\nconst GOLD_KEYS = {\n  gold_18k:['طلای ۱۸ عیار','🟡'], gold_mesghal:['مثقال طلا','🟡'], gold_ounce:['انس طلا','🟡'],\n  coin_emami:['سکه امامی','🪙'], coin_bahar:['سکه بهار','🪙'], coin_half:['نیم سکه','🪙'],\n  coin_quarter:['ربع سکه','🪙'], coin_gram:['سکه گرمی','🪙']\n};\nconst CRYPTO = [\n  {id:'bitcoin',sym:'BTC',name:'بیت‌کوین'},\n  {id:'ethereum',sym:'ETH',name:'اتریوم'},\n  {id:'tether',sym:'USDT',name:'تتر'},\n  {id:'binancecoin',sym:'BNB',name:'بایننس‌کوین'},\n  {id:'solana',sym:'SOL',name:'سولانا'},\n  {id:'ripple',sym:'XRP',name:'ریپل'},\n  {id:'dogecoin',sym:'DOGE',name:'دوج‌کوین'},\n  {id:'toncoin',sym:'TON',name:'تون‌کوین'},\n  {id:'cardano',sym:'ADA',name:'کاردانو'},\n  {id:'tron',sym:'TRX',name:'ترون'}\n];\nfunction faNum(n){\n  if(n==null||isNaN(n)) return '—';\n  return Number(n).toLocaleString('fa-IR');\n}\nfunction card(title, emoji, price, unit){\n  return `<div class=\"card p-4 hover:border-ya-red/50 transition\">\n    <div class=\"flex items-center justify-between mb-2\">\n      <span class=\"text-2xl\">${emoji}</span>\n      <span class=\"text-xs text-ya-muted font-mono\">${unit||''}</span>\n    </div>\n    <div class=\"font-bold text-sm mb-1\">${title}</div>\n    <div class=\"price text-xl font-extrabold text-ya-red2\">${price}</div>\n  </div>`;\n}\nfunction showTab(id){\n  ['fiat','gold','crypto'].forEach(t=>{\n    document.getElementById(t).classList.toggle('hidden', t!==id);\n    document.querySelector(`[data-tab=\"${t}\"]`).classList.toggle('active', t===id);\n  });\n}\nasync function loadMarket(){\n  try{\n    const r=await fetch('/yaprice/market.json?t='+Date.now());\n    const m=await r.json();\n    document.getElementById('upd').textContent = (m.date_shamsi_full||m.date||'') + ' · ' + (m.time||'');\n    const fiat=document.getElementById('fiat'); fiat.innerHTML='';\n    for(const [k,[title,em]] of Object.entries(FIAT_KEYS)){\n      if(m[k]==null) continue;\n      fiat.innerHTML += card(title, em, faNum(m[k])+' تومان', k.toUpperCase());\n    }\n    const gold=document.getElementById('gold'); gold.innerHTML='';\n    for(const [k,[title,em]] of Object.entries(GOLD_KEYS)){\n      if(m[k]==null) continue;\n      gold.innerHTML += card(title, em, k==='gold_ounce' ? '$'+Number(m[k]).toLocaleString('en-US') : faNum(m[k])+' تومان', k);\n    }\n  }catch(e){\n    document.getElementById('fiat').innerHTML='<div class=\"text-ya-muted\">خطا در بارگذاری market.json</div>';\n  }\n}\nasync function loadCrypto(){\n  const box=document.getElementById('crypto');\n  box.innerHTML='<div class=\"text-ya-muted text-sm\">در حال دریافت رمزارز...</div>';\n  try{\n    const ids=CRYPTO.map(c=>c.id).join(',');\n    const r=await fetch('https://api.coingecko.com/api/v3/simple/price?ids='+ids+'&vs_currencies=usd,usdt');\n    const j=await r.json();\n    box.innerHTML='';\n    for(const c of CRYPTO){\n      const p=j[c.id]?.usd ?? j[c.id]?.usdt;\n      box.innerHTML += card(c.name+' ('+c.sym+')', '₿', p!=null?('$'+Number(p).toLocaleString('en-US',{maximumFractionDigits:4})):'—', c.sym);\n    }\n  }catch(e){\n    box.innerHTML='<div class=\"text-ya-muted\">خطا در دریافت رمزارز (CoinGecko)</div>';\n  }\n}\nasync function loadAll(){ await loadMarket(); await loadCrypto(); }\nloadAll();\nsetInterval(loadAll, 5*60*1000);\n(function(){try{var t=new URLSearchParams(location.search).get('tab');if(['fiat','gold','crypto'].indexOf(t)>-1)showTab(t);if(window.Telegram&&Telegram.WebApp){Telegram.WebApp.ready();Telegram.WebApp.expand();}}catch(e){}})();\n</script>\n</body>\n</html>\n";
const YA_PROXY_HTML = "<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\"/>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n<title>YAProxy — پروکسی تلگرام</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;600;700;800&family=JetBrains+Mono:wght@500;700&display=swap\" rel=\"stylesheet\"/>\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<style>\nbody{background:#0a0a0b;color:#fafafa;font-family:Vazirmatn,system-ui,sans-serif}\n.card{background:#141416;border:1px solid #2a0f12;border-radius:1rem}\n.pill{background:rgba(225,29,72,.12);border:1px solid rgba(225,29,72,.35);color:#fb7185}\n.btn{background:#e11d48;color:#fff;border-radius:.75rem;font-weight:700}\n.btn-ghost{background:#1c1c1f;border:1px solid #2a0f12;border-radius:.75rem}\n.mono{font-family:'JetBrains Mono',monospace}\n.online{color:#4ade80}.offline{color:#f87171}\n</style>\n</head>\n<body class=\"min-h-screen\">\n<div class=\"max-w-5xl mx-auto px-4 py-8\">\n  <header class=\"mb-8 pb-6 border-b border-[#2a0f12] flex flex-col md:flex-row md:items-center justify-between gap-4\">\n    <div>\n      <div class=\"inline-flex items-center gap-2 pill text-xs font-bold px-3 py-1 rounded-full mb-3\">\n        <span class=\"w-2 h-2 rounded-full bg-[#e11d48]\"></span> پایش پروکسی\n      </div>\n      <h1 class=\"text-3xl md:text-4xl font-extrabold\">YA<span class=\"text-[#e11d48]\">Proxy</span></h1>\n      <p class=\"text-zinc-400 text-sm mt-1\">پروکسی‌های MTProto تست‌شده — تم مشکی و قرمز</p>\n    </div>\n    <div class=\"flex gap-3 text-sm\">\n      <div class=\"card px-4 py-2\"><div class=\"text-zinc-400 text-xs\">آنلاین</div><div id=\"on\" class=\"text-xl font-bold online\">—</div></div>\n      <div class=\"card px-4 py-2\"><div class=\"text-zinc-400 text-xs\">کل</div><div id=\"tot\" class=\"text-xl font-bold\">—</div></div>\n      <button class=\"btn px-4 py-2 text-sm\" onclick=\"load()\">بروزرسانی</button>\n    </div>\n  </header>\n  <div class=\"mb-4 flex gap-2\">\n    <button class=\"btn px-4 py-2 text-sm\" onclick=\"pickRandom()\">🎲 پروکسی تصادفی</button>\n    <button class=\"btn-ghost px-4 py-2 text-sm\" onclick=\"load()\">همه</button>\n  </div>\n  <div id=\"list\" class=\"grid gap-3\"></div>\n  <div id=\"toast\" class=\"fixed bottom-6 left-1/2 -translate-x-1/2 bg-[#141416] border border-[#e11d48]/40 px-4 py-2 rounded-xl text-sm opacity-0 transition\">کپی شد</div>\n</div>\n<script>\nlet DATA=[];\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}\nfunction toast(m){const t=document.getElementById('toast');t.textContent=m;t.style.opacity=1;setTimeout(()=>t.style.opacity=0,1500)}\nfunction isOn(p){return String(p.status||'').toLowerCase()==='online'||p.online===true}\nfunction linkOf(p){\n  if(p.server&&p.port&&p.secret) return 'https://t.me/proxy?server='+encodeURIComponent(p.server)+'&port='+encodeURIComponent(p.port)+'&secret='+encodeURIComponent(p.secret);\n  return '';\n}\nfunction row(p){\n  const st=isOn(p), L=linkOf(p);\n  const lat=p.latency!=null?esc(p.latency)+' ms':'—';\n  return '<div class=\"card p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3\">'\n    +'<div><div class=\"font-bold mono text-sm\">'+esc(p.server||'—')+':'+esc(p.port||'')+'</div>'\n    +'<div class=\"text-xs text-zinc-400 mt-1\">'+esc(p.type||'MTProto')+' · تاخیر: <span class=\"mono\">'+lat+'</span> · <span class=\"'+(st?'online':'offline')+'\">'+(st?'آنلاین':'آفلاین')+'</span></div></div>'\n    +'<div class=\"flex gap-2\">'\n    +(L?'<button class=\"btn-ghost px-3 py-2 text-xs\" data-l=\"'+esc(L)+'\">کپی</button><a class=\"btn px-3 py-2 text-xs\" href=\"'+esc(L)+'\" target=\"_blank\" rel=\"noopener\">اتصال</a>':'')\n    +'</div></div>';\n}\nfunction render(list){\n  document.getElementById('list').innerHTML=list.map(row).join('')||'<div class=\"text-zinc-500\">هنوز پروکسی‌ای پیدا نشده؛ اسکن خودکار هر یک ساعت انجام می‌شود.</div>';\n  document.getElementById('tot').textContent=DATA.length;\n  document.getElementById('on').textContent=DATA.filter(isOn).length;\n}\nfunction pickRandom(){\n  const online=DATA.filter(isOn);\n  const pool=online.length?online:DATA;\n  if(!pool.length) return toast('خالی است');\n  const p=pool[Math.floor(Math.random()*pool.length)];\n  render([p]);\n  const L=linkOf(p); if(L) navigator.clipboard.writeText(L).then(()=>toast('پروکسی تصادفی کپی شد'));\n}\ndocument.getElementById('list').addEventListener('click',function(e){\n  const b=e.target.closest('button[data-l]');\n  if(b) navigator.clipboard.writeText(b.getAttribute('data-l')).then(()=>toast('لینک کپی شد'));\n});\nasync function load(){\n  try{\n    const r=await fetch('/yaproxy/extracted_proxies.json?t='+Date.now());\n    DATA=await r.json();\n    if(!Array.isArray(DATA)) DATA=[];\n    render(DATA.slice(0,80));\n  }catch(e){\n    document.getElementById('list').innerHTML='<div class=\"text-zinc-500\">خطا در بارگذاری لیست پروکسی.</div>';\n  }\n}\nload();\ntry{if(window.Telegram&&Telegram.WebApp){Telegram.WebApp.ready();Telegram.WebApp.expand();}}catch(e){}\n</script>\n</body>\n</html>\n";
const YA_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';
const YA_PRICE_EVERY = 9 * 60 * 1000; // one batch (1/3 of the assets) about every 10 minutes
const YA_PROXY_EVERY = 55 * 60 * 1000;
const YA_BATCHES = 3;

const yaJson = (obj, status = 200, extra = {}) => new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'access-control-allow-origin': '*', 'cache-control': 'public, max-age=30', ...extra } });
const yaHtml = (h) => new Response(h, { headers: { 'content-type': 'text/html; charset=utf-8', 'x-content-type-options': 'nosniff', 'referrer-policy': 'no-referrer', 'cache-control': 'no-cache' } });
const yaDig = (s) => String(s).replace(/\d/g, (d) => '۰۱۲۳۴۵۶۷۸۹'[d]);
const yaFa = (n) => {
  if (n == null || n === '' || isNaN(Number(n))) return '—';
  const [i, f] = String(Number(n)).split('.');
  return yaDig(i.replace(/\B(?=(\d{3})+(?!\d))/g, '٬') + (f ? '٫' + f : ''));
};
const yaNum = (v) => { const n = Number(String(v == null ? '' : v).replace(/,/g, '').trim()); return Number.isFinite(n) ? n : NaN; };
const yaAttr = (tag, name) => { const m = String(tag).match(new RegExp('\\b' + name + '=["\']([^"\']*)["\']', 'i')); return m ? m[1] : ''; };

async function yaGet(url, ms = 9000) {
  const r = await fetch(url, { headers: { 'user-agent': YA_UA, 'accept-language': 'en-US,en;q=0.9' }, signal: AbortSignal.timeout(ms) });
  if (!r.ok) throw new Error('HTTP ' + r.status);
  return r.text();
}
async function yaPool(items, n, fn) {
  const out = new Array(items.length).fill(null);
  let i = 0;
  await Promise.all(Array.from({ length: Math.min(n, items.length) }, async () => {
    while (i < items.length) { const idx = i++; out[idx] = await fn(items[idx]).catch(() => null); }
  }));
  return out;
}

// ---------- prices (port of fetch_rates.py — the alanchand.com scraper) ----------
function yaParseAsset(html, ty) {
  let price = null;
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while (price == null && (m = re.exec(html))) {
    try {
      const j = JSON.parse(m[1].trim());
      for (const c of Array.isArray(j) ? j : [j]) {
        if (c && c['@type'] === 'Product') {
          const raw = yaNum(c.offers && c.offers.price);
          const cur = c.offers && c.offers.priceCurrency;
          if (raw > 0 && cur === 'IRR') price = Math.round(raw / 10);
          else if (raw > 0 && cur === 'USD') price = Math.round(raw * 100) / 100;
          break;
        }
      }
    } catch { /* next block */ }
  }
  if (price == null) {
    const tag = (html.match(/<input[^>]*data-curr=["']tmn["'][^>]*>/i) || html.match(/<input[^>]*id=["']inputCalcValue["'][^>]*>/i) || [''])[0];
    const raw = yaNum(yaAttr(tag, 'data-price') || yaAttr(tag, 'value'));
    if (raw > 0) price = Math.round(raw / 10);
  }
  if (price == null && ty === 'ounce') {
    const mm = html.match(/(\d+(?:,\d+)*(?:\.\d+)?)\s*\$/);
    if (mm) price = Math.round(yaNum(mm[1]) * 100) / 100;
  }
  if (price == null) {
    const hm = html.match(/(?:const|let|var)\s+fullPriceData\s*=\s*(\[\s*\{[\s\S]*?\}\]\s*);/);
    if (hm) {
      try {
        const arr = JSON.parse(hm[1]);
        const last = arr.length && arr[arr.length - 1].price;
        if (last > 0) price = ty === 'ounce' ? Math.round(last * 100) / 100 : Math.round(last);
      } catch { /* ignore */ }
    }
  }
  return price > 0 ? price : null;
}
async function yaFetchUsd() { // USD = AED(toman) / (AED per USD)
  const [a, u] = await Promise.allSettled([yaGet('https://alanchand.com/en/currencies-price/aed'), yaGet('https://alanchand.com/en/exchange-rates/aed-usd')]);
  if (a.status !== 'fulfilled') return null;
  const usdHtml = u.status === 'fulfilled' ? u.value : '';
  const rt = (usdHtml.match(/<input[^>]*id=["'](?:inputCalcValue|outputCalcValue)["'][^>]*>/i) || [''])[0];
  const rate = yaNum(yaAttr(rt, 'data-rate')) || 0.2723;
  const at = (a.value.match(/<input[^>]*data-curr=["']tmn["'][^>]*>/i) || [''])[0];
  const raw = yaNum(yaAttr(at, 'data-price') || yaAttr(at, 'value'));
  return raw > 0 && rate > 0 ? Math.round(raw / 10 / rate) : null;
}
async function yaFetchOil() {
  const h = await yaGet('https://oilprice.com/oil-price-charts/46');
  const m = h.match(/class=["'][^"']*\blast_price\b[^"']*["'][^>]*>\s*([^<]+?)\s*</i);
  return m && /^[\d.,]+$/.test(m[1].trim()) ? m[1].trim() : null;
}
function yaItems() {
  return [{ k: 'usd', kind: 'usd' }, { k: 'oil', kind: 'oil' }, ...YA_ASSETS.filter((a) => a.p).map((a) => ({ k: a.k, kind: 'asset', p: a.p, ty: a.y }))];
}
async function yaFetchItem(it) {
  if (it.kind === 'usd') return yaFetchUsd();
  if (it.kind === 'oil') return yaFetchOil();
  return yaParseAsset(await yaGet('https://alanchand.com/en/' + it.p), it.ty);
}
function yaStamp(now = new Date()) {
  const tz = 'Asia/Tehran';
  const g = (parts, t) => (parts.find((x) => x.type === t) || {}).value || '';
  const iso = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(now);
  const date = `${g(iso, 'year')}-${g(iso, 'month')}-${g(iso, 'day')}`;
  const out = { updated_at: `${date} ${g(iso, 'hour')}:${g(iso, 'minute')}:${g(iso, 'second')}`, date, time: `${g(iso, 'hour')}:${g(iso, 'minute')}` };
  try {
    const sh = new Intl.DateTimeFormat('en-US-u-ca-persian-nu-latn', { timeZone: tz, year: 'numeric', month: 'numeric', day: 'numeric' }).formatToParts(now);
    out.date_shamsi = `${g(sh, 'year')}/${String(g(sh, 'month')).padStart(2, '0')}/${String(g(sh, 'day')).padStart(2, '0')}`;
    out.date_shamsi_full = new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: tz, day: 'numeric', month: 'long', year: 'numeric' }).format(now);
  } catch { /* no persian calendar: keep gregorian date only */ }
  return out;
}
async function yaPriceRefresh(env, opts = {}) {
  const st = (await env.KV.get('cfg:yap', 'json').catch(() => null)) || {};
  const now = Date.now();
  if (!opts.force && st.at && now - st.at < YA_PRICE_EVERY) return { skipped: true };
  const items = yaItems();
  const m = { ...YA_SNAPSHOT, ...(st.m || {}) };
  const first = (Number(st.next) || 0) % YA_BATCHES;
  const batches = opts.all ? Array.from({ length: YA_BATCHES }, (_, i) => i) : [first];
  let tried = 0;
  let got = 0;
  for (const b of batches) {
    const slice = items.filter((_, i) => i % YA_BATCHES === b);
    const res = await yaPool(slice, 6, yaFetchItem);
    slice.forEach((it, i) => { tried++; if (res[i] != null) { m[it.k] = res[i]; got++; } });
  }
  if (m.usd_xau != null) m.gold_ounce = m.usd_xau;
  if (got) Object.assign(m, yaStamp());
  await env.KV.put('cfg:yap', JSON.stringify({ m, at: now, next: (Number(st.next) || 0) + 1 })).catch(() => {});
  return { tried, got, updated_at: m.updated_at };
}
let yaExtP = { t: 0, v: null };
async function yaMarket(env) {
  if (/^https:\/\//i.test(String(env.YAPRICE_JSON || ''))) {
    if (yaExtP.v && Date.now() - yaExtP.t < 120000) return yaExtP.v;
    try {
      const j = JSON.parse(await yaGet(env.YAPRICE_JSON));
      if (j && typeof j === 'object' && j.usd) { yaExtP = { t: Date.now(), v: j }; return j; }
    } catch { /* fall back */ }
    if (yaExtP.v) return yaExtP.v;
  }
  const st = await env.KV.get('cfg:yap', 'json').catch(() => null);
  return { ...YA_SNAPSHOT, ...((st && st.m) || {}) };
}

// ---------- proxies (port of extract_proxies.php) ----------
const YA_HOST_OK = (h) => /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i.test(h) || /^(?:\d{1,3}\.){3}\d{1,3}$/.test(h);
const YA_PRIVATE = /^(?:localhost$|127\.|10\.|0\.|169\.254\.|192\.168\.|172\.(?:1[6-9]|2\d|3[01])\.)/i;
function yaCleanSecret(s) {
  s = String(s || '').trim().toLowerCase();
  if (!/^[0-9a-f]+$/.test(s)) return null;
  const n = s.length;
  if (s.startsWith('dd')) return n === 32 || n === 34 ? s : null;
  if (s.startsWith('ee')) return n >= 34 ? s : null;
  return n === 32 ? s : null;
}
function yaValidProxy(p) {
  return !!p && YA_HOST_OK(String(p.server || '')) && !YA_PRIVATE.test(String(p.server)) && Number.isInteger(Number(p.port)) && Number(p.port) > 0 && Number(p.port) < 65536 && !!yaCleanSecret(p.secret);
}
function yaExtractProxies(html, found) {
  const re = /(?:tg:\/\/|t\.me\/)proxy\?([^"'\s<>]+)/gi;
  let m;
  while ((m = re.exec(html))) {
    let q;
    try { q = new URLSearchParams(m[1].replace(/&amp;/g, '&')); } catch { continue; }
    const server = String(q.get('server') || '').trim().toLowerCase();
    const port = Number(q.get('port'));
    const secret = yaCleanSecret(q.get('secret'));
    if (!secret || !yaValidProxy({ server, port, secret })) continue;
    const key = `${server}:${port}`;
    if (found.has(key)) continue;
    found.set(key, { server, port, secret, type: secret.startsWith('dd') ? 'MTProto Secure' : secret.startsWith('ee') ? 'MTProto TLS' : 'MTProto', tg_url: `tg://proxy?server=${server}&port=${port}&secret=${secret}` });
  }
}
let yaSock;
async function yaSockets() {
  if (yaSock === undefined) { try { yaSock = await import('cloudflare:sockets'); } catch { yaSock = null; } }
  return yaSock;
}
async function yaTcp(host, port, ms = 2500) {
  const mod = await yaSockets();
  if (!mod || !mod.connect) return null;
  const t0 = Date.now();
  let s;
  try {
    s = mod.connect({ hostname: host, port });
    const opened = s.opened;
    opened.catch(() => {});
    await Promise.race([opened, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))]);
    return { ok: true, ms: Date.now() - t0 };
  } catch { return { ok: false }; } finally { try { if (s) s.close(); } catch { /* ignore */ } }
}
async function yaProxyRefresh(env, opts = {}) {
  const st = (await env.KV.get('cfg:yapx', 'json').catch(() => null)) || {};
  const now = Date.now();
  if (!opts.force && st.ts && now - st.ts < YA_PROXY_EVERY) return { skipped: true };
  const custom = String(env.YAPROXY_CHANNELS || '').split(/[\s,;]+/).map((x) => x.replace(/^@/, '').trim()).filter((x) => /^[A-Za-z0-9_]{4,32}$/.test(x));
  const chans = custom.length ? custom : YA_CHANNELS;
  const found = new Map();
  const pages = await yaPool(chans, 6, (u) => yaGet('https://t.me/s/' + encodeURIComponent(u), 8000));
  pages.forEach((h) => { if (h) yaExtractProxies(h, found); });
  if (!found.size) { // blocked / offline: keep the old list and retry in ~10 minutes
    await env.KV.put('cfg:yapx', JSON.stringify({ ts: now - YA_PROXY_EVERY + 10 * 60 * 1000, list: st.list || [] })).catch(() => {});
    return { found: 0, kept: (st.list || []).length };
  }
  const key = (p) => `${p.server}:${p.port}`;
  const prev = new Map((st.list || []).map((p) => [key(p), p]));
  const list = [...found.values()].slice(0, 80).map((p) => { const o = prev.get(key(p)); return o ? { ...p, status: o.status, latency: o.latency, checked: o.checked || 0 } : { ...p, status: 'Unknown', latency: null, checked: 0 }; });
  const order = [...list].sort((a, b) => a.checked - b.checked).slice(0, 24); // never-checked first, then the oldest checks
  const res = await yaPool(order, 6, (p) => yaTcp(p.server, p.port));
  order.forEach((p, i) => { const r = res[i]; if (r) { p.status = r.ok ? 'Online' : 'Offline'; p.latency = r.ok ? r.ms : null; p.checked = now; } });
  const rank = (p) => (p.status === 'Online' ? 0 : p.status === 'Unknown' ? 1 : 2);
  list.sort((a, b) => rank(a) - rank(b) || (a.latency ?? 9999) - (b.latency ?? 9999));
  await env.KV.put('cfg:yapx', JSON.stringify({ ts: now, list })).catch(() => {});
  return { found: found.size, checked: order.length, online: list.filter((p) => p.status === 'Online').length };
}
let yaExtX = { t: 0, v: null };
async function yaProxies(env) {
  if (/^https:\/\//i.test(String(env.YAPROXY_JSON || ''))) {
    if (yaExtX.v && Date.now() - yaExtX.t < 120000) return yaExtX.v;
    try {
      const j = JSON.parse(await yaGet(env.YAPROXY_JSON));
      if (Array.isArray(j)) { const v = { list: j.slice(0, 200), ts: Date.now() }; yaExtX = { t: Date.now(), v }; return v; }
    } catch { /* fall back */ }
    if (yaExtX.v) return yaExtX.v;
  }
  const st = await env.KV.get('cfg:yapx', 'json').catch(() => null);
  return { list: (st && st.list) || [], ts: (st && st.ts) || 0 };
}

// ---------- cron + HTTP ----------
async function yaCron(env) {
  if (!env.YAPRICE_JSON) await yaPriceRefresh(env).catch((e) => console.error('yaprice', e && e.message));
  if (!env.YAPROXY_JSON) await yaProxyRefresh(env).catch((e) => console.error('yaproxy', e && e.message));
  await yacCron(env).catch((e) => console.error('yaconfig', e && e.message));
  await ydCron(env).catch((e) => console.error('ydojo', e && e.message));
}
async function yaHttp(request, env, ctx) {
  const url = new URL(request.url);
  const p = url.pathname.replace(/\/+$/, '');
  if (!p.startsWith('/ya')) return null;
  if (p === '/yaprice') return yaHtml(YA_PRICE_HTML);
  if (p === '/yaprice/market.json') return yaJson(await yaMarket(env));
  if (p === '/yaproxy') return yaHtml(YA_PROXY_HTML);
  if (p === '/yaproxy/extracted_proxies.json') return yaJson((await yaProxies(env)).list);
  if (p === '/yaprice/refresh' || p === '/yaproxy/refresh') {
    if (!env.WEBHOOK_SECRET || !safeEq(url.searchParams.get('key'), env.WEBHOOK_SECRET)) return new Response('forbidden', { status: 403 });
    const out = p === '/yaprice/refresh'
      ? await yaPriceRefresh(env, { force: true, all: url.searchParams.get('all') === '1' })
      : await yaProxyRefresh(env, { force: true });
    return yaJson(out, 200, { 'cache-control': 'no-store' });
  }
  if (p === '/yaconfig' || p.startsWith('/yaconfig/')) return yacHttp(request, env, p, url);
  if (p.startsWith('/yatmdb/')) return yaTmdb(request, env, p, url);
  return null;
}

