const YA_FILL = new Set(['قیمت', 'نرخ', 'چنده', 'چقدره', 'چقد', 'چقدر', 'الان', 'الآن', 'امروز', 'لحظه ای', 'لطفا', 'لطفاً', 'پلیز', 'تومان', 'تومن', 'بگو', 'بگید', 'بگین', 'بده', 'بدید', 'ها', 'رو', 'را', 'price', 'چند', 'شد', 'شده']);
let yaAliasMap = null;
function yaAliases() {
  if (yaAliasMap) return yaAliasMap;
  yaAliasMap = Object.create(null);
  for (const [k, names] of Object.entries(YA_NAMES)) for (const n of names) yaAliasMap[pk(n)] = k;
  return yaAliasMap;
}
function yaAliasKey(str) {
  const t = pk(String(str || '').replace(/[?؟!.,،:؛"«»()]/g, ' '));
  if (!t || t.length > 40) return null;
  const A = yaAliases();
  if (A[t]) return A[t];
  const w = t.split(' ').filter((x) => x && !YA_FILL.has(x));
  if (!w.length) return /قیمت|نرخ/.test(t) ? 'overview' : null;
  if (w.length > 3) return null;
  return A[w.join(' ')] || (w.length === 1 ? A[w[0]] : null) || null;
}
const YA_PX_CORE = new Set(['پروکسی', 'پراکسی', 'پروکسیی', 'proxy', 'proxies', 'mtproto', 'mtproxy']);
const YA_PX_FILL = new Set(['ها', 'بده', 'بدید', 'بدین', 'بفرست', 'بفرستید', 'بفرستین', 'میخوام', 'می', 'خوام', 'میخواستم', 'لطفا', 'لطفاً', 'پلیز', 'یه', 'یک', 'تلگرام', 'تلگرامی', 'جدید', 'تازه', 'رایگان', 'مجانی', 'لینک', 'ممنون', 'سلام', 'رو', 'را', 'لازم', 'دارم', 'دارید', 'داری', 'داره', 'کسی', 'کی', 'هست', 'برا', 'برای', 'من', 'ما', 'فعال', 'خوب', 'سالم', 'سریع', 'ایران', 'ایرانی', 'free', 'telegram', 'tg', 'new', 'بزن', 'بزارید', 'بذارید', 'ی']);
function yaIsProxyWord(text) {
  const t = pk(String(text || '').replace(/[?؟!.,،:؛"«»()]/g, ' '));
  if (!t || t.length > 40) return false;
  const w = t.split(' ').filter(Boolean);
  if (!w.length || w.length > 5) return false;
  let core = false;
  for (const x of w) { if (YA_PX_CORE.has(x)) core = true; else if (!YA_PX_FILL.has(x)) return false; }
  return core;
}
function yaDetect(text, inGroup) {
  if (!text || text.length > 40 || text.startsWith('/')) return null;
  if (yaIsProxyWord(text)) return { t: 'proxy' };
  if (yacIsConfigWord(text)) return { t: 'config' };
  const k = yaAliasKey(text);
  if (!k) return null;
  if (k === 'overview' && inGroup) return null; // "قیمت" / "ارز" alone is too common in groups
  return { t: 'price', k };
}

