async function yaViewProxy(env, priv, shuffle) {
  const { list } = await yaProxies(env);
  const ok = list.filter(yaValidProxy);
  const on = ok.filter((p) => String(p.status || '').toLowerCase() === 'online').sort((a, b) => (a.latency ?? 9e9) - (b.latency ?? 9e9));
  const pool = on.length ? on : ok;
  let pick = pool.slice(0, 6);
  if (shuffle && pool.length > 6) pick = pool.map((p) => [Math.random(), p]).sort((a, b) => a[0] - b[0]).slice(0, 6).map((x) => x[1]);
  const rows = pick.map((p, i) => [{ text: `🔗 ${i + 1}. ${String(p.server).slice(0, 26)}:${p.port}${p.latency != null ? ' · ' + p.latency + 'ms' : ''}`, url: `https://t.me/proxy?server=${encodeURIComponent(p.server)}&port=${Number(p.port)}&secret=${yaCleanSecret(p.secret)}` }]);
  const panel = await yaPanelBtn(env, 'proxy', priv, '🌐 همه‌ی پروکسی‌ها');
  const ctl = [];
  if (pool.length > 6) ctl.push({ text: '🔄 پروکسی‌های دیگر', callback_data: 'ya:xs' });
  if (panel) ctl.push(panel);
  if (ctl.length) rows.push(ctl);
  rows.push([{ text: '💱 قیمت ارز و طلا', callback_data: 'ya:p' }, ...(priv ? [{ text: '🏠 منوی اصلی', callback_data: 'xm:home' }] : [])]);
  if (!pick.length) return { text: '📡 <b>YAProxy</b>\nهنوز پروکسی‌ای پیدا نشده؛ اسکن خودکار هر یک ساعت انجام می‌شه. چند دقیقه‌ی دیگه دوباره امتحان کن.', kb: { inline_keyboard: rows } };
  const L = ['📡 <b>YAProxy — پروکسی MTProto</b>', `✅ آنلاین: <b>${yaDig(on.length)}</b> از ${yaDig(ok.length)}${on.length ? '' : ' (وضعیت بررسی نشده)'}`, ''];
  pick.forEach((p, i) => L.push(`${yaDig(i + 1)}) <code>${esc(p.server)}:${p.port}</code> · ${esc(p.type || 'MTProto')}${p.latency != null ? ' · ' + yaDig(p.latency) + 'ms' : ''}`));
  L.push('', 'روی دکمه بزن تا مستقیم توی تلگرام اضافه بشه.', '💡 هر وقت لیست تازه خواستی فقط بنویس: پروکسی');
  return { text: L.join('\n'), kb: { inline_keyboard: rows } };
}
