// ---- entry points ----
const yaCool = new Map();
const yaKwCool = new Map();
async function yaKeyword(env, m, text, inGroup) {
  const d = yaDetect(text, inGroup);
  if (!d) return false;
  if (inGroup) { // one answer per chat+topic per minute, like the bot's own price words
    const ck = `${m.chat.id}:${d.t}:${d.k || ''}`;
    if (Date.now() - (yaKwCool.get(ck) || 0) < 60000) return true;
    if (yaKwCool.size > 800) yaKwCool.clear();
    yaKwCool.set(ck, Date.now());
  }
  await tg(env, 'sendChatAction', { chat_id: m.chat.id, action: 'typing' }).catch(() => {});
  const view = d.t === 'proxy' ? await yaViewProxy(env, !inGroup, false) : d.t === 'config' ? await yacView(env, !inGroup) : await yaViewPrice(env, d.k, !inGroup);
  await yaSend(env, m, inGroup, view);
  return true;
}
async function yaCommand(env, m, text, inGroup) {
  const mm = text.match(/^\/(yaprice|yaproxy|yaconfig|proxy|vpn|config|ya)(?:@(\w+))?(?:\s+([\s\S]*))?$/i);
  if (!mm) return false;
  const cmd = mm[1].toLowerCase();
  const arg = (mm[3] || '').trim();
  if (mm[2]) {
    const me = await botInfo(env).catch(() => null);
    if (me && me.username && me.username.toLowerCase() !== mm[2].toLowerCase()) return false;
  }
  if (cmd === 'ya') return ydCommand(env, m, arg, inGroup);
  if (inGroup) {
    const g = await getGroup(env, m.chat.id).catch(() => null);
    if (!g || !g.enabled) return false;
    if (Date.now() - (yaCool.get(m.chat.id) || 0) < 15000) return true; // anti-spam: one answer per 15 s per group
    if (yaCool.size > 500) yaCool.clear();
    yaCool.set(m.chat.id, Date.now());
  }
  if (cmd === 'yaprice') {
    const a = arg.toLowerCase();
    const key = a === 'all' || a === 'همه' ? 'all' : arg ? yaAliasKey(arg) : null;
    await yaSend(env, m, inGroup, await yaViewPrice(env, key, !inGroup));
    return true;
  }
  if (cmd === 'yaconfig' || cmd === 'vpn' || cmd === 'config') { await yaSend(env, m, inGroup, await yacView(env, !inGroup)); return true; }
  await yaSend(env, m, inGroup, await yaViewProxy(env, !inGroup, false));
  return true;
}
async function yaCallback(env, cq) {
  const ans = (t, alert) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: String(t).slice(0, 190), show_alert: !!alert } : {}) });
  const msg = cq.message;
  if (!msg || !msg.chat) return ans();
  if (!rateOk(`yacb:${cq.from.id}`, 25, 60000)) return ans('یه کم آروم‌تر 🙂');
  const priv = msg.chat.type === 'private';
  const [, a, b] = String(cq.data || '').split(':');
  let view = null;
  try {
    if (a === 'p') { if (b && !YA_KEYS.has(b)) return ans(); view = await yaViewPrice(env, b, priv); }
    else if (a === 'pa') view = await yaViewPrice(env, 'all', priv);
    else if (a === 'x') view = await yaViewProxy(env, priv, false);
    else if (a === 'xs') view = await yaViewProxy(env, priv, true);
    else if (a === 'c') view = await yaViewCrypto(env, priv);
    else if (a === 'k') view = await yacView(env, priv);
    else if (a === 't') view = yaViewTools(priv);
    else if (a === 'h') view = yaViewHelp(b, priv);
  } catch (e) { return ans('⚠️ ' + String((e && e.message) || e).slice(0, 120), true); }
  if (!view) return ans();
  const body = { chat_id: msg.chat.id, message_id: msg.message_id, text: view.text, reply_markup: view.kb, disable_web_page_preview: true };
  if (!view.plain) body.parse_mode = 'HTML';
  const r = await tg(env, 'editMessageText', body);
  if (r.ok) return ans();
  if (/not modified/i.test(r.description || '')) return ans('✅ همین الان به‌روز است');
  const nb = { chat_id: msg.chat.id, text: view.text, reply_markup: view.kb, disable_web_page_preview: true };
  if (!view.plain) nb.parse_mode = 'HTML';
  await tg(env, 'sendMessage', nb);
  return ans();
}

