const YAC_HTML = "<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#090909\">\n<title>YAconfig | پنل اشتراک</title>\n<style>\n:root{color-scheme:dark;--bg:#080808;--card:#111;--line:#292929;--red:#f02735;--muted:#aaa;--white:#f7f7f7}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#25090d 0,transparent 45%),var(--bg);color:var(--white);font-family:Tahoma,Arial,sans-serif;min-height:100vh}\n.wrap{width:min(1050px,92%);margin:auto;padding:36px 0 24px}.hero{text-align:center;padding:25px 0 28px}.logo{display:inline-grid;place-items:center;width:76px;height:76px;border:2px solid var(--red);border-radius:22px;color:var(--red);font-size:38px;font-weight:900;box-shadow:0 0 34px #f0273525}\nh1{font-size:clamp(28px,5vw,42px);margin:18px 0 8px;letter-spacing:.3px}h1 span{color:var(--red)}.sub{color:var(--muted);line-height:1.9;margin:0 auto;max-width:640px}\n.status{display:flex;justify-content:center;gap:9px;align-items:center;color:#bbb;font-size:13px;margin-top:16px}.dot{width:8px;height:8px;background:#4ade80;border-radius:50%;box-shadow:0 0 10px #4ade8055}\n.toolbar{display:flex;gap:12px;align-items:center;justify-content:space-between;margin:10px 0 18px;flex-wrap:wrap}.toolbar p{color:var(--muted);margin:0;font-size:13px}\nbutton,.copy{font:inherit;cursor:pointer;border:1px solid #482027;background:#1b0c0e;color:#fff;border-radius:10px;padding:10px 14px;text-decoration:none}button:hover,.copy:hover{border-color:var(--red);background:#2b0d12}\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:14px}.card{border:1px solid var(--line);background:linear-gradient(145deg,#151515,#0d0d0d);border-radius:16px;padding:18px;transition:.2s}.card:hover{border-color:#74212b;transform:translateY(-2px)}.cardhead{display:flex;align-items:center;gap:12px;margin-bottom:9px}.ico{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#2a0d11;color:var(--red);font-size:18px;font-weight:bold}.card h2{font-size:17px;margin:0 0 5px}.card small{color:var(--muted)}.card p{color:#aaa;font-size:13px;line-height:1.8;min-height:44px;margin:12px 0}\n.actions{display:flex;gap:8px;flex-wrap:wrap}.actions a{flex:1;text-align:center;font-size:13px;padding:10px 8px}.primary{background:var(--red);border-color:var(--red);color:white}.primary:hover{background:#d91b29}\n.notice{border:1px solid #342024;background:#120b0c;border-radius:12px;padding:14px 16px;color:#c8bfc0;font-size:12px;line-height:1.9;margin:18px 0 22px}.notice strong{color:#ff727b}\nfooter{text-align:center;border-top:1px solid #242424;padding:22px 0 0;margin-top:24px;color:#8c8c8c;font-size:13px}footer a{color:var(--red);font-weight:bold;text-decoration:none}footer a:hover{text-decoration:underline}\n#msg{color:#ff8790;font-size:12px}\n</style><script src=\"https://telegram.org/js/telegram-web-app.js\"></script></head>\n<body><main class=\"wrap\">\n<header class=\"hero\"><div class=\"logo\">S</div><h1>❤️‍🔥 <span>YACONFIG</span></h1>\n<p class=\"sub\">پنل دریافت لینک‌های اشتراک پروکسی. لینک مناسب برنامه‌ات را انتخاب و مستقیم کپی یا باز کن.</p>\n<div class=\"status\"><span class=\"dot\"></span><span>سرویس آنلاین · داده‌ها از منبع عمومی دریافت می‌شوند</span></div></header>\n<div class=\"toolbar\"><p>فرمت عادی برای اکثر کلاینت‌ها؛ Base64 برای کلاینت‌هایی که این فرمت را می‌خواهند.</p><button id=\"refresh\">↻ بررسی و تازه‌سازی</button><a class=\"copy primary\" href=\"{{BUY_URL}}\" target=\"_blank\" rel=\"noopener\">🛒 خرید کانفیگ اختصاصی</a></div>\n<section class=\"grid\" id=\"cards\"></section>\n<div class=\"notice\"><strong>توجه:</strong> این نسخه روی Cloudflare Workers اجرا می‌شود و فهرست را از منبع بالادستی می‌خواند. تست زندهٔ پورت، اندازه‌گیری پینگ و تشخیص کشورِ نسخهٔ Python در این نسخه انجام نمی‌شود؛ بنابراین «سرعت بالا» تضمین سرعت نیست.</div>\n<footer>ساخته‌شده با ♥ · کانال تلگرام: <a href=\"{{CHANNEL_URL}}\" target=\"_blank\" rel=\"noopener noreferrer\">{{CHANNEL_HANDLE}}</a> · <a href=\"{{BUY_URL}}\" target=\"_blank\" rel=\"noopener noreferrer\">خرید کانفیگ اختصاصی</a></footer>\n</main>\n<script>\nconst items=[\n [\"mixed\",\"همه کانفیگ‌ها\",\"ترکیبی از پروتکل‌های پشتیبانی‌شده\",\"✦\"],\n [\"high_speed\",\"منتخب\",\"فهرست کوتاه‌شده از کانفیگ‌ها؛ سرعت تضمین نمی‌شود\",\"⚡\"],\n [\"vless\",\"VLESS\",\"کانفیگ‌های پروتکل VLESS\",\"V\"],\n [\"vmess\",\"VMess\",\"کانفیگ‌های پروتکل VMess\",\"M\"],\n [\"trojan\",\"Trojan\",\"کانفیگ‌های پروتکل Trojan\",\"T\"],\n [\"ss\",\"Shadowsocks\",\"کانفیگ‌های Shadowsocks\",\"S\"],\n [\"hy2\",\"Hysteria 2\",\"کانفیگ‌های Hysteria 2\",\"H\"],\n [\"tuic\",\"TUIC\",\"کانفیگ‌های TUIC\",\"U\"]\n];\nconst cards=document.querySelector(\"#cards\");\nfunction render(){cards.innerHTML=items.map(([id,title,desc,ico])=>'<article class=\"card\"><div class=\"cardhead\"><div class=\"ico\">'+ico+'</div><div><h2>'+title+'</h2><small>YACONFIG / '+id.toUpperCase()+'</small></div></div><p>'+desc+'</p><div class=\"actions\"><a class=\"copy primary\" href=\"/yaconfig/sub/'+id+'\" target=\"_blank\" rel=\"noopener\">لینک عادی ↗</a><a class=\"copy\" href=\"/yaconfig/sub/base64/'+id+'\" target=\"_blank\" rel=\"noopener\">Base64 ↗</a><button data-copy=\"/yaconfig/sub/'+id+'\">کپی لینک</button></div></article>').join(\"\");}\nrender();\ncards.addEventListener(\"click\",async e=>{const b=e.target.closest(\"button[data-copy]\");if(!b)return;const url=location.origin+b.dataset.copy;try{await navigator.clipboard.writeText(url);b.textContent=\"کپی شد ✓\";setTimeout(()=>b.textContent=\"کپی لینک\",1600)}catch{prompt(\"لینک را کپی کنید:\",url)}});\ndocument.querySelector(\"#refresh\").addEventListener(\"click\",async e=>{const b=e.currentTarget;b.disabled=true;b.textContent=\"در حال بررسی…\";try{const r=await fetch(\"/yaconfig/api/status?refresh=1\");const j=await r.json();b.textContent=j.ok?(\"آماده · \"+j.total+\" کانفیگ\"):\"خطا در دریافت\";}catch{b.textContent=\"خطا در دریافت\"}finally{setTimeout(()=>{b.disabled=false;b.textContent=\"↻ بررسی و تازه‌سازی\"},2200)}});\ndocument.addEventListener('click',function(e){var a=e.target.closest('a[href^=\"https://t.me/\"]');if(a&&window.Telegram&&Telegram.WebApp&&Telegram.WebApp.openTelegramLink){e.preventDefault();Telegram.WebApp.openTelegramLink(a.href)}});\ntry{if(window.Telegram&&Telegram.WebApp){Telegram.WebApp.ready();Telegram.WebApp.expand()}}catch(e){}\n</script></body></html>";
const yacHttps = (v) => (/^https:\/\/[^\s"'<>]+$/i.test(String(v || '').trim()) ? String(v).trim() : '');
const yacBuyUrl = (env) => (env.YACONFIG_BUY_URL !== undefined ? yacHttps(env.YACONFIG_BUY_URL) : yacHttps(YAC_BUY_URL));
const yacChannelUrl = (env) => (env.YACONFIG_CHANNEL_URL !== undefined ? yacHttps(env.YACONFIG_CHANNEL_URL) : yacHttps(YAC_CHANNEL_URL));
function yacPanelHtml(env) {
  const buy = yacBuyUrl(env);
  const ch = yacChannelUrl(env);
  let h = YAC_HTML;
  if (buy) h = h.split('{{BUY_URL}}').join(buy);
  else h = h.replace(/<a class="copy primary" href="\{\{BUY_URL\}\}"[^>]*>[^<]*<\/a>/, '').replace(/ · <a href="\{\{BUY_URL\}\}"[^>]*>[^<]*<\/a>/, '');
  if (ch) h = h.split('{{CHANNEL_URL}}').join(ch).split('{{CHANNEL_HANDLE}}').join(ch.replace(/^https:\/\/t\.me\//i, '@').slice(0, 40));
  else h = h.replace(/ · کانال تلگرام: <a href="\{\{CHANNEL_URL\}\}"[^>]*>\{\{CHANNEL_HANDLE\}\}<\/a>/, '');
  return h;
}

function yacDecode(input) {
  try {
    let s = String(input).trim().replace(/-/g, '+').replace(/_/g, '/');
    while (s.length % 4) s += '=';
    const bin = atob(s);
    return new TextDecoder().decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
  } catch { return ''; }
}
function yacEncode(input) {
  const bytes = new TextEncoder().encode(input);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin);
}
function yacTypeOf(line) {
  const s = String(line).trim().toLowerCase();
  if (s.startsWith('vmess://')) return 'vmess';
  if (s.startsWith('vless://')) return 'vless';
  if (s.startsWith('trojan://')) return 'trojan';
  if (s.startsWith('ss://')) return 'ss';
  if (s.startsWith('tuic://')) return 'tuic';
  if (s.startsWith('hy2://') || s.startsWith('hysteria2://') || s.startsWith('hysteria://')) return 'hy2';
  return null;
}
function yacHostPort(line, type) {
  try {
    if (type === 'vmess') { const o = JSON.parse(yacDecode(line.slice(8))); return { host: o.add, port: Number(o.port) }; }
    if (type === 'ss') {
      const raw = line.slice(5).split('#')[0];
      const afterAt = raw.includes('@') ? raw.slice(raw.lastIndexOf('@') + 1) : '';
      const u = new URL('https://' + afterAt);
      return { host: u.hostname, port: Number(u.port) };
    }
    const u = new URL(line);
    return { host: u.hostname, port: Number(u.port) };
  } catch { return { host: '', port: 0 }; }
}
let yacMemo = { t: 0, v: null };
async function yacLoad(env, force) {
  if (!force && yacMemo.v && Date.now() - yacMemo.t < 300000) return yacMemo.v;
  const source = /^https:\/\//i.test(String(env.YACONFIG_SOURCE_URL || '')) ? String(env.YACONFIG_SOURCE_URL) : YAC_SOURCE;
  const res = await fetch(source, { headers: { 'user-agent': 'YAconfig-Worker/1.0' }, cf: { cacheTtl: 180, cacheEverything: true }, signal: AbortSignal.timeout(15000) });
  if (!res.ok) throw new Error('Upstream returned HTTP ' + res.status);
  const raw = await res.text();
  if (raw.length > 12 * 1024 * 1024) throw new Error('Upstream too large');
  let decoded = yacDecode(raw);
  if (!decoded.includes('://')) decoded = raw;
  const lines = decoded.split(/\r?\n/).map((x) => x.trim()).filter((x) => x && x.length <= 4000).slice(0, 20000);
  const byType = { vless: [], vmess: [], trojan: [], ss: [], hy2: [], tuic: [] };
  const seen = new Set();
  for (const line of lines) {
    const type = yacTypeOf(line);
    if (!type) continue;
    const hp = yacHostPort(line, type);
    if (!hp.host || !hp.port || hp.port < 1 || hp.port > 65535) continue;
    if (seen.has(line)) continue;
    seen.add(line);
    byType[type].push(line);
  }
  byType.mixed = [...new Set(Object.values(byType).flat())];
  byType.high_speed = byType.mixed.slice(0, 15); // a capped sample, not a speed ranking (no TCP probing here)
  const breakdown = {};
  for (const t of Object.keys(byType)) breakdown[t] = byType[t].length;
  const v = { generated_at: new Date().toISOString(), source, total: byType.mixed.length, breakdown, byType };
  yacMemo = { t: Date.now(), v };
  return v;
}
function yacMakePool(data) { // small random pool kept in KV so the bot never waits for the upstream
  const pool = {};
  for (const t of ['vless', 'vmess', 'trojan', 'ss', 'hy2', 'tuic']) {
    const arr = (data.byType[t] || []).filter((l) => l.length <= 700);
    pool[t] = arr.map((l) => [Math.random(), l]).sort((a, b) => a[0] - b[0]).slice(0, t === 'vless' || t === 'vmess' || t === 'trojan' ? 30 : 12).map((x) => x[1]);
  }
  return { at: Date.now(), total: data.total, breakdown: data.breakdown, pool };
}
async function yacCron(env) {
  const st = await env.KV.get('cfg:yacfg', 'json').catch(() => null);
  if (st && st.at && Date.now() - st.at < 29 * 60 * 1000) return;
  const data = await yacLoad(env, true);
  await env.KV.put('cfg:yacfg', JSON.stringify(yacMakePool(data))).catch(() => {});
}
async function yacHttp(request, env, p, url) {
  const ip = request.headers.get('cf-connecting-ip') || 'x';
  if (p === '/yaconfig') return yaHtml(yacPanelHtml(env));
  if (p === '/yaconfig/health') return yaJson({ ok: true, service: 'YAconfig', time: new Date().toISOString() }, 200, { 'cache-control': 'no-store' });
  if (p === '/yaconfig/api/status') {
    const refresh = url.searchParams.get('refresh') === '1';
    if (!rateOk(`yac:${ip}`, refresh ? 6 : 40, 60000)) return yaJson({ ok: false, error: 'rate limit' }, 429, { 'cache-control': 'no-store' });
    try {
      const d = await yacLoad(env, refresh);
      return yaJson({ ok: true, generated_at: d.generated_at, total: d.total, breakdown: d.breakdown }, 200, { 'cache-control': 'no-store' });
    } catch (e) { return yaJson({ ok: false, error: String((e && e.message) || e) }, 502, { 'cache-control': 'no-store' }); }
  }
  const m = p.match(/^\/yaconfig\/sub\/(?:(base64)\/)?([a-z0-9_-]+)$/i);
  if (m) {
    if (!rateOk(`yac:${ip}`, 60, 60000)) return new Response('rate limit', { status: 429 });
    const type = m[2].toLowerCase();
    if (!YAC_TYPES.includes(type)) return new Response('Not found', { status: 404 });
    try {
      const d = await yacLoad(env, false);
      const list = d.byType[type] || [];
      const content = list.join('\n');
      return new Response(m[1] ? yacEncode(content) : content, { headers: { 'content-type': 'text/plain; charset=utf-8', 'access-control-allow-origin': '*', 'cache-control': 'public, max-age=300', 'x-config-count': String(list.length) } });
    } catch (e) { return new Response('Upstream error: ' + String((e && e.message) || e), { status: 502, headers: { 'content-type': 'text/plain; charset=utf-8' } }); }
  }
  return new Response('Not found', { status: 404 });
}

// ---- bot side ----
const YAC_CORE = new Set(['کانفیگ', 'کانفیگها', 'vpn', 'وپن', 'فیلترشکن', 'v2ray', 'v2rayng', 'vless', 'vmess', 'trojan']);
const YAC_FILL = new Set(['ها', 'رایگان', 'مجانی', 'جدید', 'تازه', 'سالم', 'قوی', 'پرسرعت', 'سرعت', 'بالا', 'بده', 'بدید', 'بدین', 'بفرست', 'بفرستید', 'بفرستین', 'میخوام', 'می', 'خوام', 'لطفا', 'لطفاً', 'پلیز', 'یه', 'یک', 'برا', 'برای', 'من', 'ما', 'ایران', 'ایرانی', 'کسی', 'کی', 'داره', 'دارید', 'دارم', 'لازم', 'هست', 'ممنون', 'سلام', 'رو', 'را', 'فیلتر', 'شکن', 'تلگرام', 'free', 'new', 'بزن', 'بذارید', 'بزارید', 'ی']);
function yacIsConfigWord(text) {
  let t = pk(String(text || '').replace(/[?؟!.,،:؛"«»()]/g, ' '));
  if (!t || t.length > 40) return false;
  t = t.replace(/وی ?پی ?ان/g, 'vpn').replace(/فیلتر ?شکن/g, 'فیلترشکن');
  const w = t.split(' ').filter(Boolean);
  if (!w.length || w.length > 5) return false;
  let core = false;
  for (const x of w) { if (YAC_CORE.has(x)) core = true; else if (!YAC_FILL.has(x)) return false; }
  return core;
}
function yacPick(pool) {
  const types = ['vless', 'vmess', 'trojan', 'ss', 'hy2', 'tuic'].filter((t) => (pool[t] || []).length);
  const lists = types.map((t) => [...pool[t]].sort(() => Math.random() - 0.5));
  const picked = [];
  let size = 0;
  for (let round = 0; round < 12 && picked.length < 5; round++) {
    for (const l of lists) {
      const c = l[round];
      if (!c || picked.length >= 5 || size + c.length > 3000) continue;
      picked.push(c);
      size += c.length;
    }
  }
  return picked;
}
async function yacView(env, priv) {
  let st = await env.KV.get('cfg:yacfg', 'json').catch(() => null);
  if (!st || !st.pool) {
    try { st = yacMakePool(await yacLoad(env, false)); await env.KV.put('cfg:yacfg', JSON.stringify(st)).catch(() => {}); } catch { st = null; }
  }
  const picks = st && st.pool ? yacPick(st.pool) : [];
  const panel = await yaPanelBtn(env, 'config', priv, '🌐 پنل وب کانفیگ');
  const rows = [];
  if (panel) rows.push([panel]);
  const buy = yacBuyUrl(env);
  if (buy) rows.push([{ text: '🛒 خرید کانفیگ اختصاصی', url: buy }]);
  rows.push([{ text: '🔄 کانفیگ‌های دیگر', callback_data: 'ya:k' }, ...(priv ? [{ text: '🏠 منوی اصلی', callback_data: 'xm:home' }] : [])]);
  if (!picks.length) return { text: '🆓 <b>کانفیگ رایگان</b>\nالان نتونستم کانفیگ تازه بگیرم 😕 چند دقیقه‌ی دیگه دوباره امتحان کن؛ یا از پنل وب و خرید کانفیگ اختصاصی استفاده کن.', kb: { inline_keyboard: rows } };
  const L = [`🆓 <b>کانفیگ رایگان</b>${st.total ? ' — ' + yaDig(st.total) + ' کانفیگ در دسترس' : ''}`, 'روی هر کانفیگ بزن تا کپی بشه، بعد توی برنامه (v2rayNG، Hiddify، Streisand و…) از کلیپ‌بورد اضافه‌ش کن.', ''];
  for (const c of picks) L.push(`🔹 ${YAC_LABEL[yacTypeOf(c)] || ''}`, `<code>${esc(c)}</code>`, '');
  L.push('⚠️ کانفیگ رایگان عمومیه و سرعت و پایداریش تضمین نیست؛ برای اتصال اختصاصی و پایدار دکمه‌ی خرید رو بزن.');
  return { text: L.join('\n'), kb: { inline_keyboard: rows } };
}

// ======================= YA Dojo (owner feedback -> versioned behavior rules, rollback, daily auto-promotion) =======================
// Owner commands: /ya  /ya status|analyze|feedback <text>|good <text>|improve|history|rollback <id>|auto on|off  (+ glass buttons)
// Needs the D1 binding DB. Active rules are appended to the system prompt of every AI call (except translation/JSON tasks).
const YD = (() => {
/**
 * YA Dojo — standalone Cloudflare Worker
 * Zero dependencies. D1-backed feedback learning, versioning, rollback and scheduled promotion.
 *
 * Required bindings:
 *   DB                 D1 database
 *   TELEGRAM_BOT_TOKEN Telegram bot token (secret)
 *   OWNER_ID           Telegram numeric user ID allowed to manage YA Dojo
 *
 * Optional bindings:
 *   WEBHOOK_SECRET     Telegram webhook secret token (recommended)
 *   AUTO_PROMOTE       "true" to enable daily automatic promotion of repeated owner corrections
 *
 * Endpoints:
 *   GET  /health       health check
 *   POST /telegram     Telegram webhook
 *
 * Commands (private chat, owner only):
 *   /ya
 *   /ya status
 *   /ya analyze
 *   /ya feedback <desired behavior>
 *   /ya good <positive feedback>
 *   /ya improve
 *   /ya history
 *   /ya rollback <version_id>
 *   /ya auto on|off
 *
 * Note: this is a standalone Worker/bot endpoint. A Telegram bot token can have only
 * one webhook URL at a time. To use the SAME bot as another Worker, integrate this file
 * as a module into that Worker and route updates to its exported handleUpdate().
 */

const APP = "YA Dojo";
const MAX_RULES = 12;
const MAX_LESSON = 240;
const CACHE_TTL_MS = 15_000;

let initPromise;
let activeCache;
let activeCacheAt = 0;

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" }
  });
}

function safeText(value, max = MAX_LESSON) {
  return String(value ?? "")
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, max);
}

function ownerId(env) {
  return String(env.OWNER_ID ?? "").trim();
}

async function init(env) {
  if (!env.DB) throw new Error("Missing D1 binding: DB");
  if (initPromise) return initPromise;

  initPromise = (async () => {
    const statements = [
      `CREATE TABLE IF NOT EXISTS ya_dojo_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        at INTEGER NOT NULL,
        kind TEXT NOT NULL,
        area TEXT NOT NULL,
        detail TEXT NOT NULL
      )`,
      `CREATE INDEX IF NOT EXISTS idx_ya_dojo_events_at ON ya_dojo_events(at)`,
      `CREATE TABLE IF NOT EXISTS ya_dojo_feedback (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        at INTEGER NOT NULL,
        kind TEXT NOT NULL,
        lesson TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        version_id INTEGER
      )`,
      `CREATE INDEX IF NOT EXISTS idx_ya_dojo_feedback_status ON ya_dojo_feedback(status, kind)`,
      `CREATE TABLE IF NOT EXISTS ya_dojo_versions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        created_at INTEGER NOT NULL,
        status TEXT NOT NULL,
        reason TEXT NOT NULL,
        payload TEXT NOT NULL,
        previous_id INTEGER,
        rolled_back_from INTEGER
      )`,
      `CREATE TABLE IF NOT EXISTS ya_dojo_state (
        k TEXT PRIMARY KEY,
        v TEXT NOT NULL
      )`
    ];
    for (const sql of statements) await env.DB.prepare(sql).run();

    const active = await env.DB.prepare(
      "SELECT v FROM ya_dojo_state WHERE k='active_version'"
    ).first();

    if (!active) {
      const payload = JSON.stringify({ rules: [] });
      const result = await env.DB.prepare(
        "INSERT INTO ya_dojo_versions(created_at,status,reason,payload,previous_id) VALUES(?,?,?,?,NULL)"
      ).bind(Date.now(), "active", "initial YA Dojo version", payload).run();
      const id = Number(result.meta?.last_row_id || 1);
      await env.DB.prepare(
        "INSERT INTO ya_dojo_state(k,v) VALUES('active_version',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v"
      ).bind(String(id)).run();
    }
    return true;
  })().catch((error) => {
    initPromise = null;
    throw error;
  });

  return initPromise;
}

async function recordEvent(env, kind, area, detail = "") {
  await init(env);
  await env.DB.prepare(
    "INSERT INTO ya_dojo_events(at,kind,area,detail) VALUES(?,?,?,?)"
  ).bind(Date.now(), safeText(kind, 32), safeText(area, 60), safeText(detail, 240)).run();
}

async function activeVersion(env) {
  await init(env);
  if (activeCache && Date.now() - activeCacheAt < CACHE_TTL_MS) return activeCache;

  const state = await env.DB.prepare(
    "SELECT v FROM ya_dojo_state WHERE k='active_version'"
  ).first();
  const id = Number(state?.v || 0);
  const row = id ? await env.DB.prepare(
    "SELECT id,payload,created_at,reason FROM ya_dojo_versions WHERE id=?"
  ).bind(id).first() : null;

  let payload = {};
  try { payload = JSON.parse(row?.payload || "{}"); } catch {}
  activeCache = {
    version: id,
    rules: Array.isArray(payload.rules) ? payload.rules.slice(0, MAX_RULES) : [],
    created_at: Number(row?.created_at || 0),
    reason: row?.reason || ""
  };
  activeCacheAt = Date.now();
  return activeCache;
}

async function makeVersion(env, rules, reason, rolledBackFrom = null) {
  const current = await activeVersion(env);
  const cleanRules = [...new Set((rules || []).map((x) => safeText(x, MAX_LESSON)).filter(Boolean))]
    .slice(0, MAX_RULES);
  const result = await env.DB.prepare(
    "INSERT INTO ya_dojo_versions(created_at,status,reason,payload,previous_id,rolled_back_from) VALUES(?,?,?,?,?,?)"
  ).bind(Date.now(), "active", safeText(reason, 100), JSON.stringify({ rules: cleanRules }),
    current.version || null, rolledBackFrom).run();

  const id = Number(result.meta?.last_row_id);
  if (!id) throw new Error("D1 did not return the new version ID");

  await env.DB.prepare(
    "UPDATE ya_dojo_versions SET status='archived' WHERE id<>? AND status='active'"
  ).bind(id).run();
  await env.DB.prepare(
    "INSERT INTO ya_dojo_state(k,v) VALUES('active_version',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v"
  ).bind(String(id)).run();

  activeCache = null;
  activeCacheAt = 0;
  await recordEvent(env, "version_created", "learning", `version=${id}; reason=${reason}`);
  return id;
}

async function promoteRepeatedFeedback(env) {
  await init(env);
  const cutoff = Date.now() - 90 * 86400000;
  const candidates = (await env.DB.prepare(
    `SELECT lesson,COUNT(*) AS n FROM ya_dojo_feedback
     WHERE kind='correction' AND status='pending' AND at>=?
     GROUP BY lesson HAVING COUNT(*)>=2 ORDER BY n DESC LIMIT 8`
  ).bind(cutoff).all()).results || [];

  const current = await activeVersion(env);
  const rules = [...current.rules];
  const promoted = [];

  for (const item of candidates) {
    const lesson = safeText(item.lesson);
    if (!lesson || rules.includes(lesson)) continue;
    if (rules.length >= MAX_RULES) break;
    rules.push(lesson);
    promoted.push(lesson);
  }

  if (!promoted.length) {
    const pending = Number((await env.DB.prepare(
      "SELECT COUNT(*) AS n FROM ya_dojo_feedback WHERE kind='correction' AND status='pending'"
    ).first())?.n || 0);
    return { changed: false, message: `هنوز اصلاح تکرارشدهٔ جدیدی برای اعمال وجود ندارد.\nبازخوردهای در انتظار: ${pending}` };
  }

  const version = await makeVersion(env, rules, "repeated owner feedback auto-promotion");
  for (const item of candidates) {
    if (promoted.includes(safeText(item.lesson))) {
      await env.DB.prepare(
        "UPDATE ya_dojo_feedback SET status='applied',version_id=? WHERE kind='correction' AND status='pending' AND lesson=?"
      ).bind(version, item.lesson).run();
    }
  }
  return { changed: true, version, promoted, previous: current.version,
    message: `✅ بهبود ثبت شد.\nنسخهٔ جدید: #${version}\nقواعد افزوده‌شده: ${promoted.length}\n${promoted.map((x, i) => `${i + 1}. ${x}`).join("\n")}\n\nبازگشت: /ya rollback ${current.version}` };
}

async function command(env, text) {
  const raw = safeText(text, 600);
  const parts = raw.split(/\s+/);
  const action = (parts[0] || "help").toLowerCase();
  const rest = raw.slice(action.length).trim();

  await init(env);

  if (action === "help" || action === "") {
    return `${APP}\n\n/ya status — وضعیت و نسخهٔ فعال\n/ya analyze — تحلیل خطاها و بازخوردها\n/ya feedback متن — ثبت اصلاح رفتاری\n/ya good متن — ثبت بازخورد مثبت\n/ya improve — اعمال اصلاحات تکرارشده\n/ya history — تاریخچهٔ نسخه‌ها\n/ya rollback ID — بازگشت به نسخه\n/ya auto on|off — چرخهٔ خودکار روزانه`;
  }

  if (action === "feedback" || action === "good") {
    const lesson = safeText(rest);
    if (lesson.length < 4) return "متن بازخورد کوتاه است. مثال: /ya feedback اگر مطمئن نیستی، عدم قطعیت را واضح بگو";
    await env.DB.prepare(
      "INSERT INTO ya_dojo_feedback(at,kind,lesson,status) VALUES(?,?,?,'pending')"
    ).bind(Date.now(), action === "good" ? "positive" : "correction", lesson).run();
    await recordEvent(env, "feedback", "owner", `${action}: ${lesson}`);
    return action === "good"
      ? "👍 بازخورد مثبت ثبت شد."
      : "🧠 اصلاح ثبت شد. برای اعمال خودکار، یک اصلاح یکسان باید دست‌کم دو بار ثبت شود؛ سپس /ya improve را اجرا کن یا چرخهٔ خودکار را فعال کن.";
  }

  if (action === "status") {
    const active = await activeVersion(env);
    const feedback = await env.DB.prepare(
      "SELECT kind,status,COUNT(*) AS n FROM ya_dojo_feedback GROUP BY kind,status"
    ).all();
    const events = Number((await env.DB.prepare(
      "SELECT COUNT(*) AS n FROM ya_dojo_events WHERE at>=?"
    ).bind(Date.now() - 86400000).first())?.n || 0);
    const auto = (await env.DB.prepare("SELECT v FROM ya_dojo_state WHERE k='auto'").first())?.v === "on";
    const summary = (feedback.results || []).map((x) => `${x.kind}/${x.status}: ${x.n}`).join("\n") || "بدون بازخورد";
    return `🧠 ${APP}\nنسخهٔ فعال: #${active.version}\nقواعد فعال: ${active.rules.length}/${MAX_RULES}\nچرخهٔ خودکار: ${auto ? "روشن" : "خاموش"}\nرویدادهای ۲۴ ساعت اخیر: ${events}\n\n${summary}`;
  }

  if (action === "analyze") {
    const since = Date.now() - 7 * 86400000;
    const eventRows = (await env.DB.prepare(
      "SELECT kind,area,COUNT(*) AS n FROM ya_dojo_events WHERE at>=? GROUP BY kind,area ORDER BY n DESC LIMIT 10"
    ).bind(since).all()).results || [];
    const feedbackRows = (await env.DB.prepare(
      "SELECT kind,status,COUNT(*) AS n FROM ya_dojo_feedback WHERE at>=? GROUP BY kind,status ORDER BY n DESC"
    ).bind(since).all()).results || [];
    const active = await activeVersion(env);
    return `📊 تحلیل ۷ روز اخیر\nنسخهٔ فعال: #${active.version}\nقواعد: ${active.rules.length}\n\nرویدادها:\n${eventRows.map(x => `• ${x.kind} / ${x.area}: ${x.n}`).join("\n") || "• رویدادی ثبت نشده"}\n\nبازخوردها:\n${feedbackRows.map(x => `• ${x.kind} / ${x.status}: ${x.n}`).join("\n") || "• بازخوردی ثبت نشده"}\n\nقواعد فعال:\n${active.rules.map((x, i) => `${i + 1}. ${x}`).join("\n") || "هنوز قاعده‌ای ثبت نشده"}`;
  }

  if (action === "improve") {
    const result = await promoteRepeatedFeedback(env);
    return result.message;
  }

  if (action === "history") {
    const rows = (await env.DB.prepare(
      "SELECT id,created_at,status,reason,previous_id,rolled_back_from,payload FROM ya_dojo_versions ORDER BY id DESC LIMIT 12"
    ).all()).results || [];
    if (!rows.length) return "هنوز نسخه‌ای ثبت نشده است.";
    return "🗂 تاریخچهٔ نسخه‌ها\n" + rows.map((row) => {
      let count = 0;
      try { count = JSON.parse(row.payload || "{}").rules?.length || 0; } catch {}
      const stamp = new Date(Number(row.created_at)).toISOString().replace("T", " ").slice(0, 16) + " UTC";
      return `#${row.id} · ${row.status} · ${count} قاعده · ${stamp}\n  ${safeText(row.reason, 100)}${row.rolled_back_from ? ` (بازگشت از #${row.rolled_back_from})` : ""}`;
    }).join("\n\n");
  }

  if (action === "rollback") {
    const id = Number(rest);
    if (!Number.isInteger(id) || id < 1) return "شناسهٔ نسخه معتبر نیست. مثال: /ya rollback 3";
    const target = await env.DB.prepare(
      "SELECT id,payload FROM ya_dojo_versions WHERE id=?"
    ).bind(id).first();
    if (!target) return `نسخهٔ #${id} پیدا نشد.`;
    let payload;
    try { payload = JSON.parse(target.payload); } catch { return "محتوای نسخه قابل خواندن نیست."; }
    const newId = await makeVersion(env, payload.rules || [], `rollback to version ${id}`, id);
    await recordEvent(env, "rollback", "owner", `restored=${id}; new_version=${newId}`);
    return `↩️ قواعد نسخهٔ #${id} بازیابی شد.\nنسخهٔ جدید و فعال: #${newId}\nتاریخچه حفظ شده است.`;
  }

  if (action === "auto") {
    const mode = rest.toLowerCase();
    if (!["on", "off"].includes(mode)) return "استفاده: /ya auto on یا /ya auto off";
    await env.DB.prepare(
      "INSERT INTO ya_dojo_state(k,v) VALUES('auto',?) ON CONFLICT(k) DO UPDATE SET v=excluded.v"
    ).bind(mode).run();
    await recordEvent(env, "auto_mode", "owner", mode);
    return mode === "on"
      ? "🔁 چرخهٔ خودکار روشن شد. اجرای دوره‌ای به Cron Trigger این Worker نیاز دارد."
      : "⏸️ چرخهٔ خودکار خاموش شد.";
  }

  return `دستور ناشناخته است.\n\n${await command(env, "help")}`;
}

async function telegram(env, method, body) { return tg(env, method, { ...body, x4raw: true }); }

async function sendText(env, chatId, text) {
  const chunks = [];
  let remaining = String(text || "");
  while (remaining.length) {
    let end = Math.min(remaining.length, 3900);
    if (end < remaining.length) {
      const newline = remaining.lastIndexOf("\n", end);
      if (newline > 500) end = newline;
    }
    chunks.push(remaining.slice(0, end));
    remaining = remaining.slice(end);
  }
  for (const chunk of chunks) {
    await telegram(env, "sendMessage", { chat_id: chatId, text: chunk, disable_web_page_preview: true });
  }
}


  return { init, activeVersion, command, promoteRepeatedFeedback, recordEvent, safeText, sendText, MAX_RULES };
})();

async function ydApply(env, body) { // inject the active rules into the AI request
  try {
    if (!env.DB || !body || !Array.isArray(body.messages)) return body;
    const a = await YD.activeVersion(env);
    if (!a.rules.length) return body;
    const first = body.messages[0];
    const sysText = first && first.role === 'system' && typeof first.content === 'string' ? first.content : '';
    if (/translation engine|ONLY (?:a )?(?:valid )?JSON|valid JSON/i.test(sysText)) return body;
    const block = '\n\n[Owner-approved behavior rules — follow them whenever they apply]\n' + a.rules.map((r, i) => `${i + 1}. ${r}`).join('\n');
    const msgs = body.messages.slice();
    if (sysText) msgs[0] = { ...first, content: first.content + block };
    else msgs.unshift({ role: 'system', content: block.trim() });
    return { ...body, messages: msgs };
  } catch { return body; }
}
let ydLogN = { t: 0, n: 0 };
function ydLog(env, kind, area, detail) { // bot errors -> Dojo events (max 20/hour)
  try {
    if (!env.DB) return;
    if (Date.now() - ydLogN.t > 3600000) ydLogN = { t: Date.now(), n: 0 };
    if (ydLogN.n++ >= 20) return;
    const p = YD.recordEvent(env, kind, area, detail).catch(() => {});
    if (env._ctx && env._ctx.waitUntil) env._ctx.waitUntil(p);
  } catch { /* never break the bot */ }
}
const ydIsOwner = (env, id) => !!String(env.OWNER_ID || '').trim() && String(id) === String(env.OWNER_ID).trim();
async function ydAutoOn(env) {
  try { return ((await env.DB.prepare("SELECT v FROM ya_dojo_state WHERE k='auto'").first()) || {}).v === 'on'; } catch { return false; }
}
async function ydKb(env, priv, extra) {
  const auto = await ydAutoOn(env);
  const rows = [
    [{ text: '📊 وضعیت', callback_data: 'yd:status' }, { text: '🔍 تحلیل', callback_data: 'yd:analyze' }],
    [{ text: '⬆️ اعمال بهبودها', callback_data: 'yd:improve' }, { text: '🗂 تاریخچه', callback_data: 'yd:history' }],
    [{ text: auto ? '🔁 چرخه‌ی خودکار: روشن ✅' : '🔁 چرخه‌ی خودکار: خاموش', callback_data: 'yd:auto' }],
  ];
  if (extra && extra.length) rows.push(extra);
  if (priv) rows.push([{ text: '🏠 منوی اصلی', callback_data: 'xm:home' }]);
  return { inline_keyboard: rows };
}
const YD_TIP = '\n\n💡 ثبت اصلاح: /ya feedback متن — وقتی یک اصلاحِ یکسان دو بار ثبت بشه، با «اعمال بهبودها» (یا چرخه‌ی خودکار) تبدیل به قاعده می‌شه و روی جواب‌های AI اثر می‌ذاره. هر نسخه قابل بازگشته.';
async function ydCommand(env, m, arg, inGroup) {
  if (!ydIsOwner(env, m.from && m.from.id)) return false; // owner only; everyone else falls through to normal handling
  if (!env.DB) { await reply(env, m, 'YA Dojo به دیتابیس D1 نیاز داره؛ بایند DB رو به ورکر وصل کن.', inGroup); return true; }
  const out = await YD.command(env, arg || 'status');
  const isFeedback = /^(feedback|good)\b/i.test(arg || '');
  await reply(env, m, out + (arg && !/^(help|status)$/i.test(arg) ? '' : YD_TIP), inGroup, false, isFeedback ? undefined : await ydKb(env, !inGroup));
  return true;
}
async function ydCallback(env, cq) {
  const ans = (t, alert) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: String(t).slice(0, 190), show_alert: !!alert } : {}) });
  if (!ydIsOwner(env, cq.from && cq.from.id)) return ans('این بخش فقط برای مالک بات است.', true);
  const msg = cq.message;
  if (!msg || !msg.chat) return ans();
  if (!env.DB) return ans('بایند DB وصل نیست.', true);
  const priv = msg.chat.type === 'private';
  const [, a, b] = String(cq.data || '').split(':');
  let out = '';
  let extra = [];
  try {
    if (a === 'auto') {
      out = await YD.command(env, (await ydAutoOn(env)) ? 'auto off' : 'auto on');
    } else if (a === 'rb') {
      const id = Number(b);
      if (!Number.isInteger(id) || id < 1) return ans();
      out = await YD.command(env, 'rollback ' + id);
    } else if (['status', 'analyze', 'improve', 'history'].includes(a)) {
      out = await YD.command(env, a);
      if (a === 'history') {
        const rows = ((await env.DB.prepare('SELECT id,status FROM ya_dojo_versions ORDER BY id DESC LIMIT 6').all()).results) || [];
        extra = rows.filter((r) => r.status !== 'active').slice(0, 3).map((r) => ({ text: `↩️ بازگشت به #${r.id}`, callback_data: `yd:rb:${r.id}` }));
      }
    } else return ans();
  } catch (e) { return ans('⚠️ ' + String((e && e.message) || e).slice(0, 150), true); }
  const r = await tg(env, 'editMessageText', { chat_id: msg.chat.id, message_id: msg.message_id, text: String(out).slice(0, 4000), reply_markup: await ydKb(env, priv, extra), disable_web_page_preview: true, x4raw: true });
  if (r.ok) return ans();
  if (/not modified/i.test(r.description || '')) return ans('✅ بدون تغییر');
  await tg(env, 'sendMessage', { chat_id: msg.chat.id, text: String(out).slice(0, 4000), reply_markup: await ydKb(env, priv, extra), x4raw: true });
  return ans();
}
async function ydCron(env) {
  if (!env.DB) return;
  const now = new Date();
  if (now.getUTCHours() !== 3) return;
  const day = now.toISOString().slice(0, 10);
  if ((await env.KV.get('cfg:ydlast').catch(() => null)) === day) return;
  await env.KV.put('cfg:ydlast', day).catch(() => {});
  await YD.init(env);
  const enabled = (await ydAutoOn(env)) || String(env.AUTO_PROMOTE || '').toLowerCase() === 'true';
  if (!enabled) return;
  const r = await YD.promoteRepeatedFeedback(env);
  if (r.changed && env.OWNER_ID) await YD.sendText(env, env.OWNER_ID, '🧠 YA Dojo: بهبود دوره‌ای انجام شد.\n' + r.message);
}


// ---------- TMDB proxy: the Filmyar web app calls /yatmdb/... and the key is added here, never sent to the browser ----------
async function yaTmdb(request, env, p, url) {
  if (!env.TMDB_API_KEY) return yaJson({ error: 'TMDB_API_KEY is not set' }, 503, { 'cache-control': 'no-store' });
  const ip = request.headers.get('cf-connecting-ip') || 'x';
  if (!rateOk(`tmdb:${ip}`, 90, 60000)) return yaJson({ error: 'rate limit' }, 429, { 'cache-control': 'no-store' });
  const path = p.slice('/yatmdb'.length);
  if (!/^\/(?:find\/tt\d{5,12}|(?:movie|tv)\/\d{1,10}(?:\/(?:credits|external_ids|recommendations|similar))?)$/.test(path)) return yaJson({ error: 'bad path' }, 400, { 'cache-control': 'no-store' });
  const qp = new URLSearchParams();
  for (const k of ['language', 'append_to_response', 'external_source', 'page']) {
    const v = url.searchParams.get(k);
    if (v && /^[A-Za-z0-9_,\-]{1,60}$/.test(v)) qp.set(k, v);
  }
  qp.set('api_key', env.TMDB_API_KEY);
  const r = await fetch('https://api.themoviedb.org/3' + path + '?' + qp.toString(), { signal: AbortSignal.timeout(10000) });
  return new Response(r.body, { status: r.status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'public, max-age=3600' } });
}

// ======================= Several backup AI providers (owner, private chat): /backup =======================
// A backup = base URL + model + one or more API keys (keys are stored AES-GCM encrypted). They are tried in order when the main AI fails.
const BK_MAX = 8;
const bkOwner = (env, id) => !!String(env.OWNER_ID || '').trim() && String(id) === String(env.OWNER_ID).trim();
const bkHost = (b) => { try { return new URL(b).hostname.replace(/^api\./, ''); } catch { return '—'; } };
async function bkGet(env) {
  const v = await env.KV.get('cfg:bklist', 'json').catch(() => null);
  return { items: Array.isArray(v && v.items) ? v.items : [], next: Number(v && v.next) || 1 };
}
async function bkPut(env, st) {
  await env.KV.put('cfg:bklist', JSON.stringify(st));
  _bkMemo = { v: undefined, t: 0 };
}
async function bkMigrateSlot(env) { // a finished old-style slot becomes a normal list entry
  const slot = await env.KV.get('cfg:backup', 'json').catch(() => null);
  if (!slot || !slot.base || !slot.model) return;
  const keysEnc = [];
  if (slot.k) keysEnc.push(slot.k);
  if (Array.isArray(slot.keysEnc)) keysEnc.push(...slot.keysEnc);
  if (Array.isArray(slot.keys)) for (const k of slot.keys) keysEnc.push(await encSecret(env, String(k)));
  if (!keysEnc.length) return;
  const st = await bkGet(env);
  if (st.items.length >= BK_MAX) return;
  st.items.push({ id: st.next++, base: slot.base, model: slot.model, keysEnc, paused: !!slot.paused });
  await bkPut(env, st);
  await env.KV.delete('cfg:backup');
}
async function bkListView(env) {
  await bkMigrateSlot(env).catch(() => {});
  const st = await bkGet(env);
  const L = ['🛟 <b>سرویس‌های پشتیبان AI</b>', 'وقتی AI اصلی خطا بده یا سقفش تموم بشه، بات به ترتیب این سرویس‌ها رو امتحان می‌کنه. هر سرویس می‌تونه چند کلید داشته باشه.', ''];
  const rows = [];
  st.items.forEach((it, i) => {
    L.push(`${yaDig(i + 1)}) ${it.paused ? '⚪️' : '🟢'} <code>${esc(bkHost(it.base))}</code> · ${esc(String(it.model).slice(0, 40))} · ${yaDig((it.keysEnc || []).length)} کلید`);
    rows.push([{ text: `${i + 1}. ${bkHost(it.base)} · ${String(it.model).slice(0, 24)}`.slice(0, 60), callback_data: `bk:i:${it.id}` }]);
  });
  if (!st.items.length) L.push('هنوز سرویسی اضافه نشده.');
  if (env.AI_BACKUP_BASE_URL && env.AI_BACKUP_MODEL) L.push('', 'ℹ️ تنظیم AI_BACKUP_* (متغیر محیطی) هم به‌عنوان آخرین پشتیبان استفاده می‌شه.');
  if (st.items.length < BK_MAX) rows.push([{ text: '➕ افزودن سرویس پشتیبان', callback_data: 'mb:h' }]);
  rows.push(st.items.length ? [{ text: '🧪 تست همه', callback_data: 'bk:ta' }, { text: '🏠 منوی اصلی', callback_data: 'xm:home' }] : [{ text: '🏠 منوی اصلی', callback_data: 'xm:home' }]);
  return { text: L.join('\n'), kb: rows };
}
function bkItemView(st, id) {
  const idx = st.items.findIndex((x) => x.id === id);
  if (idx < 0) return null;
  const it = st.items[idx];
  const L = [`🛟 <b>پشتیبان شماره ${yaDig(idx + 1)}</b>`, `سرویس: <code>${esc(bkHost(it.base))}</code>`, `مدل: <code>${esc(it.model)}</code>`, `کلیدها: ${yaDig((it.keysEnc || []).length)}`, `وضعیت: ${it.paused ? '⚪️ خاموش' : '🟢 فعال'}`, `اولویت: ${yaDig(idx + 1)} از ${yaDig(st.items.length)}`];
  const kb = [
    [{ text: '🧪 تست', callback_data: `bk:t:${id}` }, { text: it.paused ? '🟢 روشن‌کردن' : '⏸ خاموش‌کردن', callback_data: `bk:e:${id}` }],
    [{ text: '🔑 کلیدها', callback_data: `bk:k:${id}` }, { text: '📝 تغییر مدل', callback_data: `bk:m:${id}` }],
    [...(idx > 0 ? [{ text: '⬆️ اولویت بالاتر', callback_data: `bk:u:${id}` }] : []), { text: '🗑 حذف', callback_data: `bk:d:${id}` }],
    [{ text: '↩️ لیست', callback_data: 'bk:l' }],
  ];
  return { text: L.join('\n'), kb };
}
async function bkKeysView(env, st, id) {
  const it = st.items.find((x) => x.id === id);
  if (!it) return null;
  const L = [`🔑 <b>کلیدهای ${esc(bkHost(it.base))}</b>`, 'کلیدها به ترتیب امتحان می‌شن؛ اگه یکی به سقف بخوره بات خودکار می‌ره سراغ بعدی.', ''];
  const kb = [];
  for (let i = 0; i < (it.keysEnc || []).length; i++) {
    let tail = '••••';
    try { tail = '…' + (await decSecret(env, it.keysEnc[i])).slice(-4); } catch { tail = '⚠️ خراب'; }
    L.push(`${yaDig(i + 1)}) <code>${esc(tail)}</code>`);
    kb.push([{ text: `🗑 حذف کلید ${i + 1} (${tail})`, callback_data: `bk:kd:${id}:${i}` }]);
  }
  if (!(it.keysEnc || []).length) L.push('کلیدی ثبت نشده.');
  kb.push([{ text: '➕ کلید جدید', callback_data: `bk:ka:${id}` }, { text: '↩️ برگشت', callback_data: `bk:i:${id}` }]);
  return { text: L.join('\n'), kb };
}
async function bkOpen(env, m) {
  if (m.chat.type !== 'private') return tg(env, 'sendMessage', { chat_id: m.chat.id, text: 'تنظیم سرویس پشتیبان فقط توی پیوی بات انجام می‌شه (کلید نباید توی گروه فرستاده بشه).' });
  const v = await bkListView(env);
  return tg(env, 'sendMessage', { chat_id: m.chat.id, text: v.text, parse_mode: 'HTML', link_preview_options: { is_disabled: true }, reply_markup: { inline_keyboard: v.kb } });
}
async function bkCallback(env, cq) {
  const ans = (t, alert) => tg(env, 'answerCallbackQuery', { callback_query_id: cq.id, ...(t ? { text: String(t).slice(0, 190), show_alert: !!alert } : {}) });
  if (!bkOwner(env, cq.from && cq.from.id)) return ans('فقط مالک بات', true);
  const msg = cq.message;
  if (!msg || msg.chat.type !== 'private') return ans('این پنل فقط توی پیوی بات کار می‌کنه.', true);
  if (!rateOk(`bk:${cq.from.id}`, 40, 60000)) return ans('⏳ آروم‌تر', true);
  const [, act, a1, a2] = String(cq.data || '').split(':');
  const id = Number(a1);
  const chat = msg.chat.id;
  const edit = (v) => tg(env, 'editMessageText', { chat_id: chat, message_id: msg.message_id, text: v.text, parse_mode: 'HTML', link_preview_options: { is_disabled: true }, reply_markup: { inline_keyboard: v.kb } });
  try {
    if (act === 'l') { await edit(await bkListView(env)); return ans(); }
    if (act === 'save') { // finish the wizard: the slot (service + key + model) becomes one more backup
      const slot = await maGet(env, 'b', cq.from.id);
      if (!(slot.base && slot.k && slot.model)) return ans('اول سرویس، کلید و مدل رو کامل کن.', true);
      const st = await bkGet(env);
      if (st.items.length >= BK_MAX) return ans(`حداکثر ${BK_MAX} سرویس پشتیبان.`, true);
      st.items.push({ id: st.next++, base: slot.base, model: slot.model, keysEnc: [slot.k], paused: false });
      await bkPut(env, st);
      await maDel(env, 'b', cq.from.id);
      await edit(await bkListView(env));
      return ans('✅ به لیست پشتیبان‌ها اضافه شد');
    }
    if (act === 'ta') {
      await ans('در حال تست…');
      const st = await bkGet(env);
      const res = await Promise.all(st.items.map(async (it, i) => {
        if (!(it.keysEnc || []).length) return `${yaDig(i + 1)}) ${esc(bkHost(it.base))}: ⚠️ بدون کلید`;
        try { return `${yaDig(i + 1)}) ${esc(bkHost(it.base))} / ${esc(it.model)}: ${esc((await testProvider({ base: it.base, key: await decSecret(env, it.keysEnc[0]), model: it.model })).text)}`; } catch (e) { return `${yaDig(i + 1)}) ${esc(bkHost(it.base))}: ⚠️ ${esc(String((e && e.message) || e).slice(0, 80))}`; }
      }));
      await tg(env, 'sendMessage', { chat_id: chat, text: '🧪 <b>نتیجه‌ی تست</b>\n' + (res.join('\n') || 'سرویسی نیست.'), parse_mode: 'HTML' });
      return;
    }
    if (!Number.isInteger(id)) return ans();
    const st = await bkGet(env);
    const it = st.items.find((x) => x.id === id);
    if (!it) { await edit(await bkListView(env)); return ans('این مورد دیگه وجود نداره.', true); }
    if (act === 'i') { await edit(bkItemView(st, id)); return ans(); }
    if (act === 't') {
      if (!(it.keysEnc || []).length) return ans('کلیدی ثبت نشده.', true);
      const r = await testProvider({ base: it.base, key: await decSecret(env, it.keysEnc[0]), model: it.model });
      return ans(r.text, true);
    }
    if (act === 'e') { it.paused = !it.paused; await bkPut(env, st); await edit(bkItemView(st, id)); return ans(it.paused ? 'خاموش شد' : 'روشن شد'); }
    if (act === 'u') {
      const i = st.items.findIndex((x) => x.id === id);
      if (i > 0) { [st.items[i - 1], st.items[i]] = [st.items[i], st.items[i - 1]]; await bkPut(env, st); }
      await edit(bkItemView(st, id));
      return ans('اولویت بالاتر رفت');
    }
    if (act === 'd') {
      await edit({ text: `🗑 سرویس <code>${esc(bkHost(it.base))}</code> و همه‌ی کلیدهاش حذف بشه؟`, kb: [[{ text: '✅ بله، حذف شه', callback_data: `bk:dd:${id}` }, { text: '↩️ نه', callback_data: `bk:i:${id}` }]] });
      return ans();
    }
    if (act === 'dd') { st.items = st.items.filter((x) => x.id !== id); await bkPut(env, st); await edit(await bkListView(env)); return ans('حذف شد'); }
    if (act === 'k') { await edit(await bkKeysView(env, st, id)); return ans(); }
    if (act === 'kd') {
      const i = Number(a2);
      if (Number.isInteger(i) && i >= 0 && i < (it.keysEnc || []).length) { it.keysEnc.splice(i, 1); await bkPut(env, st); }
      await edit(await bkKeysView(env, st, id));
      return ans('کلید حذف شد');
    }
    if (act === 'ka') {
      await maAsk(env, chat, `🗝 کلید جدید برای پشتیبان #${id}\nروی همین پیام ریپلای کن و کلید API رو بفرست.\nسرویس: ${bkHost(it.base)}\n(بعد از دریافت، پیامت خودکار پاک و کلید رمزنگاری می‌شه.)`, 'sk-...');
      return ans();
    }
    if (act === 'm') {
      await maAsk(env, chat, `📝 مدل پشتیبان #${id}\nنام مدل جدید رو روی همین پیام ریپلای کن.\nمثال: llama-3.3-70b-versatile`, 'model-name');
      return ans();
    }
  } catch (e) { return ans('⚠️ ' + String((e && e.message) || e).slice(0, 150), true); }
  return ans();
}
async function bkTryReply(env, m, text) { // replies to the "new key" / "new model" prompts
  const rt = m.reply_to_message;
  if (!rt || !rt.from || !rt.from.is_bot || typeof rt.text !== 'string' || !text || text.startsWith('/')) return false;
  const km = rt.text.match(/^🗝 کلید جدید برای پشتیبان #(\d+)/);
  const mm = rt.text.match(/^📝 مدل پشتیبان #(\d+)/);
  if (!km && !mm) return false;
  if (!bkOwner(env, m.from && m.from.id) || m.chat.type !== 'private') return false;
  if (!rateOk(`bkr:${m.from.id}`, 15, 60000)) { await maSend(env, m.chat.id, '⏳ آروم‌تر.'); return true; }
  const id = Number((km || mm)[1]);
  const st = await bkGet(env);
  const it = st.items.find((x) => x.id === id);
  if (km && m.message_id) await tg(env, 'deleteMessage', { chat_id: m.chat.id, message_id: m.message_id }); // never leave a key in the chat
  if (!it) { await maSend(env, m.chat.id, 'این پشتیبان دیگه وجود نداره.'); return true; }
  if (km) {
    const key = text.trim();
    if (!/^\S{8,400}$/.test(key)) { await maSend(env, m.chat.id, '❌ کلید معتبر نیست (بدون فاصله، حداقل ۸ حرف).', [[{ text: '🔑 دوباره', callback_data: `bk:ka:${id}` }, { text: '↩️ برگشت', callback_data: `bk:k:${id}` }]]); return true; }
    for (const e of it.keysEnc || []) { try { if ((await decSecret(env, e)) === key) { await maSend(env, m.chat.id, 'این کلید قبلاً ثبت شده.'); return true; } } catch { /* skip */ } }
    it.keysEnc = [...(it.keysEnc || []), await encSecret(env, key)].slice(0, 20);
    await bkPut(env, st);
    const v = await bkKeysView(env, st, id);
    await tg(env, 'sendMessage', { chat_id: m.chat.id, text: '✅ کلید ذخیره شد و پیامت پاک شد.\n\n' + v.text, parse_mode: 'HTML', reply_markup: { inline_keyboard: v.kb } });
    return true;
  }
  const model = text.trim();
  if (!/^[\w\-.:\/+@~]{2,100}$/.test(model)) { await maSend(env, m.chat.id, '❌ نام مدل معتبر نیست (بدون فاصله).', [[{ text: '📝 دوباره', callback_data: `bk:m:${id}` }, { text: '↩️ برگشت', callback_data: `bk:i:${id}` }]]); return true; }
  it.model = model;
  await bkPut(env, st);
  const v = bkItemView(st, id);
  await tg(env, 'sendMessage', { chat_id: m.chat.id, text: `✅ مدل: ${esc(model)}\n\n` + v.text, parse_mode: 'HTML', reply_markup: { inline_keyboard: v.kb } });
  return true;
}


